handleCollectorWishlist(state,p,action);
break;

case 'collector-wish-request':
case 'collector-wish-peek':
case 'collector-wish-buy':
case 'collector-wish-skip':
handleCollectorWishlist(state,p,action);
break;

case 'collector-wish-request':
case 'collector-wish-peek':
case 'collector-wish-buy':
case 'collector-wish-skip':
handleCollectorWishlist(state,p,action);
break;

case 'collector-wish-request':
case 'collector-wish-peek':
case 'collector-wish-buy':
case 'collector-wish-skip':
handleCollectorWishlist(state,p,action);
break;

case 'theft-start':
check(state.config.secureEconomy && ['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','ตอบเหตุการณ์ก่อนขโมย');
startTheftDuel(state,p,action);
break;

case 'reappraise-owned':
check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','ตอบเหตุการณ์ก่อนประเมินใหม่');
reappraiseOwnedItem(state,p,action.itemId,action.value);
break;

case 'liquidate':
check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','ตอบเหตุการณ์ก่อนขายของ');
liquidateOwnedItem(state,p,action.itemId);
break;

case 'enter':
{
      check(state.phase==='PORTALS' && !p.eventOffer,'phase','เลือก event ก่อนเข้าประตู');
      const portal=p.portals.find(v=>v.id===action.portalId && !v.disabled); check(portal,'portal','ประตูนี้เข้าไม่ได้');
      p.selectedPortalId=portal.id;p.stock=[...portal.stock];
      for(let slot=2;slot<2+stockBonus(state,p).extra;slot++)p.stock.push(spawnStockItem(state,p.id,state.players.indexOf(p),state.encounter,p.portals.indexOf(portal),slot,portal.npc));
      for(const id of p.stock)ensureItemAppearance(state,state.items[id]!);
      redeemNpcContracts(state,p,portal.npc);p.done=true;trace(state,p,'portal-entered',{portalId:portal.id,npc:portal.npc});break;
    }

case 'reroll-portal':
rerollPortal(state,p,action.portalId);
break;

case 'inspect':
npcActionAllowed(state,p);
inspect(state,p,action.itemId,action.property);
break;

case 'appraise':
case 'counter':
{
      npcActionAllowed(state,p);check(!p.caught,'npc-closed','NPC ที่จับได้แล้วไม่รับการประเมินใหม่');
      const caught=appraise(state,p,action.itemId,action.value,action.type==='counter',action.acceptDanger===true); drawBacklashEvent(state,p);if(caught && !p.eventOffer) drawEvent(state,p,true);break;
    }

case 'appraise':
case 'counter':
{
      npcActionAllowed(state,p);check(!p.caught,'npc-closed','NPC ที่จับได้แล้วไม่รับการประเมินใหม่');
      const caught=appraise(state,p,action.itemId,action.value,action.type==='counter',action.acceptDanger===true); drawBacklashEvent(state,p);if(caught && !p.eventOffer) drawEvent(state,p,true);break;
    }

case 'buy':
npcActionAllowed(state,p);
purchase(state,p,p,action.itemIds,{condition:action.condition});
break;

case 'activate':
check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','resolve event ก่อนเปิดใช้');
activate(state,p,action.itemId,action.npc,action.otherNpc);
break;

case 'recover-resource':
{
      npcActionAllowed(state,p);check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');const offer=recoveryOffer(state,p);
      check(offer && offer.target===action.target,'recovery','พ่อค้านี้ไม่มีดีลฟื้นที่เลือกหรือใช้สิทธิ์แล้ว');
      check(offer.target==='life'?p.life!<maxLifeOf(state,p)!:p.energy<maxEnergyOf(state,p),'recovery','ทรัพยากรนี้เต็มแล้ว');
      spend(state,p,offer.credits,0,'recovery-deal');p.recoveryUsed=true;
      const amount=recoveryAmount(state,p,offer);
      if(offer.target==='life'){if(amount)healLife(state,p,amount,'recovery-deal');p.notes.push(`ดีลฟื้นชีวิต: จ่าย ${offer.credits} เครดิต ได้ฟื้น ${amount}`);p.notes=p.notes.slice(-30);}
      else recover(state,p,amount,'recovery-deal');
      break;
    }

case 'steal':
check(!state.config.secureEconomy,'rps-required','เลือกมือเป่ายิ้งฉุบเพื่อขโมย');
npcActionAllowed(state,p);
stealShop(state,p,action.itemId);
drawTheftEvent(state,p);
break;

case 'pickpocket':
check(!state.config.secureEconomy,'rps-required','เลือกมือเป่ายิ้งฉุบเพื่อขโมย');
check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','resolve event ก่อน');
pickpocket(state,p,action.victimId);
drawTheftEvent(state,p);
break;

case 'barter':
npcActionAllowed(state,p);
check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');
check(state.config.core2,'action-type','ห้องนี้ไม่มีการแลกของ');
barter(state,p,action.itemId,action.targetItemId);
drawTheftEvent(state,p);
break;

case 'merchant-ability':
useMerchantAbility(state,p,action);
break;

case 'skill':
check(!state.config.trustAbilities,'skill','ใช้ความสามารถพ่อค้าแบบใหม่');
npcActionAllowed(state,p);
useSkill(state,p,action.itemId);
break;

case 'wish-new':
npcActionAllowed(state,p);
check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');
wishNew(state,p,action.replaceNpc);
break;

case 'wish-sell':
npcActionAllowed(state,p);
wishSell(state,p,action.itemId,action.markup);
break;

case 'cleanse':
npcActionAllowed(state,p);
check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');
cleanseItem(state,p,action.itemId,action.stoneId);
break;

case 'event':
resolveEvent(state,p,action);
break;

case 'unsold':
check(state.config.brokerage && ['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','resolve event ก่อนจัดการของค้าง');
settleUnsold(state,p,action.itemId,action.choice);
break;

case 'bid':
check(state.config.brokerage,'action-type','ห้องนี้ไม่มีการประมูล');
placeBid(state,p,action.lotId,action.credits);
break;

case 'market-sell':
marketSell(state,p,action.itemId,action.orderId,action.resolution);
break;

case 'share':
check(['APPRAISAL','TRADE'].includes(state.phase),'phase','ยังเปิดรายการไม่ได้');
share(state,p,action.itemId,action.allow,action.purchase,action.claims,action.rebate);
break;

case 'force-buy':
check(state.phase==='TRADE','phase','ยังไม่ใช่ช่วงต่อรอง');
forceBuy(state,p,action);
break;

case 'propose':
check(state.phase==='TRADE','phase','ยังไม่ใช่ช่วงต่อรอง');
propose(state,p,action);
break;

case 'respond':
check(state.phase==='TRADE','phase','ยังไม่ใช่ช่วงต่อรอง');
respond(state,p,action.offerId,action.accept);
break;

case 'theft-timeout':
case 'done':
if(action.type==='theft-timeout'){
        check(state.config.secureEconomy,'action-type','ไม่มีการเป่ายิ้งฉุบ');
        for(const duel of state.theftDuels??[])if(duel.status==='open' && [duel.thiefId,duel.victimId].includes(p.id)){duel.status='cancelled';duel.hands={};}
      }
check(!state.config.secureEconomy || !state.theftDuels?.some(d=>d.status==='open' && [d.thiefId,d.victimId].includes(p.id)),'theft-pending','เลือกมือเป่ายิ้งฉุบให้เสร็จก่อน');
finishAbilityChoice(state,p);
defaultEvent(state,p);
p.done=true;
for(const offer of state.trades) if(offer.status==='open' && [offer.buyerId,offer.sellerId].includes(p.id)) offer.status='rejected';
break;

case 'theft-timeout':
case 'done':
if(action.type==='theft-timeout'){
        check(state.config.secureEconomy,'action-type','ไม่มีการเป่ายิ้งฉุบ');
        for(const duel of state.theftDuels??[])if(duel.status==='open' && [duel.thiefId,duel.victimId].includes(p.id)){duel.status='cancelled';duel.hands={};}
      }
check(!state.config.secureEconomy || !state.theftDuels?.some(d=>d.status==='open' && [d.thiefId,d.victimId].includes(p.id)),'theft-pending','เลือกมือเป่ายิ้งฉุบให้เสร็จก่อน');
finishAbilityChoice(state,p);
defaultEvent(state,p);
p.done=true;
for(const offer of state.trades) if(offer.status==='open' && [offer.buyerId,offer.sellerId].includes(p.id)) offer.status='rejected';
break;

case 'seal-offer':
offerSeal(state,p,action);
break;

case 'seal-respond':
respondOffer(state,p,action.offerId,action.accept,action.itemIds);
break;

case 'seal-cancel':
{
      const offer = offers(state).find(o => o.id === action.offerId);
      check(offer && offer.status === 'open' && offer.holderId === p.id,'seal-offer','ไม่มีข้อเสนอที่ยกเลิกได้');
      offer.status = 'cancelled'; break;
    }

case 'seal-redeem':
redeem(state,p,action.thiefId);
break;

case 'seal-pick':
pick(state,p,action.redemptionId,action.slot);
break;

case 'vault-deposit-item':
{
      check(vault.items.length<vault.slots,'vault-full','คลังส่วนตัวเต็ม');
      const item=movable(state,p,action.itemId);
      removeFromHand(state,p,item,`personal-vault:${p.id}`);
      vault.items.push(item.id);break;
    }

case 'vault-withdraw-item':
{
      check(vault.items.includes(action.itemId) && state.items[action.itemId]?.owner===`personal-vault:${p.id}`,'vault-owner','สินค้าไม่ได้อยู่ในคลังของคุณ');
      vault.items=vault.items.filter(id=>id!==action.itemId);
      state.items[action.itemId]!.owner=p.id;p.inventory.push(action.itemId);break;
    }

case 'vault-deposit-credits':
{
      positive(action.amount);check(p.credits>=action.amount,'credits','เครดิตไม่พอ');addable(vault.credits,action.amount);
      p.credits-=action.amount;vault.credits+=action.amount;
      state.ledger.push({from:p.id,to:`vault:${p.id}`,amount:action.amount,reason:'vault-deposit',encounter:state.encounter});break;
    }

case 'vault-withdraw-credits':
{
      positive(action.amount);check(vault.credits>=action.amount,'credits','เครดิตในคลังไม่พอ');addable(p.credits,action.amount);
      vault.credits-=action.amount;p.credits+=action.amount;
      if(state.config.vaultInterestRules===1 && vault.interest)vault.interest.principal=Math.min(vault.interest.principal,vault.credits);
      state.ledger.push({from:`vault:${p.id}`,to:p.id,amount:action.amount,reason:'vault-withdraw',encounter:state.encounter});break;
    }

case 'vault-expand':
{
      const amount=pilotExpansionCost(state,p,quoteVaultExpansion(vault.slots));check(p.credits>=amount,'credits','เครดิตไม่พอเพิ่มช่องคลัง');
      addable(vault.slots,1);spend(state,p,amount,0,'vault-expand');vault.slots++;break;
    }

