case 'E132':
if(choice==='compass')grant(state,p,'B26');else {const selected=item();stockItem(state,p,selected);check(known(state,p,selected).genuine===undefined,'known','รู้ความแท้แล้ว');spend(state,p,0,1,id);learn(p,selected,{genuine:state.items[selected]!.genuine});}
break;

case 'E01':
if(choice==='stay') spend(state,p,0,1,id); else p.portals[0]!.disabled=true;
break;

case 'E03':
check(state.config.systemLinks!==1 || eventChoices(state,p,id).includes(choice),'event-cost','ตัวเลือกนี้ไม่มีต้นทุนเพิ่มแล้ว');
if(choice==='pay') spend(state,p,2,0,id); else grant(state,p,'D10');
recover(state,p,3,id);
if(state.config.survival && choice==='debt')damageLife(state,p,1,'blood-pact',false);
break;

case 'E10':
if(choice==='pay') spend(state,p,2,0,id); else if(choice==='fog') grant(state,p,'D02'); else p.portals[0]!.disabled=true;
break;

case 'E37':
if(choice==='pay') spend(state,p,2,0,id); else if(choice==='drop') {const v=item();ownedItem(state,p,v,true);retire(state,p,v,id);} else grant(state,p,'D06');
break;

case 'E40':
if(!reworked(state)) {if(choice==='repair') {spend(state,p,0,2,id); removeStatus(p,'D02');} else grant(state,p,'D02'); break;}
if(choice==='repair') spend(state,p,0,2,id); else if(choice==='discard') retire(state,p,ownKind('scanner'),id,false); else grant(state,p,'D02');
break;

case 'E42':
if(choice==='energy') recover(state,p,2,id,reworked(state)); else {check(status(p,'D10'),'status','ไม่มี D10'); removeStatus(p,'D10');}
break;

case 'E43':
check(state.bank-state.market.budget-state.reservedRewards>=1,'bank','งบรางวัลไม่พอ');
p.subsidy=true;
state.reservedRewards++;
break;

case 'E47':
{
      const v=item(); check(state.listings.some(l=>l.itemId===v && l.ownerId!==p.id && state.items[v]!.owner.startsWith('npc:')),'listing','รายการข้ามร้านไม่ได้เปิด');
      if(reworked(state)) {
        // Rule 1: one credit buys one fact the other appraiser verified, picked by the seed.
        const facts=ledgerFacts(state,p,v); check(facts.length>0,'ledger','ผู้ประเมินคนนั้นไม่มีข้อมูลใหม่ให้คุณแล้ว');
        const fact=facts[Math.floor(randomAt(state.seed,`${offer.key}:ledger`)*facts.length)]!;
        spend(state,p,1,0,id); learn(p,v,{[fact]:state.items[v]![fact]});
        p.notes.push(`อ่านสมุดข้ามร้าน: ได้${fact==='base'?'มูลค่าจริง':fact==='genuine'?'ความแท้':'คำสาป'}ของ ${ITEM_SPECS[state.items[v]!.kind].name}`); p.notes=p.notes.slice(-30);
      }
      trace(state,p,'cross-shop-viewed',{itemId:v}); break;
    }

case 'E94':
case 'E95':
case 'E96':
case 'E97':
case 'E98':
case 'E99':
case 'E100':
case 'E101':
{
      const spec=POLISH_EVENTS[id]!;check(spec.avoid.every(s=>!status(p,s)),'status','ผลติดตัวนี้ทำให้เหตุการณ์ไม่มีความหมายแล้ว');
      spend(state,p,spec.credits??0,spec.energy??0,id); if(spec.reward) reward(state,p,spec.reward,id); for(const s of spec.grant) grant(state,p,s); break;
    }

case 'E48':
if(choice==='pay') spend(state,p,2,0,id); else if(choice==='item') penaltyItem(state,p,item()); else {check(p.credits<2 && !p.inventory.length,'penalty','ต้องเลือกค่าปรับที่ยังจ่ายได้'); p.energy=Math.max(0,p.energy-2);}
break;

case 'E49':
if(choice==='pay') spend(state,p,2,0,id); else grant(state,p,'D08');
break;

case 'E50':
if(choice==='surrender') retire(state,p,item(),id,false); else kill(state,p);
break;

case 'E109':
(p.npcContracts??={}).vampire={signedAt:state.encounter,...(state.config.personalScoringRules===1?{performanceId:offer.key}:{})};
note(p,'สัญญาเลือด: จ่ายชีวิต 2 แล้ว รับผลตอบแทนสุ่มเมื่อเลือกพบ Vampire ครั้งหน้า');
break;

case 'E110':
{
      const count=Number(command.choice.slice(5)),ids=command.itemIds;
      check(Number.isInteger(count) && count>=1 && count<=terms.loanMax! && Array.isArray(ids) && ids.length===count && new Set(ids).size===count && ids.every(id=>offer.itemIds.includes(id)),'event-target','เลือกของให้ยืมให้ครบจำนวนและห้ามซ้ำ');
      for(const id of ids)ownedItem(state,p,id,true);
      check(freeBank(state)>=8*count,'bank','งบผลตอบแทนไม่พอ');
      for(const id of ids){p.inventory=p.inventory.filter(itemId=>itemId!==id);state.items[id]!.owner=`alien-loan:${p.id}`;}
      state.listings=state.listings.filter(l=>!ids.includes(l.itemId));
      state.reservedRewards+=8*count;(p.npcContracts??={}).alien={lentAt:state.encounter,dueAt:state.encounter+2,itemIds:[...ids],key:offer.key,reservedCredits:8*count};
      trace(state,p,'alien-loan',{itemIds:ids,dueAt:state.encounter+2});note(p,`Alien ยืมของ ${count} ชิ้น พบอีกครั้งตั้งแต่ช่วง ${state.encounter+2} เพื่อคืนของพร้อมโบนัสตามจำนวนชิ้น`);break;
    }

case 'E111':
{
      if(command.choice==='purge'){removeStatus(p,command.statusId!);note(p,`Dark One ล้าง ${STATUS_CATALOG.find(s=>s.id===command.statusId)!.name} ให้แล้ว`);}
      else {const pool=statusPool(state,victim!,'D');const id=pick(state,`${offer.key}:hex`,pool.length?pool:['D01'] as StatusId[]);grant(state,victim!,id);note(p,`Dark One ส่ง ${STATUS_CATALOG.find(s=>s.id===id)!.name} ให้ ${victim!.id}`);note(victim!,`${p.id} ส่ง ${STATUS_CATALOG.find(s=>s.id===id)!.name} ผ่าน Dark One`);trace(state,p,'npc-hex',{targetId:victim!.id,statusId:id});}break;
    }

case 'E115':
{
      const ids=p.stock.filter(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}`);
      const clues=ids.flatMap(itemId=>{const k=known(state,p,itemId);return (['base','genuine','cursed'] as const).filter(fact=>k[fact]===undefined).map(fact=>({itemId,fact}));});
      check(clues.length,'event-target','ไม่มีข้อมูลใหม่ในร้าน');const clue=pick(state,`${offer.key}:whisper`,clues);learn(p,clue.itemId,{[clue.fact]:state.items[clue.itemId]![clue.fact]});
      randomBuff(state,p,`${offer.key}:depth`,['B12','B14','B16']);note(p,`เสียงจากก้นบึ้งเปิดผลตรวจ ${ITEM_SPECS[state.items[clue.itemId]!.kind].name} หนึ่งด้าน`);break;
    }

if (state.config.systemLinks===1 && state.config.statusLinks===1 && id==='E128') {
      if(c.id==='offer' && (status(p,'B06') || status(p,'B19')))return false;
      if(c.id==='ward' && status(p,'B21'))return false;
    }

if (id==='E126') {
    const drink=(state.config.survival?p.life!==undefined && p.life<(state.config.systemLinks===1?maxLifeOf(state,p)!:state.config.survival.maxLife):p.energy<(state.config.systemLinks===1?maxEnergyOf(state,p):state.config.maxEnergy)) && p.credits>=3;
    // Status links: the calming rite (B23) is open to any seat with the energy for it.
    return drink || state.config.statusLinks===1 && p.energy>=1 && !status(p,'B23');
  }

if (id==='E45') {
    for(const itemId of itemIds) {
      const proof:Knowledge={};
      for(const fact of ['base','genuine','cursed'] as const) if(p.knowledge[itemId]?.[fact]!==undefined && state.publicKnowledge[itemId]?.[fact]===undefined && !p.revealedInfo.includes(`${itemId}:${fact}`)) Object.assign(proof,{[fact]:p.knowledge[itemId]![fact]});
      if(Object.keys(proof).length) facts[itemId]=proof;
    }
    itemIds=Object.keys(facts);
  }

if (id==='E111') {
    const costs:Array<keyof Pick<typeof terms,'credits'|'energy'|'life'|'items'>>=[];
    if(p.credits>=2)costs.push('credits');if(p.energy>=1)costs.push('energy');if(state.config.survival && p.life!>1)costs.push('life');if(itemIds.length)costs.push('items');
    const ranked=costs.map(cost=>({cost,rank:randomAt(state.seed,`${key}:cost:${cost}`)})).sort((a,b)=>a.rank-b.rank);
    const count=1+Math.floor(randomAt(state.seed,`${key}:cost-count`)*Math.min(3,costs.length));
    for(const {cost} of ranked.slice(0,count)) terms[cost]=cost==='credits'?Math.min(p.credits,2+Math.floor(randomAt(state.seed,`${key}:credits`)*4)):cost==='energy'?Math.min(p.energy,2):1;
    choices=[...(p.statuses.some(s=>s.id.startsWith('D'))?['purge']:[]),...(livingOthers(state,p).length?['send-debuff']:[]),'decline'];
  }

if (['E09','E24','E27','E29','E30'].includes(offer.id) && choice==='accept') {
    const discount=offer.id==='E29'?3:offer.id==='E30'?-2:2;
    if(!target || p.credits<buyPrice(v,target)-discount || p.energy<npcEnergy(v)) choice='decline';
  }

