export function bondEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  const spec=bondSpec(id);
  if(!spec || !state.config.brokerage || state.phase!=='APPRAISAL' || currentNpc(state,p)!==spec.npc) return false;
  const held=bondItems(state,p,spec);if(!held.length) return false;
  if(spec.mode==='swap' && !shopStock(state,p).length) return false;
  if(spec.mode==='reveal' && !revealTargets(state,p,spec).length) return false;
  if(spec.mode==='sell' && freeBank(state)<Math.max(...held.map(itemId=>bondQuote(state,p,spec,itemId)))) return false;
  if(spec.energyCost && p.energy<spec.energyCost) return false;
  if(spec.cleanse==='debuffs' && !p.statuses.some(s=>s.id.startsWith('D'))) return false;
  // Event choice rules 1: a showing that would change none of its statuses, or only half of a trade, is not offered.
  if(state.config.eventChoiceRules===1 && spec.mode==='show' && [...(spec.buffs??[]),...(spec.debuffs??[])].some(s=>!!status(p,s))) return false;
  return true;
}

export function core2EventChoices(state:AppraisalState,p:Appraiser,id:EventId):string[] {
  const spec=CORE2_SPECS[id]!;
  const open=core2Choices(id,state.config).filter(c=>{
    if(c.id==='decline')return true;
    if(state.config.systemLinks===1 && state.config.statusLinks===1 && id==='E128'){
      if(c.id==='offer' && (status(p,'B06') || status(p,'B19')))return false;
      if(c.id==='ward' && status(p,'B21'))return false;
    }
    return affordable(state,p,c) && !debtWithoutNext(state,c);
  }).map(c=>c.id);
  if(spec.consequence){return open.length?open:[FALLBACK_BRAND.id];}
  if(spec.phase==='PORTALS' && !open.length)return [FALLBACK_BRAND.id];
  return open;
}

export function core2EventEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  const spec=CORE2_SPECS[id];
  if(!spec || !state.config.core2 || p.paused || p.done || ['REVEAL','RESULTS'].includes(state.phase))return false;
  if(spec.consequence){
    if(p.consequenceSlots>=1)return false;
    if(CORE2_BACKLASH_IDS.includes(id))return !!p.inflated;
    return !!p.theft && (id==='E123'?p.theft.kind==='shop':p.theft.kind==='player' && !!p.theft.victim);
  }
  if(state.phase!==spec.phase)return false;
  if(spec.phase==='PORTALS')return p.portals.filter(v=>!v.disabled).length>1 && core2EventChoices(state,p,id).some(c=>c!==FALLBACK_BRAND.id);
  if(id==='E125')return p.stock.length>0 && !Object.keys(p.valuations).length && !status(p,'B01');
  if(id==='E126'){
    const drink=(state.config.survival?p.life!==undefined && p.life<(state.config.systemLinks===1?maxLifeOf(state,p)!:state.config.survival.maxLife):p.energy<(state.config.systemLinks===1?maxEnergyOf(state,p):state.config.maxEnergy)) && p.credits>=3;
    // Status links: the calming rite (B23) is open to any seat with the energy for it.
    return drink || state.config.statusLinks===1 && p.energy>=1 && !status(p,'B23');
  }
  if(id==='E127')return state.bank-state.market.budget-state.reservedRewards>=5 && !status(p,'D04') && (state.config.eventChoiceRules!==1 || !!state.config.survival || state.encounter<state.config.encounters);
  if(id==='E128')return state.config.systemLinks===1 && state.config.statusLinks===1
    ?core2EventChoices(state,p,id).some(choice=>choice!=='decline')
    :p.inventory.length>0 && !status(p,'B06') && !status(p,'B19');
  // Status links: whisper's price is D24, so it is not offered while that is already on (it would come free).
  if(id==='E129')return p.stock.length>0 && !Object.keys(p.valuations).length && !status(p,'B04') && !status(p,'D03') && (state.config.statusLinks!==1 || !status(p,'D24'));
  return true;
}

export function resolveCore2Event(state:AppraisalState,p:Appraiser,offer:EventOffer,command:Extract<AppraisalAction,{type:'event'}>):void {
  const spec=CORE2_SPECS[offer.id]!;const choice=command.choice;
  const picked:Core2Choice|undefined=choice===FALLBACK_BRAND.id?FALLBACK_BRAND:core2Choices(offer.id,state.config).find(c=>c.id===choice);
  check(picked,'event-choice','ไม่มีตัวเลือกนี้');
  if(choice!=='decline' && choice!==FALLBACK_BRAND.id)check(state.config.systemLinks===1?core2EventChoices(state,p,offer.id).includes(choice):affordable(state,p,picked),'event-cost','จ่ายตัวเลือกนี้ไม่ไหวแล้ว');
  if(picked.lose){
    check(command.itemId && offer.itemIds.includes(command.itemId),'event-target','เลือกสินค้าที่จะสละ');
    penaltyItem(state,p,command.itemId);
  }
  const victim=picked.toVictim && p.theft?.victim?state.players.find(v=>v.id===p.theft!.victim):undefined;
  if(picked.credits){
    if(victim)transfer(state,p,victim,picked.credits,spec.id);else spend(state,p,picked.credits,0,spec.id);
  }
  if(picked.energy)spend(state,p,0,picked.energy,spec.id);
  if(picked.life)damageLife(state,p,picked.life,spec.id,false);
  if(picked.heal){if(state.config.survival)healLife(state,p,picked.heal,spec.id);else recover(state,p,3,spec.id);}
  if(picked.reward)reward(state,p,picked.reward,spec.id);
  for(const s of picked.grant??[])grant(state,p,s);
  if(picked.gamble){
    const won=randomAt(state.seed,`${offer.key}:gamble`)<picked.gamble.chance;
    for(const s of won?picked.gamble.win:picked.gamble.lose)grant(state,p,s);
    p.notes.push(won?`${spec.name}: ได้ผลดี`:`${spec.name}: ผลข้างเคียงร้าย`);
    trace(state,p,'core2-gamble',{id:spec.id,won});
  }
  if(picked.door)p.portals.forEach((portal,index)=>{if(index===(picked.door==='first'?1:0))portal.disabled=true;});
  if(picked.deal)p.dealMode=picked.deal;
  if(spec.consequence){delete p.inflated;delete p.theft;}
  p.notes.push(`${spec.name}: ${choice}`);p.notes=p.notes.slice(-30);
  trace(state,p,'core2-event',{id:spec.id,choice});
}

function spawnStockItem(state:AppraisalState,id:string,seat:number,encounter:number,index:number|string,slot:number,npc:NpcId):string {
  const {seed,config}=state;let favorites=merchantKinds(npc,config.catalogVersion??1,!!config.cleanse,!!config.challenge,expansionActive(config),!!config.polish,!!config.trustAbilities);
  if(config.trustAbilities){const offered=new Set(Object.values(state.items).filter(i=>i.npcOwnerId===id&&i.encounter===encounter&&i.npc===npc&&i.owner.startsWith('npc:')).map(i=>i.kind));const fresh=favorites.filter(kind=>!offered.has(kind));if(fresh.length)favorites=fresh;}
  const itemId=`item-${encounter}-${seat}-${index}-${slot}`;
  const kind=favorites[Math.floor(randomAt(seed,`${itemId}:kind`)*favorites.length)]!;
  const anchor=anchorOf(config,kind);const range=priceRange(kind,anchor); const base=range[0]+Math.floor(randomAt(seed,`${itemId}:base`)*(range[1]-range[0]+1));
  const reservation=NPC_SPECS[npc].reservation;
  const ask=Math.max(1,anchor-2+Math.floor(randomAt(seed,`${itemId}:ask`)*6));
  const minimum=Math.ceil(base*(reservation[0]+(reservation[1]-reservation[0])*randomAt(seed,`${itemId}:reservation`)));
  state.items[itemId]={
    id:itemId,kind,base,ask,genuine:randomAt(seed,`${itemId}:genuine`)<.75,
    cursed:randomAt(seed,`${itemId}:curse`)<.35,owner:`npc:${id}:${encounter}`,
    npcOwnerId:id,npc,encounter,certificate:randomAt(seed,`${itemId}:certificate`)<.65,
    lastAppraisal:null,lastAccepted:null,reservation:Math.min(ask,Math.max(1,minimum)),
    ...(slot>=2?{bonus:true}:{}),
  };
  return itemId;
}

function generatePortals(state:AppraisalState,id:string,seat:number,encounter:number):Portal[] {
      const {seed,config}=state;const npcIds=activeNpcs(config);
      const npcs=npcIds.map(npc=>({npc,rank:randomAt(seed,`${encounter}:${seat}:${npc}:portal`)})).sort((a,b)=>a.rank-b.rank).slice(0,3);
      const portals=npcs.map(({npc},index)=>{
        const stock:string[]=[];
        for(let slot=0;slot<2;slot++) stock.push(spawnStockItem(state,id,seat,encounter,index,slot,npc));
        return {id:`portal-${encounter}-${seat}-${index}`,npc,stock,disabled:false};
      });return portals;
}

function makeMarket(state:AppraisalState):DarkMarket {
  const market:DarkMarket={encounter:state.encounter,open:false,budget:0,orders:[]};
  // Vault auctions roll independently of the sell-order market.
  if(state.config.brokerage) market.lots=auctionLots(state);
  if(!(state.config.core2 && omenNow(state)?.marketOpen) && randomAt(state.seed,`${state.encounter}:market:open`)>=state.config.marketProbability) return market;
  const pool=[...new Set(publicOfferItems(state).map(item=>item.kind))];
  const count=1+Math.floor(randomAt(state.seed,`${state.encounter}:market:count`)*Math.min(pool.length,state.config.marketMaxOrders));
  const ranked=pool.map(kind=>({kind,rank:randomAt(state.seed,`${state.encounter}:market:${kind}:rank`)})).sort((a,b)=>a.rank-b.rank);
  const orderFor=(kind:ItemKind)=>{
    const price=Math.round(anchorOf(state.config,kind)*(1.25+.5*randomAt(state.seed,`${state.encounter}:market:${kind}:price`)));
    const order={id:`quote-${state.encounter}-${kind}`,kind,price,...(state.config.rarityEconomy?{rarityReserveMultiplier:Math.max(...Object.values(state.config.rarityEconomy.tiers).map(t=>t.value))}:{}),quota:Object.fromEntries(state.players.map(p=>[p.id,state.config.marketQuota])),...(state.config.commerce?{contract:makeMarketContract(key=>randomAt(state.seed,`${state.encounter}:market:${kind}:contract:${key}`),!!state.config.survival)}:{})};
    return {order,reserved:marketOrderReserve(order)*state.config.marketQuota*state.players.length};
  };
  const free=state.bank-state.reservedRewards;
  // The market opens every encounter, so it may only hold half of the free bank: the rest stays for event and sale rewards promised meanwhile.
  const cap=Math.floor(free*MARKET_BANK_SHARE);
  for(const {kind} of ranked.slice(0,count)) {const {order,reserved}=orderFor(kind);if(market.budget+reserved>cap)continue;market.orders.push(order);market.budget+=reserved;}
  // Every drawn quote too dear for the cap: open with the cheapest quote the bank can still back, so the market never skips an encounter while the bank has money.
  if(!market.orders.length){const cheapest=ranked.map(({kind})=>orderFor(kind)).sort((a,b)=>a.reserved-b.reserved)[0];if(cheapest && cheapest.reserved<=free){market.orders.push(cheapest.order);market.budget+=cheapest.reserved;}}
  market.open=market.orders.length>0; return market;
}

function settleEncounter(state:AppraisalState):void {
  if(state.config.brokerage) {for(const p of state.players) settleRemainingUnsold(state,p);settleAuction(state);}
  for(const p of state.players) {
    if(state.config.survival && p.life===0){
      if(p.subsidy){p.subsidy=false;state.reservedRewards--;}
      state.history.push({encounter:state.encounter,playerId:p.id,gain:0,accuracy:0,score:0,paused:'dead'});continue;
    }
    if(status(p,'D05')) {p.energy=Math.max(0,p.energy-integerEffect(statusMagnitude(p,'D05',2)));consumeStatus(p,'D05');trace(state,p,'breath-drain');}
    if(status(p,'D11')) {p.energy=Math.max(0,p.energy-integerEffect(statusMagnitude(p,'D11',1)));consumeStatus(p,'D11');trace(state,p,'swarm-venom');}
    if(omenNow(state)?.settleEnergy) {p.energy=Math.max(0,p.energy-omenNow(state)!.settleEnergy!);trace(state,p,'omen-plague');}
    if(state.config.core2) applyCore2Settlement(state,p);
    pauseIfNeeded(state,p);
    const gain=Math.max(0,wealth(state,p)-p.startWealth);
    const score=state.config.survival?0:p.paused==='dead'?0:gain+p.accuracyBonus;
    p.score+=score; state.history.push({encounter:state.encounter,playerId:p.id,gain,accuracy:p.accuracyBonus,score,paused:p.paused});
    if(p.subsidy) {p.subsidy=false;state.reservedRewards--;}
    if(state.config.survival && p.life!>0 && state.config.core2) applyDread(state,p);
    if(state.config.survival && p.life!>0){damageLife(state,p,state.config.core2?decayFor(state.encounter):state.config.survival.encounterLifeCost,'dimensional-decay');if(p.life!>0)mendWithShards(state,p);}
    if(state.config.survival&&p.life!>0)recordPersonalActivity(state,p,'survived',1,String(state.encounter));
  }
  state.market.open=false; state.market.budget=0;
  for(const offer of state.trades) if(offer.status==='open') offer.status='rejected';
  if(state.config.survival && (state.players.every(p=>p.life===0) || collectorDue(state)))collectRun(state);
  else {state.phase='REVEAL';openRoundRewards(state);}
  if(state.config.secureEconomy)cancelTheftDuels(state);
}

function progress(state:AppraisalState):void {
  let moves=0;
  while(moves++<4 && state.players.every(p=>p.done || !!p.paused)) {
    if(state.phase==='PORTALS') {
      state.phase='APPRAISAL';
      for(const p of state.players) { p.done=!!p.paused || !p.stock.length; if(!p.done && !drawPersonalNpcEvent(state,p) && !drawBondEvent(state,p) && !drawWishEvent(state,p) && !drawExpansionEvent(state,p) && !drawPolishEvent(state,p)) drawEvent(state,p); }
    } else if(state.phase==='APPRAISAL') {
      state.phase='TRADE';
      for(const p of state.players) {p.done=!!p.paused; if(!p.done && !drawExpansionEvent(state,p) && !drawPolishEvent(state,p)) drawEvent(state,p);}
    } else if(state.phase==='TRADE') { settleEncounter(state); break; }
    else break;
  }
}

export function advanceAppraisalEncounter(previous:AppraisalState):AppraisalState {
  check(previous.phase==='REVEAL','phase','ต้องเปิดผลก่อน');
  const state=structuredClone(previous);state.commands.push({type:'advance'});state.revision++;
  for(const p of state.players)if(p.roundReward && !p.roundReward.settled)bankRoundReward(state,p);
  if(state.config.secureEconomy)settleLoansBeforeAdvance(state);
  if(!state.config.survival && state.encounter===state.config.encounters) {if(state.config.secureEconomy && state.config.loanEndSettlement)settleLoansBeforeAdvance(state,true);closeNpcContracts(state);state.phase='RESULTS';enforceCaps(state);reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,{type:'advance'});assertAppraisalInvariants(state);return state;}
  state.encounter++;state.phase='PORTALS';state.listings=[];state.market={encounter:state.encounter,open:false,budget:0,orders:[]};
  if(state.config.secureEconomy){cancelTheftDuels(state);collectCompensations(state);payVaultInterest(state);closeSealOffers(state);}
  for(const p of state.players) {
    delete p.roundReward;
    delete p.merchantActionsUsed;
    if(state.config.trustAbilities){p.skillUsed=false;delete p.abilityItemUsed;delete p.orcDeal;delete p.preserveItemId;}
    delete p.itemUseBonuses;
    delete p.itemUseStrength;
    delete p.itemUseKinds;
    delete p.vampireDiscount;resetCore2Encounter(p);
    if(state.config.survival && p.life===0)continue;
    if(passivesEnabled(state.config))p.passiveUses={};
    if(state.config.survival){state.schedule[p.id]!.push(generatePortals(state,p.id,state.players.indexOf(p),state.encounter));p.recoveryUsed=false;}
    const rested=!!p.paused; p.paused=null;p.done=false;p.portals=structuredClone(state.schedule[p.id]![state.encounter-1]!);p.selectedPortalId=null;p.stock=[];p.valuations={};p.inspections=0;p.counters=0;p.activated=[];p.accuracyBonus=0;p.eventOffer=null;p.offerSlots=0;p.consequenceSlots=0;p.honorJob=false;p.honestyReward=null;p.acceptedDanger=false;p.caught=false;p.dealMode='any';if(p.cleansed)p.cleansed=[];if(p.wishes)p.wishTried=false;
    p.statuses=p.statuses.filter(s=>s.expires>=state.encounter && s.charges>0);p.startWealth=wealth(state,p);
    if(state.config.survival)spend(state,p,0,Math.min(p.energy,state.config.survival.entryEnergyCost),'encounter-entry');
    else if(rested) recover(state,p,Math.max(0,state.config.recoveryEnergy-p.energy),'encounter-recovery',true);else recover(state,p,2,'encounter-rest',true);
    if(status(p,'D04')?.starts===state.encounter) {spend(state,p,Math.min(integerEffect(statusMagnitude(p,'D04',2)),p.credits),0,'D04');consumeStatus(p,'D04');}
    if(status(p,'B09')?.starts===state.encounter) {const amount=integerEffect(statusMagnitude(p,'B09',2));consumeStatus(p,'B09');recover(state,p,amount,'B09');}
    if(status(p,'D07')?.starts===state.encounter) {p.portals.at(-1)!.disabled=true;consumeStatus(p,'D07');}
  }
  state.market=makeMarket(state);
  for(const p of state.players) if(randomAt(state.seed,`${state.encounter}:${p.id}:entry-event`)<.55) drawEvent(state,p);
  enforceCaps(state);reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,{type:'advance'});assertAppraisalInvariants(state);return state;
}

function polishEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  const spec=POLISH_EVENTS[id];
  if(!state.config.polish || !spec || state.phase!==spec.phase) return false;
  return p.credits>=(spec.credits??0) && p.energy>=(spec.energy??0) && freeBankOf(state)>=(spec.reward??0)
    && !spec.avoid.some(s=>!!status(p,s)) && (!spec.needsAuctions || !!state.config.brokerage);
}

function expansionEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  if(!expansionActive(state.config)) return false;
  const npc=p.selectedPortalId?p.portals.find(portal=>portal.id===p.selectedPortalId)?.npc:undefined;
  const bank=freeBankOf(state);const survival=!!state.config.survival;
  // Selling trade news needs something to trade, and is pointless while the smell of the hive still clings.
  if(id==='E92') return state.phase==='TRADE' && bank>=2 && !status(p,'D13') && (!state.config.polish || p.inventory.length>0);
  if(state.phase!=='APPRAISAL') return false;
  switch(id) {
    case 'E84': return npc==='deepsea' && p.energy>=1;
    case 'E85': return npc==='swarm' && p.credits>=1;
    case 'E86': return bank>=3 && !status(p,'D15');
    case 'E87': return p.energy>=2 && bank>=6;
    case 'E88': return p.credits>=1 && p.statuses.some(s=>NEW_DEBUFFS.includes(s.id) && s.charges>0);
    case 'E89': return !status(p,'B11') && !status(p,'D14');
    case 'E90': return npc==='swarm' && (!reworked(state) || !status(p,'B13') && !status(p,'D11'));
    case 'E91': return npc==='deepsea' && (survival?p.life!>1:p.energy>=2);
    case 'E93': return p.energy>=1 && bank>=1;
    default: return false;
  }
}

export function eventEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  if (p.paused || p.done || ['RESULTS','REVEAL'].includes(state.phase)) return false;
  if((ABILITY_EVENT_IDS as readonly string[]).includes(id)){
    if(!state.config.trustAbilities || p.abilityChoice)return false;
    const trusted=Object.values(p.npcTrust??{}).some(v=>v>=1);
    if(id==='E130')return p.credits>=3 && (Object.keys(MERCHANT_ABILITIES) as NpcId[]).some(n=>(p.npcTrust?.[n]??0)>=1&&reducibleCooldown(p,n,state.encounter)>0);
    if(id==='E131')return trusted && !status(p,'B25') && !status(p,'D25') && freeBankOf(state)>=5;
    return state.phase==='APPRAISAL' && trusted && !status(p,'B26') && p.stock.some(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}`);
  }
  if(core2Spec(id))return core2EventEligible(state,p,id);
  if(state.config.core2 && ['E01','E08','E10'].includes(id))return false;
  // Rule 1: declining E08 keeps both doors and every way to pay, so neither offer could ever be worth taking.
  if(id==='E08' && reworked(state))return false;
  if(isNpcEvent(id))return npcEventEligible(state,p,id);
  if (bondSpec(id)) return bondEligible(state,p,id);
  if (id==='E73') return wishEligible(state,p);
  if ((EXPANSION_EVENT_IDS as readonly string[]).includes(id)) return expansionEligible(state,p,id);
  if ((POLISH_EVENT_IDS as readonly string[]).includes(id)) return polishEligible(state,p,id);
  if (id===BOON_EVENT_ID) return !!state.config.polish && state.phase==='APPRAISAL' && boonPool(state,p).length>=3;
  const npc=p.stock[0] ? state.items[p.stock[0]]!.npc : null;
  const stock=p.stock.filter(itemId => state.items[itemId]?.owner===`npc:${p.id}:${state.encounter}`);
  const unknownPrice=stock.some(itemId=>known(state,p,itemId).base===undefined);
  const inspectable=p.inspections<inspectionLimit(state,p);
  const next=!!state.config.survival || state.encounter<state.config.encounters;
  if (consequences.includes(id)) {
    if (!p.caught || p.consequenceSlots>=1) return false;
    return id==='E48' || (id==='E49' && next) || (id==='E50' && npc==='darkone' && p.acceptedDanger);
  }
  if (['E01','E08','E10'].includes(id)) return state.phase==='PORTALS' && p.portals.filter(v=>!v.disabled).length>1 && (id!=='E08' || next || NPC_SPECS[p.portals[1]!.npc].condition!=='D04') && (id!=='E10' || unknownPrice || p.stock.length===0);
  if (state.phase==='PORTALS') return false;
  if (Number(id.slice(1))<=30 && state.phase!=='APPRAISAL') return false;
  const bank=state.bank-state.market.budget-state.reservedRewards;
  switch(id) {
    case 'E02': return npc==='orc' && stock.length>0 && !Object.keys(p.valuations).length;
    case 'E03': return npc==='vampire' && p.energy<maxEnergyOf(state,p) && (state.config.systemLinks!==1 || eventChoices(state,p,id).some(choice=>choice!=='decline'));
    case 'E04': return npc==='autometa' && unknownPrice;
    case 'E05': return npc==='alien' && inspectable && stock.some(v=>effectsUnknown(state,p,v));
    case 'E06': return npc==='darkone' && next && debuffs(p).some(v=>v!=='D04' || next);
    case 'E07': return npc==='beast' && inspectable && kindOwned(state,p,'food').some(v=>unlocked(p,v));
    case 'E09': return stock.length>0 && p.counters<counterLimit(p);
    case 'E11': return inspectable && stock.some(v=>known(state,p,v).genuine===undefined);
    case 'E12': return inspectable && stock.some(v=>state.items[v]!.certificate && known(state,p,v).certificate===undefined);
    case 'E13': return inspectable && stock.length>=2 && stock.filter(v=>known(state,p,v).base===undefined).length>=2;
    case 'E14': return historyPrice(state,p)!==undefined;
    case 'E15': return inspectable && stock.length>0 && unknownPrice;
    case 'E16': return inspectable && stock.some(v=>effectsUnknown(state,p,v));
    case 'E17': return inspectable && unknownPrice;
    case 'E18': return stock.length>0 && !Object.keys(p.valuations).length;
    case 'E19': return bank>=1 && stock.some(v=>known(state,p,v).genuine===false && state.publicKnowledge[v]?.genuine===undefined);
    case 'E20': return inspectable && stock.some(v=>!known(state,p,v).activationKnown);
    case 'E21': return stock.length>=2;
    case 'E22': return !status(p,'B07') && ['orc','darkone','beast'].includes(npc??'');
    case 'E23': return p.energy>=1 && stock.length>0;
    case 'E24': return npc==='vampire' && stock.length>0;
    case 'E25': return stock.length>0 && movable(p).some(v=>!state.items[v]!.copy && NPC_SPECS[npc!].favorite.includes(state.items[v]!.kind));
    case 'E26': return next;
    case 'E27': return next && stock.length>0;
    case 'E28': return npc==='darkone' && !status(p,'B08');
    case 'E29': return stock.length>0 && !status(p,'D09');
    case 'E30': return stock.length>0 && !status(p,'B06');
    case 'E31': return kindOwned(state,p,'mirror').length>0;
    case 'E32': return kindOwned(state,p,'orb').length>0 && p.energy<maxEnergyOf(state,p);
    case 'E33': return kindOwned(state,p,'key').length>0 && !!status(p,'D07');
    case 'E34': return kindOwned(state,p,'mask').length>0 && p.statuses.some(s=>s.id.startsWith('B') && s.id!=='B10');
    case 'E35': return kindOwned(state,p,'potion').length>0 && (!!status(p,'D01') || !!status(p,'D05'));
    case 'E36': return kindOwned(state,p,'battery').length>0 && inspectable;
    case 'E37': return state.phase==='APPRAISAL' && p.inventory.length>=3 && stock.length>0;
    case 'E38': return kindOwned(state,p,'amulet').length>0;
    case 'E39': return state.phase==='APPRAISAL' && kindOwned(state,p,'blade').length>0 && stock.some(v=>!p.valuations[v]);
    case 'E40': return kindOwned(state,p,'scanner').length>0 && (!reworked(state) || !status(p,'D02'));
    case 'E41': return debuffs(p).length>0;
    case 'E42': return p.energy<maxEnergyOf(state,p) || !!status(p,'D10');
    case 'E43': return state.phase==='TRADE' && !p.subsidy && bank>=1;
    case 'E44': return (!state.config.secureEconomy || !merchantTradeBanned(state,p)) && movable(p).length>=2 && bank>=Math.max(...movable(p).map(v=>systemSaleQuote(state,state.items[v]!,salePreview(state,p,rarityValue(state.items[v]!,Math.floor(anchorOf(state.config,state.items[v]!.kind)*.75))))));
    case 'E45': return Object.entries(p.knowledge).some(([item,k])=>['base','genuine','cursed'].some(f=>k[f as keyof Knowledge]!==undefined && state.publicKnowledge[item]?.[f as keyof Knowledge]===undefined && !p.revealedInfo.includes(`${item}:${f}`)));
    case 'E46': return p.energy>=1 && stock.some(v=>known(state,p,v).genuine===undefined) && bank>=2;
    case 'E47': if(reworked(state))return p.credits>=1 && state.listings.some(l=>ledgerFacts(state,p,l.itemId).length>0);
      return state.listings.some(l=>l.ownerId!==p.id && state.items[l.itemId]?.owner.startsWith('npc:') && !!state.players.find(other=>other.id===l.ownerId)?.valuations[l.itemId]);
    default: return false;
  }
}

export function eventChoices(state:AppraisalState,p:Appraiser,id:EventId):string[] {
  if(core2Spec(id))return core2EventChoices(state,p,id);
  if(reworked(state)) {
    if(isBondGift(id))return ['accept'];
    switch(id) {
      case 'E01': return [...(p.energy>=1?['stay']:[]),'switch'];
      case 'E10': return [...(p.credits>=2?['pay']:[]),'fog','switch'];
      case 'E37': return [...(p.credits>=2?['pay']:[]),'burden',...(movable(p).length?['drop']:[])];
      case 'E40': return [...(p.energy>=2?['repair']:[]),'discard','endure'];
      case 'E42': return [...(p.energy<maxEnergyOf(state,p)?['energy']:[]),...(status(p,'D10')?['cleanse']:[])];
      case 'E43': return ['accept'];
      case 'E108': return ['pick'];
      case 'E131': return ['haste','credits'];
      case 'E132': return ['compass',...(p.energy>=1 && p.stock.some(id=>known(state,p,id).genuine===undefined)?['survey']:[])];
    }
  }
  switch(id) {
    case 'E130': return ['wind','decline'];
    case 'E131': return ['haste','credits','decline'];
    case 'E132': return ['compass',...(p.energy>=1 && p.stock.some(id=>known(state,p,id).genuine===undefined)?['survey']:[]),'decline'];
    case 'E01': return ['stay','switch','decline'];
    case 'E03': return state.config.systemLinks===1
      ?[...(p.credits>=2?['pay']:[]),...(state.config.survival || !status(p,'D10')?['debt']:[]),'decline']
      :['pay','debt','decline'];
    case 'E06': return [...(debuffs(p).some(v=>v!=='D04')?['interest']:[]),...(debuffs(p).some(v=>v!=='D07')?['seal']:[]),'decline'];
    case 'E08': return ['cash','condition','decline'];
    case 'E10': return ['pay','fog','switch','decline'];
    case 'E11': return ['careful','force','decline'];
    case 'E15': return ['price','curse','decline'];
    case 'E18': return ['discount','risk','decline'];
    case 'E37': return ['pay','burden','decline'];
    case 'E40': return ['repair','fog','decline'];
    case 'E42': return [...(p.energy<maxEnergyOf(state,p)?['energy']:[]),...(status(p,'D10')?['cleanse']:[]),'decline'];
    case 'E48': return [...(p.credits>=2?['pay']:[]),...(p.inventory.length?['item']:[]),...(p.credits<2 && !p.inventory.length?['energy']:[])];
    case 'E49': return [...(p.credits>=2?['pay']:[]),'oath'];
    case 'E108': return ['pick','decline'];
    case 'E73': {const npc=shopNpcOf(p);const open=Object.keys(p.wishes??{});return state.config.wishContract && npc && !p.wishes?.[npc] && open.length>=wishSlotsOf(state,p,2)?[...open.map(n=>`replace:${n}`),'decline']:['accept','decline'];}
    case 'E50': return [...(p.inventory.length?['surrender']:[]),'die'];
    default: return ['accept','decline'];
  }
}

export function offerEvent(state:AppraisalState,p:Appraiser,id:EventId):void {
  check(!p.eventOffer && eventEligible(state,p,id),'event-ineligible','event ไม่เข้าเงื่อนไข');
  const reaction=isConsequence(id);
  const key=`${state.encounter}:${p.id}:${id}:${p.offerSlots}:${p.consequenceSlots}`;
  const ownKinds:Partial<Record<EventId,ItemKind>>={E07:'food',E31:'mirror',E32:'orb',E33:'key',E34:'mask',E35:'potion',E36:'battery',E38:'amulet',E39:'blade'};
  let itemIds=ownKinds[id]?kindOwned(state,p,ownKinds[id]!):p.stock;
  if(id==='E132')itemIds=p.stock.filter(id=>known(state,p,id).genuine===undefined);
  if(id==='E25') itemIds=movable(p).filter(v=>!state.items[v]!.copy && NPC_SPECS[state.items[p.stock[0]!]!.npc].favorite.includes(state.items[v]!.kind));
  if(['E44','E48','E50'].includes(id)) itemIds=id==='E44'?movable(p):p.inventory;
  if(core2Spec(id)) itemIds=core2EventItems(id,p);
  if(id==='E45') itemIds=Object.keys(p.knowledge);
  if(id==='E47') itemIds=state.listings.filter(l=>l.ownerId!==p.id && state.items[l.itemId]!.owner.startsWith('npc:')).map(l=>l.itemId);
  if(id==='E11') itemIds=itemIds.filter(v=>known(state,p,v).genuine===undefined);
  if(id==='E12') itemIds=itemIds.filter(v=>state.items[v]!.certificate && known(state,p,v).certificate===undefined);
  if(id==='E19') itemIds=itemIds.filter(v=>known(state,p,v).genuine===false && state.publicKnowledge[v]?.genuine===undefined);
  if(id==='E07') itemIds=itemIds.filter(v=>unlocked(p,v));
  if(reworked(state)) {
    if(id==='E37') itemIds=movable(p);
    if(id==='E40') itemIds=kindOwned(state,p,'scanner');
    if(id==='E47') itemIds=itemIds.filter(v=>ledgerFacts(state,p,v).length>0);
  }
  const quotedPrices=Object.fromEntries(p.inventory.map(itemId=>{const item=state.items[itemId]!;const quote=copySaleQuote(item,salePreview(state,p,rarityValue(item,Math.floor(anchorOf(state.config,item.kind)*.75))));return [itemId,id==='E44'?systemSaleQuote(state,item,quote):quote];}));
  const facts:Record<string,Knowledge>={};
  if(id==='E45') {
    for(const itemId of itemIds) {
      const proof:Knowledge={};
      for(const fact of ['base','genuine','cursed'] as const) if(p.knowledge[itemId]?.[fact]!==undefined && state.publicKnowledge[itemId]?.[fact]===undefined && !p.revealedInfo.includes(`${itemId}:${fact}`)) Object.assign(proof,{[fact]:p.knowledge[itemId]![fact]});
      if(Object.keys(proof).length) facts[itemId]=proof;
    }
    itemIds=Object.keys(facts);
  }
  let giveItemId:string|undefined;let quotes=quotedPrices;
  const boons=id===BOON_EVENT_ID?draftBoons(state,p,key):undefined;
  const wish=id==='E73'?wishPick(state,p,shopNpcOf(p)!):undefined;
  if(bondSpec(id)) {const targets=bondTargets(state,p,id);itemIds=targets.itemIds;giveItemId=targets.giveItemId;quotes=bondQuotes(state,p,id);}
  const targetKinds=Object.fromEntries([...itemIds,...(giveItemId?[giveItemId]:[])].map(itemId=>[itemId,state.items[itemId]!.kind]));
  p.eventOffer={id,key,choices:eventChoices(state,p,id),itemIds:[...itemIds],statusIds:p.statuses.map(s=>s.id),otherPlayerIds:state.listings.filter(l=>l.ownerId!==p.id).map(l=>l.ownerId),quotedPrices:quotes,facts,targetKinds,...(giveItemId?{giveItemId}:{}),...(wish?{wish}:{}),...(boons?{boons}:{})};
  if(isNpcEvent(id))Object.assign(p.eventOffer,personalNpcOffer(state,p,id,key));
  // Rule 1: a merchant's gift is not a decision, so it does not use one of the seat's two event slots.
  if(reaction) p.consequenceSlots++; else if(!(reworked(state) && isBondGift(id))) p.offerSlots++;
  p.seenEvents.push(id); trace(state,p,'event-offered',{id,key,choices:p.eventOffer.choices});
}

export function drawEvent(state:AppraisalState,p:Appraiser,reaction=false):void {
  if(p.eventOffer || p.paused || p.done || (!reaction && p.offerSlots>=2) || (reaction && p.consequenceSlots>=1)) return;
  let pool=[...EVENT_IDS,...(state.config.trustAbilities && !reaction?ABILITY_EVENT_IDS:[]),...(state.config.core2 && !reaction?CORE2_DRAW_IDS:[])].filter(id=>consequences.includes(id)===reaction && eventEligible(state,p,id));
  const unseen=pool.filter(id=>!p.seenEvents.includes(id)); if(unseen.length) pool=unseen;
  if(!pool.length) return;
  const index=Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:${p.offerSlots}:${p.consequenceSlots}:event`)*pool.length);
  offerEvent(state,p,pool[index]!);
}

export function drawPolishEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!state.config.polish || p.eventOffer || p.paused || p.done || p.offerSlots>=2) return false;
  const pool=preferUnseen(state,p,[...POLISH_EVENT_IDS,BOON_EVENT_ID].filter(id=>eventEligible(state,p,id)));
  if(!pool.length || randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:polish`)>=(state.phase==='TRADE'?.3:.45)) return false;
  offerEvent(state,p,pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:polish:pick`)*pool.length)]!);return true;
}

export function drawPersonalNpcEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!state.config.npcEvents || p.eventOffer || p.offerSlots>=2)return false;
  const npc=shopNpcOf(p);const id=npc?NPC_PERSONAL_EVENT[npc]:undefined;
  if(!id || !eventEligible(state,p,id) || randomAt(state.seed,`${state.encounter}:${p.id}:personal-npc`)>=.65)return false;
  offerEvent(state,p,id);return true;
}

export function drawExpansionEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!expansionActive(state.config) || p.eventOffer || p.paused || p.done || p.offerSlots>=2) return false;
  const pool=preferUnseen(state,p,EXPANSION_EVENT_IDS.filter(id=>eventEligible(state,p,id)));
  if(!pool.length || randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:expansion`)>=(state.phase==='TRADE' && state.config.polish?.3:.5)) return false;
  offerEvent(state,p,pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:expansion:pick`)*pool.length)]!);return true;
}

export function drawBondEvent(state:AppraisalState,p:Appraiser):boolean {
  const rules=state.config.brokerage;
  if(!rules || p.eventOffer || p.paused || p.done || p.offerSlots>=2) return false;
  const pool=preferUnseen(state,p,BOND_EVENT_IDS.filter(id=>eventEligible(state,p,id)));
  if(!pool.length || randomAt(state.seed,`${state.encounter}:${p.id}:bond`)>=rules.bondProbability) return false;
  offerEvent(state,p,pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:bond:pick`)*pool.length)]!);return true;
}

export function defaultEvent(state:AppraisalState,p:Appraiser):void {
  const offer=p.eventOffer; if(!offer) return;
  if(core2Spec(offer.id)){
    if(state.config.systemLinks===1){
      // Finance and other seats can change resources while an offer is pending.
      // Keep its captured choices/targets; never seize a newly acquired item instead.
      const available=core2EventChoices(state,p,offer.id);
      const itemId=offer.itemIds.find(id=>p.inventory.includes(id) && state.items[id]?.owner===p.id);
      const choice=offer.choices.includes('decline')?'decline':offer.choices.find(c=>available.includes(c) && (!core2NeedsItem(offer.id,c,state.config) || !!itemId))??FALLBACK_BRAND.id;
      if(!offer.choices.includes(choice)){
        // Only the system default may add the existing mandatory-penalty fallback.
        offer.choices.push(choice);trace(state,p,'event-default-fallback',{id:offer.id,choice});
      }
      resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(core2NeedsItem(offer.id,choice,state.config)?{itemId:itemId!}:{})});return;
    }
    const choice=offer.choices.includes('decline')?'decline':offer.choices[0]!;
    resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(core2NeedsItem(offer.id,choice,state.config)?{itemId:p.inventory[0]!}:{})});return;
  }
  if(reworked(state) && !offer.choices.includes('decline') && !isConsequence(offer.id)) {
    // Rule 1: no decline to fall back on, so take the safe option: a gift, the first boon, or the mishap's mildest cost.
    const choice=REWORKED_DEFAULT[offer.id] && offer.choices.includes(REWORKED_DEFAULT[offer.id]!)?REWORKED_DEFAULT[offer.id]!:offer.choices[0]!;
    const needsItem=(offer.id==='E37' && choice==='drop') || (offer.id==='E40' && choice==='discard') || (bondSpec(offer.id)?.mode==='reveal');
    resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(needsItem?{itemId:offer.itemIds[0]!}:{}),...(offer.id==='E108'?{statusId:offer.boons![0]!}:{})});
    return;
  }
  const choice=offer.choices.includes('decline')?'decline':offer.choices.includes('pay')?'pay':offer.choices.includes('oath')?'oath':offer.choices.includes('die')?'die':offer.choices.includes('energy')?'energy':'item';
  resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(choice==='item'?{itemId:p.inventory[0]!}:{})});
}

export function npcEventEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  if(!state.config.npcEvents || state.phase!=='APPRAISAL' || p.paused || p.done || NPC_PERSONAL_EVENT[merchant(p)!]!==id)return false;
  const items=movable(state,p);
  const buffs=statusPool(state,p,'B').length;
  switch(id) {
    case 'E109': return !!state.config.survival && p.life!>2 && !p.npcContracts?.vampire;
    case 'E110': return !p.npcContracts?.alien && items.length>0 && freeBank(state)>=8;
    case 'E111': return (p.credits>=2 || p.energy>=1 || !!state.config.survival && p.life!>1 || items.length>0) && (p.statuses.some(s=>s.id.startsWith('D')) || livingOthers(state,p).length>0);
    case 'E112': return buffs>0 && (p.energy>=2 || items.length>0);
    case 'E113': return buffs>0 && p.energy>=2;
    case 'E114': return buffs>0 && items.length>0;
    case 'E116': return buffs>=2 && items.length>0;
    case 'E115': return buffs>0 && p.credits>=3 && p.stock.some(id=>{const k=known(state,p,id);return k.base===undefined || k.genuine===undefined || k.cursed===undefined;});
    default: return false;
  }
}

export function omenOf(config:Pick<AppraisalConfig,'polish'|'core2'>,seed:string,encounter:number):Omen|undefined {
  if(!config.polish) return undefined;
  if(config.core2) return core2Omen(seed,encounter);
  let index=pick(seed,1);
  for(let e=2;e<=encounter;e++) {
    const next=pick(seed,e);
    index=next===index?(index+1+Math.floor(randomAt(seed,`${e}:omen:shift`)*(OMENS.length-1)))%OMENS.length:next;
  }
  return OMENS[index];
}

core2Weight=(omen:typeof CORE2_OMENS[number],encounter:number)=>{
  if((omen.from??1)>encounter) return 0;
  return omen.kind==='harsh'?1+(encounter-1)*.25:omen.kind==='relief'?Math.max(.35,1-(encounter-1)*.08):1;
}

function core2Omen(seed:string,encounter:number):Omen {
  let previous=-1,chosen=0;
  for(let e=1;e<=encounter;e++) {
    const weights=CORE2_OMENS.map((omen,index)=>index===previous?0:core2Weight(omen,e));
    let roll=randomAt(seed,`${e}:omen2`)*weights.reduce((a,b)=>a+b,0);
    chosen=weights.findIndex(weight=>(roll-=weight)<0);
    if(chosen<0) chosen=weights.findLastIndex(weight=>weight>0);
    previous=chosen;
  }
  return CORE2_OMENS[chosen]!;
}

export function drawWishEvent(state:AppraisalState,p:Appraiser,offer:(id:'E73')=>void):boolean {
  if(!state.config.wishlist || p.eventOffer || p.paused || p.done || p.offerSlots>=2 || !wishEligible(state,p)) return false;
  if(randomAt(state.seed,`${state.encounter}:${p.id}:wish`)>=WISH_PROBABILITY) return false;
  offer('E73');return true;
}

protected override sweep(room: Room, now: number): boolean {
    let changed = false;
    for (const [key, deadline] of this.duelDeadlines(room)) {
      if (now < deadline || !room.game) continue;
      const duel = room.game.theftDuels?.find(d => d.status === 'open' && `${d.id}:${d.round}` === key);
      if (!duel) continue;
      const previous = room.game;
      try { room.game = applyAppraisalAction(previous, { type: 'theft-expire', duelId: duel.id, playerId: duel.thiefId, requestId: `duel_${room.matchId}_${duel.id}_${duel.round}`, encounter: previous.encounter }); }
      catch (error) { console.error(error); continue; /* the phase timer or the next action settles it */ }
      this.phaseChanged(room, previous); changed = true;
    }
    if (changed) this.duelDeadlines(room);
    return changed;
  }

protected timeout(room: Room, now: number): void {
    insist(room.game, 'phase', 'run ยังไม่เริ่ม');
    const phase = room.game.phase, number = room.game.encounter;
    if (phase === 'REVEAL') { room.timeouts.push({ at: now, number, phase, playerId: null }); this.advance(room); return; }
    // Snapshot only the pending seats in the expired phase; the last action may advance it.
    const pending = room.game.players.filter(p => !p.paused && !p.done).map(p => p.id);
    for (const playerId of pending) {
      if (room.game.phase !== phase || room.game.encounter !== number) break;
      const previous = room.game;
      const action = defaultAppraisalAction(previous, playerId, `timeout_${room.matchId}_${number}_${phase}_${playerId}`);
      if (!action) continue;
      room.game = applyAppraisalAction(previous, action); room.timeouts.push({ at: now, number, phase, playerId }); this.phaseChanged(room, previous);
    }
  }

