export function reducibleCooldown(p:Pick<Appraiser,'abilityReady'|'abilityLastUsed'|'abilityAdjusted'>,npc:NpcId,encounter:number):number {
  const ready=p.abilityReady?.[npc]??0;
  return Math.max(0,Math.min(ready-Math.max(encounter,(p.abilityLastUsed?.[npc]??0)+1),Math.floor(MERCHANT_ABILITIES[npc].cooldown/2)-(p.abilityAdjusted?.[npc]??0)));
}

export function reduceAbilityCooldown(p:Appraiser,npc:NpcId,encounter:number,amount:number):number {
  const reduced=Math.round(Math.min(amount,reducibleCooldown(p,npc,encounter))*100)/100;
  if(reduced>0){p.abilityReady??={};p.abilityReady[npc]=Math.round((p.abilityReady[npc]!-reduced)*100)/100;p.abilityAdjusted??={};p.abilityAdjusted[npc]=(p.abilityAdjusted[npc]??0)+reduced;}
  return reduced;
}

export function scoresFromAppraisalHistory(history:EncounterResult[]):Record<string,number> {
  const scores:Record<string,number>={};
  for(const row of history) {
    check(row.score===(row.paused==='dead'?0:row.gain+row.accuracy),'score','คะแนน encounter ไม่ตรง breakdown');
    scores[row.playerId]=(scores[row.playerId]??0)+row.score;
  }
  return scores;
}

export function exportAppraisalAudit(state:AppraisalState):AppraisalAudit {
  check(state.phase==='RESULTS','audit-private','ดาวน์โหลด seed/audit ได้หลังจบ run เท่านั้น');
  return structuredClone({...(state.personalPerformance?{personalPerformance:state.personalPerformance}:{}),schemaVersion:state.version,playerIds:state.players.map(p=>p.id),seed:state.seed,config:state.config,commands:state.commands,ledger:state.ledger,history:state.history,trace:state.trace,items:state.items,final:state.players.map(p=>({id:p.id,credits:p.credits,energy:p.energy,inventory:p.inventory,score:p.score,...(p.life!==undefined?{life:p.life}:{})})),...(state.collector?{collector:state.collector}:{})});
}

export function replayAppraisalAudit(audit:AppraisalAudit):AppraisalState {
  check((audit?.schemaVersion===4 || audit?.schemaVersion===5) && Array.isArray(audit.commands) && (audit.schemaVersion===5)===!!audit.config.survival,'audit','เวอร์ชัน appraisal audit ไม่ตรงกติกา');
  let state=restoreAppraisalRun(audit.playerIds,audit.seed,audit.config);
  for(const command of audit.commands) state=command.type==='advance'?advanceAppraisalEncounter(state):applyAppraisalAction(state,command);
  check(state.phase==='RESULTS' && isDeepStrictEqual(exportAppraisalAudit(state),audit),'audit','ผล audit ไม่ตรง replay');
  assertAppraisalInvariants(state);if(state.config.survival)return state;
  const scores=scoresFromAppraisalHistory(state.history);
  check(state.players.every(p=>scores[p.id]===p.score),'score','คะแนน run ไม่ตรงประวัติ');return state;
}

function shopStock(state:AppraisalState,p:Appraiser):string[] {
  return p.stock.filter(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}`);
}

function bondPrice(state:AppraisalState,spec:BondSpec,itemId:string):number {
  return copySaleQuote(state.items[itemId]!,rarityValue(state.items[itemId]!,Math.floor(anchorOf(state.config,state.items[itemId]!.kind)*(spec.price??1))));
}

export function bondItems(state:AppraisalState,p:Appraiser,spec:BondSpec):string[] {
  const gives=['swap','sell','tribute'].includes(spec.mode);
  return p.inventory.filter(id=>{
    const item=state.items[id]!;const k=known(state,p,id);
    if(spec.mode==='swap' && item.copy)return false;
    if(spec.kinds && !spec.kinds.includes(item.kind)) return false;
    if(spec.families && !spec.families.includes(itemFamily(item.kind))) return false;
    if(spec.exclude?.includes(item.kind)) return false;
    if(spec.known==='cursed' && k.cursed!==true) return false;
    if(spec.known==='fake' && k.genuine!==false) return false;
    return !gives || (unlocked(p,id) && !p.activated.includes(id));
  });
}

function revealTargets(state:AppraisalState,p:Appraiser,spec:BondSpec):string[] {
  return shopStock(state,p).filter(id=>spec.reveal!.some(fact=>known(state,p,id)[fact]===undefined));
}

export function bondEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  const spec=bondSpec(id);
  if(!spec || !state.config.brokerage || state.phase!=='APPRAISAL' || currentNpc(state,p)!==spec.npc) return false;
  const held=bondItems(state,p,spec);if(!held.length) return false;
  if(spec.mode==='swap' && !shopStock(state,p).length) return false;
  if(spec.mode==='reveal' && !revealTargets(state,p,spec).length) return false;
  if(spec.mode==='sell' && freeBank(state)<Math.max(...held.map(itemId=>bondQuote(state,p,spec,itemId)))) return false;
  if(spec.energyCost && p.energy<spec.energyCost) return false;
  if(spec.cleanse==='debuffs' && !p.statuses.some(s=>s.id.startsWith('D'))) return false;
  // Event choice rules 1: a showing that would change none of its statuses, or only half of a trade, is not offered.
  if(state.config.eventChoiceRules===1 && spec.mode==='show' && [...(spec.buffs??[]),...(spec.debuffs??[])].some(s=>!!status(p,s))) return false;
  return true;
}

export function bondTargets(state:AppraisalState,p:Appraiser,id:EventId):{itemIds:string[];giveItemId?:string} {
  const spec=bondSpec(id)!;const held=bondItems(state,p,spec);
  if(spec.mode==='swap') return {itemIds:shopStock(state,p),giveItemId:held[0]!};
  if(spec.mode==='reveal') return {itemIds:revealTargets(state,p,spec)};
  if(spec.mode==='show') return {itemIds:[]};
  return {itemIds:held};
}

export function bondQuotes(state:AppraisalState,p:Appraiser,id:EventId):Record<string,number> {
  const spec=bondSpec(id);
  return spec?.mode==='sell'?Object.fromEntries(bondItems(state,p,spec).map(itemId=>[itemId,bondQuote(state,p,spec,itemId)])):{};
}

function applyGain(state:AppraisalState,p:Appraiser,spec:BondSpec):void {
  if(spec.cleanse==='D10') removeStatus(p,'D10');
  if(spec.cleanse==='debuffs') p.statuses=p.statuses.filter(s=>!s.id.startsWith('D'));
  for(const id of spec.buffs??[]) grant(state,p,id);
  for(const id of spec.debuffs??[]) grant(state,p,id);
  if(spec.energy) recover(state,p,spec.energy,spec.id);
  if(spec.life && state.config.survival && p.life!>0) healLife(state,p,spec.life,spec.id);
}

function takeFromShop(state:AppraisalState,p:Appraiser,itemId:string):void {
  const item=stockItem(state,p,itemId);
  item.owner=p.id;p.inventory.push(item.id);p.stock=p.stock.filter(id=>id!==item.id);
  state.listings=state.listings.filter(l=>l.itemId!==item.id);
}

export function resolveBond(state:AppraisalState,p:Appraiser,offer:EventOffer,command:Extract<AppraisalAction,{type:'event'}>):void {
  const spec=bondSpec(offer.id)!;
  if(state.config.secureEconomy && (spec.mode==='sell' || spec.mode==='swap'))check(!merchantTradeBanned(state,p),'merchant-banned','ยังถูกห้ามค้าขายกับพ่อค้า');
  const chosen=()=>{check(command.itemId && offer.itemIds.includes(command.itemId),'event-target','เลือกสินค้าที่อยู่ใน event');return command.itemId;};
  const stillHeld=(itemId:string)=>{check(bondItems(state,p,spec).includes(itemId),'event-target','ไม่มีของที่ NPC ต้องการแล้ว');return ownedItem(state,p,itemId,true);};
  switch(spec.mode) {
    case 'show': check(bondItems(state,p,spec).length>0,'event-target','ไม่มีของที่ NPC ต้องการแล้ว');applyGain(state,p,spec);break;
    case 'reveal': {
      const itemId=chosen();const item=stockItem(state,p,itemId);check(bondItems(state,p,spec).length>0,'event-target','ไม่มีของที่ NPC ต้องการแล้ว');
      if(spec.energyCost) spend(state,p,0,spec.energyCost,spec.id);
      const facts={base:item.base,genuine:item.genuine,cursed:item.cursed,effectsKnown:true};
      learn(p,itemId,Object.fromEntries(spec.reveal!.map(fact=>[fact,facts[fact]])));
      trace(state,p,'bond-revealed',{id:spec.id,itemId,facts:spec.reveal});break;
    }
    case 'sell': case 'tribute': {
      const itemId=chosen();stillHeld(itemId);
      if(spec.mode==='sell') {const item=state.items[itemId]!;const paid=systemSaleQuote(state,item,saleApply(state,p,bondPrice(state,spec,itemId)));reward(state,p,paid,spec.id);recordItemTrade(state,item,paid);if(state.config.personalScoringFacts===2)recordPersonalSale(state,p,item,paid);}
      retire(state,p,itemId,spec.id);if(spec.mode==='tribute') applyGain(state,p,spec);break;
    }
    case 'swap': {
      const target=chosen();stockItem(state,p,target);
      const give=stillHeld(offer.giveItemId!);
      if(spec.genuineOnly && !give.genuine) {grant(state,p,'D10');p.notes.push(`${ITEM_SPECS[give.kind].name}เป็นของปลอม NPC ปฏิเสธการแลก`);trace(state,p,'bond-refused',{id:spec.id,itemId:give.id});break;}
      if(spec.risk && randomAt(state.seed,`${offer.key}:bond-risk`)<spec.risk) {grant(state,p,'D03');p.notes.push('NPC จับได้ว่าเป็นของปลอม ไม่ยอมแลก');trace(state,p,'bond-caught',{id:spec.id,itemId:give.id});break;}
      retire(state,p,give.id,spec.id);takeFromShop(state,p,target);
      trace(state,p,'bond-swapped',{id:spec.id,gave:give.id,received:target});break;
    }
  }
  p.notes=p.notes.slice(-30);
}

export function unsoldItems(state:AppraisalState,p:Appraiser):string[] {
  if(!state.config.brokerage) return [];
  return shopStock(state,p).filter(id=>!!p.valuations[id]);
}

function leaveShop(state:AppraisalState,p:Appraiser,item:AppraisalItem):void {
  p.stock=p.stock.filter(id=>id!==item.id);state.listings=state.listings.filter(l=>l.itemId!==item.id);
}

function payUpTo(state:AppraisalState,p:Appraiser,credits:number,reason:string):number {
  const paid=Math.min(credits,p.credits);spend(state,p,paid,0,reason);return paid;
}

export function unsoldPenalty(state:AppraisalState,p:Appraiser,item:AppraisalItem):void {
  const rule=UNSOLD_PENALTIES[item.npc];
  // Spirit ward turns a credit/energy penalty into a lighter one; an open wound doubles the credits. Life penalties go through damageLife.
  const lifePenalty=!!(rule.life && state.config.survival);
  const ward=!lifePenalty && !!state.config.polish && !!status(p,'B19'),wound=!lifePenalty && !!state.config.polish && !!status(p,'D20');
  if(ward) consumeStatus(p,'B19');if(wound) consumeStatus(p,'D20');
  const paid=payUpTo(state,p,ward?0:rule.credits*(wound?2:1),'unsold-penalty');
  const drained=Math.min(Math.max(0,rule.energy-(ward?1:0)),p.energy);p.energy-=drained;
  for(const id of rule.statuses) grant(state,p,id);
  leaveShop(state,p,item);
  p.notes.push(`${ITEM_SPECS[item.kind].name}ขายไม่ออก: ${rule.text}`);p.notes=p.notes.slice(-30);
  trace(state,p,'unsold-penalty',{itemId:item.id,npc:item.npc,credits:paid,energy:drained,statuses:rule.statuses});
  if(rule.life && state.config.survival && p.life!>0) damageLife(state,p,rule.life,'unsold-penalty');
}

function consign(state:AppraisalState,p:Appraiser,item:AppraisalItem):void {
  const roll=randomAt(state.seed,`${state.encounter}:${p.id}:${item.id}:consign`);
  leaveShop(state,p,item);item.owner='dark-market';state.vault!.push(item.id);
  let outcome='clean';
  if(state.config.core2) {
    // v0.6: the Dark Market pays a share of the item's real value (fake and cursed goods are worth less), minus its cut.
    const owed=systemSaleQuote(state,item,consignPayout(item.base,item.genuine,item.cursed));
    const free=state.bank-state.market.budget-state.reservedRewards;const paid=Math.max(0,Math.min(owed,free));
    if(paid>0) reward(state,p,paid,'consign-payout');
    recordItemTrade(state,item,paid);if(state.config.personalScoringFacts===2)recordPersonalSale(state,p,item,paid);
    p.notes.push(`Dark Market รับฝากของและจ่ายให้ ${paid} เครดิต (หลังหักค่าธรรมเนียม ${CORE2.consign.fee})`);
    if(roll>=CORE2.consign.debuffBelow) {const fee=payUpTo(state,p,CORE2.consign.extraFee,'consign-fee');outcome=`fee:${fee}`;p.notes.push(`แต่ถูกเก็บค่าผ่านทางเพิ่ม ${fee} เครดิต`);}
    else if(roll>=CORE2.consign.cleanBelow) {
      const pool=state.config.polish?[...CONSIGN_RULES.debuffs,'D17' as const,'D18' as const]:CONSIGN_RULES.debuffs;
      const debuff=pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${item.id}:consign-debuff`)*pool.length)]!;
      grant(state,p,debuff);outcome=`debuff:${debuff}`;p.notes.push(`และทิ้ง ${debuff} ไว้กับคุณ`);
    } else p.notes.push('ไม่มีผลติดตัว');
    p.notes=p.notes.slice(-30);
    trace(state,p,'unsold-consigned',{itemId:item.id,outcome,paid});
    return;
  }
  if(roll>=CONSIGN_RULES.debuffBelow) {const paid=payUpTo(state,p,CONSIGN_RULES.fee,'consign-fee');outcome=`fee:${paid}`;p.notes.push(`Dark Market รับฝากของ เก็บค่าผ่านทาง ${paid} เครดิต`);}
  else if(roll>=CONSIGN_RULES.cleanBelow) {
    // Polish rules add market inflation and hidden taxes to the debuffs a consignment can leave behind.
    const pool=state.config.polish?[...CONSIGN_RULES.debuffs,'D17' as const,'D18' as const]:CONSIGN_RULES.debuffs;
    const debuff=pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${item.id}:consign-debuff`)*pool.length)]!;
    grant(state,p,debuff);outcome=`debuff:${debuff}`;p.notes.push(`Dark Market รับฝากของ แต่ทิ้ง ${debuff} ไว้กับคุณ`);
  } else p.notes.push('Dark Market รับฝากของเงียบ ๆ ไม่มีผลติดตัว');
  p.notes=p.notes.slice(-30);
  trace(state,p,'unsold-consigned',{itemId:item.id,outcome});
}

export function settleUnsold(state:AppraisalState,p:Appraiser,itemId:string,choice:UnsoldChoice):void {
  check(['buy','penalty','consign'].includes(choice),'unsold','ตัวเลือกของค้างไม่ถูกต้อง');
  check(unsoldItems(state,p).includes(itemId),'unsold','ไม่มีของที่ประเมินแล้วค้างอยู่ในร้าน');
  const item=state.items[itemId]!;
  if(choice==='buy') purchase(state,p,p,[itemId],{condition:p.dealMode==='condition'});
  else if(choice==='penalty') unsoldPenalty(state,p,item);
  else consign(state,p,item);
}

export function settleRemainingUnsold(state:AppraisalState,p:Appraiser):void {
  if(p.paused==='dead') return;
  for(const itemId of unsoldItems(state,p)) {
    if(p.life===0) break;
    unsoldPenalty(state,p,state.items[itemId]!);
  }
}

export function vaultSale(state:AppraisalState,item:AppraisalItem):void {
  if(!state.config.brokerage) return;
  item.owner='dark-market';state.vault!.push(item.id);
}

export function auctionLots(state:AppraisalState):AuctionLot[] {
  const rules=state.config.brokerage;const vault=state.vault??[];
  if(!rules || !vault.length || randomAt(state.seed,`${state.encounter}:auction:open`)>=rules.auctionProbability) return [];
  return vault.map(itemId=>({itemId,rank:randomAt(state.seed,`${state.encounter}:auction:${itemId}:rank`)}))
    .sort((a,b)=>a.rank-b.rank).slice(0,rules.maxLots)
    .map(({itemId})=>({id:`lot-${state.encounter}-${itemId}`,itemId,minimum:Math.max(1,rarityValue(state.items[itemId]!,Math.floor(anchorOf(state.config,state.items[itemId]!.kind)*.6))),bids:{}}));
}

export function placeBid(state:AppraisalState,p:Appraiser,lotId:string,credits:number):void {
  const lot=state.market.lots?.find(l=>l.id===lotId);
  check(lot && lot.winnerId===undefined,'lot','ไม่มีรายการประมูลนี้');
  check(Number.isSafeInteger(credits) && credits>=0 && credits<=1000,'bid','ราคาประมูลไม่ถูกต้อง');
  if(credits===0) {delete lot.bids[p.id];trace(state,p,'bid-withdrawn',{lotId});return;}
  check(credits>=lot.minimum,'bid',`ประมูลขั้นต่ำ ${lot.minimum} เครดิต`);
  check(p.credits>=credits,'credits','credit ไม่พอสำหรับราคาประมูล');
  lot.bids[p.id]=credits;trace(state,p,'bid-placed',{lotId});
}

export function settleAuction(state:AppraisalState):void {
  for(const lot of state.market.lots??[]) {
    if(lot.winnerId!==undefined) continue;
    const bidders=Object.entries(lot.bids).map(([id,amount])=>({p:player(state,id),amount,tie:randomAt(state.seed,`${lot.id}:${id}:tie`)}))
      .filter(b=>b.p.paused!=='dead' && b.p.life!==0).sort((a,b)=>b.amount-a.amount || a.tie-b.tie);
    const winner=bidders.find(b=>b.p.credits>=b.amount);
    if(!winner) {lot.winnerId=null;continue;}
    const item=state.items[lot.itemId]!;
    const edge=!!state.config.polish && !!status(winner.p,'B20');const paid=edge?winner.amount-Math.floor(winner.amount*20/100):winner.amount;
    if(edge) consumeStatus(winner.p,'B20');
    spend(state,winner.p,paid,0,'dark-auction');
    recordPersonalItemActivity(state,winner.p,'bought',item,1,paid>0,'zero-credit auction');
    completeAppraisedSale(state,item,paid);
    recordItemTrade(state,item,paid);
    item.owner=winner.p.id;winner.p.inventory.push(item.id);state.vault=state.vault!.filter(id=>id!==item.id);
    lot.winnerId=winner.p.id;lot.price=paid;
    winner.p.darkTickets=(winner.p.darkTickets??0)+1;winner.p.notes.push(`ชนะประมูล ได้ตั๋วคำสั่งมืด ${winner.p.darkTickets}/${TRUST_RULES.ticketsToForce}`);winner.p.notes=winner.p.notes.slice(-30);
    trace(state,winner.p,'auction-won',{lotId:lot.id,itemId:item.id,price:paid,...(edge?{bid:winner.amount}:{})});
  }
}

CHALLENGE_TOOLS={
  'doubt-lens':{text:`ถือไว้ ท้าทายถูกแล้วลดราคาเพิ่ม +${CHALLENGE_LENS_BONUS} จุดเปอร์เซ็นต์ต่อชิ้น (สูงสุด ${CHALLENGE_CAP}%)`},
  'void-seal':{text:'แนบกับการท้าทาย ถ้าท้าทายผิด ค่าปรับเป็นโมฆะ ใช้แล้วหมดไปเฉพาะเมื่อมีผลยกเลิก'},
} as const

export function settleChallenge(state:AppraisalState,buyer:Appraiser,seller:Appraiser,offer:TradeOffer):{discount:number;penalty:number} {
  const key=offer.challenge!;const item=state.items[offer.itemId]!;const claim=state.listings.find(l=>l.itemId===offer.itemId && l.ownerId===seller.id)?.claims?.[key];
  const truth=item[key];const quote=npcQuote(seller,item);const name=ITEM_SPECS[item.kind].name;
  learn(buyer,item.id,{[key]:truth});
  const lenses=buyer.inventory.filter(id=>state.items[id]!.kind==='doubt-lens').reduce((sum,id)=>sum+itemEffectScale(state.items[id]!),0);
  if(claim===undefined || claim===truth) {
    const owed=challengePenalty(quote);const hasSeal=offer.sealId!==undefined && buyer.inventory.includes(offer.sealId) && unlocked(buyer,offer.sealId) && state.items[offer.sealId]!.kind==='void-seal';
    const sealed=hasSeal && (!state.items[offer.sealId!]!.copy || randomAt(state.seed,`${state.encounter}:${offer.id}:copy-seal`)<.4);
    if(hasSeal) retire(state,buyer,offer.sealId!,'challenge-void-seal');
    const penalty=sealed?0:owed;
    buyer.notes.push(`ท้าทายคำระบุของ${name}ผิด ผู้ประเมินพูดจริง (${claimText(key,truth)})${sealed?' ตราโมฆะยกเลิกค่าปรับ':` เสียค่าปรับ ${penalty} เครดิต`}`);
    seller.notes.push(`คำระบุของ${name}ถูกท้าทายแต่เป็นความจริง${sealed?' ผู้ซื้อใช้ตราโมฆะ ไม่ต้องจ่ายค่าปรับ':` ได้ค่าปรับ ${penalty} เครดิต`}`);
    trace(state,buyer,'challenge-lost',{offerId:offer.id,itemId:item.id,key,penalty,sealed});
    buyer.notes=buyer.notes.slice(-30);seller.notes=seller.notes.slice(-30);return {discount:0,penalty};
  }
  const discount=challengeDiscount(quote,lenses);
  buyer.notes.push(`ท้าทายคำระบุของ${name}ถูก ผู้ประเมินโกหก (จริงคือ${claimText(key,truth)}) ลดราคา ${discount} เครดิต`);
  seller.notes.push(`คำระบุของ${name}เป็นเท็จและถูกจับได้ ผู้ซื้อลดราคา ${discount} เครดิต`);
  trace(state,buyer,'challenge-won',{offerId:offer.id,itemId:item.id,key,discount});
  buyer.notes=buyer.notes.slice(-30);seller.notes=seller.notes.slice(-30);return {discount,penalty:0};
}

CLEANSE_TOOLS = {
  'smith-hammer':{bonus:10,consumed:false,text:'ถือไว้ โอกาสล้างคำสาปสำเร็จ +10 จุดเปอร์เซ็นต์ต่อชิ้น (ซ้อนได้)'},
  whetstone:{bonus:20,consumed:true,text:'เลือกใช้ตอนล้างคำสาป โอกาสสำเร็จ +20 จุดเปอร์เซ็นต์ ใช้แล้วหมดไป'},
} as const satisfies Partial<Record<ItemKind,{bonus:number;consumed:boolean;text:string}>>

export function cleansePrice(kind:ItemKind,npc:NpcId,trust:number,roll:number):number {
  const [low,high]=CLEANSE_RULES[npc].price;
  return Math.max(1,Math.round(cleanseBasePrice(kind)*(low+(high-low)*roll)*(1-CLEANSE_TRUST_PRICE*trust/100)));
}

export function cleanseChance(npc:NpcId,trust:number,held:ItemKind[],stone?:ItemKind,modifier=0):number {
  const hammers=held.filter(kind=>kind==='smith-hammer').length*CLEANSE_TOOLS['smith-hammer'].bonus;
  const stoneBonus=stone && isCleanseTool(stone) && CLEANSE_TOOLS[stone].consumed?CLEANSE_TOOLS[stone].bonus:0;
  return Math.max(5,Math.min(CLEANSE_CAP,CLEANSE_RULES[npc].chance+trust*CLEANSE_TRUST_CHANCE+hammers+stoneBonus+modifier));
}

function shopNpc(state:AppraisalState,p:Appraiser):NpcId|undefined {
  return state.config.cleanse && state.phase==='APPRAISAL' && p.selectedPortalId?p.portals.find(portal=>portal.id===p.selectedPortalId)?.npc:undefined;
}

function quote(state:AppraisalState,p:Appraiser,npc:NpcId,itemId:string,stoneKind?:ItemKind,stonePower=1):{price:number;chance:number} {
  const item=state.items[itemId]!;const trust=trustOf(p,npc);
  const heldItems=p.inventory.filter(id=>id!==itemId).map(id=>state.items[id]!);
  const held=heldItems.filter(i=>!i.copy).map(i=>i.kind);
  const copyTools=heldItems.filter(i=>i.kind==='smith-hammer').reduce((sum,i)=>sum+10*(itemEffectScale(i)-(i.copy?0:1)),0)+(stonePower-1)*(stoneKind==='whetstone'?20:0);
  // Polish: golden mouth takes 2 off the fee, hidden taxes add to it; the festival omen helps the odds.
  const fee=state.config.polish?feeSurcharge(state,p)-integerEffect(statusMagnitude(p,'B03',2)):0;
  const base=cleansePrice(item.kind,npc,trust,randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:cleanse-price`));
  return {price:Math.max(1,base+fee),chance:cleanseChance(npc,trust,held,stoneKind,statusMagnitude(p,'B16',20)-statusMagnitude(p,'D16',15)+(omenNow(state)?.accept??0)+copyTools)};
}

export function cleanseOffer(state:AppraisalState,p:Appraiser):CleanseOffer|undefined {
  const npc=shopNpc(state,p);if(!npc || p.life===0) return;
  const items=p.inventory.map(itemId=>({itemId,...quote(state,p,npc,itemId),done:!!p.cleansed?.includes(itemId)}));
  return {npc,items,stoneBonus:CLEANSE_TOOLS.whetstone.bonus};
}

export function cleanseItem(state:AppraisalState,p:Appraiser,itemId:string,stoneId?:string):void {
  const npc=shopNpc(state,p);check(npc,'cleanse','พ่อค้านี้ไม่รับล้างคำสาปตอนนี้');
  const item=ownedItem(state,p,itemId);
  check(!p.cleansed!.includes(itemId),'cleanse','ชิ้นนี้ล้างคำสาปในช่วงนี้แล้ว');
  let stoneKind:ItemKind|undefined;let stonePower=1;
  if(stoneId!==undefined) {
    check(stoneId!==itemId,'cleanse','ใช้หินขัดกับตัวมันเองไม่ได้');
    const stone=ownedItem(state,p,stoneId);check(stone.kind==='whetstone','cleanse','ของที่เลือกไม่ใช่หินขัด');stoneKind=stone.kind;stonePower=itemEffectScale(stone);
  }
  const {price,chance}=quote(state,p,npc,itemId,stoneKind,stonePower);
  spend(state,p,price,0,'cleanse-curse');consumeStatus(p,'B16');if(state.config.polish)consumeStatus(p,'B03');p.cleansed!.push(itemId);
  if(stoneId) retire(state,p,stoneId,'cleanse-stone',false);
  const name=ITEM_SPECS[item.kind].name;const who='พ่อค้า';
  const wasCursed=item.cursed;
  if(!wasCursed) {
    learn(p,itemId,{cursed:false});p.notes.push(`${who}ตรวจ${name}แล้วไม่พบคำสาป เสียค่าบริการ ${price} เครดิตเปล่า`);
  } else if(randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:cleanse-roll`)*100<chance) {
    item.cursed=false;learn(p,itemId,{cursed:false});p.notes.push(`ล้างคำสาป${name}สำเร็จ (โอกาส ${chance}%) จ่าย ${price} เครดิต`);
  } else {
    learn(p,itemId,{cursed:true});p.notes.push(`ล้างคำสาป${name}ไม่สำเร็จ (โอกาส ${chance}%) จ่าย ${price} เครดิต คำสาปยังติดอยู่`);
  }
  p.notes=p.notes.slice(-30);trace(state,p,'cursed-cleanse',{itemId,npc,price,chance,stone:!!stoneId,cleansed:wasCursed && !item.cursed});
}

function deliver(state:AppraisalState,p:Appraiser,s:CollectorWishlistState):void{
 const pending=s.pending!,kinds=pool(state),rest=[...kinds.keys()].filter(k=>!pending.kinds.includes(k)).sort((a,b)=>randomAt(state.seed,`${pending.id}:extra:${a}`)-randomAt(state.seed,`${pending.id}:extra:${b}`)||a.localeCompare(b));
 const selected=[...pending.kinds,...rest.slice(0,2)].sort((a,b)=>randomAt(state.seed,`${pending.id}:slot:${a}`)-randomAt(state.seed,`${pending.id}:slot:${b}`)||a.localeCompare(b));
 check(selected.length===5&&new Set(selected).size===5,'collector-pool','คลังสินค้าสำหรับ Collector ไม่พอ');
 const itemIds=selected.map((kind,index)=>{const id=`${pending.id}-item-${index}`,npc=kinds.get(kind)!;check(npc,'collector-pool','ชนิดสินค้านี้ไม่มีในรัน');const anchor=anchorOf(state.config,kind),range=priceRange(kind,anchor),base=range[0]+Math.floor(randomAt(state.seed,`${id}:base`)*(range[1]-range[0]+1)),ask=Math.max(1,anchor-2+Math.floor(randomAt(state.seed,`${id}:ask`)*6));
  const item:AppraisalItem={id,kind,npc,npcOwnerId:p.id,encounter:state.encounter,base,ask,reservation:ask,genuine:randomAt(state.seed,`${id}:genuine`)<.75,cursed:randomAt(state.seed,`${id}:curse`)<.35,certificate:randomAt(state.seed,`${id}:certificate`)<.65,lastAppraisal:null,lastAccepted:null,owner:prefix+pending.id};ensureItemAppearance(state,item);state.items[id]=item;return id;});
 const rawQuote=Math.max(1,Math.ceil(itemIds.reduce((n,id)=>n+rarityValue(state.items[id]!,anchorOf(state.config,state.items[id]!.kind)),0)/5));s.offer={id:pending.id,encounter:state.encounter,itemIds,rawQuote,status:'open'};delete s.pending;note(p,`Collector ส่งชุด ${s.offer.id} มาแล้ว 5 ช่อง ราคาต้นทุนร่วม ${rawQuote} เครดิต`);trace(state,p,'collector-wish-delivered',{batchId:s.offer.id,rawQuote});
}

export function reconcileCollectorWishlist(state:AppraisalState):void{
 if(state.config.collectorWishlistRules!==1)return;state.collectorWishes??={};
 if(state.phase==='RESULTS'){closeCollectorWishlists(state);return;}
 for(const p of state.players){if(!Object.hasOwn(state.collectorWishes,p.id))state.collectorWishes[p.id]={lastWindowAt:0};const s=state.collectorWishes[p.id]!;
  if(!alive(p)){closeOffer(state,p,'cancelled');if(s.pending){note(p,`Collector ยกเลิกคำขอ ${s.pending.id} เพราะเสียชีวิต`);trace(state,p,'collector-wish-cancelled',{batchId:s.pending.id,reason:'dead'});delete s.pending;}continue;}
  if(s.pending&&s.pending.dueAt<=state.encounter){if(s.pending.dueAt===state.encounter)deliver(state,p,s);else {note(p,`Collector ปิดคำขอ ${s.pending.id} เพราะเลยช่วงส่งของ`);trace(state,p,'collector-wish-expired',{batchId:s.pending.id});delete s.pending;}}
  if(!phaseWindow(state)||state.phase==='APPRAISAL'&&p.done){if(s.offer?.status==='open')closeOffer(state,p,'expired');if(state.encounter%2===0)s.lastWindowAt=state.encounter;}
 }
}

export function collectorWishlistView(state:AppraisalState,p:Appraiser):CollectorWishlistView|undefined{
 if(state.config.collectorWishlistRules!==1||!alive(p)||pool(state).size<5)return;const s=state.collectorWishes?.[p.id];const offer=s?.offer;
 const delivery=offer?(()=>{const quote=cost(state,p,offer.rawQuote),open=offer.status==='open'&&interactive(state,p),reason=!open?'phase':merchantTradeBanned(state,p)?'merchant-banned':p.credits<quote.total?'credits':p.energy<quote.energy?'energy':undefined;
 return {id:offer.id,quoteId:quoteKey(offer,quote),status:offer.status,cost:quote,canPeek:open&&offer.peek===undefined&&p.credits>=quote.total,canBuy:open&&reason===undefined,...(reason?{reason}:{}),slots:offer.itemIds.map((id,index)=>{const item=state.items[id]!;return {id:`s${index}`,...(offer.peek===index?{peek:{kind:item.kind,name:ITEM_SPECS[item.kind].name,image:itemImage(item.kind),...(item.appearance?{rarity:item.appearance.rarity}:{})}}:{})};})};})():undefined;
 return {request:{available:available(state,p),kinds:[...pool(state).keys()].map(kind=>({kind,name:ITEM_SPECS[kind].name,image:itemImage(kind)})),dueAt:state.encounter+2},...(s?.pending?{pending:structuredClone(s.pending)}:{}),...(delivery?{delivery}:{})};
}

export function handleCollectorWishlist(state:AppraisalState,p:Appraiser,action:CollectorWishlistAction):void{
 check(state.config.collectorWishlistRules===1&&interactive(state,p),'collector-window','ช่วงนี้ยังใช้บริการ Collector ไม่ได้');const s=state.collectorWishes?.[p.id];check(s,'collector-window','ยังไม่มีสิทธิ์ Collector');
 if(action.type==='collector-wish-request'){check(available(state,p),'collector-window','ยังส่งคำขอใหม่ไม่ได้');check(Array.isArray(action.kinds)&&action.kinds.length===3&&new Set(action.kinds).size===3&&action.kinds.every(k=>typeof k==='string'&&pool(state).has(k)),'collector-kinds','เลือกสินค้า 3 ชนิดที่ไม่ซ้ำกัน');s.pending={id:`cw-${p.id}-${state.encounter}`,kinds:[...action.kinds],requestedAt:state.encounter,dueAt:state.encounter+2};s.lastWindowAt=state.encounter;note(p,`ขอ Collector: ${action.kinds.map(k=>ITEM_SPECS[k].name).join(' / ')} รับช่วง ${s.pending.dueAt}`);trace(state,p,'collector-wish-requested',{batchId:s.pending.id,kinds:[...action.kinds],dueAt:s.pending.dueAt});return;}
 if(action.type==='collector-wish-skip'&&action.batchId===undefined){check(available(state,p),'collector-window','ยังข้ามคำขอไม่ได้');s.lastWindowAt=state.encounter;note(p,`ข้ามการส่งรายการ Collector ช่วง ${state.encounter}`);trace(state,p,'collector-wish-request-skipped',{});return;}
 const offer=s.offer;check(offer&&offer.status==='open'&&action.batchId===offer.id,'collector-batch','ชุด Collector นี้ไม่พร้อมแล้ว');if(action.type==='collector-wish-skip'){closeOffer(state,p,'skipped');return;}
 const index=offer.itemIds.findIndex((_,n)=>action.slotId===`s${n}`);check(index>=0,'collector-slot','ช่องสินค้าไม่ถูกต้อง');const quote=cost(state,p,offer.rawQuote);check(p.credits>=quote.total,'credits','เครดิตในกระเป๋าไม่พอ');
 if(action.type==='collector-wish-peek'){check(offer.peek===undefined,'collector-peek','เปิดดูชุดนี้แล้ว');offer.peek=index;note(p,`เปิดดู Collector ช่อง ${index+1}: ${ITEM_SPECS[state.items[offer.itemIds[index]!]!.kind].name}`);trace(state,p,'collector-wish-peeked',{batchId:offer.id,slotId:action.slotId});return;}
 check(action.quoteId===quoteKey(offer,quote),'collector-quote','ต้นทุนเปลี่ยนแล้ว กรุณาตรวจและยืนยันราคาใหม่');const item=state.items[offer.itemIds[index]!]!;check(item.owner===prefix+offer.id,'collector-owner','สินค้าชุดนี้ไม่พร้อมแล้ว');
 check(!merchantTradeBanned(state,p),'merchant-banned','ยังถูกห้ามค้าขายกับพ่อค้า');spend(state,p,quote.total,quote.energy,'collector-purchase');for(const id of ['B03','D06','D12'] as const)consumeStatus(p,id);
 item.owner=p.id;p.inventory.push(item.id);p.paid={...p.paid,[item.id]:quote.price};recordItemTrade(state,item,quote.price);recordPersonalItemActivity(state,p,'bought',item,1,quote.price>0,'zero-credit purchase');closeOffer(state,p,'bought');note(p,`ซื้อ ${ITEM_SPECS[item.kind].name} จาก Collector ${offer.id}: สินค้า ${quote.price} + ค่าธรรมเนียม ${quote.fee} เครดิต ใช้ ${quote.energy} พลัง`);trace(state,p,'collector-wish-purchased',{batchId:offer.id,itemId:item.id,slotId:action.slotId,...quote});
}

export function assertCollectorWishlistInvariants(state:AppraisalState):void{
 check((state.config.collectorWishlistRules===1)===!!state.collectorWishes,'collector-state','สถานะ Collector ไม่ตรงกติกา');if(!state.collectorWishes)return;check(Object.keys(state.collectorWishes).length===state.players.length&&state.players.every(p=>Object.hasOwn(state.collectorWishes!,p.id)),'collector-state','สิทธิ์ Collector ไม่ครบผู้เล่น');const escrow=new Set<string>();
 for(const [id,s] of Object.entries(state.collectorWishes??{})){check(state.players.some(p=>p.id===id)&&Number.isSafeInteger(s.lastWindowAt)&&s.lastWindowAt>=0&&s.lastWindowAt<=state.encounter,'collector-state','เจ้าของหรือรอบ Collector ไม่ถูกต้อง');
  if(s.pending)check(s.pending.kinds.length===3&&new Set(s.pending.kinds).size===3&&s.pending.dueAt===s.pending.requestedAt+2&&s.pending.requestedAt%2===0&&s.pending.dueAt>state.encounter,'collector-state','คำขอ Collector ไม่ถูกต้อง');
  if(s.offer){const o=s.offer;check(o.itemIds.length===5&&new Set(o.itemIds).size===5&&new Set(o.itemIds.map(i=>state.items[i]?.kind)).size===5&&Number.isSafeInteger(o.rawQuote)&&o.rawQuote>=1&&(o.peek===undefined||Number.isSafeInteger(o.peek)&&o.peek>=0&&o.peek<5),'collector-state','ชุด Collector ไม่ถูกต้อง');if(o.status==='open')for(const itemId of o.itemIds)check(!escrow.has(itemId)&&!!escrow.add(itemId)&&state.items[itemId]?.owner===prefix+o.id,'collector-owner','ของค้าง Collector ไม่ตรงเจ้าของ');}
 }
 for(const item of Object.values(state.items))if(item.owner.startsWith(prefix))check(escrow.has(item.id),'collector-owner','ของค้าง Collector ไม่มีชุด');
}

