export function merchantKinds(npc:NpcId,catalogVersion:1|2|3|4=1,cleanse=false,challenge=false,expansion=false,polish=false,trustAbilities=false):ItemKind[] {
  if(catalogVersion===4)return (Object.keys(PILOT_ITEMS) as Array<keyof typeof PILOT_ITEMS>).filter(kind=>PILOT_ITEMS[kind].merchant===npc);
  const favorites=NPC_SPECS[npc].favorite;
  return catalogVersion===1 ? favorites : (Object.keys(ITEM_SPECS) as ItemKind[]).filter(kind=>!(kind in PILOT_ITEMS) && (trustAbilities && catalogVersion===3 || !(ABILITY_ITEM_IDS as readonly string[]).includes(kind)) && (catalogVersion===3 && cleanse || !CLEANSE_KINDS.includes(kind)) && (catalogVersion===3 && challenge || !CHALLENGE_KINDS.includes(kind)) && (catalogVersion===3 && expansion || !EXPANSION_KINDS.includes(kind)) && (catalogVersion===3 && polish || !POLISH_KINDS.includes(kind)) && (catalogVersion===3 || !passiveSpec(kind)) && favorites.some(f=>f===itemFamily(kind)));
}

export function priceRange(kind:ItemKind,anchor:number=ITEM_SPECS[kind].anchor):[number,number] {
  return [Math.floor(anchor*.7),Math.ceil(anchor*1.3)];
}

statusMagnitude=(p:Pick<Appraiser,'statuses'>,id:StatusId,amount:number):number=>{
  const found=p.statuses.find(s=>s.id===id&&s.charges>0);return found?amount*(found.power??1):0;
}

function startTheft(state:AppraisalState,p:Appraiser,target:string):void {
  check(state.config.core2 && !p.eventOffer && !p.stealTried?.length,'steal','ขโมยได้ครั้งเดียวต่อช่วง');
  (p.stealTried??=[]).push(target);
}

function loseTrust(p:Appraiser,npc:NpcId,amount:number):void {
  if(p.npcTrust)p.npcTrust[npc]=Math.max(0,trustOf(p,npc)-amount);
}

export function stealChance(state:AppraisalState,p:Appraiser,npc?:NpcId,friend=false):number {
  return clamp(CORE2.steal.base+(npc?CORE2.steal.perTrust*trustOf(p,npc):0)+(omenNow(state)?.steal??0)/100+(status(p,'B22')?.25:0)-(status(p,'D21')?.15:0)+(friend?CORE2.steal.friend:0));
}

export function stealShop(state:AppraisalState,p:Appraiser,itemId:string):void {
  const item=stockItem(state,p,itemId);
  startTheft(state,p,itemId);spend(state,p,0,CORE2.steal.energy,'steal');
  const chance=stealChance(state,p,item.npc);
  const ok=randomAt(state.seed,`${state.encounter}:${p.id}:steal:${itemId}`)<chance;
  consumeStatus(p,'B22');
  if(ok){
    item.owner=p.id;item.stolen=true;p.inventory.push(itemId);p.stock=p.stock.filter(id=>id!==itemId);
    state.listings=state.listings.filter(l=>l.itemId!==itemId);
    note(p,`ฉกสำเร็จ: ได้ ${NPC_SPECS[item.npc].name}ขายของชิ้นนี้ไปฟรี แต่ขายต่อไม่ได้`);
    recordPersonalActivity(state,p,'theft',1,JSON.stringify([p.id,'item',personalOrigin(item)]));
    trace(state,p,'stolen',{itemId,chance});return;
  }
  loseTrust(p,item.npc,1);p.theft={kind:'shop'};
  note(p,`ฉกพลาด! ${NPC_SPECS[item.npc].name}จับมือไว้ได้`);
  trace(state,p,'steal-failed',{itemId,chance});
}

export function pickpocket(state:AppraisalState,p:Appraiser,victimId:string):void {
  const victim=state.players.find(v=>v.id===victimId);
  check(victim && victim.id!==p.id && !victim.paused && victim.credits>0 && ['APPRAISAL','TRADE'].includes(state.phase),'steal','ล้วงกระเป๋าคนนี้ไม่ได้');
  startTheft(state,p,`p:${victimId}`);spend(state,p,0,CORE2.steal.energy,'pickpocket');
  const guarded=!!status(victim,'B21');
  const chance=stealChance(state,p,undefined,true);
  const ok=!guarded && randomAt(state.seed,`${state.encounter}:${p.id}:pickpocket:${victimId}`)<chance;
  consumeStatus(p,'B22');
  if(ok){
    const taken=Math.min(3,victim.credits);transfer(state,victim,p,taken,'pickpocket');
    note(p,`ล้วงกระเป๋าเพื่อนได้ ${taken} เครดิต`);note(victim,`มีคนล้วงกระเป๋าคุณไป ${taken} เครดิต`);
    if(taken>0)recordPersonalActivity(state,p,'theft',1,JSON.stringify([p.id,'credits',victimId,state.encounter]));
    trace(state,p,'pickpocketed',{victimId,taken,chance});return;
  }
  if(guarded){consumeStatus(victim,'B21');note(victim,'ผู้คุ้มกันจับมือโจรไว้ได้');}
  p.theft={kind:'player',victim:victim.id};
  note(p,'ล้วงพลาด! เพื่อนจับข้อมือไว้ได้');
  trace(state,p,'pickpocket-failed',{victimId,chance});
}

export function barter(state:AppraisalState,p:Appraiser,itemId:string,targetItemId:string):void {
  const mine=ownedItem(state,p,itemId,true);const target=stockItem(state,p,targetItemId);
  const npc=NPC_SPECS[target.npc];
  check(!mine.copy && npc.favorite.includes(mine.kind) || copySaleQuote(mine,rarityValue(mine,anchorOf(state.config,mine.kind)))>=target.ask,'barter','ของที่เสนอมูลค่าไม่พอสำหรับแลก');
  check(!mine.stolen,'stolen','ของที่ฉกมาแลกไม่ได้');
  const suspicious=!mine.genuine || mine.cursed;
  if(suspicious && randomAt(state.seed,`${state.encounter}:${p.id}:barter:${itemId}`)<CORE2.barter.detect){
    spend(state,p,0,CORE2.barter.energy,'barter-caught');loseTrust(p,target.npc,1);p.theft={kind:'shop'};
    note(p,`${npc.name}ตรวจพบว่าของที่เสนอมีตำหนิ แลกไม่สำเร็จ`);trace(state,p,'barter-caught',{itemId});return;
  }
  purchase(state,p,p,[targetItemId],{barterItemId:itemId,condition:p.dealMode==='condition'});
  note(p,`แลก ${npc.name} สำเร็จโดยไม่เสียเครดิต`);
}

function skillPayable(state:AppraisalState,p:Appraiser,npc:NpcId):boolean {
  const life=!!state.config.survival && p.life!==undefined;
  switch(npc) {
    case 'vampire': return life?p.life!>1:p.credits>=2;
    case 'darkone': return p.statuses.some(s=>s.id.startsWith('D')) && (life?p.life!>1:p.credits>=3);
    default: return p.energy>=1;
  }
}

export function useSkill(state:AppraisalState,p:Appraiser,itemId?:string):void {
  check(skillOpen(state,p),'skill','ความสามารถนี้ยังไม่พร้อมใช้');
  const npc=skillNpc(state,p)!;const strong=trustOf(p,npc)>=CORE2.skill.strong;
  const life=!!state.config.survival && p.life!==undefined;
  const target=()=>{check(itemId,'skill','เลือกสินค้าของร้านนี้');return stockItem(state,p,itemId);};
  switch(npc) {
    case 'orc': {const item=target();spend(state,p,0,1,'skill');learn(p,item.id,{base:item.base,...(strong?{genuine:item.genuine}:{})});break;}
    case 'vampire': {
      if(life){check(p.life!>1,'skill','ชีวิตไม่พอ');damageLife(state,p,1,'vampire-rite',false);}else spend(state,p,2,0,'vampire-rite');
      recover(state,p,strong?4:3,'vampire-rite');break;
    }
    case 'autometa': {const item=target();spend(state,p,0,1,'skill');learn(p,item.id,{genuine:item.genuine,...(strong?{effectsKnown:true}:{})});break;}
    case 'alien': {const item=target();spend(state,p,0,1,'skill');learn(p,item.id,{effectsKnown:true,cursed:item.cursed,...(strong?{genuine:item.genuine}:{})});break;}
    case 'darkone': {
      const debuff=p.statuses.find(s=>s.id.startsWith('D'));check(debuff,'skill','ไม่มี debuff ให้ลบ');
      if(life){check(p.life!>1,'skill','ชีวิตไม่พอ');damageLife(state,p,1,'darkone-pact',false);}else spend(state,p,3,0,'darkone-pact');
      removeStatus(p,debuff.id);if(strong)grant(state,p,'B06');break;
    }
    case 'beast': spend(state,p,0,1,'skill');grant(state,p,'B05');if(strong)grant(state,p,'B11');break;
    case 'deepsea': spend(state,p,0,1,'skill');grant(state,p,'B14');if(strong)grant(state,p,'B13');break;
    case 'swarm': spend(state,p,0,1,'skill');grant(state,p,'B13');if(strong)grant(state,p,'B15');break;
  }
  p.skillUsed=true;note(p,`ใช้ความสามารถ: ${SKILLS[npc].name}`);trace(state,p,'skill',{npc,strong});
}

export function core2ActionsOf(state:AppraisalState,p:Appraiser):Core2Actions {
  const npc=skillNpc(state,p);const open=skillOpen(state,p);
  return {
    theftUsed:!!p.stealTried?.length,trustForSkill:CORE2.skill.trust,
    ...(open && npc && !state.config.trustAbilities?{skill:{npc,name:SKILLS[npc].name,needsItem:!!SKILLS[npc].needsItem,strong:trustOf(p,npc)>=CORE2.skill.strong}}:{}),
    ...(!state.config.secureEconomy?{...(npc?{stealChance:stealChance(state,p,npc)}:{}),pickpocketChance:stealChance(state,p,undefined,true)}:{}),
  };
}

function affordable(state:AppraisalState,p:Appraiser,c:Core2Choice):boolean {
  if(c.credits && p.credits<c.credits)return false;
  if(c.energy && p.energy<c.energy)return false;
  if(c.life && (!state.config.survival || p.life===undefined || p.life<=c.life))return false;
  if(c.lose && !p.inventory.length)return false;
  if(c.reward && state.bank-state.market.budget-state.reservedRewards<c.reward)return false;
  if(c.heal && state.config.survival && p.life!==undefined && p.life>=(state.config.systemLinks===1?maxLifeOf(state,p)!:state.config.survival.maxLife))return false;
  return true;
}

export function core2EventChoices(state:AppraisalState,p:Appraiser,id:EventId):string[] {
  const spec=CORE2_SPECS[id]!;
  const open=core2Choices(id,state.config).filter(c=>{
    if(c.id==='decline')return true;
    if(state.config.systemLinks===1 && state.config.statusLinks===1 && id==='E128'){
      if(c.id==='offer' && (status(p,'B06') || status(p,'B19')))return false;
      if(c.id==='ward' && status(p,'B21'))return false;
    }
    return affordable(state,p,c) && !debtWithoutNext(state,c);
  }).map(c=>c.id);
  if(spec.consequence){return open.length?open:[FALLBACK_BRAND.id];}
  if(spec.phase==='PORTALS' && !open.length)return [FALLBACK_BRAND.id];
  return open;
}

export function core2EventEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  const spec=CORE2_SPECS[id];
  if(!spec || !state.config.core2 || p.paused || p.done || ['REVEAL','RESULTS'].includes(state.phase))return false;
  if(spec.consequence){
    if(p.consequenceSlots>=1)return false;
    if(CORE2_BACKLASH_IDS.includes(id))return !!p.inflated;
    return !!p.theft && (id==='E123'?p.theft.kind==='shop':p.theft.kind==='player' && !!p.theft.victim);
  }
  if(state.phase!==spec.phase)return false;
  if(spec.phase==='PORTALS')return p.portals.filter(v=>!v.disabled).length>1 && core2EventChoices(state,p,id).some(c=>c!==FALLBACK_BRAND.id);
  if(id==='E125')return p.stock.length>0 && !Object.keys(p.valuations).length && !status(p,'B01');
  if(id==='E126'){
    const drink=(state.config.survival?p.life!==undefined && p.life<(state.config.systemLinks===1?maxLifeOf(state,p)!:state.config.survival.maxLife):p.energy<(state.config.systemLinks===1?maxEnergyOf(state,p):state.config.maxEnergy)) && p.credits>=3;
    // Status links: the calming rite (B23) is open to any seat with the energy for it.
    return drink || state.config.statusLinks===1 && p.energy>=1 && !status(p,'B23');
  }
  if(id==='E127')return state.bank-state.market.budget-state.reservedRewards>=5 && !status(p,'D04') && (state.config.eventChoiceRules!==1 || !!state.config.survival || state.encounter<state.config.encounters);
  if(id==='E128')return state.config.systemLinks===1 && state.config.statusLinks===1
    ?core2EventChoices(state,p,id).some(choice=>choice!=='decline')
    :p.inventory.length>0 && !status(p,'B06') && !status(p,'B19');
  // Status links: whisper's price is D24, so it is not offered while that is already on (it would come free).
  if(id==='E129')return p.stock.length>0 && !Object.keys(p.valuations).length && !status(p,'B04') && !status(p,'D03') && (state.config.statusLinks!==1 || !status(p,'D24'));
  return true;
}

export function pickBacklash(state:AppraisalState,p:Appraiser):EventId {
  const weights=[3,2,1+Math.floor((state.encounter-1)/3)];
  const total=weights.reduce((a,b)=>a+b,0);
  let roll=randomAt(state.seed,`${state.encounter}:${p.id}:backlash:pick`)*total;
  for(const [index,weight] of weights.entries()){roll-=weight;if(roll<0)return CORE2_BACKLASH_IDS[index]!;}
  return CORE2_BACKLASH_IDS[0]!;
}

export function resolveCore2Event(state:AppraisalState,p:Appraiser,offer:EventOffer,command:Extract<AppraisalAction,{type:'event'}>):void {
  const spec=CORE2_SPECS[offer.id]!;const choice=command.choice;
  const picked:Core2Choice|undefined=choice===FALLBACK_BRAND.id?FALLBACK_BRAND:core2Choices(offer.id,state.config).find(c=>c.id===choice);
  check(picked,'event-choice','ไม่มีตัวเลือกนี้');
  if(choice!=='decline' && choice!==FALLBACK_BRAND.id)check(state.config.systemLinks===1?core2EventChoices(state,p,offer.id).includes(choice):affordable(state,p,picked),'event-cost','จ่ายตัวเลือกนี้ไม่ไหวแล้ว');
  if(picked.lose){
    check(command.itemId && offer.itemIds.includes(command.itemId),'event-target','เลือกสินค้าที่จะสละ');
    penaltyItem(state,p,command.itemId);
  }
  const victim=picked.toVictim && p.theft?.victim?state.players.find(v=>v.id===p.theft!.victim):undefined;
  if(picked.credits){
    if(victim)transfer(state,p,victim,picked.credits,spec.id);else spend(state,p,picked.credits,0,spec.id);
  }
  if(picked.energy)spend(state,p,0,picked.energy,spec.id);
  if(picked.life)damageLife(state,p,picked.life,spec.id,false);
  if(picked.heal){if(state.config.survival)healLife(state,p,picked.heal,spec.id);else recover(state,p,3,spec.id);}
  if(picked.reward)reward(state,p,picked.reward,spec.id);
  for(const s of picked.grant??[])grant(state,p,s);
  if(picked.gamble){
    const won=randomAt(state.seed,`${offer.key}:gamble`)<picked.gamble.chance;
    for(const s of won?picked.gamble.win:picked.gamble.lose)grant(state,p,s);
    p.notes.push(won?`${spec.name}: ได้ผลดี`:`${spec.name}: ผลข้างเคียงร้าย`);
    trace(state,p,'core2-gamble',{id:spec.id,won});
  }
  if(picked.door)p.portals.forEach((portal,index)=>{if(index===(picked.door==='first'?1:0))portal.disabled=true;});
  if(picked.deal)p.dealMode=picked.deal;
  if(spec.consequence){delete p.inflated;delete p.theft;}
  p.notes.push(`${spec.name}: ${choice}`);p.notes=p.notes.slice(-30);
  trace(state,p,'core2-event',{id:spec.id,choice});
}

export function applyDread(state:AppraisalState,p:Appraiser):void {
  if(!state.config.core2 || !state.config.survival || p.life===0 || p.paused==='dead')return;
  const chance=dreadNow(state,p);
  if(randomAt(state.seed,`${state.encounter}:${p.id}:dread`)>=chance)return;
  const movable=p.inventory.filter(id=>unlocked(p,id));
  const pool=dreadKinds(state.encounter,true,movable.length>0);
  const kind=pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:dread:kind`)*pool.length)]!;
  switch(kind) {
    case 'storm': damageLife(state,p,1,'dread-storm');note(p,'พายุมิติซัดใส่: เสียชีวิต 1');break;
    case 'tax': {const paid=Math.min(p.credits,dreadTax(state.encounter));if(paid)spend(state,p,paid,0,'dread-tax');note(p,`ผู้เก็บภาษีเงาบุกโต๊ะ: เสียเครดิต ${paid}`);break;}
    case 'rot': {
      const itemId=movable[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:dread:item`)*movable.length)]!;
      if(status(p,'B07')){consumeStatus(p,'B07');note(p,'ของเกือบถูกยึด แต่กรมธรรม์พ่อค้าคุ้มครองไว้');}
      else {const name=ITEM_SPECS[state.items[itemId]!.kind].name;retire(state,p,itemId,'dread-rot',false);note(p,`${name}ผุพังหายไปในความมืด`);}
      break;
    }
    case 'wound': if(status(p,'D20')){recover(state,p,0,'dread');p.energy=Math.max(0,p.energy-2);note(p,'แผลเก่าเปิดซ้ำ: เสียพลัง 2');}else {grant(state,p,'D20');note(p,'แผลเปิด: ความเสียหายถัดไปหนักขึ้น 1');}break;
    case 'fatigue': {const lost=Math.min(2,p.energy);p.energy-=lost;note(p,`ความอ่อนล้าจากมิติ: เสียพลัง ${lost}`);break;}
  }
  trace(state,p,'dread-hit',{kind,chance});
}

export function applyOmenPressure(state:AppraisalState,p:Appraiser):void {
  const omen=omenNow(state);
  if(!state.config.core2 || !omen || p.paused==='dead' || p.life===0)return;
  if(omen.settleLife && state.config.survival){damageLife(state,p,omen.settleLife,'omen');note(p,`${omen.name}: เสียชีวิต ${omen.settleLife}`);}
  if(omen.taxPct){const paid=Math.floor(p.credits*omen.taxPct/100);if(paid){spend(state,p,paid,0,'omen-tax');note(p,`${omen.name}: ภาษีเงา ${paid} เครดิต`);}}
}

export function applyCore2Settlement(state:AppraisalState,p:Appraiser):void {
  if(p.paused==='dead' || state.config.survival && p.life===0)return;
  if(status(p,'D22')){const paid=Math.min(3,p.credits);if(paid)spend(state,p,paid,0,'torn-pouch');consumeStatus(p,'D22');note(p,`กระเป๋าฉีก: เสียเครดิต ${paid}`);}
  if(status(p,'D23')){
    consumeStatus(p,'D23');
    if(state.config.survival){damageLife(state,p,1,'bleeding');note(p,'เลือดไหลไม่หยุด: เสียชีวิต 1');}
    else {p.energy=Math.max(0,p.energy-2);note(p,'เลือดไหลไม่หยุด: เสียพลัง 2');}
  }
  applyOmenPressure(state,p);
  if(state.config.survival && p.life===0)return;
  if(status(p,'B24')){
    consumeStatus(p,'B24');
    if(state.config.survival && p.life!==undefined){healLife(state,p,1,'blessing');note(p,'พรปลอบชีพ: ฟื้นชีวิต 1');}
    else {recover(state,p,2,'blessing',true);note(p,'พรปลอบชีพ: ฟื้นพลัง 2');}
  }
}

