CORE2={
  /** Survival: the encounter after which the Collector arrives whoever is still alive. */
  collectorEncounter:15,
  /** Survival decay: 1 life per encounter, plus 1 more for every `decayEvery` encounters past the first, up to `decayCap`. */
  decayEvery:7,decayCap:3,
  /** Chance per living seat per encounter of a dread affliction at settlement: base + step per encounter, capped. */
  dread:{base:.08,step:.03,cap:.6},
  /** An appraisal at or above this multiple of the merchant's asking price may draw a backlash (and is then refused). */
  overvalue:{ratio:2,base:.5,step:.25,cap:.95},
  /** Buying this many goods other seats appraised refunds energy, at most `cap` times per encounter. */
  scrap:{need:2,energy:3,cap:2},
  /** Consigning an unsold appraisal pays this share of its real value (fake and cursed goods are worth less), minus a flat fee. */
  consign:{percent:80,fee:3,cleanBelow:.3,debuffBelow:.7,extraFee:4},
  /** Restoratives (food and potions) heal life in survival, so they cost what the life is worth. */
  restorativePremium:7,
  /** Credits added to a recovery deal for every `step` encounters past the first. */
  recoveryStep:4,
  /** Rerolling a merchant door costs `energy` for the first reroll of an encounter and `step` more for every reroll after it. */
  reroll:{energy:2,step:1},
  /** Theft and barter. */
  steal:{energy:1,base:.5,perTrust:.03,friend:-.15},
  barter:{energy:1,detect:.35},
  /** Merchant skills unlock at this trust and are stronger from `strong`. */
  skill:{trust:3,strong:6},
} as const

export function anchorOf(config:Pick<AppraisalConfig,'core2'|'survival'>,kind:ItemKind):number {
  const spec=ITEM_SPECS[kind];
  if(!config.core2)return spec.anchor;
  const tier=!!spec.buff && WEAK_BUFFS.includes(spec.buff)?.85:!!spec.buff && STRONG_BUFFS.includes(spec.buff)?1.15:1;
  const healing=!!config.survival && ['food','potion'].includes(itemFamily(kind))?CORE2.restorativePremium:0;
  return Math.max(4,Math.round(spec.anchor*tier)+healing);
}

export function overvalueChance(value:number,ask:number):number {
  if(ask<=0 || value<ask*CORE2.overvalue.ratio)return 0;
  const {base,step,cap}=CORE2.overvalue;return Math.min(cap,base+step*(value/ask-CORE2.overvalue.ratio));
}

export function dreadKinds(encounter:number,survival:boolean,hasItems:boolean):Dread[] {
  const pool:Dread[]=['tax','fatigue','tax',survival?'storm':'fatigue','wound'];
  if(hasItems && encounter>=3)pool.push('rot');
  if(survival && encounter>=5)pool.push('storm','storm');
  return pool;
}

function validateConfig(config:AppraisalConfig):void {
  check(config.personalScoringRules===undefined||config.personalScoringRules===1,'config','กติกาคะแนนผลงานไม่ถูกต้อง');
  check(config.personalScoringFacts===undefined||config.personalScoringFacts===2,'config','รุ่นตัวบันทึกคะแนนไม่ถูกต้อง');
  check(config.personalScoringFacts===undefined||config.personalScoringRules===1,'config','ตัวบันทึกคะแนนต้องเปิดกติกาคะแนน');
  check(config.personalScoringFacts!==2||!!config.survival&&(!config.secureEconomy||config.loanEndSettlement===true),'config','คะแนนผลงานต้องใช้ Survival และปิดหนี้ก่อน Collector');
  check(config.collectorWishlistRules===undefined||config.collectorWishlistRules===1,'config','กติกา Collector ไม่ถูกต้อง');
  if(config.rarityEconomy!==undefined){validateRarityEconomy(config.rarityEconomy);check(!!config.rarity,'config','Rarity economy requires rarity generation');}
  if(config.rarity!==undefined)validateRarityConfig(config.rarity);
  check(config.secureEconomy===undefined || typeof config.secureEconomy==='boolean','config','กติกาคลังและสัญญาไม่ถูกต้อง');
  check(config.eventChoiceRules===undefined || config.eventChoiceRules===1,'config','กติกาตัวเลือกเหตุการณ์ไม่ถูกต้อง');
  check(config.statusLinks===undefined || config.statusLinks===1,'config','กติกาเชื่อมสถานะไม่ถูกต้อง');
  check(config.systemLinks===undefined || config.systemLinks===1,'config','กติกาเชื่อมระบบไม่ถูกต้อง');
  check(config.theftTimeoutRules===undefined || config.theftTimeoutRules===1,'config','กติกาหมดเวลาเป่ายิ้งฉุบไม่ถูกต้อง');
  check(config.vaultInterestRules===undefined || config.vaultInterestRules===1,'config','กติกาดอกเบี้ยไม่ถูกต้อง');
  check(config.loanEndSettlement===undefined || typeof config.loanEndSettlement==='boolean','config','กติกาปิดสัญญากู้ตอนจบไม่ถูกต้อง');
  check(config.collectorDeadline===undefined || Number.isSafeInteger(config.collectorDeadline) && config.collectorDeadline>=1 && config.collectorDeadline<=100,'config','ช่วงที่ Collector มาไม่ถูกต้อง');
  check(config.trustAbilities===undefined || typeof config.trustAbilities==='boolean','config','กติกาความสามารถพ่อค้าไม่ถูกต้อง');
  check(config.itemEffects===undefined || typeof config.itemEffects==='boolean','config','กติกาผลสินค้าไม่ถูกต้อง');
  check(config.npcEvents===undefined || typeof config.npcEvents==='boolean','config','กติกาอีเวนต์เฉพาะพ่อค้าไม่ถูกต้อง');
  check(config.core2===undefined || typeof config.core2==='boolean','config','กติกาแกนเกมใหม่ไม่ถูกต้อง');
  check(config.commerce===undefined || typeof config.commerce==='boolean','config','กติกาการค้าไม่ถูกต้อง');
  check(config.totalTrustStock===undefined || typeof config.totalTrustStock==='boolean','config','กติกาโบนัสความไว้ใจรวมไม่ถูกต้อง');
  check(config.polish===undefined || typeof config.polish==='boolean','config','กติกาขัดเกลาไม่ถูกต้อง');
  check(config.expansion===undefined || typeof config.expansion==='boolean','config','กติกาส่วนขยายไม่ถูกต้อง');
  check(config.challenge===undefined || typeof config.challenge==='boolean','config','กติกาท้าทายคำระบุไม่ถูกต้อง');
  check(config.wishContract===undefined || typeof config.wishContract==='boolean','config','กติกาสัญญาตามหาของไม่ถูกต้อง');
  check(config.wishlist===undefined || typeof config.wishlist==='boolean','config','กติกาของที่พ่อค้าตามหาไม่ถูกต้อง');
  check(config.cleanse===undefined || typeof config.cleanse==='boolean','config','กติกาล้างคำสาปไม่ถูกต้อง');
  check(config.fakeEffect===undefined || typeof config.fakeEffect==='boolean','config','กติกาผลของปลอมไม่ถูกต้อง');
  check(config.freeMerchantAction===undefined || typeof config.freeMerchantAction==='boolean','config','กติกาสิทธิ์ฟรีประจำสินค้าไม่ถูกต้อง');
  check(config.freeBuy===undefined || typeof config.freeBuy==='boolean','config','กติกาซื้อฟรีพลังไม่ถูกต้อง');
  check(config.curseSight===undefined || typeof config.curseSight==='boolean','config','กติกาตรวจคำสาปไม่ถูกต้อง');
  check(config.multiCoinRewards===undefined || typeof config.multiCoinRewards==='boolean','config','กติกาทบเหรียญไม่ถูกต้อง');
  check(config.roundRewards===undefined || typeof config.roundRewards==='boolean','config','กติการางวัลจบรอบไม่ถูกต้อง');
  check(config.catalogVersion===undefined || config.catalogVersion===1 || config.catalogVersion===2 || config.catalogVersion===3 || config.catalogVersion===4,'config','เวอร์ชันคลังสินค้าไม่ถูกต้อง');
  for(const key of ['encounters','startingCredits','maxEnergy','recoveryEnergy','bankReserve','marketMaxOrders','marketQuota'] as const)
    check(Number.isSafeInteger(config[key]) && config[key]>=0 && config[key]<=10000,'config',`ค่า ${key} ไม่ถูกต้อง`);
  check(config.encounters>=1 && config.encounters<=10 && config.maxEnergy>=1 && config.recoveryEnergy>=1 && config.recoveryEnergy<=config.maxEnergy,'config','จำนวน encounter หรือพลังไม่ถูกต้อง');
  check(Number.isFinite(config.marketProbability) && config.marketProbability>=0 && config.marketProbability<=1 && config.marketMaxOrders>=1 && config.marketQuota>=1,'config','การสุ่มตลาดไม่ถูกต้อง');
  check(config.survival===undefined || !!config.survival && typeof config.survival==='object' && !Array.isArray(config.survival),'config','กติกาชีวิตไม่ถูกต้อง');
  if(config.survival){
    const rules=config.survival;
    check(Object.keys(rules).length===3 && ['maxLife','encounterLifeCost','entryEnergyCost'].every(key=>Number.isSafeInteger(rules[key as keyof typeof rules])),'config','กติกาชีวิตไม่ถูกต้อง');
    check(rules.maxLife>=1 && rules.maxLife<=100 && rules.encounterLifeCost>=1 && rules.encounterLifeCost<=rules.maxLife && rules.entryEnergyCost>=0 && rules.entryEnergyCost<=config.maxEnergy,'config','ค่าชีวิตหรือต้นทุนเริ่มรอบไม่ถูกต้อง');
  }
  if(config.brokerage!==undefined){
    const rules=config.brokerage;
    check(!!rules && typeof rules==='object' && !Array.isArray(rules) && Object.keys(rules).length===3,'config','กติกานายหน้าไม่ถูกต้อง');
    check([rules.auctionProbability,rules.bondProbability].every(v=>Number.isFinite(v) && v>=0 && v<=1) && Number.isSafeInteger(rules.maxLots) && rules.maxLots>=1 && rules.maxLots<=4,'config','กติกานายหน้าไม่ถูกต้อง');
  }
}

export function createAppraisalRun(playerIds:string[],seed:string,overrides:Partial<AppraisalConfig>={}):AppraisalState {
  return initialiseAppraisalRun(playerIds,seed,structuredClone({...DEFAULT_APPRAISAL_CONFIG,...overrides,...(overrides.personalScoringRules===1&&overrides.personalScoringFacts===undefined?{personalScoringFacts:2 as const}:{}),...(overrides.catalogVersion!==undefined&&overrides.catalogVersion<3&&overrides.trustAbilities===undefined?{trustAbilities:false}:{})}));
}

export function restoreAppraisalRun(playerIds:string[],seed:string,config:AppraisalConfig):AppraisalState {
  return initialiseAppraisalRun(playerIds,seed,structuredClone(config));
}

function initialiseAppraisalRun(playerIds:string[],seed:string,config:AppraisalConfig):AppraisalState {
  check(playerIds.length>=2 && playerIds.length<=4 && new Set(playerIds).size===playerIds.length && playerIds.every(id=>typeof id==='string' && /^[a-zA-Z0-9_-]{1,64}$/.test(id) && !['bank','__proto__','constructor','prototype'].includes(id)),'players','ต้องมีผู้เล่น 2–4 คนและ ID ไม่ซ้ำ');
  check(typeof seed==='string' && seed.length>0 && seed.length<=256,'seed','seed ไม่ถูกต้อง');
  check(config && typeof config==='object','config','กติกาไม่ถูกต้อง'); validateConfig(config);
  const state:AppraisalState={version:config.survival?5:4,seed,config,encounter:1,phase:'PORTALS',revision:0,players:[],items:{},schedule:{},bank:config.bankReserve,reservedRewards:0,market:{encounter:1,open:false,budget:0,orders:[]},listings:[],publicKnowledge:{},trades:[],ledger:[],trace:[],history:[],accepted:{},commands:[]};
  if(config.personalScoringRules===1)state.personalPerformance={version:1,facts:[]};
  if(config.brokerage) state.vault=[];
  if(config.secureEconomy){state.loans=[];state.theftDuels=[];}
  playerIds.forEach((id,seat)=>{
    const schedule:Portal[][]=[];
    for(let encounter=1;encounter<=(config.survival?1:config.encounters);encounter++) {
      schedule.push(generatePortals(state,id,seat,encounter));
    }
    state.schedule[id]=schedule;
    state.players.push({id,credits:config.startingCredits,energy:config.maxEnergy,inventory:[],statuses:[],paused:null,done:false,portals:structuredClone(schedule[0]!),selectedPortalId:null,stock:[],knowledge:{},valuations:{},inspections:0,counters:0,activated:[],score:0,startWealth:config.startingCredits,accuracyBonus:0,eventOffer:null,seenEvents:[],resolvedEvents:[],offerSlots:0,consequenceSlots:0,honorJob:false,honestyReward:null,acceptedDanger:false,caught:false,subsidy:false,revealedInfo:[],dealMode:'any',notes:[],...(passivesEnabled(config)?{passiveUses:{}}:{}),...(config.commerce?{npcTrust:{}}:{}),...(config.cleanse?{cleansed:[]}:{}),...(config.wishlist?{wishes:{},wishTried:false}:{}),...(config.wishContract?{wishRolls:0}:{}),...(config.survival?{life:config.survival.maxLife,recoveryUsed:false}:{})});
  });
  if(config.secureEconomy)for(const p of state.players)p.personalVault={items:[],credits:0,slots:2};
  if(config.survival)for(const p of state.players)spend(state,p,0,Math.min(p.energy,config.survival.entryEnergyCost),'encounter-entry');
  state.market=makeMarket(state);
  for(const p of state.players) if(randomAt(seed,`${state.encounter}:${p.id}:entry-event`)<.55) drawEvent(state,p);
  for(const p of state.players)p.journal=[{id:0,encounter:1,phase:'PORTALS',action:'เริ่มการเดินทาง',cause:'ทรัพยากรตั้งต้นของห้อง',changes:[`เครดิต +${p.credits}`,`พลัง +${p.energy}`,...(p.life!==undefined?[`ชีวิต +${p.life}`]:[])]}];
  reconcileCollectorWishlist(state);assertAppraisalInvariants(state); return state;
}

function spawnStockItem(state:AppraisalState,id:string,seat:number,encounter:number,index:number|string,slot:number,npc:NpcId):string {
  const {seed,config}=state;let favorites=merchantKinds(npc,config.catalogVersion??1,!!config.cleanse,!!config.challenge,expansionActive(config),!!config.polish,!!config.trustAbilities);
  if(config.trustAbilities){const offered=new Set(Object.values(state.items).filter(i=>i.npcOwnerId===id&&i.encounter===encounter&&i.npc===npc&&i.owner.startsWith('npc:')).map(i=>i.kind));const fresh=favorites.filter(kind=>!offered.has(kind));if(fresh.length)favorites=fresh;}
  const itemId=`item-${encounter}-${seat}-${index}-${slot}`;
  const kind=favorites[Math.floor(randomAt(seed,`${itemId}:kind`)*favorites.length)]!;
  const anchor=anchorOf(config,kind);const range=priceRange(kind,anchor); const base=range[0]+Math.floor(randomAt(seed,`${itemId}:base`)*(range[1]-range[0]+1));
  const reservation=NPC_SPECS[npc].reservation;
  const ask=Math.max(1,anchor-2+Math.floor(randomAt(seed,`${itemId}:ask`)*6));
  const minimum=Math.ceil(base*(reservation[0]+(reservation[1]-reservation[0])*randomAt(seed,`${itemId}:reservation`)));
  state.items[itemId]={
    id:itemId,kind,base,ask,genuine:randomAt(seed,`${itemId}:genuine`)<.75,
    cursed:randomAt(seed,`${itemId}:curse`)<.35,owner:`npc:${id}:${encounter}`,
    npcOwnerId:id,npc,encounter,certificate:randomAt(seed,`${itemId}:certificate`)<.65,
    lastAppraisal:null,lastAccepted:null,reservation:Math.min(ask,Math.max(1,minimum)),
    ...(slot>=2?{bonus:true}:{}),
  };
  return itemId;
}

function generatePortals(state:AppraisalState,id:string,seat:number,encounter:number):Portal[] {
      const {seed,config}=state;const npcIds=activeNpcs(config);
      const npcs=npcIds.map(npc=>({npc,rank:randomAt(seed,`${encounter}:${seat}:${npc}:portal`)})).sort((a,b)=>a.rank-b.rank).slice(0,3);
      const portals=npcs.map(({npc},index)=>{
        const stock:string[]=[];
        for(let slot=0;slot<2;slot++) stock.push(spawnStockItem(state,id,seat,encounter,index,slot,npc));
        return {id:`portal-${encounter}-${seat}-${index}`,npc,stock,disabled:false};
      });return portals;
}

function rerollPortal(state:AppraisalState,p:Appraiser,portalId:string):void {
  check(state.config.core2 && state.phase==='PORTALS' && !p.eventOffer && !p.selectedPortalId,'reroll','รีประตูได้เฉพาะตอนเลือกประตู');
  const index=p.portals.findIndex(v=>v.id===portalId);const old=p.portals[index];
  check(old && !old.disabled,'portal','ประตูนี้รีไม่ได้');
  const shown=new Set(p.portals.map(v=>v.npc));
  const unseen=activeNpcs(state.config).filter(npc=>!shown.has(npc));
  const pool=unseen.length?unseen:activeNpcs(state.config).filter(npc=>npc!==old.npc);
  check(pool.length,'reroll','ไม่มีพ่อค้าให้เปลี่ยน');
  const done=p.portalRerolls??0,cost=pilotRerollCost(state,p,rerollCost(done));spend(state,p,0,cost,'portal-reroll');
  const seat=state.players.indexOf(p);const tag=`${index}r${done+1}`;
  const npc=pool.map(npc=>({npc,rank:randomAt(state.seed,`${state.encounter}:${seat}:${npc}:portal:reroll${done+1}`)})).sort((a,b)=>a.rank-b.rank)[0]!.npc;
  const stock=[0,1].map(slot=>spawnStockItem(state,p.id,seat,state.encounter,tag,slot,npc));
  p.portals[index]={id:`portal-${state.encounter}-${seat}-${tag}`,npc,stock,disabled:false};
  p.portalRerolls=done+1;trace(state,p,'portal-rerolled',{from:old.npc,to:npc,energy:cost});
}

function makeMarket(state:AppraisalState):DarkMarket {
  const market:DarkMarket={encounter:state.encounter,open:false,budget:0,orders:[]};
  // Vault auctions roll independently of the sell-order market.
  if(state.config.brokerage) market.lots=auctionLots(state);
  if(!(state.config.core2 && omenNow(state)?.marketOpen) && randomAt(state.seed,`${state.encounter}:market:open`)>=state.config.marketProbability) return market;
  const pool=[...new Set(publicOfferItems(state).map(item=>item.kind))];
  const count=1+Math.floor(randomAt(state.seed,`${state.encounter}:market:count`)*Math.min(pool.length,state.config.marketMaxOrders));
  const ranked=pool.map(kind=>({kind,rank:randomAt(state.seed,`${state.encounter}:market:${kind}:rank`)})).sort((a,b)=>a.rank-b.rank);
  const orderFor=(kind:ItemKind)=>{
    const price=Math.round(anchorOf(state.config,kind)*(1.25+.5*randomAt(state.seed,`${state.encounter}:market:${kind}:price`)));
    const order={id:`quote-${state.encounter}-${kind}`,kind,price,...(state.config.rarityEconomy?{rarityReserveMultiplier:Math.max(...Object.values(state.config.rarityEconomy.tiers).map(t=>t.value))}:{}),quota:Object.fromEntries(state.players.map(p=>[p.id,state.config.marketQuota])),...(state.config.commerce?{contract:makeMarketContract(key=>randomAt(state.seed,`${state.encounter}:market:${kind}:contract:${key}`),!!state.config.survival)}:{})};
    return {order,reserved:marketOrderReserve(order)*state.config.marketQuota*state.players.length};
  };
  const free=state.bank-state.reservedRewards;
  // The market opens every encounter, so it may only hold half of the free bank: the rest stays for event and sale rewards promised meanwhile.
  const cap=Math.floor(free*MARKET_BANK_SHARE);
  for(const {kind} of ranked.slice(0,count)) {const {order,reserved}=orderFor(kind);if(market.budget+reserved>cap)continue;market.orders.push(order);market.budget+=reserved;}
  // Every drawn quote too dear for the cap: open with the cheapest quote the bank can still back, so the market never skips an encounter while the bank has money.
  if(!market.orders.length){const cheapest=ranked.map(({kind})=>orderFor(kind)).sort((a,b)=>a.reserved-b.reserved)[0];if(cheapest && cheapest.reserved<=free){market.orders.push(cheapest.order);market.budget+=cheapest.reserved;}}
  market.open=market.orders.length>0; return market;
}

function pauseIfNeeded(state:AppraisalState,p:Appraiser):void {
  if(state.config.secureEconomy && p.life!==0 && state.theftDuels?.some(d=>d.status==='open' && [d.thiefId,d.victimId].includes(p.id)))return;
  if(!state.config.survival && p.energy===0 && !p.paused && !(state.config.freeMerchantAction && (p.selectedPortalId===null || p.stock.some(id=>merchantActionFree(state,p,id))))) {
    // Settle a previously accepted risk before energy exhaustion removes action rights.
    if(p.eventOffer && isConsequence(p.eventOffer.id)) defaultEvent(state,p);
    if(!p.paused) { p.paused='exhausted'; p.done=true; p.eventOffer=null; trace(state,p,'exhausted'); }
  }
  if(p.paused) {p.done=true;p.eventOffer=null;}
}

function settleEncounter(state:AppraisalState):void {
  if(state.config.brokerage) {for(const p of state.players) settleRemainingUnsold(state,p);settleAuction(state);}
  for(const p of state.players) {
    if(state.config.survival && p.life===0){
      if(p.subsidy){p.subsidy=false;state.reservedRewards--;}
      state.history.push({encounter:state.encounter,playerId:p.id,gain:0,accuracy:0,score:0,paused:'dead'});continue;
    }
    if(status(p,'D05')) {p.energy=Math.max(0,p.energy-integerEffect(statusMagnitude(p,'D05',2)));consumeStatus(p,'D05');trace(state,p,'breath-drain');}
    if(status(p,'D11')) {p.energy=Math.max(0,p.energy-integerEffect(statusMagnitude(p,'D11',1)));consumeStatus(p,'D11');trace(state,p,'swarm-venom');}
    if(omenNow(state)?.settleEnergy) {p.energy=Math.max(0,p.energy-omenNow(state)!.settleEnergy!);trace(state,p,'omen-plague');}
    if(state.config.core2) applyCore2Settlement(state,p);
    pauseIfNeeded(state,p);
    const gain=Math.max(0,wealth(state,p)-p.startWealth);
    const score=state.config.survival?0:p.paused==='dead'?0:gain+p.accuracyBonus;
    p.score+=score; state.history.push({encounter:state.encounter,playerId:p.id,gain,accuracy:p.accuracyBonus,score,paused:p.paused});
    if(p.subsidy) {p.subsidy=false;state.reservedRewards--;}
    if(state.config.survival && p.life!>0 && state.config.core2) applyDread(state,p);
    if(state.config.survival && p.life!>0){damageLife(state,p,state.config.core2?decayFor(state.encounter):state.config.survival.encounterLifeCost,'dimensional-decay');if(p.life!>0)mendWithShards(state,p);}
    if(state.config.survival&&p.life!>0)recordPersonalActivity(state,p,'survived',1,String(state.encounter));
  }
  state.market.open=false; state.market.budget=0;
  for(const offer of state.trades) if(offer.status==='open') offer.status='rejected';
  if(state.config.survival && (state.players.every(p=>p.life===0) || collectorDue(state)))collectRun(state);
  else {state.phase='REVEAL';openRoundRewards(state);}
  if(state.config.secureEconomy)cancelTheftDuels(state);
}

function progress(state:AppraisalState):void {
  let moves=0;
  while(moves++<4 && state.players.every(p=>p.done || !!p.paused)) {
    if(state.phase==='PORTALS') {
      state.phase='APPRAISAL';
      for(const p of state.players) { p.done=!!p.paused || !p.stock.length; if(!p.done && !drawPersonalNpcEvent(state,p) && !drawBondEvent(state,p) && !drawWishEvent(state,p) && !drawExpansionEvent(state,p) && !drawPolishEvent(state,p)) drawEvent(state,p); }
    } else if(state.phase==='APPRAISAL') {
      state.phase='TRADE';
      for(const p of state.players) {p.done=!!p.paused; if(!p.done && !drawExpansionEvent(state,p) && !drawPolishEvent(state,p)) drawEvent(state,p);}
    } else if(state.phase==='TRADE') { settleEncounter(state); break; }
    else break;
  }
}

function npcActionAllowed(state:AppraisalState,p:Appraiser):void {
  check(state.phase==='APPRAISAL','phase','ยังไม่ใช่ช่วงประเมิน'); check(!p.eventOffer,'event-pending','เลือกผล event ก่อน');
}

function share(state:AppraisalState,p:Appraiser,itemId:string,allow:boolean,purchaseAllowed:boolean,claims?:Claims,rebate=0):void {
  const item=state.items[itemId];
  check(item && (item.owner===p.id || p.stock.includes(itemId)),'owner','เปิดได้เฉพาะรายการของตน');
  check(!purchaseAllowed || (item.owner===p.id ? unlocked(p,itemId) : !!p.valuations[itemId]),'listing','ต้องประเมินสินค้าหรือปลดล็อกก่อนเปิดให้ซื้อ');
  const stated=claims && Object.keys(claims).length?{...(claims.genuine!==undefined?{genuine:claims.genuine}:{}),...(claims.cursed!==undefined?{cursed:claims.cursed}:{})}:undefined;
  // An appraiser may state facts they never checked: that is exactly what a buyer can challenge.
  check(!stated || (state.config.challenge && item.owner.startsWith('npc:') && allow && purchaseAllowed),'claims','ระบุข้อมูลได้เฉพาะสินค้าร้านที่ประกาศขายและประเมินแล้ว');
  check(Number.isSafeInteger(rebate) && rebate>=0 && rebate<=1000 && (rebate===0 || allow && purchaseAllowed && p.credits>=rebate),'rebate','ค่าแถมต้องเป็นจำนวนเต็ม 0–1000 เปิดขายอยู่ และเจ้าของต้องมีเครดิตพอ');
  state.listings=state.listings.filter(l=>l.itemId!==itemId);
  if(allow) state.listings.push({ownerId:p.id,itemId,purchase:purchaseAllowed,...(stated?{claims:stated}:{}),...(rebate?{rebate}:{})});
  trace(state,p,'listing-shared',{itemId,allow,purchase:purchaseAllowed,...(stated?{claims:stated}:{}),...(rebate?{rebate}:{})});
}

function propose(state:AppraisalState,p:Appraiser,action:Extract<AppraisalAction,{type:'propose'}>):void {
  const seller=player(state,action.sellerId);
  check(seller.id!==p.id && !seller.paused && !seller.done,'seller','เจ้าของยังไม่พร้อมต่อรอง');
  const listing=state.listings.find(l=>l.ownerId===seller.id && l.itemId===action.itemId && l.purchase);
  check(listing,'listing','เจ้าของยังไม่เปิดให้ซื้อ');
  check(Number.isSafeInteger(action.credits) && action.credits>=0 && action.credits<=1000 && p.credits>=action.credits,'price','credit ที่เสนอไม่ถูกต้อง');
  const item=state.items[action.itemId]!; const source=item.owner.startsWith('npc:')?'npc':'inventory';
  if(source==='inventory') ownedItem(state,seller,item.id,true); else stockItem(state,seller,item.id);
  if(source==='npc') check(seller.dealMode!=='condition' || action.condition===true,'condition','ต้องยอมรับเงื่อนไขร้านนี้');
  if(action.challenge!==undefined) {
    const claim=listing.claims?.[action.challenge];
    check(state.config.challenge && source==='npc' && claim!==undefined,'challenge','ท้าทายได้เฉพาะคำระบุที่ผู้ประเมินให้ไว้');
    const quote=npcQuote(seller,item);check(p.credits>=action.credits+quote+challengePenalty(quote),'credits','เครดิตไม่พอสำหรับราคา ค่าแนะนำ และค่าปรับถ้าท้าทายผิด');
    if(action.sealId!==undefined) {check(ownedItem(state,p,action.sealId,true).kind==='void-seal','challenge','ของที่เลือกไม่ใช่ตราโมฆะ');}
  } else check(action.sealId===undefined,'challenge','ตราโมฆะใช้ได้กับการท้าทายเท่านั้น');
  if(action.swapItemId) {check(source==='inventory','swap','ร้าน NPC รับค่าแนะนำเป็น credit เท่านั้น');ownedItem(state,p,action.swapItemId,true);}
  check(state.trades.filter(o=>o.status==='open' && o.buyerId===p.id).length<8,'offers','มีข้อเสนอค้างมากเกินไป');
  state.trades.push({id:`trade-${state.encounter}-${p.id}-${action.requestId}`,buyerId:p.id,sellerId:seller.id,itemId:item.id,swapItemId:action.swapItemId??null,credits:action.credits,source,encounter:state.encounter,status:'open',condition:action.condition===true,...(action.challenge!==undefined?{challenge:action.challenge}:{}),...(action.sealId!==undefined?{sealId:action.sealId}:{})});
}

function forceBuy(state:AppraisalState,p:Appraiser,action:Extract<AppraisalAction,{type:'force-buy'}>):void {
  const seller=player(state,action.sellerId);
  check((p.darkTickets??0)>=TRUST_RULES.ticketsToForce,'tickets',`ต้องมีตั๋วคำสั่งมืด ${TRUST_RULES.ticketsToForce} ใบ`);
  check(seller.id!==p.id && seller.paused!=='dead','seller','บังคับซื้อจากเจ้าของนี้ไม่ได้');
  check(state.listings.some(l=>l.ownerId===seller.id && l.itemId===action.itemId),'listing','เจ้าของยังไม่เปิดรายการนี้');
  const item=stockItem(state,seller,action.itemId);
  const rebate=state.listings.find(l=>l.itemId===action.itemId)?.rebate;
  check(!!seller.valuations[item.id],'appraisal','บังคับซื้อได้เฉพาะของที่ประเมินแล้ว');
  if(state.config.survival){linkTrade(p,seller.id,state.encounter);linkTrade(seller,p.id,state.encounter);}
  p.darkTickets=p.darkTickets!-TRUST_RULES.ticketsToForce;
  purchase(state,p,seller,[item.id],{condition:seller.dealMode==='condition'});
  const rebated=payRebate(state,seller,p,rebate,false);p.paid={...p.paid,[item.id]:Math.max(0,(p.paid?.[item.id]??0)-rebated)};
  state.listings=state.listings.filter(l=>l.itemId!==item.id);
  const note=`ใช้ตั๋วคำสั่งมืดบังคับซื้อ ${ITEM_SPECS[item.kind].name} ตามราคาประเมิน`;
  p.notes.push(note);p.notes=p.notes.slice(-30);
  seller.notes.push(`${ITEM_SPECS[item.kind].name}ถูกบังคับซื้อด้วยตั๋วคำสั่งมืด ตามราคาประเมิน`);seller.notes=seller.notes.slice(-30);
  trace(state,p,'forced-purchase',{itemId:item.id,sellerId:seller.id,tickets:p.darkTickets});
}

function respond(state:AppraisalState,p:Appraiser,offerId:string,accept:boolean):void {
  const offer=state.trades.find(o=>o.id===offerId);
  check(offer && offer.encounter===state.encounter && offer.status==='open' && offer.sellerId===p.id,'offer','ข้อเสนอหมดอายุหรือไม่ใช่ของคุณ');
  if(!accept) {offer.status='rejected';return;}
  const buyer=player(state,offer.buyerId); check(!buyer.paused && !buyer.done,'buyer','ผู้ซื้อยังไม่พร้อม');
  const listing=state.listings.find(l=>l.itemId===offer.itemId && l.ownerId===p.id && l.purchase);
  check(listing,'listing','รายการไม่เปิดแล้ว');
  check(p.credits+offer.credits>=(listing.rebate??0),'rebate','เครดิตเจ้าของไม่พอจ่ายค่าแถม');
  if(state.config.survival){linkTrade(p,buyer.id,state.encounter);linkTrade(buyer,p.id,state.encounter);}
  let penalty=0;
  if(offer.source==='npc') {
    const settled=offer.challenge?settleChallenge(state,buyer,p,offer):{discount:0,penalty:0};penalty=settled.penalty;
    purchase(state,buyer,p,[offer.itemId],{condition:offer.condition,...(settled.discount?{discount:settled.discount}:{})});
  }
  else {
    const item=ownedItem(state,p,offer.itemId,true);
    const swap=offer.swapItemId?ownedItem(state,buyer,offer.swapItemId,true):null;
    check(buyer.credits>=offer.credits,'credits','ผู้ซื้อเงินไม่พอ');
    p.inventory=p.inventory.filter(id=>id!==item.id); buyer.inventory.push(item.id); item.owner=buyer.id;
    if(swap) {buyer.inventory=buyer.inventory.filter(id=>id!==swap.id);p.inventory.push(swap.id);swap.owner=p.id;}
  }
  transfer(state,buyer,p,offer.credits,offer.source==='npc'?'cross-shop-fee':'p2p');
  if(offer.source==='inventory'&&!offer.swapItemId){
    const item=state.items[offer.itemId]!;
    recordPersonalItemActivity(state,buyer,'bought',item,1,offer.credits>0,'zero-credit transfer');
    recordPersonalSale(state,p,item,offer.credits);
  }
  if(state.config.secureEconomy && offer.source==='inventory' && !offer.swapItemId)recordItemTrade(state,state.items[offer.itemId]!,offer.credits);
  if(penalty) transfer(state,buyer,p,penalty,'challenge-penalty');
  const rebated=payRebate(state,p,buyer,listing.rebate,true);
  buyer.paid={...buyer.paid,[offer.itemId]:Math.max(0,(offer.source==='npc'?(buyer.paid?.[offer.itemId]??0):0)+offer.credits+penalty-rebated)};
  state.listings=state.listings.filter(l=>l.itemId!==offer.itemId && l.itemId!==offer.swapItemId);
  offer.status='accepted';
  for(const party of [p,buyer]) if(party.subsidy) {party.subsidy=false;state.reservedRewards--;reward(state,party,1,'E43');}
  trace(state,p,'trade-completed',{offerId,itemId:offer.itemId,buyerId:buyer.id,credits:offer.credits,source:offer.source});
  pauseIfNeeded(state,buyer);
}

function expireUnavailableOffers(state:AppraisalState):void {
  for(const offer of state.trades) {
    if(offer.status!=='open') continue;
    const seller=player(state,offer.sellerId),buyer=player(state,offer.buyerId),item=state.items[offer.itemId];
    const listed=state.listings.some(l=>l.itemId===offer.itemId && l.ownerId===seller.id && l.purchase);
    const available=offer.source==='inventory'?item?.owner===seller.id && unlocked(seller,offer.itemId):item?.owner===`npc:${seller.id}:${state.encounter}` && seller.stock.includes(offer.itemId);
    const swapAvailable=!offer.swapItemId || (state.items[offer.swapItemId]?.owner===buyer.id && unlocked(buyer,offer.swapItemId));
    if(!listed || !available || !swapAvailable || seller.paused || buyer.paused || seller.done || buyer.done) {
      offer.status='rejected';trace(state,seller,'offer-expired',{offerId:offer.id,itemId:offer.itemId});
    }
  }
}

export function applyAppraisalAction(previous:AppraisalState,action:AppraisalAction):AppraisalState {
  check(action && typeof action==='object' && typeof action.playerId==='string' && typeof action.requestId==='string' && /^[a-zA-Z0-9_-]{1,80}$/.test(action.requestId),'request','คำสั่งไม่ถูกต้อง');
  const key=`${action.playerId}:${action.requestId}`; const signature=JSON.stringify(action);
  if(previous.accepted[key]) {check(previous.accepted[key]===signature,'request-conflict','request ID ถูกใช้กับคำสั่งอื่น');return previous;}
  check(action.encounter===previous.encounter,'stale-encounter','คำสั่งมาจาก encounter เก่า');
  const ghostAction=action.type.startsWith('ghost-');
  const roundAction=action.type==='round-flip' || action.type==='round-bank' || action.type==='round-raise';
  const storageAction=action.type.startsWith('vault-');
  const loanAction=action.type.startsWith('loan-');
  const sealAction=action.type.startsWith('seal-');
  const financeAction=storageAction || loanAction || sealAction || action.type==='crime-clear';
  check(ghostAction?previous.phase!=='RESULTS':roundAction?previous.phase==='REVEAL':financeAction?previous.phase!=='RESULTS':!['REVEAL','RESULTS'].includes(previous.phase),'phase','ช่วงนี้ไม่รับ action');
  const state=structuredClone(previous); const p=player(state,action.playerId);
  if(ghostAction){handleGhostAction(state,p.id,action as import('./ghost-service.js').GhostAction);enforceCaps(state);state.revision++;state.accepted[key]=signature;state.commands.push(structuredClone(action));reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,action);assertAppraisalInvariants(state);return state;}
  const duelling=state.config.secureEconomy && state.theftDuels?.some(d=>d.status==='open' && [d.thiefId,d.victimId].includes(p.id));
  check(!duelling || action.type==='theft-hand' || action.type==='theft-timeout' || action.type==='theft-expire','theft-pending','เลือกมือเป่ายิ้งฉุบให้เสร็จก่อน');
  check(!p.abilityChoice || action.type==='merchant-ability' && !!action.choiceId || action.type==='done' || action.type==='theft-timeout' || action.type==='theft-expire','ability-choice','เลือกสินค้าที่พ่อค้าเสนอให้ก่อน');
  if(roundAction) {
    if(action.type==='round-flip')flipRoundReward(state,p,action.guess,action.attempt,action.guesses);
    else if(action.type==='round-raise')raiseRoundReward(state,p,action.coinCount,action.attempt);
    else bankRoundReward(state,p);
    state.revision++;state.accepted[key]=signature;state.commands.push(structuredClone(action));enforceCaps(state);reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,action);assertAppraisalInvariants(state);return state;
  }
  const forcedTimeout=action.type==='theft-timeout'&&state.config.theftTimeoutRules===1;
  if(financeAction || action.type==='theft-hand' || action.type==='theft-expire' || forcedTimeout) {
    check(state.config.secureEconomy && p.life!==0 && p.paused!=='dead','inactive','ผู้เล่นที่หมดชีวิตทำรายการไม่ได้');
    if(storageAction)handleStorageAction(state,p,action as import('./secure-storage.js').StorageAction);
    else if(loanAction)handleLoanAction(state,p,action as import('./secure-storage.js').LoanAction);
    else if(sealAction)handleSealAction(state,p,action as import('./seals.js').SealAction);
    else if(action.type==='crime-clear')clearCrime(state,p);
    else if(action.type==='theft-hand'){
      if(state.config.theftTimeoutRules===1)check(Number.isSafeInteger(action.round)&&action.round===state.theftDuels?.find(d=>d.id===action.duelId)?.round,'theft-round','รอบเป่ายิ้งฉุบผ่านไปแล้ว ใช้สถานะล่าสุด');
      chooseTheftHand(state,p,action.duelId,action.hand);
    }
    else if(action.type==='theft-expire')expireTheftDuel(state,p,action.duelId);
    else if(action.type==='theft-timeout')for(const duel of state.theftDuels??[])if(duel.status==='open'&&[duel.thiefId,duel.victimId].includes(p.id))expireTheftDuel(state,p,duel.id);
    cancelTheftDuels(state);for(const seat of state.players)pauseIfNeeded(state,seat);progress(state);expireUnavailableOffers(state);
    state.revision++;state.accepted[key]=signature;state.commands.push(structuredClone(action));enforceCaps(state);reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,action);assertAppraisalInvariants(state);return state;
  }
  check(!p.paused && !p.done,'inactive','ผู้เล่นพักหรือจบช่วงแล้ว');
  check(!p.eventOffer || !isConsequence(p.eventOffer.id) || action.type==='event' || action.type==='done' || action.type==='theft-timeout','consequence','resolve ผล NPC ก่อน');
  switch(action.type) {
    case 'collector-wish-request': case 'collector-wish-peek': case 'collector-wish-buy': case 'collector-wish-skip':handleCollectorWishlist(state,p,action);break;
    case 'theft-start': check(state.config.secureEconomy && ['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','ตอบเหตุการณ์ก่อนขโมย');startTheftDuel(state,p,action);break;
    case 'reappraise-owned': check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','ตอบเหตุการณ์ก่อนประเมินใหม่');reappraiseOwnedItem(state,p,action.itemId,action.value);break;
    case 'liquidate': check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','ตอบเหตุการณ์ก่อนขายของ');liquidateOwnedItem(state,p,action.itemId);break;
    case 'enter': {
      check(state.phase==='PORTALS' && !p.eventOffer,'phase','เลือก event ก่อนเข้าประตู');
      const portal=p.portals.find(v=>v.id===action.portalId && !v.disabled); check(portal,'portal','ประตูนี้เข้าไม่ได้');
      p.selectedPortalId=portal.id;p.stock=[...portal.stock];
      for(let slot=2;slot<2+stockBonus(state,p).extra;slot++)p.stock.push(spawnStockItem(state,p.id,state.players.indexOf(p),state.encounter,p.portals.indexOf(portal),slot,portal.npc));
      for(const id of p.stock)ensureItemAppearance(state,state.items[id]!);
      redeemNpcContracts(state,p,portal.npc);p.done=true;trace(state,p,'portal-entered',{portalId:portal.id,npc:portal.npc});break;
    }
    case 'reroll-portal': rerollPortal(state,p,action.portalId);break;
    case 'inspect': npcActionAllowed(state,p);inspect(state,p,action.itemId,action.property);break;
    case 'appraise': case 'counter': {
      npcActionAllowed(state,p);check(!p.caught,'npc-closed','NPC ที่จับได้แล้วไม่รับการประเมินใหม่');
      const caught=appraise(state,p,action.itemId,action.value,action.type==='counter',action.acceptDanger===true); drawBacklashEvent(state,p);if(caught && !p.eventOffer) drawEvent(state,p,true);break;
    }
    case 'buy': npcActionAllowed(state,p);purchase(state,p,p,action.itemIds,{condition:action.condition});break;
    case 'activate': check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','resolve event ก่อนเปิดใช้');activate(state,p,action.itemId,action.npc,action.otherNpc);break;
    case 'recover-resource': {
      npcActionAllowed(state,p);check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');const offer=recoveryOffer(state,p);
      check(offer && offer.target===action.target,'recovery','พ่อค้านี้ไม่มีดีลฟื้นที่เลือกหรือใช้สิทธิ์แล้ว');
      check(offer.target==='life'?p.life!<maxLifeOf(state,p)!:p.energy<maxEnergyOf(state,p),'recovery','ทรัพยากรนี้เต็มแล้ว');
      spend(state,p,offer.credits,0,'recovery-deal');p.recoveryUsed=true;
      const amount=recoveryAmount(state,p,offer);
      if(offer.target==='life'){if(amount)healLife(state,p,amount,'recovery-deal');p.notes.push(`ดีลฟื้นชีวิต: จ่าย ${offer.credits} เครดิต ได้ฟื้น ${amount}`);p.notes=p.notes.slice(-30);}
      else recover(state,p,amount,'recovery-deal');
      break;
    }
    case 'steal': check(!state.config.secureEconomy,'rps-required','เลือกมือเป่ายิ้งฉุบเพื่อขโมย');npcActionAllowed(state,p);stealShop(state,p,action.itemId);drawTheftEvent(state,p);break;
    case 'pickpocket': check(!state.config.secureEconomy,'rps-required','เลือกมือเป่ายิ้งฉุบเพื่อขโมย');check(['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','resolve event ก่อน');pickpocket(state,p,action.victimId);drawTheftEvent(state,p);break;
    case 'barter': npcActionAllowed(state,p);check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');check(state.config.core2,'action-type','ห้องนี้ไม่มีการแลกของ');barter(state,p,action.itemId,action.targetItemId);drawTheftEvent(state,p);break;
    case 'merchant-ability': useMerchantAbility(state,p,action);break;
    case 'skill': check(!state.config.trustAbilities,'skill','ใช้ความสามารถพ่อค้าแบบใหม่');npcActionAllowed(state,p);useSkill(state,p,action.itemId);break;
    case 'wish-new': npcActionAllowed(state,p);check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');wishNew(state,p,action.replaceNpc);break;
    case 'wish-sell': npcActionAllowed(state,p);wishSell(state,p,action.itemId,action.markup);break;
    case 'cleanse': npcActionAllowed(state,p);check(!merchantTradeBanned(state,p),'merchant-banned','พ่อค้าทั้งหมดระงับการค้าชั่วคราว');cleanseItem(state,p,action.itemId,action.stoneId);break;
    case 'event': resolveEvent(state,p,action);break;
    case 'unsold': check(state.config.brokerage && ['APPRAISAL','TRADE'].includes(state.phase) && !p.eventOffer,'phase','resolve event ก่อนจัดการของค้าง');settleUnsold(state,p,action.itemId,action.choice);break;
    case 'bid': check(state.config.brokerage,'action-type','ห้องนี้ไม่มีการประมูล');placeBid(state,p,action.lotId,action.credits);break;
    case 'market-sell': marketSell(state,p,action.itemId,action.orderId,action.resolution);break;
    case 'share': check(['APPRAISAL','TRADE'].includes(state.phase),'phase','ยังเปิดรายการไม่ได้');share(state,p,action.itemId,action.allow,action.purchase,action.claims,action.rebate);break;
    case 'force-buy': check(state.phase==='TRADE','phase','ยังไม่ใช่ช่วงต่อรอง');forceBuy(state,p,action);break;
    case 'propose': check(state.phase==='TRADE','phase','ยังไม่ใช่ช่วงต่อรอง');propose(state,p,action);break;
    case 'respond': check(state.phase==='TRADE','phase','ยังไม่ใช่ช่วงต่อรอง');respond(state,p,action.offerId,action.accept);break;
    case 'theft-timeout': case 'done':
      if(action.type==='theft-timeout'){
        check(state.config.secureEconomy,'action-type','ไม่มีการเป่ายิ้งฉุบ');
        for(const duel of state.theftDuels??[])if(duel.status==='open' && [duel.thiefId,duel.victimId].includes(p.id)){duel.status='cancelled';duel.hands={};}
      }
      check(!state.config.secureEconomy || !state.theftDuels?.some(d=>d.status==='open' && [d.thiefId,d.victimId].includes(p.id)),'theft-pending','เลือกมือเป่ายิ้งฉุบให้เสร็จก่อน');
      finishAbilityChoice(state,p);defaultEvent(state,p);p.done=true;for(const offer of state.trades) if(offer.status==='open' && [offer.buyerId,offer.sellerId].includes(p.id)) offer.status='rejected';break;
    default: check(false,'action-type','ไม่รู้จักคำสั่ง');
  }
  pauseIfNeeded(state,p); progress(state); if(state.config.secureEconomy)cancelTheftDuels(state);expireUnavailableOffers(state); state.revision++;
  state.accepted[key]=signature;state.commands.push(structuredClone(action));enforceCaps(state);reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,action);assertAppraisalInvariants(state);return state;
}

export function advanceAppraisalEncounter(previous:AppraisalState):AppraisalState {
  check(previous.phase==='REVEAL','phase','ต้องเปิดผลก่อน');
  const state=structuredClone(previous);state.commands.push({type:'advance'});state.revision++;
  for(const p of state.players)if(p.roundReward && !p.roundReward.settled)bankRoundReward(state,p);
  if(state.config.secureEconomy)settleLoansBeforeAdvance(state);
  if(!state.config.survival && state.encounter===state.config.encounters) {if(state.config.secureEconomy && state.config.loanEndSettlement)settleLoansBeforeAdvance(state,true);closeNpcContracts(state);state.phase='RESULTS';enforceCaps(state);reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,{type:'advance'});assertAppraisalInvariants(state);return state;}
  state.encounter++;state.phase='PORTALS';state.listings=[];state.market={encounter:state.encounter,open:false,budget:0,orders:[]};
  if(state.config.secureEconomy){cancelTheftDuels(state);collectCompensations(state);payVaultInterest(state);closeSealOffers(state);}
  for(const p of state.players) {
    delete p.roundReward;
    delete p.merchantActionsUsed;
    if(state.config.trustAbilities){p.skillUsed=false;delete p.abilityItemUsed;delete p.orcDeal;delete p.preserveItemId;}
    delete p.itemUseBonuses;
    delete p.itemUseStrength;
    delete p.itemUseKinds;
    delete p.vampireDiscount;resetCore2Encounter(p);
    if(state.config.survival && p.life===0)continue;
    if(passivesEnabled(state.config))p.passiveUses={};
    if(state.config.survival){state.schedule[p.id]!.push(generatePortals(state,p.id,state.players.indexOf(p),state.encounter));p.recoveryUsed=false;}
    const rested=!!p.paused; p.paused=null;p.done=false;p.portals=structuredClone(state.schedule[p.id]![state.encounter-1]!);p.selectedPortalId=null;p.stock=[];p.valuations={};p.inspections=0;p.counters=0;p.activated=[];p.accuracyBonus=0;p.eventOffer=null;p.offerSlots=0;p.consequenceSlots=0;p.honorJob=false;p.honestyReward=null;p.acceptedDanger=false;p.caught=false;p.dealMode='any';if(p.cleansed)p.cleansed=[];if(p.wishes)p.wishTried=false;
    p.statuses=p.statuses.filter(s=>s.expires>=state.encounter && s.charges>0);p.startWealth=wealth(state,p);
    if(state.config.survival)spend(state,p,0,Math.min(p.energy,state.config.survival.entryEnergyCost),'encounter-entry');
    else if(rested) recover(state,p,Math.max(0,state.config.recoveryEnergy-p.energy),'encounter-recovery',true);else recover(state,p,2,'encounter-rest',true);
    if(status(p,'D04')?.starts===state.encounter) {spend(state,p,Math.min(integerEffect(statusMagnitude(p,'D04',2)),p.credits),0,'D04');consumeStatus(p,'D04');}
    if(status(p,'B09')?.starts===state.encounter) {const amount=integerEffect(statusMagnitude(p,'B09',2));consumeStatus(p,'B09');recover(state,p,amount,'B09');}
    if(status(p,'D07')?.starts===state.encounter) {p.portals.at(-1)!.disabled=true;consumeStatus(p,'D07');}
  }
  state.market=makeMarket(state);
  for(const p of state.players) if(randomAt(state.seed,`${state.encounter}:${p.id}:entry-event`)<.55) drawEvent(state,p);
  enforceCaps(state);reconcileGhostJobs(state);reconcilePilotCustody(state);reconcileCollectorWishlist(state);recordJournal(previous,state,{type:'advance'});assertAppraisalInvariants(state);return state;
}

export function defaultAppraisalAction(state:AppraisalState,playerId:string,requestId:string):AppraisalAction | null {
  const p=player(state,playerId);if(p.paused || p.done || ['RESULTS','REVEAL'].includes(state.phase)) return null;
  if(state.config.theftTimeoutRules===1&&state.theftDuels?.some(d=>d.status==='open'&&[d.thiefId,d.victimId].includes(p.id)))return null;
  return {type:state.config.secureEconomy && state.theftDuels?.some(d=>d.status==='open' && [d.thiefId,d.victimId].includes(p.id))?'theft-timeout':'done',playerId,requestId,encounter:state.encounter};
}

export function assertAppraisalInvariants(state:AppraisalState):void {
  personalPerformanceInvariants(state);
  assertCollectorWishlistInvariants(state);
  for(const item of Object.values(state.items))if(item.rarityPower){check(!!state.config.rarityEconomy&&!!item.appearance,'rarity','พลัง rarity ไม่มีที่มา');validateRarityPower(item.rarityPower);}
  for(const item of Object.values(state.items))if(item.appearance){check(!!state.config.rarity,'rarity','รูปลักษณ์สินค้าไม่มี config');validateItemAppearance(item.appearance);}
  if(state.config.secureEconomy){secureStorageInvariants(state);sealInvariants(state);}
  check(state.reservedRewards===state.players.filter(p=>p.subsidy).length+state.players.reduce((sum,p)=>sum+(p.npcContracts?.alien?.reservedCredits??0),0),'reward-reserve','งบรางวัลไม่ตรงสิทธิ์ที่จอง');
  check(Number.isSafeInteger(state.bank) && state.bank>=0 && state.market.budget>=0 && state.bank>=state.market.budget+state.reservedRewards,'economy','bank reserve ไม่ถูกต้อง');
  const roundFunding=state.ledger.filter(e=>e.from==='@round-fund');
  check(roundFunding.every(e=>state.config.roundRewards && e.reason==='round-reward' && state.players.some(p=>p.id===e.to)),'ledger','เงินรางวัลจบรอบไม่ถูกต้อง');
  const roundStakes=state.ledger.filter(e=>e.to==='@round-fund');
  check(roundStakes.every(e=>state.config.multiCoinRewards && e.reason==='round-stake' && state.players.some(p=>p.id===e.from)),'ledger','เงินทบเหรียญไม่ถูกต้อง');
  const itemFunding=state.ledger.filter(e=>e.from==='@item-fund');
  check(itemFunding.every(e=>passivesEnabled(state.config) && ['gear-commission','gear-market'].includes(e.reason) && state.players.some(p=>p.id===e.to)),'ledger','โบนัสสินค้าผิดกติกา');
  const expected=state.config.bankReserve+state.config.startingCredits*state.players.length+roundFunding.reduce((sum,e)=>sum+e.amount,0)-roundStakes.reduce((sum,e)=>sum+e.amount,0)+itemFunding.reduce((sum,e)=>sum+e.amount,0);
  check(state.bank+state.players.reduce((sum,p)=>sum+p.credits+(p.personalVault?.credits??0),0)===expected,'economy','credit รวมเปลี่ยนโดยไม่มี ledger');
  const initial:Record<string,number>={bank:state.config.bankReserve,'@round-fund':0,'@item-fund':0,...Object.fromEntries(state.players.map(p=>[p.id,state.config.startingCredits])),...(state.config.secureEconomy?Object.fromEntries(state.players.map(p=>[`vault:${p.id}`,0])):{})};
  for(const entry of state.ledger) {check(Number.isSafeInteger(entry.amount) && entry.amount>0 && initial[entry.from]!==undefined && initial[entry.to]!==undefined,'ledger','ledger ไม่ถูกต้อง');initial[entry.from]!-=entry.amount;initial[entry.to]!+=entry.amount;}
  check(initial.bank===state.bank && state.players.every(p=>initial[p.id]===p.credits && (!state.config.secureEconomy || initial[`vault:${p.id}`]===(p.personalVault?.credits??0))),'ledger','ledger ไม่ตรง state');
  const owned=new Set<string>();
  for(const item of Object.values(state.items))if(item.copy){const source=state.items[item.copy.sourceId];check(state.config.trustAbilities && source && !source.copy && source.kind===item.kind && Number.isSafeInteger(item.copy.number) && item.copy.number>=1 && [25,35,50].includes(item.copy.valuePercent),'copy','ที่มาสำเนาไม่ถูกต้อง');}
  for(const p of state.players) {
    check(!!p.npcTrust===!!state.config.commerce && Object.entries(p.npcTrust??{}).every(([npc,n])=>npc in NPC_SPECS && Number.isSafeInteger(n) && n>=0 && n<=TRUST_CAP),'npc-trust','ความไว้ใจ NPC ไม่ถูกต้อง');
    check(Object.values(p.passiveUses??{}).every(n=>Number.isSafeInteger(n) && n>=0),'passive-use','สิทธิ์ตรวจฟรีไม่ถูกต้อง');
    check(Object.entries(p.abilityReady??{}).every(([npc,n])=>state.config.trustAbilities && Object.hasOwn(NPC_SPECS,npc) && Number.isFinite(n) && n>=0),'ability-cooldown','เวลารอความสามารถไม่ถูกต้อง');
    const r=p.roundReward;
    if(r) {
      const validAmount=state.config.multiCoinRewards
        ? Number.isSafeInteger(r.coinCount) && r.coinCount!>=1 && Number.isSafeInteger(r.staked) && r.staked===(r.coinCount!-1)*r.base && Number.isSafeInteger(r.net)
          && r.amount===r.base+(r.incomeBonus??0)+r.staked!+r.net! && r.amount>=0 && (r.amount>0 || r.settled)
          && r.staked===roundStakes.filter(e=>e.from===p.id && e.encounter===state.encounter).reduce((sum,e)=>sum+e.amount,0)
        : r.amount===r.base+(r.incomeBonus??0)+(r.winBonus??5)*r.flips || r.amount===0 && r.settled && r.lastFlip?.correct===false;
      check(state.config.roundRewards && r.encounter===state.encounter && r.base===(state.encounter%2?10:15) && Number.isSafeInteger(r.flips) && r.flips>=0 && Number.isSafeInteger(r.amount) && validAmount,'round-reward','ยอดรางวัลจบรอบไม่ถูกต้อง');
    }
    check(Number.isSafeInteger(p.credits) && p.credits>=0 && Number.isSafeInteger(p.energy) && p.energy>=0 && p.energy<=maxEnergyOf(state,p),'resources','ทรัพยากรไม่ถูกต้อง');
    if(state.config.survival)check(Number.isSafeInteger(p.life) && p.life!>=0 && p.life!<=maxLifeOf(state,p)! && (p.life===0)===(p.paused==='dead') && p.paused!=='exhausted','life','ชีวิตหรือสิทธิ์เล่นไม่ตรงกัน');
    check(p.darkTickets===undefined || Number.isSafeInteger(p.darkTickets) && p.darkTickets>=0,'tickets','ตั๋วคำสั่งมืดไม่ถูกต้อง');
    check(p.pulseShards===undefined || state.config.survival && Number.isSafeInteger(p.pulseShards) && p.pulseShards>=0 && p.pulseShards<=PULSE_RULES.bankCap,'pulse','เศษชีพจรไม่ถูกต้อง');
    check(p.inventory.every(id=>!owned.has(id) && !!owned.add(id) && state.items[id]?.owner===p.id),'owner','สินค้าซ้ำหรือเจ้าของไม่ตรง');
    const loan=p.npcContracts?.alien;
    if(loan){check(state.config.npcEvents && loan.itemIds.length>=1 && loan.itemIds.length<=3 && loan.reservedCredits===8*loan.itemIds.length && loan.dueAt===loan.lentAt+2 && loan.lentAt<=state.encounter,'alien-loan','สัญญายืมไม่ถูกต้อง');check(loan.itemIds.every(id=>!owned.has(id) && !!owned.add(id) && state.items[id]?.owner===`alien-loan:${p.id}`),'loan-owner','ของที่ให้ยืมซ้ำหรือเจ้าของไม่ตรง');}
    check(p.statuses.every(s=>s.charges>0 && (s.power===undefined||Number.isFinite(s.power)&&s.power>0&&s.power<=(state.config.rarityEconomy?MAX_RARITY_MULTIPLIER:1)) && (s.expires>=state.encounter || !!state.config.survival && p.life===0)) && new Set(p.statuses.map(s=>s.id)).size===p.statuses.length,'status','สถานะไม่ถูกต้อง');
  }
  for(const item of Object.values(state.items)) if(state.players.some(p=>p.id===item.owner)) check(owned.has(item.id),'owner','ของมีเจ้าของแต่ไม่มีใน inventory');
  for(const item of Object.values(state.items))if(item.owner.startsWith('alien-loan:'))check(owned.has(item.id),'loan-owner','ของที่ให้ยืมไม่มีสัญญา');
  check(!!state.config.brokerage===Array.isArray(state.vault),'vault','คลัง Dark Market ไม่ตรงกติกา');
  if(state.vault) check(new Set(state.vault).size===state.vault.length && state.vault.every(id=>state.items[id]?.owner==='dark-market') && Object.values(state.items).filter(i=>i.owner==='dark-market').length===state.vault.length,'vault','คลัง Dark Market ไม่ตรงเจ้าของ');
  if(state.config.survival){check(state.version===5,'version','กติกาชีวิตต้องเป็น v0.5');if(state.phase==='RESULTS')check((state.players.every(p=>p.life===0) || collectorDue(state)) && state.collector?.length===state.players.length,'collector','จบได้เมื่อทุกคนตายหรือถึงช่วงที่ Collector มา และ Collector คิดผลแล้ว');else check(!state.collector,'collector','เปิดผล Collector ก่อนจบไม่ได้');}
}

function historyPrice(state:AppraisalState,p:Appraiser):number | undefined {
  const kinds=p.stock.map(id=>state.items[id]!.kind);
  const entry=state.trace.toReversed().find(t => {
    const ids=t.details.itemIds as string[] | undefined; const id=t.details.itemId as string | undefined;
    return t.encounter<state.encounter && typeof t.details.price==='number' && (ids?.length===1 ? kinds.includes(state.items[ids[0]!]!.kind) : !!id && kinds.includes(state.items[id]!.kind));
  });
  return entry?.details.price as number | undefined;
}

function ledgerFacts(state:AppraisalState,p:Appraiser,itemId:string):Array<typeof factKeys[number]> {
  const listing=state.listings.find(l=>l.itemId===itemId && l.ownerId!==p.id && state.items[itemId]?.owner.startsWith('npc:'));
  const owner=listing?state.players.find(other=>other.id===listing.ownerId):undefined;
  if(!owner || !owner.valuations[itemId])return [];
  return factKeys.filter(fact=>owner.knowledge[itemId]?.[fact]!==undefined && known(state,p,itemId)[fact]===undefined);
}

function draftBoons(state:AppraisalState,p:Appraiser,key:string):StatusId[] {
  return boonPool(state,p).map(id=>({id,rank:randomAt(state.seed,`${key}:boon:${id}`)})).sort((a,b)=>a.rank-b.rank).slice(0,3).map(row=>row.id);
}

function polishEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  const spec=POLISH_EVENTS[id];
  if(!state.config.polish || !spec || state.phase!==spec.phase) return false;
  return p.credits>=(spec.credits??0) && p.energy>=(spec.energy??0) && freeBankOf(state)>=(spec.reward??0)
    && !spec.avoid.some(s=>!!status(p,s)) && (!spec.needsAuctions || !!state.config.brokerage);
}

function expansionEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  if(!expansionActive(state.config)) return false;
  const npc=p.selectedPortalId?p.portals.find(portal=>portal.id===p.selectedPortalId)?.npc:undefined;
  const bank=freeBankOf(state);const survival=!!state.config.survival;
  // Selling trade news needs something to trade, and is pointless while the smell of the hive still clings.
  if(id==='E92') return state.phase==='TRADE' && bank>=2 && !status(p,'D13') && (!state.config.polish || p.inventory.length>0);
  if(state.phase!=='APPRAISAL') return false;
  switch(id) {
    case 'E84': return npc==='deepsea' && p.energy>=1;
    case 'E85': return npc==='swarm' && p.credits>=1;
    case 'E86': return bank>=3 && !status(p,'D15');
    case 'E87': return p.energy>=2 && bank>=6;
    case 'E88': return p.credits>=1 && p.statuses.some(s=>NEW_DEBUFFS.includes(s.id) && s.charges>0);
    case 'E89': return !status(p,'B11') && !status(p,'D14');
    case 'E90': return npc==='swarm' && (!reworked(state) || !status(p,'B13') && !status(p,'D11'));
    case 'E91': return npc==='deepsea' && (survival?p.life!>1:p.energy>=2);
    case 'E93': return p.energy>=1 && bank>=1;
    default: return false;
  }
}

export function eventEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  if (p.paused || p.done || ['RESULTS','REVEAL'].includes(state.phase)) return false;
  if((ABILITY_EVENT_IDS as readonly string[]).includes(id)){
    if(!state.config.trustAbilities || p.abilityChoice)return false;
    const trusted=Object.values(p.npcTrust??{}).some(v=>v>=1);
    if(id==='E130')return p.credits>=3 && (Object.keys(MERCHANT_ABILITIES) as NpcId[]).some(n=>(p.npcTrust?.[n]??0)>=1&&reducibleCooldown(p,n,state.encounter)>0);
    if(id==='E131')return trusted && !status(p,'B25') && !status(p,'D25') && freeBankOf(state)>=5;
    return state.phase==='APPRAISAL' && trusted && !status(p,'B26') && p.stock.some(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}`);
  }
  if(core2Spec(id))return core2EventEligible(state,p,id);
  if(state.config.core2 && ['E01','E08','E10'].includes(id))return false;
  // Rule 1: declining E08 keeps both doors and every way to pay, so neither offer could ever be worth taking.
  if(id==='E08' && reworked(state))return false;
  if(isNpcEvent(id))return npcEventEligible(state,p,id);
  if (bondSpec(id)) return bondEligible(state,p,id);
  if (id==='E73') return wishEligible(state,p);
  if ((EXPANSION_EVENT_IDS as readonly string[]).includes(id)) return expansionEligible(state,p,id);
  if ((POLISH_EVENT_IDS as readonly string[]).includes(id)) return polishEligible(state,p,id);
  if (id===BOON_EVENT_ID) return !!state.config.polish && state.phase==='APPRAISAL' && boonPool(state,p).length>=3;
  const npc=p.stock[0] ? state.items[p.stock[0]]!.npc : null;
  const stock=p.stock.filter(itemId => state.items[itemId]?.owner===`npc:${p.id}:${state.encounter}`);
  const unknownPrice=stock.some(itemId=>known(state,p,itemId).base===undefined);
  const inspectable=p.inspections<inspectionLimit(state,p);
  const next=!!state.config.survival || state.encounter<state.config.encounters;
  if (consequences.includes(id)) {
    if (!p.caught || p.consequenceSlots>=1) return false;
    return id==='E48' || (id==='E49' && next) || (id==='E50' && npc==='darkone' && p.acceptedDanger);
  }
  if (['E01','E08','E10'].includes(id)) return state.phase==='PORTALS' && p.portals.filter(v=>!v.disabled).length>1 && (id!=='E08' || next || NPC_SPECS[p.portals[1]!.npc].condition!=='D04') && (id!=='E10' || unknownPrice || p.stock.length===0);
  if (state.phase==='PORTALS') return false;
  if (Number(id.slice(1))<=30 && state.phase!=='APPRAISAL') return false;
  const bank=state.bank-state.market.budget-state.reservedRewards;
  switch(id) {
    case 'E02': return npc==='orc' && stock.length>0 && !Object.keys(p.valuations).length;
    case 'E03': return npc==='vampire' && p.energy<maxEnergyOf(state,p) && (state.config.systemLinks!==1 || eventChoices(state,p,id).some(choice=>choice!=='decline'));
    case 'E04': return npc==='autometa' && unknownPrice;
    case 'E05': return npc==='alien' && inspectable && stock.some(v=>effectsUnknown(state,p,v));
    case 'E06': return npc==='darkone' && next && debuffs(p).some(v=>v!=='D04' || next);
    case 'E07': return npc==='beast' && inspectable && kindOwned(state,p,'food').some(v=>unlocked(p,v));
    case 'E09': return stock.length>0 && p.counters<counterLimit(p);
    case 'E11': return inspectable && stock.some(v=>known(state,p,v).genuine===undefined);
    case 'E12': return inspectable && stock.some(v=>state.items[v]!.certificate && known(state,p,v).certificate===undefined);
    case 'E13': return inspectable && stock.length>=2 && stock.filter(v=>known(state,p,v).base===undefined).length>=2;
    case 'E14': return historyPrice(state,p)!==undefined;
    case 'E15': return inspectable && stock.length>0 && unknownPrice;
    case 'E16': return inspectable && stock.some(v=>effectsUnknown(state,p,v));
    case 'E17': return inspectable && unknownPrice;
    case 'E18': return stock.length>0 && !Object.keys(p.valuations).length;
    case 'E19': return bank>=1 && stock.some(v=>known(state,p,v).genuine===false && state.publicKnowledge[v]?.genuine===undefined);
    case 'E20': return inspectable && stock.some(v=>!known(state,p,v).activationKnown);
    case 'E21': return stock.length>=2;
    case 'E22': return !status(p,'B07') && ['orc','darkone','beast'].includes(npc??'');
    case 'E23': return p.energy>=1 && stock.length>0;
    case 'E24': return npc==='vampire' && stock.length>0;
    case 'E25': return stock.length>0 && movable(p).some(v=>!state.items[v]!.copy && NPC_SPECS[npc!].favorite.includes(state.items[v]!.kind));
    case 'E26': return next;
    case 'E27': return next && stock.length>0;
    case 'E28': return npc==='darkone' && !status(p,'B08');
    case 'E29': return stock.length>0 && !status(p,'D09');
    case 'E30': return stock.length>0 && !status(p,'B06');
    case 'E31': return kindOwned(state,p,'mirror').length>0;
    case 'E32': return kindOwned(state,p,'orb').length>0 && p.energy<maxEnergyOf(state,p);
    case 'E33': return kindOwned(state,p,'key').length>0 && !!status(p,'D07');
    case 'E34': return kindOwned(state,p,'mask').length>0 && p.statuses.some(s=>s.id.startsWith('B') && s.id!=='B10');
    case 'E35': return kindOwned(state,p,'potion').length>0 && (!!status(p,'D01') || !!status(p,'D05'));
    case 'E36': return kindOwned(state,p,'battery').length>0 && inspectable;
    case 'E37': return state.phase==='APPRAISAL' && p.inventory.length>=3 && stock.length>0;
    case 'E38': return kindOwned(state,p,'amulet').length>0;
    case 'E39': return state.phase==='APPRAISAL' && kindOwned(state,p,'blade').length>0 && stock.some(v=>!p.valuations[v]);
    case 'E40': return kindOwned(state,p,'scanner').length>0 && (!reworked(state) || !status(p,'D02'));
    case 'E41': return debuffs(p).length>0;
    case 'E42': return p.energy<maxEnergyOf(state,p) || !!status(p,'D10');
    case 'E43': return state.phase==='TRADE' && !p.subsidy && bank>=1;
    case 'E44': return (!state.config.secureEconomy || !merchantTradeBanned(state,p)) && movable(p).length>=2 && bank>=Math.max(...movable(p).map(v=>systemSaleQuote(state,state.items[v]!,salePreview(state,p,rarityValue(state.items[v]!,Math.floor(anchorOf(state.config,state.items[v]!.kind)*.75))))));
    case 'E45': return Object.entries(p.knowledge).some(([item,k])=>['base','genuine','cursed'].some(f=>k[f as keyof Knowledge]!==undefined && state.publicKnowledge[item]?.[f as keyof Knowledge]===undefined && !p.revealedInfo.includes(`${item}:${f}`)));
    case 'E46': return p.energy>=1 && stock.some(v=>known(state,p,v).genuine===undefined) && bank>=2;
    case 'E47': if(reworked(state))return p.credits>=1 && state.listings.some(l=>ledgerFacts(state,p,l.itemId).length>0);
      return state.listings.some(l=>l.ownerId!==p.id && state.items[l.itemId]?.owner.startsWith('npc:') && !!state.players.find(other=>other.id===l.ownerId)?.valuations[l.itemId]);
    default: return false;
  }
}

export function eventChoices(state:AppraisalState,p:Appraiser,id:EventId):string[] {
  if(core2Spec(id))return core2EventChoices(state,p,id);
  if(reworked(state)) {
    if(isBondGift(id))return ['accept'];
    switch(id) {
      case 'E01': return [...(p.energy>=1?['stay']:[]),'switch'];
      case 'E10': return [...(p.credits>=2?['pay']:[]),'fog','switch'];
      case 'E37': return [...(p.credits>=2?['pay']:[]),'burden',...(movable(p).length?['drop']:[])];
      case 'E40': return [...(p.energy>=2?['repair']:[]),'discard','endure'];
      case 'E42': return [...(p.energy<maxEnergyOf(state,p)?['energy']:[]),...(status(p,'D10')?['cleanse']:[])];
      case 'E43': return ['accept'];
      case 'E108': return ['pick'];
      case 'E131': return ['haste','credits'];
      case 'E132': return ['compass',...(p.energy>=1 && p.stock.some(id=>known(state,p,id).genuine===undefined)?['survey']:[])];
    }
  }
  switch(id) {
    case 'E130': return ['wind','decline'];
    case 'E131': return ['haste','credits','decline'];
    case 'E132': return ['compass',...(p.energy>=1 && p.stock.some(id=>known(state,p,id).genuine===undefined)?['survey']:[]),'decline'];
    case 'E01': return ['stay','switch','decline'];
    case 'E03': return state.config.systemLinks===1
      ?[...(p.credits>=2?['pay']:[]),...(state.config.survival || !status(p,'D10')?['debt']:[]),'decline']
      :['pay','debt','decline'];
    case 'E06': return [...(debuffs(p).some(v=>v!=='D04')?['interest']:[]),...(debuffs(p).some(v=>v!=='D07')?['seal']:[]),'decline'];
    case 'E08': return ['cash','condition','decline'];
    case 'E10': return ['pay','fog','switch','decline'];
    case 'E11': return ['careful','force','decline'];
    case 'E15': return ['price','curse','decline'];
    case 'E18': return ['discount','risk','decline'];
    case 'E37': return ['pay','burden','decline'];
    case 'E40': return ['repair','fog','decline'];
    case 'E42': return [...(p.energy<maxEnergyOf(state,p)?['energy']:[]),...(status(p,'D10')?['cleanse']:[]),'decline'];
    case 'E48': return [...(p.credits>=2?['pay']:[]),...(p.inventory.length?['item']:[]),...(p.credits<2 && !p.inventory.length?['energy']:[])];
    case 'E49': return [...(p.credits>=2?['pay']:[]),'oath'];
    case 'E108': return ['pick','decline'];
    case 'E73': {const npc=shopNpcOf(p);const open=Object.keys(p.wishes??{});return state.config.wishContract && npc && !p.wishes?.[npc] && open.length>=wishSlotsOf(state,p,2)?[...open.map(n=>`replace:${n}`),'decline']:['accept','decline'];}
    case 'E50': return [...(p.inventory.length?['surrender']:[]),'die'];
    default: return ['accept','decline'];
  }
}

export function offerEvent(state:AppraisalState,p:Appraiser,id:EventId):void {
  check(!p.eventOffer && eventEligible(state,p,id),'event-ineligible','event ไม่เข้าเงื่อนไข');
  const reaction=isConsequence(id);
  const key=`${state.encounter}:${p.id}:${id}:${p.offerSlots}:${p.consequenceSlots}`;
  const ownKinds:Partial<Record<EventId,ItemKind>>={E07:'food',E31:'mirror',E32:'orb',E33:'key',E34:'mask',E35:'potion',E36:'battery',E38:'amulet',E39:'blade'};
  let itemIds=ownKinds[id]?kindOwned(state,p,ownKinds[id]!):p.stock;
  if(id==='E132')itemIds=p.stock.filter(id=>known(state,p,id).genuine===undefined);
  if(id==='E25') itemIds=movable(p).filter(v=>!state.items[v]!.copy && NPC_SPECS[state.items[p.stock[0]!]!.npc].favorite.includes(state.items[v]!.kind));
  if(['E44','E48','E50'].includes(id)) itemIds=id==='E44'?movable(p):p.inventory;
  if(core2Spec(id)) itemIds=core2EventItems(id,p);
  if(id==='E45') itemIds=Object.keys(p.knowledge);
  if(id==='E47') itemIds=state.listings.filter(l=>l.ownerId!==p.id && state.items[l.itemId]!.owner.startsWith('npc:')).map(l=>l.itemId);
  if(id==='E11') itemIds=itemIds.filter(v=>known(state,p,v).genuine===undefined);
  if(id==='E12') itemIds=itemIds.filter(v=>state.items[v]!.certificate && known(state,p,v).certificate===undefined);
  if(id==='E19') itemIds=itemIds.filter(v=>known(state,p,v).genuine===false && state.publicKnowledge[v]?.genuine===undefined);
  if(id==='E07') itemIds=itemIds.filter(v=>unlocked(p,v));
  if(reworked(state)) {
    if(id==='E37') itemIds=movable(p);
    if(id==='E40') itemIds=kindOwned(state,p,'scanner');
    if(id==='E47') itemIds=itemIds.filter(v=>ledgerFacts(state,p,v).length>0);
  }
  const quotedPrices=Object.fromEntries(p.inventory.map(itemId=>{const item=state.items[itemId]!;const quote=copySaleQuote(item,salePreview(state,p,rarityValue(item,Math.floor(anchorOf(state.config,item.kind)*.75))));return [itemId,id==='E44'?systemSaleQuote(state,item,quote):quote];}));
  const facts:Record<string,Knowledge>={};
  if(id==='E45') {
    for(const itemId of itemIds) {
      const proof:Knowledge={};
      for(const fact of ['base','genuine','cursed'] as const) if(p.knowledge[itemId]?.[fact]!==undefined && state.publicKnowledge[itemId]?.[fact]===undefined && !p.revealedInfo.includes(`${itemId}:${fact}`)) Object.assign(proof,{[fact]:p.knowledge[itemId]![fact]});
      if(Object.keys(proof).length) facts[itemId]=proof;
    }
    itemIds=Object.keys(facts);
  }
  let giveItemId:string|undefined;let quotes=quotedPrices;
  const boons=id===BOON_EVENT_ID?draftBoons(state,p,key):undefined;
  const wish=id==='E73'?wishPick(state,p,shopNpcOf(p)!):undefined;
  if(bondSpec(id)) {const targets=bondTargets(state,p,id);itemIds=targets.itemIds;giveItemId=targets.giveItemId;quotes=bondQuotes(state,p,id);}
  const targetKinds=Object.fromEntries([...itemIds,...(giveItemId?[giveItemId]:[])].map(itemId=>[itemId,state.items[itemId]!.kind]));
  p.eventOffer={id,key,choices:eventChoices(state,p,id),itemIds:[...itemIds],statusIds:p.statuses.map(s=>s.id),otherPlayerIds:state.listings.filter(l=>l.ownerId!==p.id).map(l=>l.ownerId),quotedPrices:quotes,facts,targetKinds,...(giveItemId?{giveItemId}:{}),...(wish?{wish}:{}),...(boons?{boons}:{})};
  if(isNpcEvent(id))Object.assign(p.eventOffer,personalNpcOffer(state,p,id,key));
  // Rule 1: a merchant's gift is not a decision, so it does not use one of the seat's two event slots.
  if(reaction) p.consequenceSlots++; else if(!(reworked(state) && isBondGift(id))) p.offerSlots++;
  p.seenEvents.push(id); trace(state,p,'event-offered',{id,key,choices:p.eventOffer.choices});
}

export function drawEvent(state:AppraisalState,p:Appraiser,reaction=false):void {
  if(p.eventOffer || p.paused || p.done || (!reaction && p.offerSlots>=2) || (reaction && p.consequenceSlots>=1)) return;
  let pool=[...EVENT_IDS,...(state.config.trustAbilities && !reaction?ABILITY_EVENT_IDS:[]),...(state.config.core2 && !reaction?CORE2_DRAW_IDS:[])].filter(id=>consequences.includes(id)===reaction && eventEligible(state,p,id));
  const unseen=pool.filter(id=>!p.seenEvents.includes(id)); if(unseen.length) pool=unseen;
  if(!pool.length) return;
  const index=Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:${p.offerSlots}:${p.consequenceSlots}:event`)*pool.length);
  offerEvent(state,p,pool[index]!);
}

function preferUnseen<T extends EventId>(state:AppraisalState,p:Appraiser,pool:readonly T[]):readonly T[] {
  if(!state.config.polish) return pool;
  const unseen=pool.filter(id=>!p.seenEvents.includes(id));return unseen.length?unseen:pool;
}

export function drawPolishEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!state.config.polish || p.eventOffer || p.paused || p.done || p.offerSlots>=2) return false;
  const pool=preferUnseen(state,p,[...POLISH_EVENT_IDS,BOON_EVENT_ID].filter(id=>eventEligible(state,p,id)));
  if(!pool.length || randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:polish`)>=(state.phase==='TRADE'?.3:.45)) return false;
  offerEvent(state,p,pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:polish:pick`)*pool.length)]!);return true;
}

export function drawPersonalNpcEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!state.config.npcEvents || p.eventOffer || p.offerSlots>=2)return false;
  const npc=shopNpcOf(p);const id=npc?NPC_PERSONAL_EVENT[npc]:undefined;
  if(!id || !eventEligible(state,p,id) || randomAt(state.seed,`${state.encounter}:${p.id}:personal-npc`)>=.65)return false;
  offerEvent(state,p,id);return true;
}

export function drawExpansionEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!expansionActive(state.config) || p.eventOffer || p.paused || p.done || p.offerSlots>=2) return false;
  const pool=preferUnseen(state,p,EXPANSION_EVENT_IDS.filter(id=>eventEligible(state,p,id)));
  if(!pool.length || randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:expansion`)>=(state.phase==='TRADE' && state.config.polish?.3:.5)) return false;
  offerEvent(state,p,pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${state.phase}:expansion:pick`)*pool.length)]!);return true;
}

export function drawBondEvent(state:AppraisalState,p:Appraiser):boolean {
  const rules=state.config.brokerage;
  if(!rules || p.eventOffer || p.paused || p.done || p.offerSlots>=2) return false;
  const pool=preferUnseen(state,p,BOND_EVENT_IDS.filter(id=>eventEligible(state,p,id)));
  if(!pool.length || randomAt(state.seed,`${state.encounter}:${p.id}:bond`)>=rules.bondProbability) return false;
  offerEvent(state,p,pool[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:bond:pick`)*pool.length)]!);return true;
}

function chooseItem(offer:EventOffer,command:Extract<AppraisalAction,{type:'event'}>):string {
  check(command.itemId && offer.itemIds.includes(command.itemId),'event-target','เลือกสินค้าที่อยู่ใน event'); return command.itemId;
}

function chooseStatus(offer:EventOffer,command:Extract<AppraisalAction,{type:'event'}>):StatusId {
  check(command.statusId && offer.statusIds.includes(command.statusId),'event-target','เลือกสถานะที่อยู่ใน event'); return command.statusId;
}

function eventInspect(state:AppraisalState,p:Appraiser,itemId:string,credits:number,energy:number,k:Knowledge):void {
  stockItem(state,p,itemId); check(p.inspections<inspectionLimit(state,p),'inspections','สิทธิ์ตรวจหมด');
  const cost=Math.max(0,energy+(status(p,'D01')?1:0)-(status(p,'B05')?1:0));
  const before=known(state,p,itemId);
  spend(state,p,credits,cost,'event-inspect'); consumeStatus(p,'D01'); consumeStatus(p,'B05'); p.inspections++; learn(p,itemId,k);recordPersonalInspection(state,p,state.items[itemId]!,before,known(state,p,itemId));
}

export function resolveEvent(state:AppraisalState,p:Appraiser,command:Extract<AppraisalAction,{type:'event'}>):void {
  const offer=p.eventOffer; check(offer && offer.key===command.key && offer.choices.includes(command.choice),'event-choice','ข้อเสนอเก่าหรือไม่มีตัวเลือกนี้');
  const id=offer.id; const choice=command.choice;
  // Rule 1: an offer without a decline whose conditions lapsed (the bank ran dry, say) simply ends; there is nothing left to give.
  if(reworked(state) && !offer.choices.includes('decline') && !isConsequence(id) && !core2Spec(id) && !eventEligible(state,p,id)) {
    p.eventOffer=null; p.resolvedEvents.push(id); p.notes.push('ข้อเสนอนี้หมดเงื่อนไขแล้ว จึงจบไปโดยไม่มีผล'); p.notes=p.notes.slice(-30); trace(state,p,'event-lapsed',{id}); return;
  }
  if(choice==='decline') { check(!isConsequence(id),'consequence','ปฏิเสธผลที่รับความเสี่ยงไว้ไม่ได้'); if(['E01','E10'].includes(id)) p.portals[0]!.disabled=true; p.eventOffer=null; p.resolvedEvents.push(id); trace(state,p,'event-declined',{id}); return; }
  if((ABILITY_EVENT_IDS as readonly string[]).includes(id))check(state.config.trustAbilities && eventEligible(state,p,id),'event-ineligible','เหตุการณ์เวลาไม่เข้าเงื่อนไขแล้ว');
  if(core2Spec(id)){resolveCore2Event(state,p,offer,command);p.eventOffer=null;p.resolvedEvents.push(id);trace(state,p,'event-resolved',{id,choice});return;}
  if(isNpcEvent(id)){resolvePersonalNpcEvent(state,p,offer,command);p.eventOffer=null;p.resolvedEvents.push(id);trace(state,p,'event-resolved',{id,choice});return;}
  // The offer's captured targets are fixed. Resource/ownership conditions are rechecked at settlement.
  const item=()=>chooseItem(offer,command);
  const ownKind=(kind:ItemKind)=>{const itemId=item(); check(kindOwned(state,p,kind).includes(itemId),'event-target','สินค้าไม่เข้าเงื่อนไข'); ownedItem(state,p,itemId); return itemId;};
  if(bondSpec(id)) {resolveBond(state,p,offer,command);p.eventOffer=null;p.resolvedEvents.push(id);trace(state,p,'event-resolved',{id,choice});return;}
  if(id==='E73') {const npc=shopNpcOf(p);check(npc && offer.wish,'wish','ไม่มีคำขอ');applyWish(state,p,npc,offer.wish,choice.startsWith('replace:')?choice.slice(8) as NpcId:undefined);p.notes.push(`${NPC_SPECS[npc].name}อยากได้ ${ITEM_SPECS[offer.wish.kind].name} ให้ ${offer.wish.price} เครดิต${state.config.wishContract?` แต่ราคาลดลงทุกช่วง ไม่ต่ำกว่า ${wishFloor(offer.wish.kind)} เครดิต`:' ถ้ามีมาขายครั้งหน้า'}`);p.notes=p.notes.slice(-30);p.eventOffer=null;p.resolvedEvents.push(id);trace(state,p,'event-resolved',{id,choice});return;}
  const buy=(discount=0,extra?:StatusId,lock=false,barterItemId?:string)=>purchase(state,p,p,[item()],{discount,condition:p.dealMode==='condition',...(extra?{grantStatus:extra}:{}),lock,...(barterItemId?{barterItemId}:{})});
  switch(id) {
    case 'E130': {const npc=(Object.keys(MERCHANT_ABILITIES) as NpcId[]).filter(n=>(p.npcTrust?.[n]??0)>=1&&reducibleCooldown(p,n,state.encounter)>0).sort((a,b)=>(p.abilityReady?.[b]??0)-(p.abilityReady?.[a]??0))[0];check(npc,'ability-cooldown','ไม่มีสกิลที่ลดเวลารอได้');spend(state,p,3,0,id);reduceAbilityCooldown(p,npc,state.encounter,1);break;}
    case 'E131': if(choice==='haste')grant(state,p,'B25');else {reward(state,p,5,id);grant(state,p,'D25');}break;
    case 'E132': if(choice==='compass')grant(state,p,'B26');else {const selected=item();stockItem(state,p,selected);check(known(state,p,selected).genuine===undefined,'known','รู้ความแท้แล้ว');spend(state,p,0,1,id);learn(p,selected,{genuine:state.items[selected]!.genuine});}break;
    case 'E01': if(choice==='stay') spend(state,p,0,1,id); else p.portals[0]!.disabled=true; break;
    case 'E02': p.honorJob=true; break;
    case 'E03': check(state.config.systemLinks!==1 || eventChoices(state,p,id).includes(choice),'event-cost','ตัวเลือกนี้ไม่มีต้นทุนเพิ่มแล้ว'); if(choice==='pay') spend(state,p,2,0,id); else grant(state,p,'D10'); recover(state,p,3,id); if(state.config.survival && choice==='debt')damageLife(state,p,1,'blood-pact',false); break;
    case 'E04': spend(state,p,1,0,id); grant(state,p,'B01'); break;
    case 'E05': spend(state,p,0,1,id); grant(state,p,'B02'); break;
    case 'E06': {const selected=chooseStatus(offer,command); const next=choice==='interest'?'D04':'D07'; check(selected.startsWith('D') && selected!==next && status(p,selected),'event-target','ล้างสถานะที่เลือกไม่ได้'); removeStatus(p,selected); grant(state,p,next); break;}
    case 'E07': {const v=ownKind('food'),power=itemEffectScale(state.items[v]!);retire(state,p,v,id); grant(state,p,'B05',undefined,power); break;}
    case 'E08': p.dealMode=choice==='cash'?'cash':'condition'; p.portals.forEach((portal,index)=>portal.disabled=index!==(choice==='cash'?0:1)); break;
    case 'E09': buy(2,'D08'); break;
    case 'E10': if(choice==='pay') spend(state,p,2,0,id); else if(choice==='fog') grant(state,p,'D02'); else p.portals[0]!.disabled=true; break;
    case 'E11': {const v=item(); check(known(state,p,v).genuine===undefined,'known','รู้แล้ว'); eventInspect(state,p,v,0,choice==='careful'?2:1,{genuine:state.items[v]!.genuine}); if(choice==='force') grant(state,p,'D01'); break;}
    case 'E12': {const v=item(); check(state.items[v]!.certificate && known(state,p,v).certificate===undefined,'certificate','ไม่มีใบรับรองที่ตรวจได้'); eventInspect(state,p,v,1,0,{certificate:state.items[v]!.genuine}); break;}
    case 'E13': {const ids=p.stock.slice(0,2); check(ids.length===2 && ids.every(v=>known(state,p,v).base===undefined),'comparison','ไม่มีสินค้าคู่ที่ยังไม่รู้ราคา'); eventInspect(state,p,ids[0]!,0,1,{comparison:state.items[ids[0]!]!.base>=state.items[ids[1]!]!.base?ids[0]!:ids[1]!}); break;}
    case 'E14': {const price=historyPrice(state,p); check(price!==undefined,'history','ไม่มีประวัติราคา'); spend(state,p,1,0,id); p.notes.push(`ราคาซื้อขายจริงในอดีต ${price} credit ไม่ใช่ base ของชิ้นปัจจุบัน`); trace(state,p,'historical-price',{price}); break;}
    case 'E15': spend(state,p,0,1,id); grant(state,p,choice==='price'?'B01':'B02'); break;
    case 'E16': {const v=item();eventInspect(state,p,v,0,1,state.config.curseSight?{effectsKnown:true,cursed:state.items[v]!.cursed}:{effectsKnown:true}); break;}
    case 'E17': {const v=item(); const target=stockItem(state,p,v); const bounds=itemPriceRange(state.config,target); const offset=Math.floor(randomAt(state.seed,`${offer.key}:narrow`)*3); eventInspect(state,p,v,2,0,{range:[Math.max(bounds[0],target.base-offset-1),Math.min(bounds[1],target.base+3-offset)]}); break;}
    case 'E18': spend(state,p,0,1,id); p.honestyReward=choice==='discount'?'B03':'B04'; break;
    case 'E19': {const v=item(); check(known(state,p,v).genuine===false && state.publicKnowledge[v]?.genuine===undefined,'proof','ไม่มีผลตรวจใหม่ของปลอม'); state.publicKnowledge[v]={...state.publicKnowledge[v],genuine:false}; reward(state,p,1,id); break;}
    case 'E20': eventInspect(state,p,item(),0,2,{activationKnown:true}); break;
    case 'E21': purchase(state,p,p,p.stock.slice(0,2),{discount:2,condition:p.dealMode==='condition'}); break;
    case 'E22': spend(state,p,1,0,id); grant(state,p,'B07'); break;
    case 'E23': spend(state,p,0,1,id); grant(state,p,'B10'); break;
    case 'E24': buy(2,'D05'); break;
    case 'E25': {const v=item(); const npc=state.items[p.stock[0]!]!.npc; check(!state.items[v]!.copy && NPC_SPECS[npc].favorite.includes(ownedItem(state,p,v,true).kind),'barter','NPC ไม่ต้องการของนี้'); purchase(state,p,p,[p.stock[0]!],{barterItemId:v,condition:p.dealMode==='condition'}); break;}
    case 'E26': spend(state,p,2,0,id); grant(state,p,'B09'); break;
    case 'E27': buy(2,'D04'); break;
    case 'E28': spend(state,p,2,0,id); grant(state,p,'B08'); break;
    case 'E29': buy(3,undefined,true); break;
    case 'E30': buy(-2,'B06'); break;
    case 'E31': {const v=ownKind('mirror'),power=itemEffectScale(state.items[v]!); spend(state,p,0,1,id); p.activated.push(v); grant(state,p,'D05',undefined,itemDrawbackScale(state.items[v]!)); grant(state,p,'B01',undefined,power); break;}
    case 'E32': {const v=ownKind('orb'),power=itemEffectScale(state.items[v]!);retire(state,p,v,id,false); spend(state,p,1,0,id); recover(state,p,integerEffect(3*power),id); break;}
    case 'E33': {check(status(p,'D07'),'status','ไม่มี D07');const v=ownKind('key'),power=itemEffectScale(state.items[v]!);retire(state,p,v,id,false);if(power===1||randomAt(state.seed,`${offer.key}:${v}:copy-key`)<power)removeStatus(p,'D07');break;}
    case 'E34': {const v=ownKind('mask'); const selected=chooseStatus(offer,command); check(selected.startsWith('B') && selected!=='B10' && status(p,selected),'status','เลือก buff ที่จะสละ'); removeStatus(p,selected); grant(state,p,'B10',undefined,itemEffectScale(state.items[v]!)); break;}
    case 'E35': {const selected=chooseStatus(offer,command); check(['D01','D05'].includes(selected) && status(p,selected),'status','เลือก D01 หรือ D05'); const v=ownKind('potion'),power=itemEffectScale(state.items[v]!);retire(state,p,v,id,false);if(power===1||randomAt(state.seed,`${offer.key}:${v}:copy-potion`)<power)removeStatus(p,selected); break;}
    case 'E36': {const v=ownKind('battery'); spend(state,p,0,1,id); p.activated.push(v); grant(state,p,'B05',undefined,itemEffectScale(state.items[v]!)); break;}
    case 'E37': if(choice==='pay') spend(state,p,2,0,id); else if(choice==='drop') {const v=item();ownedItem(state,p,v,true);retire(state,p,v,id);} else grant(state,p,'D06'); break;
    case 'E38': {const v=ownKind('amulet'); spend(state,p,0,1,id); p.activated.push(v); grant(state,p,'D03',undefined,itemEffectScale(state.items[v]!)); grant(state,p,'B06',undefined,itemEffectScale(state.items[v]!)); break;}
    case 'E39': {const v=ownKind('blade'); spend(state,p,0,1,id); p.activated.push(v); grant(state,p,'D10',undefined,itemEffectScale(state.items[v]!)); grant(state,p,'B04',undefined,itemEffectScale(state.items[v]!)); break;}
    case 'E40':
      if(!reworked(state)) {if(choice==='repair') {spend(state,p,0,2,id); removeStatus(p,'D02');} else grant(state,p,'D02'); break;}
      // Rule 1: the scanner has already failed. Repair it, throw it away, or live with the price fog.
      if(choice==='repair') spend(state,p,0,2,id); else if(choice==='discard') retire(state,p,ownKind('scanner'),id,false); else grant(state,p,'D02');
      break;
    case 'E41': {const selected=chooseStatus(offer,command); check(selected.startsWith('D') && status(p,selected),'status','เลือก debuff'); spend(state,p,2,0,id); removeStatus(p,selected); break;}
    // Rule 1: the fountain's energy ignores Blood Thirst, or drinking would only spend the thirst, the same as cleansing it.
    case 'E42': if(choice==='energy') recover(state,p,2,id,reworked(state)); else {check(status(p,'D10'),'status','ไม่มี D10'); removeStatus(p,'D10');} break;
    case 'E43': check(state.bank-state.market.budget-state.reservedRewards>=1,'bank','งบรางวัลไม่พอ'); p.subsidy=true; state.reservedRewards++; break;
