export function defaultEvent(state:AppraisalState,p:Appraiser):void {
  const offer=p.eventOffer; if(!offer) return;
  if(core2Spec(offer.id)){
    if(state.config.systemLinks===1){
      // Finance and other seats can change resources while an offer is pending.
      // Keep its captured choices/targets; never seize a newly acquired item instead.
      const available=core2EventChoices(state,p,offer.id);
      const itemId=offer.itemIds.find(id=>p.inventory.includes(id) && state.items[id]?.owner===p.id);
      const choice=offer.choices.includes('decline')?'decline':offer.choices.find(c=>available.includes(c) && (!core2NeedsItem(offer.id,c,state.config) || !!itemId))??FALLBACK_BRAND.id;
      if(!offer.choices.includes(choice)){
        // Only the system default may add the existing mandatory-penalty fallback.
        offer.choices.push(choice);trace(state,p,'event-default-fallback',{id:offer.id,choice});
      }
      resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(core2NeedsItem(offer.id,choice,state.config)?{itemId:itemId!}:{})});return;
    }
    const choice=offer.choices.includes('decline')?'decline':offer.choices[0]!;
    resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(core2NeedsItem(offer.id,choice,state.config)?{itemId:p.inventory[0]!}:{})});return;
  }
  if(reworked(state) && !offer.choices.includes('decline') && !isConsequence(offer.id)) {
    // Rule 1: no decline to fall back on, so take the safe option: a gift, the first boon, or the mishap's mildest cost.
    const choice=REWORKED_DEFAULT[offer.id] && offer.choices.includes(REWORKED_DEFAULT[offer.id]!)?REWORKED_DEFAULT[offer.id]!:offer.choices[0]!;
    const needsItem=(offer.id==='E37' && choice==='drop') || (offer.id==='E40' && choice==='discard') || (bondSpec(offer.id)?.mode==='reveal');
    resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(needsItem?{itemId:offer.itemIds[0]!}:{}),...(offer.id==='E108'?{statusId:offer.boons![0]!}:{})});
    return;
  }
  const choice=offer.choices.includes('decline')?'decline':offer.choices.includes('pay')?'pay':offer.choices.includes('oath')?'oath':offer.choices.includes('die')?'die':offer.choices.includes('energy')?'energy':'item';
  resolveEvent(state,p,{type:'event',key:offer.key,playerId:p.id,requestId:'system-default',encounter:state.encounter,choice,...(choice==='item'?{itemId:p.inventory[0]!}:{})});
}

export function drawBacklashEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!state.config.core2 || !p.inflated || p.eventOffer || p.paused || p.done || p.consequenceSlots>=1)return false;
  offerEvent(state,p,pickBacklash(state,p));return true;
}

export function drawTheftEvent(state:AppraisalState,p:Appraiser):boolean {
  if(!state.config.core2 || !p.theft || p.eventOffer || p.paused || p.done || p.consequenceSlots>=1)return false;
  offerEvent(state,p,p.theft.kind==='shop'?'E123':'E124');return true;
}

export function ghostQuotes(s:AppraisalState,ghostId:string,buyerId:string){
 const all=kinds(s),g=s.ghosts?.[ghostId];if(!g?.available)return [];
 return [...all].sort((a,b)=>randomAt(s.seed,`ghost-quote:${s.encounter}:${ghostId}:${buyerId}:${a}`)-randomAt(s.seed,`ghost-quote:${s.encounter}:${ghostId}:${buyerId}:${b}`)).slice(0,3).map(kind=>{
  const prototype=structuredClone(publicOfferItems(s).find(i=>i.kind===kind)!);ensureItemAppearance(s,prototype);const base=prototype.base;
  const price=Math.ceil(base*.9)+Math.floor(randomAt(s.seed,`ghost-price:${s.encounter}:${ghostId}:${buyerId}:${kind}`)*(Math.floor(base*1.2)-Math.ceil(base*.9)+1));
  return {id:`${s.encounter}:${g.round}:${ghostId}:${buyerId}:${kind}:${price}`,kind,base,prototype,price};
 });
}

