export function handleGhostAction(state:AppraisalState,id:string,action:GhostAction){
 reconcileGhostJobs(state);
 switch(action.type){
  case 'ghost-start': case 'ghost-guess': case 'ghost-hire': case 'ghost-accept': case 'ghost-rps': case 'ghost-deliver': return handleGhostCommand(state,id,action);
  default: throw new Error('Unknown spirit action');
 }
}

export function reconcileGhostJobs(state:AppraisalState){
 for(const g of Object.values(state.ghosts??{})){
  let cancelled=false;
  for(const job of g.jobs)if(active(job)&&player(state,job.buyerId).life===0){job.status='cancelled';cancelled=true;}
  if(cancelled&&!g.jobs.some(active)){g.available=false;delete g.tracking;}
 }
}

export function startTracking(order:readonly number[],initialPosition:number):Tracking {
 if(order.length!==4 || new Set(order).size!==4 || order.some(n=>!Number.isInteger(n)||n<0||n>3) || !Number.isInteger(initialPosition) || initialPosition<0 || initialPosition>3) throw new RangeError('Invalid tracking cards');
 return {status:'guessing',initialPosition,answer:order.indexOf(initialPosition)};
}

export function trackingView(state:Tracking):{status:Tracking['status'];initialPosition:number} {
 return {status:state.status,initialPosition:state.initialPosition};
}

export function guessTracking(state:Tracking,position:number):Tracking {
 if(state.status!=='guessing' || !Number.isInteger(position) || position<0 || position>3) throw new RangeError('Invalid tracking guess');
 return {...state,status:position===state.answer?'available':'failed'};
}

export function addUseBonuses(bonuses:PassiveBonuses,used:UseBonuses|undefined):PassiveBonuses {
  for(const key of Object.keys(used??{}) as Array<keyof UseBonuses>)bonuses[key]+=used![key]??0;
  for(const key of Object.keys(bonuses) as Array<keyof PassiveBonuses>)if(!['commission','luck','acceptance','mitigation'].includes(key))bonuses[key]=integerEffect(bonuses[key]);
  return bonuses;
}

function addedNotes(before:string[],after:string[]):string[] {
  for(let overlap=Math.min(before.length,after.length);overlap>=0;overlap--) {
    if(before.slice(-overlap).every((note,index)=>note===after[index]))return after.slice(overlap);
  }
  return after;
}

function delta(label:string,before:number,after:number):string|null {
  const amount=after-before;return amount?`${label} ${amount>0?'+':''}${amount}`:null;
}

export function recordJournal(previous:AppraisalState,state:AppraisalState,action:AppraisalAction|{type:'advance'}):void {
  for(const current of state.players) {
    const prior=previous.players.find(player=>player.id===current.id)!;
    const changes=[delta('เครดิต',prior.credits,current.credits),delta('พลัง',prior.energy,current.energy),
      prior.life!==undefined&&current.life!==undefined?delta('ชีวิต',prior.life,current.life):null,
      delta('คะแนน',prior.score,current.score),delta('คะแนนวิญญาณ',previous.ghosts?.[current.id]?.bonus??0,state.ghosts?.[current.id]?.bonus??0)]
      .filter((change):change is string=>change!==null);
    const itemNameOf=(id:string)=>ITEM_SPECS[state.items[id]!.kind].name;
    changes.push(...current.inventory.filter(id=>!prior.inventory.includes(id)).map(id=>`ได้รับ ${itemNameOf(id)}`),
      ...prior.inventory.filter(id=>!current.inventory.includes(id)).map(id=>`เสีย ${itemNameOf(id)}`));
    const gained=current.statuses.filter(status=>!prior.statuses.some(old=>old.id===status.id));
    const lost=prior.statuses.filter(status=>!current.statuses.some(now=>now.id===status.id));
    const statusName=(id:string)=>ALL_STATUS_CATALOG.find(status=>status.id===id)?.name??id;
    changes.push(...gained.map(status=>`ได้สถานะ ${statusName(status.id)}`),...lost.map(status=>`สิ้นสุดสถานะ ${statusName(status.id)}`));
    const notes=addedNotes(prior.notes,current.notes);
    const actor='playerId' in action && action.playerId===current.id;
    if(!actor && !changes.length && !notes.length)continue;
    const itemId='itemId' in action && typeof action.itemId==='string'?action.itemId:undefined;
    const kind=itemId?state.items[itemId]?.kind:undefined;
    const itemName=kind?ITEM_SPECS[kind].name:'';
    const choice='choice' in action && typeof action.choice==='string'?`เลือก ${action.choice}`:'';
    const reason=notes.join(' · ') || choice || (action.type==='advance'?'ผลเมื่อเริ่มช่วงใหม่':`เกิดจาก${titles[action.type]??action.type}`);
    const entry:JournalEntry={id:state.revision,encounter:previous.encounter,phase:previous.phase,
      action:`${titles[action.type]??action.type}${itemName?` · ${itemName}`:''}`,cause:reason,changes,...(choice?{choice}:{}) ,...(kind?{itemKind:kind}:{})};
    (current.journal??=[]).push(entry);
  }
}

export function marketConditionMatch(contract:MarketContract,facts:Pick<Knowledge,'genuine'|'cursed'>):'match'|'mismatch'|'unknown' {
  if(contract.requirements.some(r=>facts[r.property]!==undefined && facts[r.property]!==r.value))return 'mismatch';
  return contract.requirements.every(r=>facts[r.property]!==undefined)?'match':'unknown';
}

export function makeMarketContract(roll:(key:string)=>number,survival:boolean):MarketContract {
  const requirements:MarketContract['requirements'][]=[
    [{property:'genuine',value:true}],[{property:'cursed',value:false}],
    [{property:'genuine',value:true},{property:'cursed',value:false}],
    [{property:'genuine',value:false}],[{property:'cursed',value:true}],
    [{property:'genuine',value:true},{property:'cursed',value:true}],
  ];
  const bonusIndex=Math.floor(roll('bonus')*4),costIndex=Math.floor(roll('cost')*3);
  const bonus:MarketContract['bonus']=bonusIndex===0?{kind:'credits',amount:3}:bonusIndex===1?{kind:'energy',amount:2}:bonusIndex===2 && survival?{kind:'life',amount:1}:{kind:'buff',statusId:'B03'};
  const fullPriceCost:MarketContract['fullPriceCost']=costIndex===0?{kind:'energy',amount:2}:costIndex===1 && survival?{kind:'life',amount:1}:{kind:'debuff',statusId:'D01'};
  return {requirements:requirements[Math.floor(roll('requirements')*requirements.length)]!,bonus,fullPriceCost};
}

export function check(condition: unknown, code: string, message: string): asserts condition {
  if (!condition) throw new RuleError(code, message);
}

export function player(state: AppraisalState, id: string): Appraiser {
  const p = state.players.find(value => value.id === id);
  check(p, 'unknown-player', 'ไม่พบผู้เล่น'); return p;
}

export function trace(state: AppraisalState, p: Appraiser, type: string, details: Record<string,unknown> = {}): void {
  state.trace.push({type, encounter:state.encounter, playerId:p.id, details});
}

export function consumeStatus(p: Appraiser, id: StatusId): void {
  const s = status(p,id); if (s) s.charges--; p.statuses = p.statuses.filter(value => value.charges > 0);
}

export function maxEnergyOf(state:AppraisalState,p:Appraiser):number {
  const b=passiveBonuses(state,p);return Math.min(MAX_ENERGY_CAP,state.config.maxEnergy+b.maxEnergy+(state.config.survival?0:b.maxLife));
}

export function maxLifeOf(state:AppraisalState,p:Appraiser):number|undefined {
  return state.config.survival?state.config.survival.maxLife+Math.min(MAX_LIFE_BONUS_CAP,passiveBonuses(state,p).maxLife):undefined;
}

export function enforceCaps(state:AppraisalState):void {
  for(const p of state.players) {
    p.energy=Math.min(p.energy,maxEnergyOf(state,p));
    if(p.life!==undefined && p.life>0){
      const next=Math.min(p.life,maxLifeOf(state,p)!);
      if(next<p.life)recordPersonalActivity(state,p,'lifeLost',p.life-next,JSON.stringify(['life-cap',state.commands.length,state.personalPerformance?.facts.length]),true,'held life-cap loss');
      p.life=next;
    }
  }
}

export function stockBonus(state:AppraisalState,p:Appraiser):{tier:number;extra:number;total?:number} {
  const tier=state.config.commerce?trustTier(p.npcTrust,activeNpcs(state.config)):0;
  if(state.config.commerce && state.config.totalTrustStock) {
    const total=activeNpcs(state.config).reduce((sum,npc)=>sum+(p.npcTrust?.[npc]??0),0);
    return {tier,total,extra:Math.floor(total/STOCK_RULES.trustPerItem)};
  }
  return {tier,extra:extraStock(tier)};
}

export function salePercent(state:AppraisalState,p:Appraiser,market=false):number {
  if(!market && !state.config.polish) return 0;
  return statusMagnitude(p,'B13',20)-statusMagnitude(p,'D13',20)+(state.config.polish?statusMagnitude(p,'B17',15)-statusMagnitude(p,'D17',20)+(omenNow(state)?.salePct??0):0);
}

export function saleApply(state:AppraisalState,p:Appraiser,base:number,market=false):number {
  const price=saleAdjusted(base,salePercent(state,p,market));
  if(market || state.config.polish){consumeStatus(p,'B13');consumeStatus(p,'D13');}
  return price;
}

export function grant(state: AppraisalState, p: Appraiser, id: StatusId, targetItemId?: string, power=1): void {
  if(power<1 && !['B03','B04','B05','B09','B10','B12','B13','B14','B15','B16','B17','B18','B19','D01','D03','D04','D05','D06','D08','D10','D11','D12','D13','D16','D17','D18','D19','D20','B25','D25'].includes(id)){
    if(randomAt(state.seed,`${state.encounter}:${p.id}:${p.activated.at(-1)}:${id}:copy-status`)>=power)return;power=1;
  }
  if (id.startsWith('D') && status(p,'B06')) { consumeStatus(p,'B06'); trace(state,p,'debuff-blocked',{id}); return; }
  if (!state.config.survival && ['B09','D04','D07'].includes(id) && state.encounter === state.config.encounters) return;
  const currentOnly = ['B05','B10','D02','D16','B17','B18','D17','D18','D19','B23','B24','D22','D23','D24'].includes(id);
  const charges = ['B05','B11','D01','D03','D05','D06','D10','D11'].includes(id) ? 2 : 1;
  const expires = state.encounter + (currentOnly ? 0 : 1);
  const starts = state.encounter + (['B09','D04','D07'].includes(id) ? 1 : 0);
  const old = status(p,id);
  if (old) { old.charges = Math.max(old.charges,charges); old.expires = Math.max(old.expires,expires); const merged=Math.max(old.power??1,power);if(merged===1)delete old.power;else old.power=merged; }
  else p.statuses.push({id,expires,charges,starts,...(power!==1?{power}:{}),...(targetItemId ? {targetItemId} : {})});
  trace(state,p,'status-granted',{id,expires,charges,...(targetItemId ? {targetItemId} : {})});
}

export function spend(state: AppraisalState, p: Appraiser, credits: number, energy: number, reason: string): void {
  check(Number.isSafeInteger(credits) && credits >= 0 && Number.isSafeInteger(energy) && energy >= 0,'cost','ต้นทุนไม่ถูกต้อง');
  check(p.credits >= credits,'credits','credit ไม่พอ'); check(p.energy >= energy,'energy','พลังไม่พอ');
  p.credits -= credits; state.bank += credits; p.energy -= energy;
  if (credits) state.ledger.push({from:p.id,to:'bank',amount:credits,reason,encounter:state.encounter});
  if (energy) trace(state,p,'energy-spent',{energy,reason});
}

export function reward(state: AppraisalState, p: Appraiser, credits: number, reason: string, market = false): void {
  check(Number.isSafeInteger(credits) && credits >= 0,'reward','รางวัลไม่ถูกต้อง');
  check(credits <= state.bank - (market ? 0 : state.market.budget + state.reservedRewards),'bank','งบรางวัลไม่พอ');
  state.bank -= credits; p.credits += credits;
  if (credits) state.ledger.push({from:'bank',to:p.id,amount:credits,reason,encounter:state.encounter});
}

export function transfer(state: AppraisalState, from: Appraiser, to: Appraiser, credits: number, reason: string): void {
  check(Number.isSafeInteger(credits) && credits >= 0 && from.credits >= credits,'credits','credit ไม่พอ');
  from.credits -= credits; to.credits += credits;
  if (credits) state.ledger.push({from:from.id,to:to.id,amount:credits,reason,encounter:state.encounter});
}

export function fundPassive(state:AppraisalState,p:Appraiser,amount:number,reason:'gear-commission'|'gear-market'):void {
  check(passivesEnabled(state.config) && Number.isSafeInteger(amount) && amount>=0,'passive-reward','โบนัสสินค้าไม่ถูกต้อง');
  if(!amount)return;p.credits+=amount;state.ledger.push({from:'@item-fund',to:p.id,amount,reason,encounter:state.encounter});
}

export function recover(state: AppraisalState, p: Appraiser, amount: number, reason: string, minimum = false): void {
  let gained = amount;
  if (!minimum && status(p,'D10')) { gained = Math.max(0,amount-integerEffect(statusMagnitude(p,'D10',2))); consumeStatus(p,'D10'); }
  if (!minimum && status(p,'B14')) { gained += integerEffect(statusMagnitude(p,'B14',2)); consumeStatus(p,'B14'); }
  const before = p.energy; p.energy = Math.min(maxEnergyOf(state,p),p.energy + gained);
  trace(state,p,'energy-restored',{amount:p.energy-before,reason});
}

export function healLife(state:AppraisalState,p:Appraiser,amount:number,reason:string):void {
  check(state.config.survival && p.life!==undefined && p.life>0,'life','ผู้ตายฟื้นกลับมาใน run นี้ไม่ได้');
  const before=p.life;p.life=Math.min(maxLifeOf(state,p)!,p.life+amount);
  trace(state,p,'life-restored',{amount:p.life-before,reason});
}

export function damageLife(state:AppraisalState,p:Appraiser,amount:number,reason:string,shieldable=true):void {
  check(p.life!==undefined,'life','กติกานี้ไม่มีชีวิตแยก');
  let hit=amount;
  if(hit>0 && shieldable && !['blood-pact','dark-one-contract','market-condition','vampire-rite','darkone-pact'].includes(reason) && state.config.catalogVersion===4 && p.pilotGuard?.encounter===state.encounter){const before=hit;hit=Math.max(0,hit-p.pilotGuard.amount);delete p.pilotGuard;trace(state,p,'pilot-guard-absorbed',{amount:before-hit,reason});}
  if(hit>0 && status(p,'B19')){hit=Math.max(0,hit-integerEffect(statusMagnitude(p,'B19',1)));consumeStatus(p,'B19');}
  if(hit>0 && status(p,'D20')){hit+=integerEffect(statusMagnitude(p,'D20',1));consumeStatus(p,'D20');}
  const before=p.life;const remaining=Math.max(0,p.life-hit);
  if(before>remaining)recordPersonalActivity(state,p,'lifeLost',before-remaining,JSON.stringify([state.commands.length,state.personalPerformance?.facts.length,reason]));
  p.life=remaining;
  trace(state,p,'life-lost',{amount:before-p.life,reason});
  if(p.life===0 && !p.paused){p.paused='dead';p.done=true;p.eventOffer=null;trace(state,p,'death',{reason});}
}

export function recoveryOffer(state:AppraisalState,p:Appraiser):RecoveryOffer|undefined {
  if(!state.config.survival || p.life===0 || !p.selectedPortalId || p.recoveryUsed)return;
  const npc=p.portals.find(portal=>portal.id===p.selectedPortalId)?.npc;
  if(!npc)return;
  const b=passiveBonuses(state,p);
  const core2=!!state.config.core2;
  const salt=integerEffect(statusMagnitude(p,'D16',2))+feeSurcharge(state,p)+(core2?recoverySurcharge(state.encounter)+(omenNow(state)?.healCost??0):0);
  if(ENERGY_DEAL_NPCS.includes(npc))return {target:'energy',credits:(core2?ENERGY_DEAL_CREDITS2:2)+salt,amount:3+b.energyRecovery};
  // Life deals follow trust: none at 0, then 3/5/7 credits for 0-1, 1-2, 2-3 life. Held gear adds to both ends.
  const terms=(core2?lifeDealTerms2:lifeDealTerms)(p.npcTrust?.[npc]??0);
  return terms?{target:'life',credits:terms.credits+salt,min:terms.min+b.lifeRecovery,amount:terms.max+b.lifeRecovery}:undefined;
}

export function recoveryAmount(state:AppraisalState,p:Appraiser,offer:RecoveryOffer):number {
  if(offer.min===undefined || offer.min>=offer.amount)return offer.amount;
  return offer.min+Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:recovery-roll`)*(offer.amount-offer.min+1));
}

export function mendWithShards(state:AppraisalState,p:Appraiser):void {
  while((p.pulseShards??0)>=PULSE_RULES.shardsPerLife && p.life!==undefined && p.life>0 && p.life<maxLifeOf(state,p)!) {
    p.pulseShards!-=PULSE_RULES.shardsPerLife;healLife(state,p,1,'pulse-shards');
  }
  if(p.pulseShards!==undefined)p.pulseShards=Math.min(p.pulseShards,PULSE_RULES.bankCap);
}

function gainShards(state:AppraisalState,p:Appraiser):void {
  const wary=merchantWary(p,state.encounter),gained=shardsPerSale(p,state.encounter);
  p.pulseShards=(p.pulseShards??0)+gained;
  p.notes.push(wary?'พ่อค้าเริ่มสงสัย: คุณซื้อขายกับคนเดิมมานานเกินไป จึงไม่ได้เศษชีพจร':`ได้เศษชีพจร +${gained}`);
  trace(state,p,'pulse-shards',{gained,wary});
  mendWithShards(state,p);
  p.notes=p.notes.slice(-30);
}

export function unlocked(p: Appraiser, itemId: string): boolean {
  return !p.statuses.some(s => s.id === 'D09' && s.targetItemId === itemId && s.charges > 0);
}

export function ownedItem(state: AppraisalState, p: Appraiser, itemId: string, movable = false): AppraisalItem {
  const item = state.items[itemId];
  check(item && item.owner === p.id && p.inventory.includes(itemId),'owner','ไม่ได้เป็นเจ้าของสินค้า');
  check(!movable || unlocked(p,itemId),'locked','สินค้าถูกล็อก'); return item;
}

export function retire(state: AppraisalState, p: Appraiser, itemId: string, reason: string, movable = true): void {
  const item = ownedItem(state,p,itemId,movable); p.inventory = p.inventory.filter(id => id !== itemId);
  if(item.copy)state.items[item.copy.sourceId]!.copyConsumed=true;
  item.owner = 'removed'; state.listings = state.listings.filter(l => l.itemId !== itemId);
  p.statuses = p.statuses.filter(s => s.id !== 'D09' || s.targetItemId !== itemId);
  trace(state,p,'item-removed',{itemId,reason});
}

export function wealth(state: AppraisalState, p: Appraiser): number {
  return p.credits + (p.personalVault?.credits??0) + ownedAssetItemIds(state,p).reduce((sum,id) => {
    const item = state.items[id]!; return sum + itemScoreValue(item.base,item.genuine,item.cursed);
  },0);
}

export function stockItem(state: AppraisalState, p: Appraiser, itemId: string): AppraisalItem {
  const item = state.items[itemId];
  check(item && item.encounter === state.encounter && item.npcOwnerId === p.id && p.stock.includes(itemId) && item.owner === `npc:${p.id}:${state.encounter}`,'stock','สินค้านี้ไม่มีในร้านแล้ว');
  return item;
}

export function known(state: AppraisalState, p: Appraiser, itemId: string): Knowledge {
  return {...state.publicKnowledge[itemId],...p.knowledge[itemId]};
}

export function learn(p: Appraiser, itemId: string, knowledge: Knowledge): void {
  p.knowledge[itemId] = {...p.knowledge[itemId],...knowledge};
}

export function merchantActionFree(state:AppraisalState,p:Appraiser,itemId:string):boolean {
  const item=state.items[itemId];
  return !!state.config.freeMerchantAction && !!item && item.encounter===state.encounter && item.owner===`npc:${p.id}:${state.encounter}` && p.stock.includes(itemId) && !p.merchantActionsUsed?.includes(itemId);
}

export function inspect(state: AppraisalState, p: Appraiser, itemId: string, property: 'price'|'authenticity'|'effects'): void {
  check(['price','authenticity','effects'].includes(property),'property','ข้อมูลที่จะตรวจไม่ถูกต้อง');
  const item = state.items[itemId];
  check(item && (item.owner === p.id || p.stock.includes(itemId)),'inspect','ตรวจได้เฉพาะของตนหรือร้านปัจจุบัน');
  const merchantFree=merchantActionFree(state,p,itemId);
  check(merchantFree || p.inspections < inspectionLimit(state,p),'inspections','ใช้สิทธิ์ตรวจครบแล้ว');
  const k = known(state,p,itemId);
  check(property === 'price' ? k.base === undefined : property === 'authenticity' ? k.genuine === undefined : state.config.curseSight ? k.cursed === undefined : !k.effectsKnown || (status(p,'B02') && k.cursed === undefined),'known','รู้ข้อมูลนี้แล้ว');
  const cost = Math.max(0,1 + integerEffect(statusMagnitude(p,'D01',1)) - integerEffect(statusMagnitude(p,'B05',1)));
  const free=!merchantFree && cost>0 && freeInspectionCount(passiveBonuses(state,p),p,property)>0;
  const insight=!merchantFree && cost>0 && !free && p.inspections===0 && !!omenNow(state)?.firstInspectFree;
  const caliper=!merchantFree && cost>0 && !free && !insight && property==='price'?priceCaliper(state,p):undefined;
  const compoundEyes=!merchantFree && cost>0 && !free && !insight && !caliper && !!status(p,'B11');
  spend(state,p,0,merchantFree||free||compoundEyes||insight||caliper?0:cost,'inspect');
  if(merchantFree)(p.merchantActionsUsed??=[]).push(itemId);
  else if(free){p.passiveUses??={};p.passiveUses[property]=(p.passiveUses[property]??0)+1;}
  else if(caliper){usePilot(state,caliper);trace(state,p,'pilot-price-check',{sourceItemId:caliper.id,itemId,savedEnergy:cost});}
  else if(insight) {/* the omen pays for it */}
  else if(compoundEyes) consumeStatus(p,'B11');
  else {consumeStatus(p,'B05');consumeStatus(p,'D01');}
  if(!merchantFree)p.inspections++;
  if (property === 'price') {
    if (status(p,'B01') && !status(p,'D02')) { learn(p,itemId,{base:item.base}); consumeStatus(p,'B01'); }
    else {
      const bounds = itemPriceRange(state.config,item); const offset = Math.floor(randomAt(state.seed,`${item.id}:narrow`)*4);
      learn(p,itemId,{range:[Math.max(bounds[0],item.base-offset-2),Math.min(bounds[1],item.base+5-offset)]});
    }
  } else if (property === 'authenticity') learn(p,itemId,{genuine:item.genuine});
  else if (state.config.curseSight) learn(p,itemId,{effectsKnown:true,cursed:item.cursed});
  else {
    learn(p,itemId,{effectsKnown:true});
    if (status(p,'B02')) { learn(p,itemId,{cursed:item.cursed}); consumeStatus(p,'B02'); }
  }
  // Curse sight: B02 lets the next price or authenticity check read the curse as well.
  if (state.config.curseSight && property !== 'effects' && status(p,'B02')) { learn(p,itemId,{effectsKnown:true,cursed:item.cursed}); consumeStatus(p,'B02'); }
  recordPersonalInspection(state,p,item,k,known(state,p,itemId),property);
  trace(state,p,'inspected',{itemId,property});
}

export function detectionRisk(p: Appraiser, item: AppraisalItem, value: number, base = item.base): number {
  const under = Math.max(0,1-value/base);
  const modifier = (under > 0 ? statusMagnitude(p,'D03',.1) - statusMagnitude(p,'B04',.1) : 0) + (p.honorJob && Math.abs(value-base)>base*.1 ? .1 : 0);
  return Math.max(0,Math.min(1,.4*under*NPC_SPECS[item.npc].sensitivity+modifier));
}

export function appraise(state: AppraisalState, p: Appraiser, itemId: string, value: number, counter: boolean, acceptDanger: boolean): boolean {
  const item = stockItem(state,p,itemId);
  check(Number.isSafeInteger(value) && value >= 0 && value <= 1000,'price','ราคาประเมินไม่ถูกต้อง');
  check(counter ? p.valuations[itemId] && p.counters < counterLimit(p) : !p.valuations[itemId],'appraisal','ไม่มีสิทธิ์ประเมินหรือต่อรองเพิ่ม');
  check(item.npc !== 'darkone' || acceptDanger,'danger','ต้องยอมรับขอบเขตผลเสียของ Dark One ก่อน');
  const merchantFree=!counter && merchantActionFree(state,p,itemId);
  spend(state,p,0,merchantFree?0:1,counter ? 'counter' : 'appraise');
  if(merchantFree)(p.merchantActionsUsed??=[]).push(itemId);
  if (counter) p.counters++;
  p.acceptedDanger ||= item.npc === 'darkone' && acceptDanger;
  const risk = detectionRisk(p,item,value);
  const caught = randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:detection`) < risk;
  const accuracy = Math.abs(value-item.base) <= item.base*.1;
  let accepted = value >= item.reservation || !!state.config.commerce && value>0 && randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:trust-accept:${counter?p.counters:0}`)<Math.min(.95,trustAcceptanceBonus(p,item.npc)+passiveBonuses(state,p).acceptance/100+pilotStrength(state,p,'alien-thought-translator')*.02+statusMagnitude(p,'B12',.25)+(omenNow(state)?.accept??0)/100);
  // v0.6: pricing far above the merchant's own asking price rings alarm bells; the merchant refuses and may take revenge.
  const overChance=state.config.core2?overvalueChance(value,item.ask):0;
  let backlash=false;
  if(overChance>0 && randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:overvalue:${counter?p.counters:0}`)<overChance) {
    if(status(p,'B21')){consumeStatus(p,'B21');p.notes.push('ผู้คุ้มกันกันผลสะท้อนจากราคาประเมินสูงเกินจริงไว้ได้');}
    else {backlash=true;accepted=false;p.inflated=true;}
  }
  const previous = p.valuations[itemId];
  recordPersonalAppraisal(state,p,item,value);
  if (accuracy && !previous?.accuracy) p.accuracyBonus += 5;
  if (!accuracy && previous?.accuracy) p.accuracyBonus -= 5;
  p.valuations[itemId] = {value,accuracy,caught,accepted};
  item.lastAppraisal = value; item.lastAccepted = accepted;
  if(state.config.commerce)item.appraisedBy=p.id;
  p.notes.push(backlash?`ราคา ${value} สูงเกิน ${CORE2.overvalue.ratio} เท่าของราคาหน้าร้าน พ่อค้าปฏิเสธและผู้ตรวจสอบเริ่มสงสัย`:accepted?`NPC ยอมรับราคา ${value} credit`:`NPC ปฏิเสธราคา ${value}; ยังซื้อราคาหน้าร้าน ${item.ask} credit ได้`);
  if (caught) {
    p.notes.push('พ่อค้าจับได้ว่าคุณกดราคา!');
    const trust=p.npcTrust;
    if(trust && (trust[item.npc]??0)>0){const lost=Math.min(trust[item.npc]!,TRUST_RULES.caughtLoss);trust[item.npc]=trust[item.npc]!-lost;p.notes.push(`ความไว้ใจ ${NPC_SPECS[item.npc].name} ลด ${lost} เหลือ ${trust[item.npc]}/${TRUST_CAP}`);trace(state,p,'trust-lost',{npc:item.npc,lost,trust:trust[item.npc]});}
  }
  p.notes = p.notes.slice(-30);
  consumeStatus(p,'B04'); consumeStatus(p,'D03'); consumeStatus(p,'B12');
  if (p.honorJob && accuracy) grant(state,p,'B07'); p.honorJob = false;
  if (p.honestyReward && accuracy) grant(state,p,p.honestyReward); p.honestyReward = null;
  auditItemPrice(state,item,value,`appraisal:${counter?p.counters:0}`);
  p.caught ||= caught; trace(state,p,'appraised',{itemId,value,risk,caught,counter,accepted,...(backlash?{overvalued:true}:{})}); return caught;
}

export function npcQuote(shop:Appraiser,item:AppraisalItem):number {
  const valuation=shop.valuations[item.id];return valuation?.accepted?valuation.value:item.ask;
}

export function completeAppraisedSale(state:AppraisalState,item:AppraisalItem,salePrice:number,bonuses?:PassiveBonuses):void {
  if(!state.config.commerce || !item.appraisedBy || item.commissionPaid || salePrice<=0)return;
  item.commissionPaid=true;const appraiser=player(state,item.appraisedBy);
  if(state.config.survival && appraiser.life===0)return;
  const b=bonuses??passiveBonuses(state,appraiser,[item.id]);const webbed=!!status(appraiser,'D15');
  const baseFull=Math.floor(salePrice/10);const baseCommission=webbed?Math.floor(baseFull/2):baseFull;
  const extraFull=Math.floor(salePrice*commissionRate(b)/100)-baseFull+b.saleFee;const extra=webbed?Math.floor(extraFull/2):extraFull;
  const commission=baseCommission+extra;
  reward(state,appraiser,baseCommission,'appraisal-commission');if(extra)fundPassive(state,appraiser,extra,'gear-commission');
  const trust=appraiser.npcTrust!;setPersonalTrust(state,appraiser,item.npc,Math.min(TRUST_CAP,(trust[item.npc]??0)+1+b.trust+integerEffect(statusMagnitude(appraiser,'B15',1))+(state.config.core2?omenNow(state)?.trust??0:0)),item);consumeStatus(appraiser,'D15');consumeStatus(appraiser,'B15');
  appraiser.notes.push(`ขาย ${ITEM_SPECS[item.kind].name} ได้ ${salePrice} เครดิต · ค่านายหน้า +${commission} เครดิต · ความไว้ใจ ${NPC_SPECS[item.npc].name} ${trust[item.npc]}/${TRUST_CAP}`);appraiser.notes=appraiser.notes.slice(-30);
  trace(state,appraiser,'appraisal-commission',{itemId:item.id,npc:item.npc,salePrice,commission,trust:trust[item.npc]});
}

export function payRebate(state:AppraisalState,seller:Appraiser,buyer:Appraiser,rebate:number|undefined,exact:boolean):number {
  if(!rebate)return 0;
  const paid=exact?rebate:Math.min(rebate,seller.credits);
  transfer(state,seller,buyer,paid,'seller-rebate');
  if(paid){buyer.notes.push(`ผู้ขายแถมเครดิตให้ ${paid} เครดิต`);buyer.notes=buyer.notes.slice(-30);trace(state,seller,'rebate-paid',{buyerId:buyer.id,paid,promised:rebate});}
  return paid;
}

export function friendAppraised(state:AppraisalState,buyer:Appraiser,shop:Appraiser,items:AppraisalItem[]):boolean {
  return !!state.config.survival && shop.id!==buyer.id && items.every(item=>item.appraisedBy===shop.id && !!shop.valuations[item.id]?.accepted);
}

function inheritKnowledge(state:AppraisalState,buyer:Appraiser,shop:Appraiser,item:AppraisalItem):void {
  if(!state.config.commerce || shop.id===buyer.id || item.appraisedBy!==shop.id)return;
  const known=shop.knowledge[item.id];if(!known)return;
  const facts:Knowledge={};
  for(const key of ['base','range','genuine','cursed','effectsKnown','activationKnown'] as const)if(known[key]!==undefined && buyer.knowledge[item.id]?.[key]===undefined)Object.assign(facts,{[key]:known[key]});
  if(!Object.keys(facts).length)return;
  learn(buyer,item.id,facts);
  buyer.notes.push(`ได้ข้อมูลที่ผู้ประเมินตรวจไว้จริงของ ${ITEM_SPECS[item.kind].name}`);buyer.notes=buyer.notes.slice(-30);
  trace(state,buyer,'knowledge-inherited',{itemId:item.id,from:shop.id,facts:Object.keys(facts)});
}

function noteRepeatBuy(state:AppraisalState,buyer:Appraiser,items:AppraisalItem[],appraisers:Array<string|undefined>):void {
  const trust=buyer.npcTrust;
  if(!trust || !state.config.commerce || !appraisers.some(id=>id!==undefined && id!==buyer.id))return;
  const npc=items[0]!.npc;
  const log=[...(buyer.buyLog??[]),npc].slice(-TRUST_RULES.repeatBuys);
  if(log.length<TRUST_RULES.repeatBuys || log.some(entry=>entry!==npc)){buyer.buyLog=log;return;}
  delete buyer.buyLog;
  const before=trust[npc]??0;setPersonalTrust(state,buyer,npc,Math.min(TRUST_CAP,before+TRUST_RULES.repeatBuyTrust),items[0]!);
  buyer.notes.push(`ซื้อของ ${NPC_SPECS[npc].name} ที่เพื่อนประเมินครบ ${TRUST_RULES.repeatBuys} ครั้งติด ความไว้ใจ ${trust[npc]}/${TRUST_CAP}`);buyer.notes=buyer.notes.slice(-30);
  trace(state,buyer,'repeat-buy-trust',{npc,trust:trust[npc]});
}

export function noteScrap(state:AppraisalState,buyer:Appraiser,items:AppraisalItem[]):void {
  if(!state.config.core2)return;
  const others=items.filter(item=>item.appraisedBy!==undefined && item.appraisedBy!==buyer.id).length;
  if(!others)return;
  buyer.scraps=(buyer.scraps??0)+others;
  while(buyer.scraps>=CORE2.scrap.need && (buyer.scrapPaid??0)<CORE2.scrap.cap) {
    buyer.scraps-=CORE2.scrap.need;buyer.scrapPaid=(buyer.scrapPaid??0)+1;
    const before=buyer.energy;recover(state,buyer,CORE2.scrap.energy,'scrap-energy',true);
    buyer.notes.push(`เก็บเศษพลังครบ ${CORE2.scrap.need} ชิ้น: ฟื้นพลัง ${buyer.energy-before}`);buyer.notes=buyer.notes.slice(-30);
    trace(state,buyer,'scrap-energy',{gained:buyer.energy-before});
  }
  if((buyer.scrapPaid??0)>=CORE2.scrap.cap)buyer.scraps=Math.min(buyer.scraps,CORE2.scrap.need-1);
  else {buyer.notes.push(`เศษพลัง ${buyer.scraps}/${CORE2.scrap.need}`);buyer.notes=buyer.notes.slice(-30);}
}

export function purchaseModifiers(state:AppraisalState,buyer:Appraiser):{discount:number;fee:number;energyAdjustment:number} {
  const b=passiveBonuses(state,buyer);return {discount:integerEffect(statusMagnitude(buyer,'B03',2))-integerEffect(statusMagnitude(buyer,'D12',2))+b.discount,fee:feeSurcharge(state,buyer),energyAdjustment:integerEffect(statusMagnitude(buyer,'D06',1))-b.buyEnergy};
}

export function purchase(state: AppraisalState, buyer: Appraiser, shop: Appraiser, itemIds: string[], options: {discount?:number;condition?:boolean;grantStatus?:StatusId;lock?:boolean;barterItemId?:string} = {}): void {
  check(!state.config.secureEconomy || !merchantTradeBanned(state,buyer) && !merchantTradeBanned(state,shop),'merchant-banned','ยังถูกห้ามค้าขายกับพ่อค้า');
  check(Array.isArray(itemIds) && itemIds.length > 0 && itemIds.length<=2 && itemIds.every(id=>typeof id==='string') && new Set(itemIds).size === itemIds.length,'bundle','ชุดสินค้าไม่ถูกต้อง');
  const items = itemIds.map(id => stockItem(state,shop,id));
  const profile = NPC_SPECS[items[0]!.npc];
  check(shop.dealMode !== 'condition' || options.condition,'condition','ข้อเสนอนี้ต้องรับเงื่อนไข');
  check(shop.dealMode !== 'cash' || !options.condition,'condition','ข้อเสนอนี้รับ credit อย่างเดียว');
  check(items.every(item => item.npc === items[0]!.npc),'bundle','สินค้าไม่ได้อยู่ร้านเดียวกัน');
  check(!options.condition || !['D04','D07'].includes(profile.condition) || !!state.config.survival || state.encounter < state.config.encounters,'condition','เงื่อนไขนี้ไม่มี encounter ถัดไป');
  const basePrice = items.reduce((sum,item) => sum + npcQuote(shop,item),0);
  const common=purchaseModifiers(state,buyer);const commissionBonuses=new Map(state.players.map(p=>[p.id,passiveBonuses(state,p)]));
  const discount = (options.discount ?? 0) + common.discount + (options.condition ? profile.discount : 0);
  const bloodDiscount=!!state.config.npcEvents && buyer.id===shop.id && items[0]!.npc==='vampire' && buyer.vampireDiscount?.encounter===state.encounter && !options.barterItemId;
  const orc=state.config.trustAbilities && buyer.orcDeal?.encounter===state.encounter && itemIds.includes(buyer.orcDeal.itemId)?buyer.orcDeal:undefined;
  const orcDiscount=orc?Math.floor(Math.max(0,Math.min(npcQuote(shop,items.find(i=>i.id===orc.itemId)!),basePrice-discount))*orc.percent/100):0;
  const price = options.barterItemId ? 0 : Math.max(0,Math.floor(Math.max(0,basePrice-discount)*(bloodDiscount?.5:1))-orcDiscount);
  const fee = options.barterItemId ? 0 : common.fee;
  const energy = Math.max(0,(state.config.freeBuy || friendAppraised(state,buyer,shop,items) ? 0 : 1) + common.energyAdjustment);
  if (options.barterItemId) ownedItem(state,buyer,options.barterItemId,true);
  spend(state,buyer,price+fee,energy,'npc-purchase');
  if(bloodDiscount)delete buyer.vampireDiscount;
  if(orc)delete buyer.orcDeal;
  if (options.barterItemId) retire(state,buyer,options.barterItemId,'npc-barter');
  consumeStatus(buyer,'B03'); consumeStatus(buyer,'D06'); consumeStatus(buyer,'D12');
  const appraisers=items.map(item=>item.appraisedBy);
  let allocated=0;
  for (const [index,item] of items.entries()) {
    const share=index===items.length-1?price-allocated:basePrice?Math.floor(price*npcQuote(shop,item)/basePrice):0;allocated+=share;
    completeAppraisedSale(state,item,share,commissionBonuses.get(item.appraisedBy??''));
    recordPersonalItemActivity(state,buyer,'bought',item,1,share>0&&!options.barterItemId,'zero-credit or barter');
    if(item.appraisedBy&&item.appraisedBy!==buyer.id&&share>0&&!options.barterItemId){
      const seller=player(state,item.appraisedBy);
      recordPersonalSale(state,seller,item,share);
    }
    if(!options.barterItemId)recordItemTrade(state,item,share);
    inheritKnowledge(state,buyer,shop,item);buyer.paid={...buyer.paid,[item.id]:share};
    item.owner = buyer.id; buyer.inventory.push(item.id); shop.stock = shop.stock.filter(id => id !== item.id);
    state.listings = state.listings.filter(l => l.itemId !== item.id);
  }
  noteRepeatBuy(state,buyer,items,appraisers);noteScrap(state,buyer,items);
  if(state.config.survival && appraisers.some(id=>id!==undefined && id!==buyer.id))gainShards(state,buyer);
  if (options.grantStatus) grant(state,buyer,options.grantStatus);
  if (options.condition) grant(state,buyer,profile.condition);
  if (options.lock) grant(state,buyer,'D09',items[0]!.id);
  trace(state,buyer,'npc-purchased',{itemIds,shopId:shop.id,price,energy,condition:options.condition ?? false,...(fee?{fee}:{})});
}

export function activate(state: AppraisalState, p: Appraiser, itemId: string, npc?:NpcId, otherNpc?:NpcId): void {
  const item = ownedItem(state,p,itemId); check(!p.activated.includes(itemId),'activated','เปิดใช้ชิ้นนี้ใน encounter แล้ว');
  const spec = ITEM_SPECS[item.kind];
  if(spec.nativeEffect){check(state.config.catalogVersion===4 && spec.explicitActivation,'activation','สินค้านี้ทำงานผ่านระบบที่ระบุ ไม่เปิดใช้แยก');check(pilotUses(state,item)===0,'activated','สินค้าชิ้นนี้ใช้ในช่วงนี้แล้ว');}
  spend(state,p,0,state.config.itemEffects && spec.consumable?0:1,'activate'); p.activated.push(itemId);
  const power=itemEffectScale(item);
  if(spec.nativeEffect)usePilot(state,item);
  const shielded = !!status(p,'B06') && !!spec.drawback?.startsWith('D');
  if (item.cursed && spec.drawback) grant(state,p,spec.drawback,undefined,itemDrawbackScale(item));
  const fogged = !!status(p,'D14'); consumeStatus(p,'D14');
  const works = !fogged && item.genuine || !fogged && (!!state.config.fakeEffect && randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:fake-effect`) < FAKE_EFFECT_CHANCE);
  if (works) {
    if(spec.nativeEffect==='effect:E62'){const amount=Math.min(2,integerEffect(power));if(amount>0)p.pilotGuard={encounter:state.encounter,amount:Math.max(amount,p.pilotGuard?.encounter===state.encounter?p.pilotGuard.amount:0)};}
    else if(state.config.trustAbilities && (ABILITY_ITEM_IDS as readonly string[]).includes(item.kind)){
      check(!p.abilityItemUsed?.includes(item.kind),'ability-item','สินค้าชนิดนี้ใช้ได้ครั้งเดียวต่อช่วง');
      if(item.kind==='chrono-gear' || item.kind==='burden-hourglass'){
        check(npc && Object.hasOwn(MERCHANT_ABILITIES,npc) && (p.npcTrust?.[npc]??0)>=1 && reducibleCooldown(p,npc,state.encounter)>0,'ability-cooldown','เลือกสกิลที่ยังลดเวลารอได้');
        if(item.kind==='burden-hourglass')check(otherNpc && otherNpc!==npc && Object.hasOwn(MERCHANT_ABILITIES,otherNpc) && (p.npcTrust?.[otherNpc]??0)>=1 && (p.abilityReady?.[otherNpc]??0)>state.encounter,'ability-cooldown','เลือกสกิลอื่นที่ยังรออยู่');
        const reduced=reduceAbilityCooldown(p,npc,state.encounter,power);
        if(item.kind==='burden-hourglass'){p.abilityReady![otherNpc!]=Math.round((p.abilityReady![otherNpc!]!+reduced)*100)/100;}
        trace(state,p,'ability-cooldown-adjusted',{npc,otherNpc:otherNpc??null,reduced});
      }else grant(state,p,'B26',undefined,power);
      (p.abilityItemUsed??=[]).push(item.kind);
    }
    else if(state.config.trustAbilities && item.kind in MODERN_ACTIVATIONS){
      const operation=MODERN_ACTIVATIONS[item.kind as keyof typeof MODERN_ACTIVATIONS].operation;
      if(operation==='energy-for-delay'){grant(state,p,'D25',undefined,itemDrawbackScale(item));recover(state,p,integerEffect(3*power),'void-cell');}
      else if(power===1 || randomAt(state.seed,`${state.encounter}:${item.id}:copy-insight`)<power){
        if(operation==='scan-shop-price'){
          const shop=p.stock.filter(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}` && known(state,p,id).base===undefined),held=p.inventory.filter(id=>state.items[id]?.owner===p.id && known(state,p,id).base===undefined);
          const pool=shop.length?shop:held;
          if(pool.length){const id=pool[Math.floor(randomAt(state.seed,`${state.encounter}:${item.id}:scan-price`)*pool.length)]!;learn(p,id,{base:state.items[id]!.base});trace(state,p,'item-insight',{itemId:item.id,targetId:id,fact:'base'});}
        }else{
          const options=p.inventory.flatMap(id=>(['base','genuine','cursed'] as const).filter(fact=>known(state,p,id)[fact]===undefined).map(fact=>({id,fact})));
          if(options.length){const option=options[Math.floor(randomAt(state.seed,`${state.encounter}:${item.id}:recall-fact`)*options.length)]!;learn(p,option.id,{[option.fact]:state.items[option.id]![option.fact]});trace(state,p,'item-insight',{itemId:item.id,targetId:option.id,fact:option.fact});}
        }
      }
    }
    else if (itemFamily(item.kind) === 'orb') recover(state,p,integerEffect((spec.energyRecovery??3)*power),'orb');
    else if (itemFamily(item.kind) === 'key' && status(p,'D07')) {if(power===1 || randomAt(state.seed,`${state.encounter}:${item.id}:copy-key`)<power)removeStatus(p,'D07');}
    else if(spec.buff)grant(state,p,spec.buff,undefined,power);
    if(state.config.survival && ['food','potion'].includes(itemFamily(item.kind)))healLife(state,p,integerEffect(2*power),'restorative-item');
    const bonus=state.config.itemEffects?ITEM_USE_EFFECTS[item.kind]:undefined;
    if(bonus) {
      const previous=(state.config.trustAbilities||state.config.rarityEconomy)?(p.itemUseStrength?.[item.kind]??(p.itemUseKinds?.includes(item.kind)?1:0)):(p.itemUseKinds?.includes(item.kind)?1:0);
      if(power>previous){
        p.itemUseKinds??=[];if(!p.itemUseKinds.includes(item.kind))p.itemUseKinds.push(item.kind);
        if(state.config.trustAbilities||state.config.rarityEconomy){p.itemUseStrength??={};p.itemUseStrength[item.kind]=power;}
        const key=bonus.effect;p.itemUseBonuses??={};p.itemUseBonuses[key]=(p.itemUseBonuses[key]??0)+bonus.amount*(power-previous);
      }
    }
  }
  if(state.config.survival && item.cursed)damageLife(state,p,integerEffect(itemDrawbackScale(item)),'cursed-activation',spec.nativeEffect!=='effect:E62');
  if (spec.consumable) {
    if(p.preserveItemId===item.id && !item.copy && !item.preserved){item.preserved=true;delete p.preserveItemId;}
    else {if(item.copy)state.items[item.copy.sourceId]!.copyConsumed=true;retire(state,p,itemId,'consumed',false);}
  }
  learn(p,itemId,{activationKnown:true});
  if (state.config.curseSight) {
    // The outcome is visible to the owner, so activating reveals what the item really was.
    learn(p,itemId,{genuine:item.genuine,cursed:item.cursed,effectsKnown:true});
    p.notes.push(activationNote(state,item,shielded,works,fogged)); p.notes = p.notes.slice(-30);
  }
  trace(state,p,'item-activated',{itemId});
}

export function activationNote(state:AppraisalState,item:AppraisalItem,shielded:boolean,worked=item.genuine,fogged=false):string {
  const spec = ITEM_SPECS[item.kind]; const name = item.copy?`สำเนา #${item.copy.number} ของ ${spec.name}`:spec.name;
  const extra=state.config.itemEffects?ITEM_USE_EFFECTS[item.kind]?.text:undefined;
  const custom=ABILITY_ITEM_TEXT[item.kind as keyof typeof ABILITY_ITEM_TEXT]??(state.config.trustAbilities?MODERN_ACTIVATIONS[item.kind as keyof typeof MODERN_ACTIVATIONS]:undefined);
  const buff = spec.benefit??(custom?custom.th:(itemFamily(item.kind) === 'orb' ? `ฟื้นพลัง ${spec.energyRecovery ?? 3}` : STATUS_CATALOG.find(s => s.id === spec.buff)!.name)+(extra?` · ${extra}`:''));
  const drawback = spec.nativeEffect?(spec.exclusions??''):STATUS_CATALOG.find(s => s.id === spec.drawback)!.name;
  const curse = spec.nativeEffect?`คำสาปทำงาน${state.config.survival?' และเสียชีวิต 1':''}`:`คำสาปทำงาน ${shielded ? `${drawback}ถูก${STATUS_CATALOG.find(s => s.id === 'B06')!.name}กันไว้` : `รับ ${drawback}`}${state.config.survival ? ' และเสียชีวิต 1' : ''}`;
  if (fogged) return `เปิดใช้ ${name}: ${item.genuine ? 'ของแท้' : 'ของปลอม'}แต่หมอกวิกลจริตทำให้ผลดีไม่ออกฤทธิ์${item.cursed ? ` · ${curse}` : ''}`;
  if (item.genuine) return item.cursed ? `เปิดใช้ ${name}: ของแท้แต่มีคำสาป ได้ ${buff} · ${curse}` : `เปิดใช้ ${name}: ของแท้ ไม่มีคำสาป ได้ ${buff}`;
  const fake = worked ? `ของปลอมแต่ยังออกฤทธิ์ได้ ได้ ${buff}` : 'ของปลอม ผลดีไม่ออกฤทธิ์';
  return item.cursed ? `เปิดใช้ ${name}: ${fake} · ${curse}` : worked ? `เปิดใช้ ${name}: ${fake} ไม่มีคำสาป` : `เปิดใช้ ${name}: ของปลอม ไม่มีคำสาป ผลดีไม่ออกฤทธิ์${state.config.itemEffects && spec.consumable?' ใช้แล้วหมด ไม่เสียพลัง':' เสียพลังเปล่า'}`;
}

export function penaltyItem(state: AppraisalState, p: Appraiser, itemId: string): void {
  ownedItem(state,p,itemId);
  if (status(p,'B07')) { consumeStatus(p,'B07'); trace(state,p,'seizure-blocked',{itemId}); }
  else retire(state,p,itemId,'npc-penalty',false);
}

export function kill(state: AppraisalState, p: Appraiser): void {
  if (status(p,'B08')) { consumeStatus(p,'B08'); p.energy = Math.max(0,p.energy-2); trace(state,p,'death-blocked'); }
  else if(state.config.survival)damageLife(state,p,p.life!,'dark-one-contract',false);
  else { p.paused = 'dead'; p.done = true; p.eventOffer = null; trace(state,p,'death'); }
}

export function marketSell(state: AppraisalState, p: Appraiser, itemId: string, orderId: string, resolution:'discount'|'sacrifice'='discount'): void {
  check(resolution==='discount' || resolution==='sacrifice','market-resolution','เลือกรับราคาลดหรือสละตามเงื่อนไข');
  const item = ownedItem(state,p,itemId,true); const order = state.market.orders.find(o => o.id === orderId);
  check(!item.stolen,'stolen','ของที่ฉกมาขาย Dark Market ไม่ได้');
  check(state.market.open && state.market.encounter === state.encounter,'market-closed','Dark Market ปิดแล้ว');
  check(order && order.kind === item.kind && (order.quota[p.id] ?? 0) > 0,'market-order','ไม่มีสิทธิ์รับซื้อตามรายการ');
  const reserved=marketOrderReserve(order);check(state.market.budget>=reserved,'market-budget','งบรับซื้อหมด');
  const contract=order.contract;
  // Check that an optional sacrifice is payable before consulting hidden item facts.
  // Otherwise a rejected sale could become a free authenticity/curse probe.
  if(contract && resolution==='sacrifice') {
    const cost=contract.fullPriceCost;
    if(cost.kind==='energy')check(p.energy>=cost.amount,'energy','พลังไม่พอสำหรับเงื่อนไขราคาเต็ม');
    if(cost.kind==='debuff')check(!status(p,cost.statusId) || status(p,'B06'),'market-cost','มีผลเสียนี้อยู่แล้ว รับซ้ำเพื่อแลกราคาเต็มไม่ได้');
    if(cost.kind==='life')check(state.config.survival && p.life!>cost.amount,'life','ต้องเหลือชีวิตอย่างน้อย 1 หลังจ่าย');
  }
  const quotePrice=rarityValue(item,order.price);
  const maximum=systemSaleQuote(state,item,copySaleQuote(item,salePreview(state,p,quotePrice,true))+(contract?.bonus.kind==='credits'?copySaleQuote(item,contract.bonus.amount):0));
  if(state.config.rarityEconomy)check(maximum<=state.bank-(state.market.budget-reserved)-state.reservedRewards,'bank','งบรับซื้อไม่พอโดยไม่แตะสัญญาอื่น');
  const matched=!contract || marketConditionMatch(contract,item)==='match';
  let price=quotePrice;
  if(contract && !matched) {
    if(resolution==='discount')price=Math.floor(price*80/100);
    else {
      const cost=contract.fullPriceCost;
      if(cost.kind==='energy')spend(state,p,0,cost.amount,'market-condition');
      else if(cost.kind==='life') {check(state.config.survival && p.life!>cost.amount,'life','ต้องเหลือชีวิตอย่างน้อย 1 หลังจ่าย');damageLife(state,p,cost.amount,'market-condition',false);}
      else grant(state,p,cost.statusId);
    }
  }
  price=systemSaleQuote(state,item,copySaleQuote(item,saleApply(state,p,price,true)));
  const creditsBonus=systemSaleQuote(state,item,matched && contract?.bonus.kind==='credits'?copySaleQuote(item,contract.bonus.amount):0);
  const gearBonus=systemSaleQuote(state,item,passiveMarketBonus(order,passiveBonuses(state,p,[itemId]),!!contract && matched,!!contract && !matched && resolution==='discount',quotePrice));
  reward(state,p,price+creditsBonus,'dark-market',true);state.market.budget-=reserved;order.quota[p.id]!--;
  if(gearBonus)fundPassive(state,p,gearBonus,'gear-market');
  if(matched && contract) {
    const bonus=contract.bonus;
    if(bonus.kind==='energy')recover(state,p,bonus.amount,'market-condition');
    else if(bonus.kind==='life')healLife(state,p,bonus.amount,'market-condition');
    else if(bonus.kind==='buff')grant(state,p,bonus.statusId);
  }
  if(contract || gearBonus) {p.notes.push(`Dark Market: ${matched?'ตรงเงื่อนไข รับโบนัส':resolution==='discount'?(gearBonus?'ไม่ตรงเงื่อนไข รับราคาลด':'ไม่ตรงเงื่อนไข ลดราคา 20%'):'ไม่ตรงเงื่อนไข สละตามข้อตกลงเพื่อรับราคาเต็ม'} · รับ ${price+creditsBonus+gearBonus} เครดิต${gearBonus?` รวมโบนัสของถือ ${gearBonus}`:''}`);p.notes=p.notes.slice(-30);}
  recordItemTrade(state,item,price+creditsBonus+gearBonus);
  recordPersonalSale(state,p,item,price);
  retire(state,p,itemId,'dark-market'); if (state.config.brokerage) { item.owner='dark-market'; state.vault!.push(itemId); }
  trace(state,p,'market-sale',{itemId,orderId,price:price+creditsBonus+gearBonus,...(contract?{matched,resolution,bonus:matched?contract.bonus:null}:{})});
}

export function abilityTargets(state:AppraisalState,p:Appraiser,npc:NpcId):string[] {
  if(npc==='orc' || npc==='autometa' || npc==='beast')return p.stock.filter(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}` && (npc!=='beast' || state.items[id]?.lastAppraisal===null && !state.listings.some(l=>l.itemId===id)));
  if(npc==='darkone')return [];
  return p.inventory.filter(id=>movable(state,p,id) && (npc!=='vampire'||!p.activated.includes(id)) && (npc!=='alien'||!state.items[id]!.copy) && (npc!=='vampire'||ITEM_SPECS[state.items[id]!.kind].consumable && !state.items[id]!.copy && !state.items[id]!.preserved) && (npc!=='swarm'||!state.items[id]!.copy && !state.items[id]!.copyConsumed && !state.items[`copy-${id}-1`] && !liveCopy(state,id)));
}

export function merchantAbilityViews(state:AppraisalState,p:Appraiser):MerchantAbilityView[] {
  return activeNpcs(state).map(npc=>{
    const spec=MERCHANT_ABILITIES[npc],trust=p.npcTrust?.[npc]??0,remaining=abilityRemaining(p,npc,state.encounter),itemIds=abilityTargets(state,p,npc);
    const statusIds=p.statuses.filter(s=>s.id.startsWith('D')&&s.charges>0).map(s=>s.id);
    // Status links: a seat merchants are watching (D21) gets no special service.
    const reason=state.config.statusLinks===1 && status(p,'D21')?'พ่อค้าจับตาคุณอยู่ ไม่ยอมใช้ความสามารถพิเศษให้':trust<1?'ต้องมีความไว้ใจอย่างน้อย 1':p.skillUsed?'ใช้ความสามารถพ่อค้าในช่วงนี้แล้ว':remaining>0?'กำลังรอ cooldown':p.abilityChoice?'เลือกสินค้าที่เสนอให้ก่อน':p.caught?'ถูกจับผิดในช่วงนี้แล้ว':p.done||p.paused?'จบช่วงหรือพักแล้ว':p.eventOffer?'ตอบเหตุการณ์ก่อน':!['APPRAISAL','TRADE'].includes(state.phase)?'ใช้ในช่วงประเมินหรือต่อรอง':npc==='darkone'&&!statusIds.length?'ไม่มี debuff ให้ลบ':spec.target!=='debuff'&&!itemIds.length?'ไม่มีสินค้าที่ใช้ความสามารถนี้ได้':null;
    return {npc,...spec,trust,tier:abilityTier(trust),remaining,ready:reason===null,reason,itemIds,statusIds};
  });
}

function makeCandidate(state:AppraisalState,p:Appraiser,npc:NpcId,key:string,slot:number,source?:AppraisalItem):AppraisalItem {
  const config=state.config;
  let pool=merchantKinds(npc,config.catalogVersion??1,!!config.cleanse,!!config.challenge,expansionActive(config),!!config.polish,!!config.trustAbilities);
  if(source && pool.length>1)pool=pool.filter(kind=>kind!==source.kind);
  const offered=new Set(Object.values(state.items).filter(i=>i.owner===`ability-choice:${p.id}`).map(i=>i.kind));
  const fresh=pool.filter(kind=>!offered.has(kind));if(fresh.length)pool=fresh;
  const kind=pool[Math.floor(randomAt(state.seed,`${key}:${slot}:kind`)*pool.length)]!;
  const id=`ability-${key}-${slot}`;
  const anchor=anchorOf(config,kind),range=priceRange(kind,anchor);
  const base=range[0]+Math.floor(randomAt(state.seed,`${id}:base`)*(range[1]-range[0]+1));
  const ask=Math.max(1,anchor-2+Math.floor(randomAt(state.seed,`${id}:ask`)*6));
  const item:AppraisalItem={id,kind,base,ask,genuine:randomAt(state.seed,`${id}:genuine`)<.75,cursed:randomAt(state.seed,`${id}:cursed`)<.35,owner:`ability-choice:${p.id}`,npcOwnerId:p.id,npc,encounter:state.encounter,certificate:false,lastAppraisal:null,lastAccepted:null,reservation:Math.max(1,Math.ceil(base*NPC_SPECS[npc].reservation[0]))};
  ensureItemAppearance(state,item);
  if(source){
    // Preserve quality instead of laundering fakes/curses; the new item cannot create score value.
    item.genuine=source.genuine;item.cursed=source.cursed;
    const ceiling=itemScoreValue(source.base,source.genuine,source.cursed,false);
    while(item.base>0 && itemScoreValue(item.base,item.genuine,item.cursed,false)>ceiling)item.base--;
    item.ask=Math.min(item.ask,source.ask);
  }
  state.items[id]=item;return item;
}

function retireChoices(state:AppraisalState,p:Appraiser,keep:string):void {
  for(const id of p.abilityChoice?.itemIds??[])if(id!==keep && state.items[id]?.owner===`ability-choice:${p.id}`)state.items[id]!.owner='retired';
}

export function settleAbilityChoice(state:AppraisalState,p:Appraiser,choiceId:string):void {
  const choice=p.abilityChoice;
  check(choice && choice.itemIds.includes(choiceId),'ability-choice','เลือกสินค้าที่เสนอให้เท่านั้น');
  const source=state.items[choice.sourceId]!;
  if(choice.npc==='alien'){
    ownedItem(state,p,source.id,true);
    const chosen=state.items[choiceId]!;check(chosen.owner===`ability-choice:${p.id}`,'ability-choice','สินค้านี้ไม่อยู่ในข้อเสนอ');
    const facts=known(state,p,source.id);retire(state,p,source.id,'alien-exchange');
    chosen.owner=p.id;p.inventory.push(chosen.id);
    learn(p,chosen.id,{...(facts.base!==undefined?{base:chosen.base}:{}),...(facts.genuine!==undefined?{genuine:chosen.genuine}:{}),...(facts.cursed!==undefined?{cursed:chosen.cursed}:{}),...(facts.effectsKnown?{effectsKnown:true}:{})});
  }else{
    stockItem(state,p,source.id);
    if(choiceId!==source.id){
      const chosen=state.items[choiceId]!;check(chosen.owner===`ability-choice:${p.id}`,'ability-choice','สินค้านี้ไม่อยู่ในข้อเสนอ');
      source.owner='retired';chosen.owner=`npc:${p.id}:${state.encounter}`;p.stock=p.stock.map(id=>id===source.id?chosen.id:id);
      const portal=p.portals.find(v=>v.id===p.selectedPortalId);if(portal)portal.stock=portal.stock.map(id=>id===source.id?chosen.id:id);
      state.listings=state.listings.filter(l=>l.itemId!==source.id);
    }
  }
  retireChoices(state,p,choiceId);delete p.abilityChoice;
  trace(state,p,'ability-choice-selected',{npc:choice.npc,sourceId:source.id,choiceId});
}

export function finishAbilityChoice(state:AppraisalState,p:Appraiser):void {
  if(p.abilityChoice)settleAbilityChoice(state,p,p.abilityChoice.itemIds[0]!);
}

export function useMerchantAbility(state:AppraisalState,p:Appraiser,action:Extract<AppraisalAction,{type:'merchant-ability'}>):void {
  check(state.config.trustAbilities && activeNpcs(state).includes(action.npc),'ability','ห้องนี้ไม่มีความสามารถที่เลือก');
  if(action.choiceId){check(p.abilityChoice?.npc===action.npc,'ability-choice','ไม่มีข้อเสนอของพ่อค้านี้');settleAbilityChoice(state,p,action.choiceId);return;}
  const view=merchantAbilityViews(state,p).find(v=>v.npc===action.npc)!;
  check(view.ready,'ability',view.reason??'ความสามารถยังไม่พร้อม');
  const npc=action.npc,tier=view.tier;
  const target=()=>{check(action.itemId && view.itemIds.includes(action.itemId),'ability-target','เลือกสินค้าที่ใช้ความสามารถนี้ได้');return state.items[action.itemId]!;};
  switch(npc){
    case 'orc': {const item=target();p.orcDeal={itemId:item.id,percent:[10,15,20][tier]!,encounter:state.encounter};break;}
    case 'autometa': {const item=target();learn(p,item.id,{base:item.base,...(tier>=1?{genuine:item.genuine}:{}),...(tier>=2?{cursed:item.cursed,effectsKnown:true}:{})});break;}
    case 'vampire': {const item=target();p.preserveItemId=item.id;if(tier)recover(state,p,tier,'vampire-preserve');break;}
    case 'darkone': {check(action.statusId && view.statusIds.includes(action.statusId),'ability-target','เลือก debuff ที่มีอยู่');removeStatus(p,action.statusId);if(tier>=1)recover(state,p,1,'darkone-release');if(tier>=2)grant(state,p,'B06');break;}
    case 'deepsea': {const item=target();item.cursed=false;for(const seat of state.players)if(seat.knowledge[item.id]?.cursed!==undefined)seat.knowledge[item.id]!.cursed=false;if(state.publicKnowledge[item.id]?.cursed!==undefined)state.publicKnowledge[item.id]!.cursed=false;learn(p,item.id,{cursed:false,...(tier>=1?{genuine:item.genuine}:{}),...(tier>=2?{base:item.base}:{})});break;}
    case 'swarm': {
      const item=target(),percent=[25,35,50][tier]!;
      const id=`copy-${item.id}-1`;
      check(!state.items[id],'ability-copy','ต้นฉบับนี้เคยมีสำเนาแล้ว');
      const copy:AppraisalItem={...item,id,base:Math.floor(item.base*percent/100),ask:Math.floor(item.ask*percent/100),reservation:0,owner:p.id,certificate:false,lastAppraisal:null,lastAccepted:null,copy:{sourceId:item.id,number:Object.values(state.items).filter(i=>i.copy).length+1,valuePercent:percent}};
      delete copy.appraisedBy;delete copy.commissionPaid;delete copy.preserved;delete copy.copyConsumed;
      state.items[id]=copy;p.inventory.push(id);
      const facts=known(state,p,item.id);learn(p,id,{...(facts.base!==undefined?{base:copy.base}:{}),...(facts.genuine!==undefined?{genuine:copy.genuine}:{}),...(facts.cursed!==undefined?{cursed:copy.cursed}:{}),...(facts.effectsKnown?{effectsKnown:true}:{})});break;
    }
    case 'alien': case 'beast': {
      const source=target(),key=`${state.encounter}-${p.id}-${npc}`;
      const count=2+tier+(npc==='beast'&&status(p,'B26')?1:0),itemIds:string[]=[];
      // Beast replaces a shop slot. Alien swaps an owned item, never the number of owned goods.
      if(npc==='beast')itemIds.push(source.id);
      for(let i=0;i<count-(npc==='beast'?1:0);i++)itemIds.push(makeCandidate(state,p,npc==='beast'?source.npc:npc,key,i,npc==='alien'?source:undefined).id);
      p.abilityChoice={npc,sourceId:source.id,itemIds};
      if(npc==='alien'){state.listings=state.listings.filter(l=>l.itemId!==source.id);for(const offer of state.trades)if(offer.status==='open' && (offer.itemId===source.id||offer.swapItemId===source.id))offer.status='rejected';}if(npc==='beast')removeStatus(p,'B26');break;
    }
  }
  const haste=statusMagnitude(p,'B25',1),delay=statusMagnitude(p,'D25',2);
  p.abilityReady??={};p.abilityLastUsed??={};p.abilityAdjusted??={};
  p.abilityReady[npc]=state.encounter+Math.max(1,MERCHANT_ABILITIES[npc].cooldown-haste+delay);
  p.abilityLastUsed[npc]=state.encounter;p.abilityAdjusted[npc]=haste;p.skillUsed=true;
  removeStatus(p,'B25');removeStatus(p,'D25');
  p.notes.push(`ใช้ ${view.name} · พร้อมอีกครั้งช่วง ${p.abilityReady[npc]}`);p.notes=p.notes.slice(-30);
  trace(state,p,'merchant-ability-used',{npc,tier,itemId:action.itemId??null,readyAt:p.abilityReady[npc]});
}

export function npcEventEligible(state:AppraisalState,p:Appraiser,id:EventId):boolean {
  if(!state.config.npcEvents || state.phase!=='APPRAISAL' || p.paused || p.done || NPC_PERSONAL_EVENT[merchant(p)!]!==id)return false;
  const items=movable(state,p);
  const buffs=statusPool(state,p,'B').length;
  switch(id) {
    case 'E109': return !!state.config.survival && p.life!>2 && !p.npcContracts?.vampire;
    case 'E110': return !p.npcContracts?.alien && items.length>0 && freeBank(state)>=8;
    case 'E111': return (p.credits>=2 || p.energy>=1 || !!state.config.survival && p.life!>1 || items.length>0) && (p.statuses.some(s=>s.id.startsWith('D')) || livingOthers(state,p).length>0);
    case 'E112': return buffs>0 && (p.energy>=2 || items.length>0);
    case 'E113': return buffs>0 && p.energy>=2;
    case 'E114': return buffs>0 && items.length>0;
    case 'E116': return buffs>=2 && items.length>0;
    case 'E115': return buffs>0 && p.credits>=3 && p.stock.some(id=>{const k=known(state,p,id);return k.base===undefined || k.genuine===undefined || k.cursed===undefined;});
    default: return false;
  }
}

export function personalNpcOffer(state:AppraisalState,p:Appraiser,id:EventId,key:string):Partial<EventOffer> {
  const itemIds=movable(state,p),terms:NonNullable<EventOffer['npcTerms']>={credits:0,energy:0,life:0,items:0};
  let choices=['accept','decline'];
  if(id==='E109')terms.life=2;
  if(id==='E110') {
    terms.loanMax=Math.min(itemIds.length,1+Math.floor(randomAt(state.seed,`${key}:loan-size`)*3),Math.floor(freeBank(state)/8));
    choices=[...Array.from({length:terms.loanMax},(_,i)=>`lend-${i+1}`),'decline'];
  }
  if(id==='E111') {
    const costs:Array<keyof Pick<typeof terms,'credits'|'energy'|'life'|'items'>>=[];
    if(p.credits>=2)costs.push('credits');if(p.energy>=1)costs.push('energy');if(state.config.survival && p.life!>1)costs.push('life');if(itemIds.length)costs.push('items');
    const ranked=costs.map(cost=>({cost,rank:randomAt(state.seed,`${key}:cost:${cost}`)})).sort((a,b)=>a.rank-b.rank);
    const count=1+Math.floor(randomAt(state.seed,`${key}:cost-count`)*Math.min(3,costs.length));
    for(const {cost} of ranked.slice(0,count)) terms[cost]=cost==='credits'?Math.min(p.credits,2+Math.floor(randomAt(state.seed,`${key}:credits`)*4)):cost==='energy'?Math.min(p.energy,2):1;
    choices=[...(p.statuses.some(s=>s.id.startsWith('D'))?['purge']:[]),...(livingOthers(state,p).length?['send-debuff']:[]),'decline'];
  }
  if(id==='E112')choices=[...(itemIds.length?['give-item']:[]),...(p.energy>=2?['give-energy']:[]),'decline'];
  if(id==='E113')terms.energy=2;
  if(id==='E114' || id==='E116')terms.items=1;
  if(id==='E115')terms.credits=3;
  return {choices,itemIds:id==='E115'?[...p.stock]:itemIds,statusIds:p.statuses.filter(s=>s.id.startsWith('D')).map(s=>s.id),otherPlayerIds:livingOthers(state,p).map(other=>other.id),npcTerms:terms,
    targetKinds:Object.fromEntries((id==='E115'?p.stock:itemIds).map(itemId=>[itemId,state.items[itemId]!.kind]))};
}

function statusPool(state:AppraisalState,p:Appraiser,prefix:'B'|'D'):StatusId[] {
  return [...STATUS_IDS,...linkedStatuses(state.config,prefix)].filter(id=>id.startsWith(prefix) && !status(p,id)
    && (state.config.expansion || Number(id.slice(1))<=10 || Number(id.slice(1))>=17) && (state.config.polish || Number(id.slice(1))<=16)
    && (state.config.brokerage || id!=='B20') && (id!=='D09')
    && (state.config.survival || state.encounter<state.config.encounters || !['B09','D04','D07'].includes(id)));
}

function randomBuff(state:AppraisalState,p:Appraiser,key:string,preferred?:StatusId[]):void {
  const pool=statusPool(state,p,'B');const candidates=preferred?.filter(id=>pool.includes(id))??pool;
  const id=pick(state,key,candidates.length?candidates:pool.length?pool:['B03'] as StatusId[]);grant(state,p,id);
  note(p,`ได้รับพร ${STATUS_CATALOG.find(s=>s.id===id)!.name}`);
}

function payLife(state:AppraisalState,p:Appraiser,amount:number,reason:string):void {
  if(!amount)return;check(state.config.survival && p.life!>amount,'life','ชีวิตไม่พอจ่ายและต้องเหลืออย่างน้อย 1');
  if(state.config.personalScoringFacts===2)recordPersonalActivity(state,p,'lifeLost',amount,JSON.stringify(['life-paid',state.commands.length,reason]));
  p.life!-=amount;trace(state,p,'life-paid',{amount,reason});
}

export function resolvePersonalNpcEvent(state:AppraisalState,p:Appraiser,offer:EventOffer,command:Extract<AppraisalAction,{type:'event'}>):void {
  check(npcEventEligible(state,p,offer.id),'event-ineligible','เงื่อนไขอีเวนต์พ่อค้าเปลี่ยนไปแล้ว');
  const terms=offer.npcTerms;check(terms,'event-terms','ไม่มีเงื่อนไขข้อตกลง');
  const selected=()=>{check(command.itemId && offer.itemIds.includes(command.itemId),'event-target','เลือกสินค้าที่เสนอให้');return command.itemId;};
  const itemCost=terms.items || offer.id==='E112' && command.choice==='give-item';
  if(itemCost)ownedItem(state,p,selected(),true);
  const energy=terms.energy+(offer.id==='E112' && command.choice==='give-energy'?2:0);
  check(p.credits>=terms.credits && p.energy>=energy && (!terms.life || p.life!>terms.life),'event-cost','ทรัพยากรไม่พอจ่ายข้อตกลง');
  // Validate all player-selected targets before any payment; the engine also settles on a clone.
  const victim=command.choice==='send-debuff'?livingOthers(state,p).find(other=>other.id===command.otherPlayerId && offer.otherPlayerIds.includes(other.id)):undefined;
  if(command.choice==='send-debuff')check(victim,'event-target','เลือกผู้เล่นอื่นที่ยังมีชีวิต');
  if(command.choice==='purge')check(command.statusId && offer.statusIds.includes(command.statusId) && command.statusId.startsWith('D') && status(p,command.statusId),'event-target','เลือกผลเสียที่คุณมีอยู่');
  spend(state,p,terms.credits,energy,offer.id);payLife(state,p,terms.life,offer.id);
  if(itemCost)retire(state,p,selected(),offer.id);
  switch(offer.id) {
    case 'E109': (p.npcContracts??={}).vampire={signedAt:state.encounter,...(state.config.personalScoringRules===1?{performanceId:offer.key}:{})};note(p,'สัญญาเลือด: จ่ายชีวิต 2 แล้ว รับผลตอบแทนสุ่มเมื่อเลือกพบ Vampire ครั้งหน้า');break;
    case 'E110': {
      const count=Number(command.choice.slice(5)),ids=command.itemIds;
      check(Number.isInteger(count) && count>=1 && count<=terms.loanMax! && Array.isArray(ids) && ids.length===count && new Set(ids).size===count && ids.every(id=>offer.itemIds.includes(id)),'event-target','เลือกของให้ยืมให้ครบจำนวนและห้ามซ้ำ');
      for(const id of ids)ownedItem(state,p,id,true);
      check(freeBank(state)>=8*count,'bank','งบผลตอบแทนไม่พอ');
      for(const id of ids){p.inventory=p.inventory.filter(itemId=>itemId!==id);state.items[id]!.owner=`alien-loan:${p.id}`;}
      state.listings=state.listings.filter(l=>!ids.includes(l.itemId));
      state.reservedRewards+=8*count;(p.npcContracts??={}).alien={lentAt:state.encounter,dueAt:state.encounter+2,itemIds:[...ids],key:offer.key,reservedCredits:8*count};
      trace(state,p,'alien-loan',{itemIds:ids,dueAt:state.encounter+2});note(p,`Alien ยืมของ ${count} ชิ้น พบอีกครั้งตั้งแต่ช่วง ${state.encounter+2} เพื่อคืนของพร้อมโบนัสตามจำนวนชิ้น`);break;
    }
    case 'E111': {
      if(command.choice==='purge'){removeStatus(p,command.statusId!);note(p,`Dark One ล้าง ${STATUS_CATALOG.find(s=>s.id===command.statusId)!.name} ให้แล้ว`);}
      else {const pool=statusPool(state,victim!,'D');const id=pick(state,`${offer.key}:hex`,pool.length?pool:['D01'] as StatusId[]);grant(state,victim!,id);note(p,`Dark One ส่ง ${STATUS_CATALOG.find(s=>s.id===id)!.name} ให้ ${victim!.id}`);note(victim!,`${p.id} ส่ง ${STATUS_CATALOG.find(s=>s.id===id)!.name} ผ่าน Dark One`);trace(state,p,'npc-hex',{targetId:victim!.id,statusId:id});}break;
    }
    case 'E112': randomBuff(state,p,`${offer.key}:upgrade`);break;
    case 'E113': randomBuff(state,p,`${offer.key}:warrior`,['B04','B07','B19']);break;
    case 'E114': recover(state,p,4,offer.id);if(state.config.survival)healLife(state,p,2,offer.id);randomBuff(state,p,`${offer.key}:guide`,['B05','B09','B14']);break;
    case 'E115': {
      const ids=p.stock.filter(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}`);
      const clues=ids.flatMap(itemId=>{const k=known(state,p,itemId);return (['base','genuine','cursed'] as const).filter(fact=>k[fact]===undefined).map(fact=>({itemId,fact}));});
      check(clues.length,'event-target','ไม่มีข้อมูลใหม่ในร้าน');const clue=pick(state,`${offer.key}:whisper`,clues);learn(p,clue.itemId,{[clue.fact]:state.items[clue.itemId]![clue.fact]});
      randomBuff(state,p,`${offer.key}:depth`,['B12','B14','B16']);note(p,`เสียงจากก้นบึ้งเปิดผลตรวจ ${ITEM_SPECS[state.items[clue.itemId]!.kind].name} หนึ่งด้าน`);break;
    }
    case 'E116': {
      randomBuff(state,p,`${offer.key}:hive:1`,['B11','B13','B15','B16']);randomBuff(state,p,`${offer.key}:hive:2`,['B11','B13','B15','B16']);break;
    }
  }
}

function returnLoanItems(state:AppraisalState,p:Appraiser):number {
  const loan=p.npcContracts?.alien;if(!loan)return 0;
  for(const id of loan.itemIds){check(state.items[id]?.owner===`alien-loan:${p.id}`,'loan-owner','ของที่ให้ยืมไม่ตรงสัญญา');state.items[id]!.owner=p.id;p.inventory.push(id);}
  state.reservedRewards-=loan.reservedCredits;delete p.npcContracts!.alien;
  trace(state,p,'alien-returned',{itemIds:loan.itemIds});return loan.itemIds.length;
}

export function redeemNpcContracts(state:AppraisalState,p:Appraiser,npc:NpcId):void {
  if(!state.config.npcEvents)return;
  const blood=p.npcContracts?.vampire;
  if(npc==='vampire' && blood && state.encounter>blood.signedAt) {
    delete p.npcContracts!.vampire;
    const stock=p.stock.filter(id=>state.items[id]?.owner===`npc:${p.id}:${state.encounter}`);
    const pool=[...(statusPool(state,p,'B').length?['buff']:[]),...(stock.length?['item','discount']:[]),...(p.energy<maxEnergyOf(state,p)?['energy']:[]),...(state.config.survival && p.life!<maxLifeOf(state,p)!?['life']:[])];
    const outcome=pick(state,`${p.id}:${blood.signedAt}:blood-return`,pool);
    if(outcome==='item'){const id=pick(state,`${p.id}:${blood.signedAt}:blood-item`,stock);state.items[id]!.owner=p.id;p.inventory.push(id);p.stock=p.stock.filter(itemId=>itemId!==id);note(p,`Vampire ตอบแทนด้วย ${ITEM_SPECS[state.items[id]!.kind].name} ฟรี 1 ชิ้น`);}
    else if(outcome==='discount'){p.vampireDiscount={encounter:state.encounter};note(p,'Vampire ลดราคาสินค้า 50% สำหรับการซื้อจากร้านนี้ครั้งแรกในช่วงนี้ (ไม่รวมค่าธรรมเนียม)');}
    else if(outcome==='energy'){recover(state,p,6,'vampire-return');note(p,'Vampire ตอบแทนด้วยการฟื้นพลังสูงสุด 6');}
    else if(outcome==='life'){healLife(state,p,3,'vampire-return');note(p,'Vampire ตอบแทนด้วยการฟื้นชีวิตสูงสุด 3');}
    else randomBuff(state,p,`${p.id}:${blood.signedAt}:blood-buff`);
    trace(state,p,'vampire-repaid',{outcome});
    recordPersonalActivity(state,p,'npcContract',1,blood.performanceId??JSON.stringify([p.id,'vampire',blood.signedAt]));
  }
  const loan=p.npcContracts?.alien;
  if(npc==='alien' && loan && state.encounter>=loan.dueAt) {
    const perItem=4+Math.floor(randomAt(state.seed,`${loan.key}:credits`)*5),energy=1+Math.floor(randomAt(state.seed,`${loan.key}:energy`)*2);
    const count=returnLoanItems(state,p);reward(state,p,perItem*count,'alien-return');recover(state,p,energy*count,'alien-return');
    note(p,`Alien คืนของเดิม ${count} ชิ้น พร้อมโบนัส ${perItem*count} เครดิตและฟื้นพลังสูงสุด ${energy*count}`);
    trace(state,p,'alien-repaid',{count,credits:perItem*count,energy:energy*count});
    if(count>0)recordPersonalActivity(state,p,'npcContract',1,loan.key);
  }
}

export function closeNpcContracts(state:AppraisalState):void {
  if(!state.config.npcEvents)return;
  for(const p of state.players){const count=returnLoanItems(state,p);if(count)note(p,`จบรัน: Alien คืนของ ${count} ชิ้นเพื่อคิดคะแนน แต่ไม่ได้โบนัสเพราะยังไม่ได้พบกันตามเงื่อนไข`);if(p.npcContracts)delete p.npcContracts.vampire;delete p.vampireDiscount;}
}

export function omenOf(config:Pick<AppraisalConfig,'polish'|'core2'>,seed:string,encounter:number):Omen|undefined {
  if(!config.polish) return undefined;
  if(config.core2) return core2Omen(seed,encounter);
  let index=pick(seed,1);
  for(let e=2;e<=encounter;e++) {
    const next=pick(seed,e);
    index=next===index?(index+1+Math.floor(randomAt(seed,`${e}:omen:shift`)*(OMENS.length-1)))%OMENS.length:next;
  }
  return OMENS[index];
}

core2Weight=(omen:typeof CORE2_OMENS[number],encounter:number)=>{
  if((omen.from??1)>encounter) return 0;
  return omen.kind==='harsh'?1+(encounter-1)*.25:omen.kind==='relief'?Math.max(.35,1-(encounter-1)*.08):1;
}

function core2Omen(seed:string,encounter:number):Omen {
  let previous=-1,chosen=0;
  for(let e=1;e<=encounter;e++) {
    const weights=CORE2_OMENS.map((omen,index)=>index===previous?0:core2Weight(omen,e));
    let roll=randomAt(seed,`${e}:omen2`)*weights.reduce((a,b)=>a+b,0);
    chosen=weights.findIndex(weight=>(roll-=weight)<0);
    if(chosen<0) chosen=weights.findLastIndex(weight=>weight>0);
    previous=chosen;
  }
  return CORE2_OMENS[chosen]!;
}

export function heldPassives(items:ReadonlyArray<PoweredItem & {kind:ItemKind;copy?:unknown}>,itemEffects=false):PassiveBonuses {
  const result=emptyPassives(),counts=new Map<ItemKind,number>();
  for(const item of itemEffects?[...items].sort((a,b)=>itemEffectScale(b)-itemEffectScale(a)):items){
    const count=counts.get(item.kind)??0;if(itemEffects && count>=HELD_STACK_CAP)continue;
    counts.set(item.kind,count+1);
    const effect=passiveSpec(item.kind)?.passive??(itemEffects?EXTRA_HELD_EFFECTS[item.kind]:undefined);
    if(effect)result[effect.effect]+=effect.amount*(itemEffects?itemEffectScale(item):rarityEffect(item));
  }
  for(const key of Object.keys(result) as Array<keyof PassiveBonuses>)if(!['commission','luck','acceptance','mitigation'].includes(key))result[key]=integerEffect(result[key]);
  return result;
}

export function passiveBonuses(state:AppraisalState,p:Appraiser,exclude:readonly string[]=[]):PassiveBonuses {
  if(p.life===0)return emptyPassives();
  const held=heldPassives(p.inventory.filter(id=>!exclude.includes(id) && state.items[id]?.owner===p.id).map(id=>state.items[id]!),!!state.config.itemEffects);
  return addUseBonuses(passivesEnabled(state.config)?held:emptyPassives(),state.config.itemEffects?p.itemUseBonuses:undefined);
}

export function freeInspectionCount(b:PassiveBonuses,p:Pick<Appraiser,'passiveUses'>,property:InspectionProperty):number {
  return Math.max(0,b[property==='price'?'freePrice':property==='authenticity'?'freeAuth':'freeEffects']-(p.passiveUses?.[property]??0));
}

export function passiveMarketBonus(order:MarketOrder,b:PassiveBonuses,match:boolean,markdown:boolean,quotePrice=order.price):number {
  return b.market+(match?b.match:0)+(markdown?Math.floor(quotePrice*(80+Math.min(20,b.mitigation))/100)-Math.floor(quotePrice*.8):0);
}

function validateFact(value:unknown):asserts value is PersonalFact {
 requireValue(!!value&&typeof value==='object','fact required');const f=value as Partial<PersonalFact>;
 for(const s of [f.id,f.playerId,f.eligibleKey,f.cause])requireValue(typeof s==='string'&&s.length>0,'fact identity required');
 requireValue(metricIds.has(f.metric as PersonalMetric),'unknown metric');requireValue(typeof f.eligible==='boolean','eligibility required');nonnegative(f.raw as number);
}

export function recordPersonalFact(state:PersonalPerformanceState,fact:PersonalFact):void {
 if(state.config.personalScoringRules!==1)return;
 validateFact(fact);requireValue(state.players.some(p=>p.id===fact.playerId),'unknown player');
 const old=state.personalPerformance?.facts.find(f=>f.id===fact.id);if(old){requireValue(signature(old)===signature(fact),'receipt identity conflict');return;}
 state.personalPerformance??={version:1,facts:[]};state.personalPerformance.facts.push({...fact});
}

export function recordPersonalActivity(state:AppraisalState,p:Appraiser,metric:PersonalMetric,raw:number,source:string,eligible=true,cause='settled'):void {
 if(state.config.personalScoringRules!==1||p.life===0||state.phase==='RESULTS')return;
 recordPersonalFact(state,{id:JSON.stringify([state.commands.length,state.personalPerformance!.facts.length,p.id,metric]),playerId:p.id,metric,raw,eligibleKey:source,eligible,cause});
}

export function recordPersonalItemActivity(state:AppraisalState,p:Appraiser,metric:PersonalMetric,item:AppraisalItem,raw=1,eligible=true,cause='settled',facet=''):void {
 recordPersonalActivity(state,p,metric,raw,JSON.stringify([p.id,personalOrigin(item),facet]),eligible&&!item.copy,item.copy?'copy':eligible?'settled':cause);
}

export function recordPersonalInspection(state:AppraisalState,p:Appraiser,item:AppraisalItem,before:Knowledge,after:Knowledge,legacyProperty?:InspectionProperty):void {
 if(state.config.personalScoringFacts!==2){if(legacyProperty)recordPersonalItemActivity(state,p,'inspection',item,1,true,'personally inspected',legacyProperty);return;}
 const price=before.base===undefined&&(after.base!==undefined||!!after.range&&JSON.stringify(after.range)!==JSON.stringify(before.range));
 const authenticity=before.genuine===undefined&&after.genuine!==undefined;
 const effects=before.cursed===undefined&&after.cursed!==undefined||!before.effectsKnown&&!!after.effectsKnown;
 for(const [facet,learned]of [['price',price],['authenticity',authenticity],['effects',effects]]as const)if(learned)recordPersonalItemActivity(state,p,'inspection',item,1,true,'personally inspected',facet);
}

export function recordPersonalSale(state:AppraisalState,p:Appraiser,item:AppraisalItem,price:number):void {
 recordPersonalItemActivity(state,p,'soldQuantity',item,1,price>0,'zero-credit sale');
 recordPersonalItemActivity(state,p,'soldGrossCredits',item,price,price>0,'zero-credit sale');
}

export function recordPersonalAppraisal(state:AppraisalState,p:Appraiser,item:AppraisalItem,value:number):void {
 if(state.config.personalScoringRules!==1)return;
 const source=JSON.stringify([p.id,personalOrigin(item),'']);
 const first=!state.personalPerformance!.facts.some(f=>f.playerId===p.id&&f.metric==='accurateAppraisal'&&f.eligibleKey===source&&f.cause!=='copy');
 const accurate=Math.abs(value-item.base)<=item.base*.2;
 recordPersonalItemActivity(state,p,'accurateAppraisal',item,accurate?1:0,first&&accurate,first?'first appraisal outside20percent':'not first appraisal');
}

export function setPersonalTrust(state:AppraisalState,p:Appraiser,npc:NpcId,next:number,item:AppraisalItem):void {
 if(!p.npcTrust)return;
 const before=p.npcTrust[npc]??0;p.npcTrust[npc]=next;
 if(next>before)recordPersonalActivity(state,p,'trustGained',next-before,JSON.stringify([p.id,personalOrigin(item),npc]));
}

export function personalScoreFor(state:AppraisalState,playerId:string,finalAssets?:{credits:number;itemValue:number;itemIds:readonly string[]}):PersonalScoreBreakdown {
 const p=state.players.find(p=>p.id===playerId);requireValue(p,'unknown player');
 const final=state.collector?.find(row=>row.playerId===playerId)?.personalScore;if(final)return structuredClone(final);
 const itemIds=finalAssets?.itemIds??ownedAssetItemIds(state,p),items=itemIds.map(id=>state.items[id]!);
 const credits=finalAssets?.credits??p.credits+(p.personalVault?.credits??0);
 const itemValue=finalAssets?.itemValue??items.reduce((sum,item)=>sum+itemScoreValue(item.base,item.genuine,item.cursed,!!item.appraisedBy&&item.appraisedBy!==p.id),0);
 return calculatePersonalScore({playerId,facts:state.personalPerformance?.facts??[],assetScore:credits+itemValue,modifierPercent:statusMagnitude(p,'B10',20)-statusMagnitude(p,'D10',20),ghostBonus:state.ghosts?.[p.id]?.bonus??0,rarities:items.filter(item=>!item.copy).map(item=>({id:item.id,rarity:item.appearance?.rarity??'common'}))});
}

export function personalScoreEstimateFor(state:AppraisalState,p:Appraiser):{min:number;max:number;unpriced:number;modifier:number} {
 let low=0,high=0,unpriced=0;
 const items=ownedAssetItemIds(state,p).map(id=>state.items[id]!);
 for(const item of items){const range=itemScoreRange(known(state,p,item.id),!!item.appraisedBy&&item.appraisedBy!==p.id);if(range){low+=range[0];high+=range[1];}else unpriced++;}
 const modifier=statusMagnitude(p,'B10',20)-statusMagnitude(p,'D10',20),credits=p.credits+(p.personalVault?.credits??0);
 const input={playerId:p.id,facts:(state.personalPerformance?.facts??[]).filter(f=>f.metric!=='accurateAppraisal'),modifierPercent:modifier,ghostBonus:state.ghosts?.[p.id]?.bonus??0,rarities:items.filter(i=>!i.copy).map(i=>({id:i.id,rarity:i.appearance?.rarity??'common' as const}))};
 const min=calculatePersonalScore({...input,assetScore:credits+low}).total;
 // Include the approved cap as a conservative unresolved allowance; never expose a hidden successful appraisal count.
 const max=calculatePersonalScore({...input,assetScore:credits+high+PERSONAL_SCORING_WEIGHTS.find(r=>r.id==='accurateAppraisal')!.cap}).total;
 return {min:Math.min(min,max),max:Math.max(min,max),unpriced,modifier};
}

export function personalPerformanceInvariants(state:PersonalPerformanceState):void {
 const performance=state.personalPerformance;requireValue((state.config.personalScoringRules===1)===!!performance,'flag/state mismatch');if(!performance)return;
 requireValue(state.config.personalScoringRules===1&&performance.version===1,'unexpected version');requireValue(Array.isArray(performance.facts),'receipt list required');
 const ids=new Set<string>();for(const f of performance.facts){validateFact(f);requireValue(state.players.some(p=>p.id===f.playerId),'unknown player');requireValue(!ids.has(f.id),'duplicate receipt');ids.add(f.id);}
}

export function calculatePersonalScore(input:PersonalScoreInput):PersonalScoreBreakdown {
 nonnegative(input.assetScore);nonnegative(input.ghostBonus);requireValue(Number.isFinite(input.modifierPercent),'finite modifier required');requireValue(typeof input.playerId==='string'&&input.playerId.length>0,'player required');
 const ids=new Set<string>();for(const f of input.facts){validateFact(f);requireValue(!ids.has(f.id),'duplicate receipt');ids.add(f.id);}
 const metrics:PersonalMetricResult[]=[];
 for(const rule of PERSONAL_SCORING_WEIGHTS){
  let raw=0,eligible=0,uncappedPoints=0;const sourceIds:string[]=[],exclusions:{id:string;cause:string}[]=[];
  if(rule.id==='rarity'){
   const origins=new Set<string>();for(const item of input.rarities){requireValue(typeof item.id==='string'&&item.id.length>0&&!origins.has(item.id),'duplicate or missing rarity origin');requireValue(Object.hasOwn(rule.byRarity,item.rarity),'unknown rarity');origins.add(item.id);sourceIds.push(item.id);raw++;uncappedPoints=add(uncappedPoints,rule.byRarity[item.rarity]);}eligible=raw;
   metrics.push({id:rule.id,raw,eligible,uncappedPoints,points:Math.min(uncappedPoints,rule.cap),cap:rule.cap,weight:{byRarity:rule.byRarity},sourceIds,exclusions});continue;
  }
  if(rule.id==='ghost'){metrics.push({id:rule.id,raw:input.ghostBonus,eligible:input.ghostBonus,uncappedPoints:input.ghostBonus,points:input.ghostBonus,cap:null,weight:{numerator:1,denominator:1},sourceIds,exclusions});continue;}
  const keys=new Set<string>();for(const f of input.facts){if(f.playerId!==input.playerId||f.metric!==rule.id)continue;raw=add(raw,f.raw);sourceIds.push(f.id);if(!f.eligible){exclusions.push({id:f.id,cause:f.cause});continue;}if(f.raw===0)continue;if(keys.has(f.eligibleKey)){exclusions.push({id:f.id,cause:'repeated origin or source'});continue;}keys.add(f.eligibleKey);eligible=add(eligible,f.raw);}
  const scaled=BigInt(eligible)*BigInt(rule.numerator)/BigInt(rule.denominator);requireValue(scaled<=BigInt(Number.MAX_SAFE_INTEGER),'safe uncapped score overflow');uncappedPoints=Number(scaled);
  metrics.push({id:rule.id,raw,eligible,uncappedPoints,points:Math.min(uncappedPoints,rule.cap),cap:rule.cap,weight:{numerator:rule.numerator,denominator:rule.denominator},sourceIds,exclusions});
 }
 const performancePoints=metrics.filter(m=>m.id!=='ghost').reduce((n,m)=>add(n,m.points),0),ordinaryBeforeModifier=add(input.assetScore,performancePoints),ordinaryScore=collectorTotal(ordinaryBeforeModifier,0,input.modifierPercent);
 requireValue(Number.isSafeInteger(ordinaryScore),'safe modified score overflow');const modifierDelta=ordinaryScore-ordinaryBeforeModifier;requireValue(Number.isSafeInteger(modifierDelta),'safe modifier delta overflow');const total=add(ordinaryScore,input.ghostBonus);
 const groups=[{id:'assets',points:input.assetScore},...['commerce','knowledge','relations','finance','journey','collection'].map(id=>({id,points:PERSONAL_SCORING_WEIGHTS.filter(r=>r.group===id).reduce((n,r)=>add(n,metrics.find(m=>m.id===r.id)!.points),0)})),{id:'modifier',points:modifierDelta},{id:'ghost',points:input.ghostBonus}];
 return {playerId:input.playerId,metrics,groups,performancePoints,ordinaryBeforeModifier,modifierDelta,ordinaryScore,ghostBonus:input.ghostBonus,total};
}

export function pilotHeld(state:AppraisalState,p:Appraiser,kind:PilotItemKind):AppraisalItem[] {
  if(state.config.catalogVersion!==4 || p.life===0 || p.paused==='dead')return [];
  return p.inventory.map(id=>state.items[id]!).filter(i=>i?.kind===kind && i.owner===p.id && !p.npcContracts?.alien?.itemIds.includes(i.id))
    .sort((a,b)=>itemEffectScale(b)-itemEffectScale(a)||a.id.localeCompare(b.id)).slice(0,5);
}

export function priceCaliper(state:AppraisalState,p:Appraiser):AppraisalItem|undefined {
  return pilotHeld(state,p,'autometa-torque-caliper').find(i=>pilotUses(state,i)<integerEffect(itemEffectScale(i)));
}

export function pilotRerollCost(state:AppraisalState,p:Appraiser,base:number):number {
  return Math.max(1,base-Math.min(2,integerEffect(pilotStrength(state,p,'deepsea-tide-compass'))));
}

export function pilotExpansionCost(state:AppraisalState,p:Appraiser,base:number):number {
  return Math.max(1,base-Math.min(Math.floor(base/2),integerEffect(2*pilotStrength(state,p,'swarm-brood-hammer'))));
}

export function pilotCrimeCost(state:AppraisalState,p:Appraiser,base:number):number {
  const discount=Math.min(5000,integerEffect(1000*pilotStrength(state,p,'darkone-crossing-token')));
  return base>0?Math.max(1,Math.floor(base*(10000-discount)/10000)):0;
}

export function heldInterestRings(state:AppraisalState,p:Appraiser):Record<string,number> {
  return Object.fromEntries(pilotHeld(state,p,'vampire-nocturne-signet').map(i=>[i.id,integerEffect(200*itemEffectScale(i))]));
}

export function ringInterestBasisPoints(state:AppraisalState,p:Appraiser,start:Record<string,number>={}):number {
  const end=heldInterestRings(state,p);
  return Math.min(400,Object.entries(start).reduce((n,[id,amount])=>n+Math.min(amount,end[id]??0),0));
}

export function swordForDuel(state:AppraisalState,p:Appraiser):AppraisalItem|undefined {
  return pilotHeld(state,p,'beast-riftfang-sword').find(i=>itemEffectScale(i)>=1 && pilotUses(state,i)===0);
}

export function reconcilePilotCustody(state:AppraisalState):void {
  if(state.config.catalogVersion!==4)return;
  for(const p of state.players){const rings=p.personalVault?.interest?.rings;if(!rings)continue;const held=new Set(pilotHeld(state,p,'vampire-nocturne-signet').map(i=>i.id));for(const id of Object.keys(rings))if(!held.has(id))delete rings[id];}
}

export function priceAuditChance(base:number,value:number):number {
  if(value<base*1.5)return 0;
  if(value<base*2)return .25;
  return value<base*2.5?.5:1;
}

export function auditItemPrice(state:AppraisalState,item:AppraisalItem,value:number,sourceKey:string):void {
  if(!state.config.secureEconomy)return;
  check(Number.isSafeInteger(value) && value>=0,'price','ราคาที่ตรวจสอบไม่ถูกต้อง');
  const integrity=item.priceIntegrity??={overpriced:false,audits:0};
  integrity.audits++;
  const chance=priceAuditChance(item.base,value);
  const flagged=randomAt(state.seed,`${state.encounter}:${item.id}:price-integrity:${sourceKey}:${integrity.audits}`)<chance;
  if(flagged)integrity.overpriced=true;
  state.trace.push({encounter:state.encounter,playerId:item.owner,type:'price-audited',details:{itemId:item.id,value,source:sourceKey,chance,flagged}});
}

export function recordItemTrade(state:AppraisalState,item:AppraisalItem,paidPrice:number):void {
  if(!state.config.secureEconomy)return;
  check(Number.isSafeInteger(paidPrice) && paidPrice>=0,'price','ราคาซื้อขายไม่ถูกต้อง');
  item.lastTradePrice=paidPrice;
  auditItemPrice(state,item,paidPrice,'trade');
}

export function systemSaleQuote(state:AppraisalState,item:AppraisalItem,quote:number):number {
  return state.config.secureEconomy && item.priceIntegrity?.overpriced?0:quote;
}

export function liquidationQuote(state:AppraisalState,item:AppraisalItem):number {
  const reference=Math.max(0,Math.min(item.base,item.priceIntegrity?.certifiedPrice??item.base));
  return systemSaleQuote(state,item,copySaleQuote(item,Math.floor(Math.min(item.lastTradePrice??reference,reference))));
}

export function liquidateOwnedItem(state:AppraisalState,p:Appraiser,itemId:string):void {
  check(state.config.secureEconomy && ['APPRAISAL','TRADE'].includes(state.phase),'liquidate','ยังขายของเพื่อรับเงินสดไม่ได้');
  const item=ownedItem(state,p,itemId,true);
  check(!item.stolen,'stolen','ของที่ฉกมาขาย Dark Market ไม่ได้');
  const price=liquidationQuote(state,item);
  reward(state,p,price,'emergency-liquidation');
  recordItemTrade(state,item,price);if(state.config.personalScoringFacts===2)recordPersonalSale(state,p,item,price);
  retire(state,p,itemId,'emergency-liquidation');
  trace(state,p,'item-liquidated',{itemId,price});
}

export function reappraiseOwnedItem(state:AppraisalState,p:Appraiser,itemId:string,value:number):void {
  check(state.config.secureEconomy && ['APPRAISAL','TRADE'].includes(state.phase),'reappraisal','ยังประเมินของในมือใหม่ไม่ได้');
  const item=ownedItem(state,p,itemId,true);
  check(Number.isSafeInteger(value) && value>=0 && value<=1000,'price','ราคาประเมินไม่ถูกต้อง');
  check(item.priceIntegrity?.lastReappraisedEncounter!==state.encounter,'reappraisal-used','ประเมินของชิ้นนี้ใหม่แล้วในช่วงนี้');
  spend(state,p,0,1,'reappraise-owned');
  const integrity=item.priceIntegrity??={overpriced:false,audits:0};
  integrity.lastReappraisedEncounter=state.encounter;
  const success=Math.abs(value-item.base)<=item.base*.1;
  auditItemPrice(state,item,value,'owner-reappraisal');
  recordPersonalAppraisal(state,p,item,value);
  if(success) {
    integrity.overpriced=false;integrity.certifiedPrice=value;
    item.lastAppraisal=value;item.lastAccepted=true;
  }
  p.notes.push(success?'ประเมินใหม่สำเร็จ ล้างตราราคาเกินจริงแล้ว':'ประเมินใหม่ไม่สำเร็จ ตราราคาเกินจริงยังคงอยู่');
  p.notes=p.notes.slice(-30);
  trace(state,p,'item-reappraised',{itemId,value,success});
}

export function integrityItemView(state:AppraisalState,item:AppraisalItem):{lastTradePrice?:number;overpriced?:boolean;reappraisalUsed?:boolean} {
  if(!state.config.secureEconomy)return {};
  return {...(item.lastTradePrice!==undefined?{lastTradePrice:item.lastTradePrice}:{}),overpriced:!!item.priceIntegrity?.overpriced,
    reappraisalUsed:item.priceIntegrity?.lastReappraisedEncounter===state.encounter};
}

export function linkTrade(p:Appraiser,partnerId:string,encounter:number):void {
  if(p.tradeLink?.partner!==partnerId)p.tradeLink={partner:partnerId,since:encounter};
}

export function ensureItemAppearance(state:AppraisalState,item:AppraisalItem):void {
  if(state.config.rarity && !item.appearance){
    const seed=Math.floor(randomAt(state.seed,`${item.id}:appearance:v1`)*0x100000000);
    item.appearance=rollAppearance(seed,state.config.rarity);
  }
  if(state.config.rarityEconomy && item.appearance && !item.rarityPower){
    item.rarityPower=rarityPowerFor(item.appearance.rarity,state.config.rarityEconomy);
    item.base=rarityValue(item,item.base);item.ask=rarityValue(item,item.ask);item.reservation=rarityValue(item,item.reservation);
  }
}

export function itemPriceRange(config:AppraisalConfig,item:AppraisalItem):[number,number] {
  const range=priceRange(item.kind,anchorOf(config,item.kind));
  if(!item.rarityPower)return range;
  const factor=(item.rarityPower?.valueMultiplier??1)*(item.copy?item.copy.valuePercent/100:1);
  return [Math.min(Math.floor(range[0]*factor),item.base),Math.max(Math.ceil(range[1]*factor),item.base)];
}

export function openRoundRewards(state:AppraisalState):void {
  if(!state.config.roundRewards)return;
  for(const p of state.players) {
    if(state.config.survival && p.life===0)continue;
    const base=state.encounter%2?10:15;
    const b=passiveBonuses(state,p);
    // Polish: lucky/unlucky coins and the omen shift the post-trade reward and the coin odds.
    const polish=state.config.polish;const income=b.income+(polish?integerEffect(statusMagnitude(p,'B18',3))-integerEffect(statusMagnitude(p,'D19',3))+(omenNow(state)?.roundBonus??0):0);
    const luck=polish?statusMagnitude(p,'B18',10)-statusMagnitude(p,'D19',10):0;
    p.roundReward={encounter:state.encounter,base,amount:base+income,flips:0,settled:false,...(passivesEnabled(state.config) || income!==b.income || luck?{incomeBonus:income,winBonus:5+b.coinWin,winChance:Math.max(15,Math.min(85,coinWinChance(b)+luck))}:{})};
    if(state.config.multiCoinRewards)Object.assign(p.roundReward,{coinCount:1,staked:0,net:0});
  }
}

export function raiseRoundReward(state:AppraisalState,p:Appraiser,coinCount:number,attempt:number):void {
  const r=p.roundReward;
  check(state.phase==='REVEAL' && state.config.multiCoinRewards && r && !r.settled && r.amount>0,'round-reward','ไม่มีรางวัลที่ทบได้');
  check(Number.isSafeInteger(coinCount) && coinCount===(r.coinCount??1)+1 && attempt===r.flips+1,'coin-attempt','ใช้จำนวนเหรียญและผลล่าสุดก่อนทบ');
  check(p.credits>=r.base,'credits','เครดิตในกระเป๋าไม่พอเพิ่มเหรียญ');
  check(Number.isSafeInteger(r.amount+r.base),'round-reward','ยอดเดิมพันสูงเกินไป');
  p.credits-=r.base;r.amount+=r.base;r.staked=(r.staked??0)+r.base;r.coinCount=coinCount;
  state.ledger.push({from:p.id,to:'@round-fund',amount:r.base,reason:'round-stake',encounter:state.encounter});
  trace(state,p,'round-coin-raised',{coinCount,stake:r.base,amount:r.amount});
}

export function flipRoundReward(state:AppraisalState,p:Appraiser,guess:CoinSide,attempt:number,guesses?:CoinSide[]):void {
  const r=p.roundReward;
  check(state.phase==='REVEAL' && r && !r.settled,'round-reward','ไม่มีรางวัลที่เดิมพันได้');
  check(guess==='heads' || guess==='tails','coin-side','เลือกหัวหรือก้อย');
  check(Number.isSafeInteger(attempt) && attempt===r.flips+1,'coin-attempt','ใช้ผลการโยนเหรียญล่าสุดก่อนเล่นต่อ');
  if(state.config.multiCoinRewards) {
    const calls=guesses??[guess];
    check(Array.isArray(calls) && calls.length===r.coinCount && calls[0]===guess && calls.every(call=>call==='heads' || call==='tails'),'coin-side','ทายหัวหรือก้อยให้ครบทุกเหรียญ');
    const coins=calls.map((call,index)=>{
      // Keep the first coin's original random stream; each added coin has an independent stream.
      const suffix=index?`:coin:${index+1}`:'';
      let side:CoinSide=randomAt(state.seed,`${state.encounter}:${p.id}:round-coin:${attempt}${suffix}`)<.5?'heads':'tails';
      const chance=r.winChance??50;
      if(side!==call && chance>50 && randomAt(state.seed,`${state.encounter}:${p.id}:round-coin-luck:${attempt}${suffix}`)<(chance-50)/50)side=call;
      if(side===call && chance<50 && randomAt(state.seed,`${state.encounter}:${p.id}:round-coin-unluck:${attempt}${suffix}`)<(50-chance)/50)side=call==='heads'?'tails':'heads';
      return {guess:call,side,correct:call===side};
    });
    const correct=coins.every(coin=>coin.correct);const step=(r.winBonus??5)*coins.length;
    const amount=correct?r.amount+step:Math.max(0,r.amount-step);
    check(Number.isSafeInteger(amount),'round-reward','ยอดเดิมพันสูงเกินไป');
    const delta=amount-r.amount;r.net=(r.net??0)+delta;r.amount=amount;r.flips=attempt;r.settled=amount===0;
    r.lastFlip={...coins[0]!,correct,coins,delta};
    trace(state,p,'round-coin',{attempt,guess,side:coins[0]!.side,correct,coins,delta,amount});
    return;
  }
  check(guesses===undefined,'coin-side','กติกานี้ทายได้ครั้งละหนึ่งเหรียญ');
  let side:CoinSide=randomAt(state.seed,`${state.encounter}:${p.id}:round-coin:${attempt}`)<.5?'heads':'tails';
  if(side!==guess && (r.winChance??50)>50 && randomAt(state.seed,`${state.encounter}:${p.id}:round-coin-luck:${attempt}`)<((r.winChance??50)-50)/50)side=guess;
  const correct=guess===side;
  r.flips=attempt;r.lastFlip={guess,side,correct};
  r.amount=correct?r.amount+(r.winBonus??5):0;r.settled=!correct;
  trace(state,p,'round-coin',{attempt,guess,side,correct,amount:r.amount});
}

export function bankRoundReward(state:AppraisalState,p:Appraiser):void {
  const r=p.roundReward;
  check(state.phase==='REVEAL' && r && !r.settled,'round-reward','ไม่มีรางวัลที่รับได้');
  // Round income is a separate source of liquidity; finite merchant reserves stay intact.
  p.credits+=r.amount;r.settled=true;
  state.ledger.push({from:'@round-fund',to:p.id,amount:r.amount,reason:'round-reward',encounter:state.encounter});
  trace(state,p,'round-reward-banked',{amount:r.amount,flips:r.flips});
}

export function itemScoreValue(base:number,genuine:boolean,cursed:boolean,certified=false):number {
  return Math.floor(base*(genuine?100:25)*(cursed?75:100)*(certified?100+PROVENANCE_PERCENT:100)/1000000);
}

export function collectorTotal(credits:number,itemValue:number,modifierPercent:number):number {
  return Math.floor((credits+itemValue)*(100+modifierPercent)/100);
}

export function itemScoreRange(k:Knowledge,certified=false):[number,number]|null {
  const range=k.base!==undefined?[k.base,k.base]:k.range;if(!range) return null;
  const genuine=k.genuine===undefined?[true,false]:[k.genuine],cursed=k.cursed===undefined?[false,true]:[k.cursed];
  const values=range.flatMap(base=>genuine.flatMap(g=>cursed.map(c=>itemScoreValue(base,g,c,certified))));
  return [Math.min(...values),Math.max(...values)];
}

text = (value: unknown) => {
  check(value === undefined || typeof value === 'string' && value.length <= 500,'seal-terms','ข้อตกลงยาวได้ไม่เกิน 500 ตัวอักษร');
  return (value as string | undefined) ?? '';
}

function ownSeal(state: AppraisalState, p: Appraiser, sealId: string): SinnerSeal {
  const seal = seals(state).find(s => s.id === sealId);
  check(seal && seal.holderId === p.id,'seal-owner','ไม่ได้ถือตรานี้');
  check(!lockedSealIds(state).has(seal.id),'seal-locked','ตรานี้อยู่ระหว่างข้อเสนอหรือการใช้สิทธิ์');
  return seal;
}

function moveGoods(state: AppraisalState, from: Appraiser, to: Appraiser, item: AppraisalItem): void {
  from.inventory = from.inventory.filter(id => id !== item.id);
  if(from.paid)delete from.paid[item.id];
  item.owner = to.id; to.inventory.push(item.id);
  state.listings = state.listings.filter(l => l.itemId !== item.id);
}

function offerSeal(state: AppraisalState, p: Appraiser, action: Extract<SealAction,{type:'seal-offer'}>): void {
  const seal = ownSeal(state,p,action.sealId);
  const buyer = player(state,action.buyerId);
  check(buyer.id !== p.id && alive(buyer),'seal-party','ต้องขายให้ผู้เล่นอื่นที่ยังมีชีวิต');
  for(const [value,code] of [[action.credits,'seal-credits'],[action.energy,'seal-energy'],[action.life,'seal-life']] as const)amount(value,code);
  check(Number.isSafeInteger(action.goods) && action.goods >= 0 && action.goods <= 8,'seal-items','จำนวนสินค้าที่ขอไม่ถูกต้อง');
  check(action.life === 0 || state.config.survival,'seal-life','ห้องนี้ไม่มีชีวิตให้แลก');
  check(action.credits+action.energy+action.life+action.goods > 0 || text(action.terms) !== '','seal-empty','ต้องระบุสิ่งตอบแทนหรือข้อตกลง');
  check(!offers(state).some(o => o.status === 'open' && o.sealId === seal.id),'seal-locked','ตรานี้มีข้อเสนอค้างอยู่');
  const list = offers(state);
  list.push({id:`seal-offer:${list.length+1}`,sealId:seal.id,holderId:p.id,buyerId:buyer.id,credits:action.credits,energy:action.energy,life:action.life,goods:action.goods,terms:text(action.terms),encounter:state.encounter,status:'open'});
  trace(state,p,action.type,{offerId:list.at(-1)!.id});
}

function respondOffer(state: AppraisalState, p: Appraiser, offerId: string, accept: boolean, itemIds: string[] = []): void {
  check(typeof accept === 'boolean','seal-response','คำตอบไม่ถูกต้อง');
  const offer = offers(state).find(o => o.id === offerId);
  check(offer && offer.status === 'open' && offer.buyerId === p.id && offer.encounter === state.encounter,'seal-offer','ไม่มีข้อเสนอซื้อตรานี้ให้ตอบ');
  if(!accept) { offer.status = 'declined'; return; }
  const holder = player(state,offer.holderId);
  const seal = seals(state).find(s => s.id === offer.sealId);
  check(seal && seal.holderId === holder.id && !redemptions(state).some(r => r.status === 'open' && r.sealIds.includes(seal.id)),'seal-owner','ผู้ขายไม่ได้ถือตรานี้แล้ว');
  check(alive(holder) && alive(p),'seal-party','คู่ค้าต้องยังมีชีวิต');
  check(Array.isArray(itemIds) && itemIds.length === offer.goods && new Set(itemIds).size === itemIds.length,'seal-items','ต้องเลือกสินค้าให้ตรงจำนวนที่ผู้ขายขอ');
  const goods = itemIds.map(id => ownedItem(state,p,id,true));
  check(p.credits >= offer.credits,'credits','เครดิตไม่พอ');
  check(p.energy >= offer.energy && holder.energy+offer.energy <= maxEnergyOf(state,holder),'seal-energy','พลังไม่พอหรือผู้รับเต็ม');
  if(offer.life > 0)check((p.life ?? 0) > offer.life && (holder.life ?? 0)+offer.life <= (maxLifeOf(state,holder) ?? 0),'seal-life','ชีวิตผู้จ่ายต้องเหลือ 1 ขึ้นไป และผู้รับต้องไม่เกินขีดสูงสุด');
  if(offer.credits)transfer(state,p,holder,offer.credits,'seal-sale');
  p.energy -= offer.energy; holder.energy += offer.energy;
  if(offer.life > 0) { if(state.config.personalScoringFacts===2)recordPersonalActivity(state,p,'lifeLost',offer.life,offer.id);p.life! -= offer.life; holder.life! += offer.life; }
  for(const item of goods)moveGoods(state,p,holder,item);
  offer.status = 'accepted';
  if(seal.thiefId === p.id) {
    // Buying back your own seal removes it for good, so nobody can combine it with another.
    (state as SealState).sinnerSeals = seals(state).filter(s => s.id !== seal.id);
    trace(state,p,'seal-destroyed',{sealId:seal.id});
  } else seal.holderId = p.id;
  trace(state,p,'seal-sold',{offerId:offer.id,sealId:seal.id});
}

function redeem(state: AppraisalState, p: Appraiser, thiefId: string): void {
  const thief = player(state,thiefId);
  check(thief.id !== p.id,'seal-party','ใช้ตรากับตัวเองไม่ได้');
  check(!redemptions(state).some(r => r.status === 'open' && r.holderId === p.id),'seal-pending','เลือกสินค้าจากตราชุดก่อนให้เสร็จก่อน');
  const locked = lockedSealIds(state);
  const usable = seals(state).filter(s => s.holderId === p.id && s.thiefId === thief.id && !locked.has(s.id));
  check(usable.length >= SEALS_PER_REDEMPTION,'seal-count','ต้องมีตราของผู้ขโมยคนเดียวกัน 2 ใบ');
  const pool = eligibleItems(state,thief);
  // Nothing to take: the seals are kept untouched for a later encounter.
  check(pool.length > 0,'seal-empty-pool','ผู้ขโมยไม่มีของติดตัวที่ยึดได้ในตอนนี้ ตรายังอยู่');
  const list = redemptions(state);
  const id = `seal-redemption:${list.length+1}`;
  const chosen: string[] = [];
  for(let i = 0; i < REDEMPTION_CHOICES && pool.length; i++)
    chosen.push(pool.splice(Math.floor(randomAt(state.seed,`${state.encounter}:${id}:${i}:seal-pick`)*pool.length),1)[0]!);
  list.push({id,holderId:p.id,thiefId:thief.id,sealIds:usable.slice(0,SEALS_PER_REDEMPTION).map(s => s.id),slots:chosen.map(itemId => ({itemId})),encounter:state.encounter,status:'open'});
  trace(state,p,'seal-redeem',{redemptionId:id,thiefId:thief.id,slots:chosen.length});
}

function pick(state: AppraisalState, p: Appraiser, redemptionId: string, slotIndex: number): void {
  const redemption = redemptions(state).find(r => r.id === redemptionId);
  check(redemption && redemption.status === 'open' && redemption.holderId === p.id && redemption.encounter === state.encounter,'seal-pick','ไม่มีชุดที่เลือกได้');
  check(Number.isSafeInteger(slotIndex) && slotIndex >= 0 && slotIndex < redemption.slots.length,'seal-slot','ช่องที่เลือกไม่ถูกต้อง');
  const slot = redemption.slots[slotIndex]!;
  check(!slot.gone,'seal-slot','ช่องนี้ว่างแล้ว เลือกช่องอื่น');
  const thief = player(state,redemption.thiefId);
  const item = state.items[slot.itemId];
  if(!item || !eligibleItems(state,thief).includes(item.id)) {
    // The good moved after the set was dealt. Show only that the slot is empty; the seals stay unspent.
    slot.gone = true;
    if(redemption.slots.every(s => s.gone))redemption.status = 'cancelled';
    return;
  }
  moveGoods(state,thief,p,item);
  // Mirrors a successful theft: seized goods keep the stolen restriction.
  item.stolen = true;
  (state as SealState).sinnerSeals = seals(state).filter(s => !redemption.sealIds.includes(s.id));
  redemption.status = 'done';
  trace(state,p,'seal-picked',{redemptionId:redemption.id,itemId:item.id,thiefId:thief.id});
}

export function handleSealAction(state: AppraisalState, p: Appraiser, action: SealAction): void {
  check(state.config.secureEconomy && alive(p),'seal','ใช้ตราคนบาปไม่ได้');
  switch(action.type) {
    case 'seal-offer': offerSeal(state,p,action); break;
    case 'seal-respond': respondOffer(state,p,action.offerId,action.accept,action.itemIds); break;
    case 'seal-cancel': {
      const offer = offers(state).find(o => o.id === action.offerId);
      check(offer && offer.status === 'open' && offer.holderId === p.id,'seal-offer','ไม่มีข้อเสนอที่ยกเลิกได้');
      offer.status = 'cancelled'; break;
    }
    case 'seal-redeem': redeem(state,p,action.thiefId); break;
    case 'seal-pick': pick(state,p,action.redemptionId,action.slot); break;
  }
}

export function closeSealOffers(state: AppraisalState): void {
  for(const offer of (state as SealState).sealOffers ?? [])if(offer.status === 'open')offer.status = 'cancelled';
  for(const r of (state as SealState).sealRedemptions ?? [])if(r.status === 'open')r.status = 'cancelled';
}

export function sealMarketViewFor(state: AppraisalState, p: Appraiser): SealMarketView {
  const s = state as SealState;
  const all = s.sinnerSeals ?? [];
  const counts = new Map<string, number>();
  for(const s of all)if(s.holderId === p.id)counts.set(s.thiefId,(counts.get(s.thiefId) ?? 0)+1);
  const open = (s.sealRedemptions ?? []).find(r => r.status === 'open' && r.holderId === p.id);
  return {
    holdings: [...counts].map(([thiefId,count]) => ({thiefId,count})),
    offers: (s.sealOffers ?? []).filter(o => o.status === 'open' && [o.holderId,o.buyerId].includes(p.id)).map(o => ({...o,thiefId:all.find(s => s.id === o.sealId)?.thiefId ?? ''})),
    ...(open ? {redemption:{id:open.id,thiefId:open.thiefId,slots:open.slots.map((slot,i) => slot.gone ? -1 : i).filter(i => i >= 0)}} : {}),
  };
}

export function sealInvariants(state: AppraisalState): void {
  const ids = new Set<string>();
  for(const seal of (state as SealState).sinnerSeals ?? []) {
    check(!ids.has(seal.id) && seal.thiefId !== seal.holderId && state.players.some(p => p.id === seal.thiefId) && state.players.some(p => p.id === seal.holderId),'seal','ตราคนบาปไม่ถูกต้อง');
    ids.add(seal.id);
  }
  for(const r of (state as SealState).sealRedemptions ?? [])if(r.status === 'open')check(r.sealIds.every(id => ids.has(id)),'seal','ชุดเลือกอ้างตราที่ไม่มีอยู่');
}

export function nextVaultInterest(state:AppraisalState,vault:PersonalVault):number {
  const p=state.players.find(p=>p.personalVault===vault);
  const bonus=p?ringInterestBasisPoints(state,p,vault.interest?.rings):0;
  return state.config.vaultInterestRules===1?Math.floor((vault.interest?.encounter===state.encounter?vault.interest.principal:0)*(1000+bonus)/10000):vaultInterestOf(vault.credits,4);
}

function positive(amount:number):void {
  check(Number.isSafeInteger(amount) && amount>0,'credits','จำนวนเครดิตต้องเป็นจำนวนเต็มบวก');
}

function addable(balance:number,amount:number):void {
  check(Number.isSafeInteger(balance+amount),'credits','จำนวนเครดิตเกินขอบเขต');
}

function enabled(state:AppraisalState,p:Appraiser):void {
  check(state.config.secureEconomy && state.players.includes(p),'secure-economy','ไม่ได้เปิดกติกาคลังส่วนตัวและเงินกู้');
  check(p.paused!=='dead' && p.life!==0,'dead','ผู้เล่นที่ตายแล้วทำรายการไม่ได้');
}

function afterReward(state:AppraisalState,p:Appraiser):void {
  check(state.phase==='REVEAL' && p.roundReward?.encounter===state.encounter && p.roundReward.settled,'vault-window','ฝากถอนได้หลังรับเงินท้ายช่วงเท่านั้น');
}

function loanWindow(state:AppraisalState,p:Appraiser):void {
  check(state.phase==='APPRAISAL' || state.phase==='TRADE' || state.phase==='REVEAL','loan-window','ยังทำสัญญากู้ไม่ได้');
  if(state.phase==='REVEAL')afterReward(state,p);
}

function movable(state:AppraisalState,p:Appraiser,itemId:string):AppraisalItem {
  const item=ownedItem(state,p,itemId,true);
  return item;
}

function removeFromHand(state:AppraisalState,p:Appraiser,item:AppraisalItem,owner:string):void {
  p.inventory=p.inventory.filter(id=>id!==item.id);item.owner=owner;
  state.listings=state.listings.filter(listing=>listing.itemId!==item.id);
}

export function quoteVaultExpansion(slots:number):number {
  check(Number.isSafeInteger(slots) && slots>=2,'vault-slots','จำนวนช่องคลังไม่ถูกต้อง');
  const cost=10+(slots-2)*5;positive(cost);return cost;
}

export function quoteLoanDeadline(collateralValue:number,firstPayoutAt:number):number {
  positive(collateralValue);positive(firstPayoutAt);
  const pairs=Math.floor((collateralValue-1)/25);
  const remaining=collateralValue-pairs*25;
  const steps=pairs*2+(remaining<=(firstPayoutAt%2?10:15)?1:2);
  const dueAt=firstPayoutAt+steps-1;
  check(Number.isSafeInteger(dueAt),'loan-deadline','กำหนดชำระเกินขอบเขต');return dueAt;
}

function firstPayout(state:AppraisalState):number {
  // REVEAL actions occur only after the acting player's payout was settled.
  return state.encounter+(state.phase==='REVEAL'?1:0);
}

export function handleStorageAction(state:AppraisalState,p:Appraiser,action:StorageAction):void {
  enabled(state,p);if(!(action.type==='vault-withdraw-credits'&&collectorCanWithdraw(state,p)))afterReward(state,p);
  const vault:PersonalVault=p.personalVault??{items:[],credits:0,slots:2};
  switch(action.type){
    case 'vault-deposit-item':{
      check(vault.items.length<vault.slots,'vault-full','คลังส่วนตัวเต็ม');
      const item=movable(state,p,action.itemId);
      removeFromHand(state,p,item,`personal-vault:${p.id}`);
      vault.items.push(item.id);break;
    }
    case 'vault-withdraw-item':{
      check(vault.items.includes(action.itemId) && state.items[action.itemId]?.owner===`personal-vault:${p.id}`,'vault-owner','สินค้าไม่ได้อยู่ในคลังของคุณ');
      vault.items=vault.items.filter(id=>id!==action.itemId);
      state.items[action.itemId]!.owner=p.id;p.inventory.push(action.itemId);break;
    }
    case 'vault-deposit-credits':{
      positive(action.amount);check(p.credits>=action.amount,'credits','เครดิตไม่พอ');addable(vault.credits,action.amount);
      p.credits-=action.amount;vault.credits+=action.amount;
      state.ledger.push({from:p.id,to:`vault:${p.id}`,amount:action.amount,reason:'vault-deposit',encounter:state.encounter});break;
    }
    case 'vault-withdraw-credits':{
      positive(action.amount);check(vault.credits>=action.amount,'credits','เครดิตในคลังไม่พอ');addable(p.credits,action.amount);
      vault.credits-=action.amount;p.credits+=action.amount;
      if(state.config.vaultInterestRules===1 && vault.interest)vault.interest.principal=Math.min(vault.interest.principal,vault.credits);
      state.ledger.push({from:`vault:${p.id}`,to:p.id,amount:action.amount,reason:'vault-withdraw',encounter:state.encounter});break;
    }
    case 'vault-expand':{
      const amount=pilotExpansionCost(state,p,quoteVaultExpansion(vault.slots));check(p.credits>=amount,'credits','เครดิตไม่พอเพิ่มช่องคลัง');
      addable(vault.slots,1);spend(state,p,amount,0,'vault-expand');vault.slots++;break;
    }
  }
  p.personalVault=vault;trace(state,p,action.type,{...action});
}

function loanOf(state:AppraisalState,p:Appraiser,id:string):SecuredLoan {
  const loan=state.loans?.find(loan=>loan.id===id);
  check(loan && (loan.borrowerId===p.id || loan.lenderId===p.id),'loan','ไม่พบสัญญาของคุณ');return loan;
}

function pending(loan:SecuredLoan):void {
  check(loan.status==='proposed' || loan.status==='countered','loan-status','ข้อเสนอนี้ปิดแล้ว');
}

function termsOf(terms:unknown):string {
  check(terms===undefined || typeof terms==='string' && terms.length<=500,'loan-terms','ข้อตกลงยาวได้ไม่เกิน 500 ตัวอักษร');return terms??'';
}

function validPrincipal(value:number,principal:number):void {
  positive(value);positive(principal);check(principal>=Math.ceil(value/2),'loan-minimum','เงินกู้ต้องไม่น้อยกว่าครึ่งราคาหลักประกัน');
}

function collateral(state:AppraisalState,p:Appraiser,itemId:string):AppraisalItem {
  const item=movable(state,p,itemId);
  check(!item.priceIntegrity?.overpriced,'loan-overpriced','สินค้าราคาเกินจริงใช้ค้ำประกันไม่ได้');
  positive(item.lastTradePrice??0);return item;
}

function returnCollateral(state:AppraisalState,loan:SecuredLoan,owner:Appraiser):void {
  const item=state.items[loan.itemId];
  check(item?.owner===`collateral:${loan.id}`,'loan-owner','เจ้าของหลักประกันไม่ตรงสัญญา');
  item.owner=owner.id;owner.inventory.push(item.id);
}

export function handleLoanAction(state:AppraisalState,p:Appraiser,action:LoanAction):void {
  enabled(state,p);loanWindow(state,p);
  if(action.type==='loan-propose'){
    const lender=player(state,action.lenderId);
    check(lender.id!==p.id && lender.paused!=='dead' && lender.life!==0,'loan-party','ต้องกู้จากผู้เล่นอื่นที่ยังมีชีวิต');
    const item=collateral(state,p,action.itemId);const value=item.lastTradePrice!;
    validPrincipal(value,action.principal);const terms=termsOf(action.terms);
    check(!state.loans?.some(loan=>loan.itemId===item.id && ['proposed','countered','active'].includes(loan.status)),'loan-collateral','สินค้านี้มีสัญญาที่ยังไม่ปิด');
    const first=firstPayout(state);const dueAt=quoteLoanDeadline(value,first);
    const loans=state.loans??=[];
    loans.push({id:`secured-loan:${loans.length+1}`,borrowerId:p.id,lenderId:lender.id,itemId:item.id,collateralValue:value,principal:action.principal,repaid:0,proposedAt:state.encounter,firstPayoutAt:first,dueAt,terms,status:'proposed'});
    trace(state,p,action.type,{loanId:loans.at(-1)!.id});return;
  }
  const loan=loanOf(state,p,action.loanId);
  if(action.type==='loan-counter'){
    pending(loan);check(p.id===loan.lenderId,'loan-party','เฉพาะผู้ให้กู้เสนอเงินใหม่ได้');
    validPrincipal(loan.collateralValue,action.principal);const terms=termsOf(action.terms??loan.terms);
    check(p.credits>=action.principal,'credits','เครดิตผู้ให้กู้ไม่พอ');
    loan.principal=action.principal;loan.terms=terms;loan.status='countered';
  }else if(action.type==='loan-cancel'){
    pending(loan);loan.status='cancelled';loan.settledAt=state.encounter;
  }else if(action.type==='loan-respond'){
    pending(loan);check(typeof action.accept==='boolean','loan-response','คำตอบสัญญาไม่ถูกต้อง');
    check(p.id===(loan.status==='proposed'?loan.lenderId:loan.borrowerId),'loan-party','ต้องให้อีกฝ่ายยืนยันข้อเสนอ');
    if(!action.accept){loan.status='cancelled';loan.settledAt=state.encounter;}
    else {
      const borrower=player(state,loan.borrowerId),lender=player(state,loan.lenderId);
      check(borrower.paused!=='dead' && borrower.life!==0 && lender.paused!=='dead' && lender.life!==0,'loan-party','คู่สัญญาต้องยังมีชีวิต');
      const item=collateral(state,borrower,loan.itemId);
      check(item.lastTradePrice===loan.collateralValue,'loan-price','ราคาหลักประกันเปลี่ยนแล้ว ต้องเสนอใหม่');
      validPrincipal(loan.collateralValue,loan.principal);check(lender.credits>=loan.principal,'credits','เครดิตผู้ให้กู้ไม่พอ');addable(borrower.credits,loan.principal);
      check(!state.loans!.some(other=>other!==loan && other.itemId===item.id && other.status==='active'),'loan-collateral','สินค้านี้ถูกใช้ค้ำแล้ว');
      const first=firstPayout(state),dueAt=quoteLoanDeadline(loan.collateralValue,first);
      transfer(state,lender,borrower,loan.principal,'secured-loan-fund');
      removeFromHand(state,borrower,item,`collateral:${loan.id}`);
      loan.status='active';loan.fundedAt=state.encounter;loan.firstPayoutAt=first;loan.dueAt=dueAt;
    }
  }else if(action.type==='loan-repay'){
    check(loan.status==='active' && p.id===loan.borrowerId,'loan-party','เฉพาะผู้กู้ชำระสัญญาที่ยังเปิดได้');
    check(state.encounter<=loan.dueAt,'loan-expired','พ้นกำหนดชำระแล้ว');
    positive(action.amount);check(action.amount<=loan.principal-loan.repaid,'loan-payment','ยอดชำระเกินหนี้ที่เหลือ');
    const lender=player(state,loan.lenderId);addable(lender.credits,action.amount);
    check(state.items[loan.itemId]?.owner===`collateral:${loan.id}`,'loan-owner','เจ้าของหลักประกันไม่ตรงสัญญา');
    transfer(state,p,lender,action.amount,'secured-loan-repay');loan.repaid+=action.amount;
    if(loan.repaid===loan.principal){
      returnCollateral(state,loan,p);loan.status='repaid';loan.settledAt=state.encounter;
      const eligible=loan.fundedAt!==undefined&&state.encounter>=loan.fundedAt+2;
      const source=JSON.stringify([[loan.borrowerId,loan.lenderId].sort(),personalOrigin(state.items[loan.itemId]!)]);
      for(const party of [p,lender])recordPersonalActivity(state,party,'loanRepaid',1,source,eligible,eligible?'aged full repayment':'loan did not span a full encounter');
    }
  }
  trace(state,p,action.type,{loanId:loan.id});
}

export function settleLoansBeforeAdvance(state:AppraisalState,final=false):void {
  if(!state.config.secureEconomy)return;
  for(const loan of state.loans??[]){
    const borrower=player(state,loan.borrowerId),lender=player(state,loan.lenderId);
    const dead=borrower.paused==='dead' || borrower.life===0;
    if(loan.status==='active' && (final || state.phase==='REVEAL' && state.encounter>=loan.dueAt)){
      const due=state.encounter>=loan.dueAt;
      returnCollateral(state,loan,lender);loan.status='foreclosed';loan.settledAt=state.encounter;
      trace(state,borrower,'secured-loan-foreclosed',{loanId:loan.id,lenderId:lender.id,reason:due?'deadline':'match-end'});
    }else if((loan.status==='proposed' || loan.status==='countered') && (final || dead || lender.paused==='dead' || lender.life===0)){
      loan.status='cancelled';loan.settledAt=state.encounter;
    }
  }
}

export function payVaultInterest(state:AppraisalState):void {
  if(!state.config.secureEconomy)return;
  for(const p of state.players){
    const vault=p.personalVault;if(!vault || p.paused==='dead' || p.life===0)continue;
    let principal=vault.credits,bonus=0;
    if(state.config.vaultInterestRules===1){
      if(vault.interest && vault.interest.encounter>=state.encounter)continue;
      principal=vault.interest?.encounter===state.encounter-1?vault.interest.principal:0;
      if(principal>0)bonus=ringInterestBasisPoints(state,p,vault.interest?.rings);
      vault.interest={principal:vault.credits,encounter:state.encounter,...(state.config.catalogVersion===4?{rings:heldInterestRings(state,p)}:{})};
    }
    const owed=state.config.vaultInterestRules===1?Math.floor(principal*(1000+bonus)/10000):vaultInterestOf(principal,4);
    const amount=Math.min(owed,Math.max(0,state.bank-state.market.budget-state.reservedRewards));
    if(amount<=0)continue;
    reward(state,p,amount,'vault-interest');
    recordPersonalActivity(state,p,'interest',amount,String(state.encounter),state.config.vaultInterestRules===1,state.config.vaultInterestRules===1?'aged interest paid':'not aged interest');
    trace(state,p,'vault-interest',{balance:vault.credits,...(state.config.vaultInterestRules===1?{principal}:{}),owed,paid:amount});
  }
}

export function loanViewFor(state:AppraisalState,p:Appraiser):SecuredLoan[] {
  return structuredClone((state.loans??[]).filter(loan=>loan.borrowerId===p.id || loan.lenderId===p.id));
}

export function secureStorageInvariants(state:AppraisalState):void {
  const held=new Set<string>();const ids=new Set<string>();
  for(const p of state.players){
    const vault=p.personalVault;if(!vault)continue;
    check(state.config.secureEconomy && Number.isSafeInteger(vault.slots) && vault.slots>=2 && vault.items.length<=vault.slots && Number.isSafeInteger(vault.credits) && vault.credits>=0,'vault','ข้อมูลคลังส่วนตัวไม่ถูกต้อง');
    if(vault.interest)check(Number.isSafeInteger(vault.interest.principal) && vault.interest.principal>=0 && vault.interest.principal<=vault.credits && Number.isSafeInteger(vault.interest.encounter) && vault.interest.encounter>=1 && vault.interest.encounter<=state.encounter,'vault-interest','ข้อมูลอายุเงินต้นไม่ถูกต้อง');
    for(const id of vault.items){check(!held.has(id) && state.items[id]?.owner===`personal-vault:${p.id}` && !p.inventory.includes(id),'vault-owner','เจ้าของคลังส่วนตัวไม่ตรง');held.add(id);}
  }
  for(const loan of state.loans??[]){
    check(state.config.secureEconomy && !ids.has(loan.id) && loan.borrowerId!==loan.lenderId && state.players.some(p=>p.id===loan.borrowerId) && state.players.some(p=>p.id===loan.lenderId),'loan','คู่สัญญาไม่ถูกต้อง');ids.add(loan.id);
    validPrincipal(loan.collateralValue,loan.principal);
    check(Number.isSafeInteger(loan.repaid) && loan.repaid>=0 && loan.repaid<=loan.principal && loan.dueAt===quoteLoanDeadline(loan.collateralValue,loan.firstPayoutAt),'loan','ยอดหรือกำหนดชำระไม่ถูกต้อง');
    if(loan.status==='active'){
      check(loan.repaid<loan.principal && !held.has(loan.itemId) && state.items[loan.itemId]?.owner===`collateral:${loan.id}`,'loan-owner','หลักประกันไม่ตรงสัญญา');held.add(loan.itemId);
    }
  }
  for(const item of Object.values(state.items)){
    if(item.owner.startsWith('personal-vault:') || item.owner.startsWith('collateral:'))check(held.has(item.id),'secure-owner','สินค้าฝากหรือค้ำไม่มีบัญชีรองรับ');
  }
}

export function ownedAssetItemIds(state:AppraisalState,p:Appraiser):string[] {
  return [...p.inventory,...(p.npcContracts?.alien?.itemIds??[]),...(state.config.secureEconomy?[...(p.personalVault?.items??[]),...(state.loans??[]).filter(l=>l.status==='active' && l.borrowerId===p.id).map(l=>l.itemId)]:[])];
}

export function collectRun(state:AppraisalState):void {
  check(state.config.survival && (state.players.every(p=>p.life===0) || collectorDue(state)),'collector','Collector รับของเมื่อทุกคนชีวิตหมดหรือถึงช่วงที่ Collector มาเท่านั้น');
  check(!state.collector,'collector','Collector คิดคะแนนแล้ว');
  closeCollectorWishlists(state);closeNpcContracts(state);
  // Saved audits keep the original settlement; new runs close every active loan at the end.
  if(state.config.secureEconomy){if(state.config.loanEndSettlement)settleLoansBeforeAdvance(state,true);else {state.phase='REVEAL';settleLoansBeforeAdvance(state);}}
  if(state.config.personalScoringRules===1)enforceCaps(state);
  const results:CollectorResult[]=state.players.map(p=>{
    const items=ownedAssetItemIds(state,p).map(id=>{const item=state.items[id]!;const certified=!!item.appraisedBy && item.appraisedBy!==p.id;return {id,kind:item.kind,base:item.base,genuine:item.genuine,cursed:item.cursed,value:itemScoreValue(item.base,item.genuine,item.cursed,certified),...(certified?{certified}:{})};});
    const itemValue=items.reduce((sum,item)=>sum+item.value,0);
    const statusIds=(['B10','D10'] as const).filter(id=>!!status(p,id));
    const modifierPercent=statusMagnitude(p,'B10',20)-statusMagnitude(p,'D10',20);
    const credits=p.credits+(p.personalVault?.credits??0);
    const personalScore=state.config.personalScoringRules===1?personalScoreFor(state,p.id,{credits,itemValue,itemIds:items.map(i=>i.id)}):undefined;
    const score=personalScore?.total??collectorTotal(credits,itemValue,modifierPercent)+(state.ghosts?.[p.id]?.bonus??0);
    for(const item of items)if(!state.items[item.id]!.owner.startsWith('collateral:'))state.items[item.id]!.owner='collector';
    if(p.personalVault)p.personalVault.items=[];
    p.inventory=[];p.score=score;
    trace(state,p,'collector-scored',{credits:p.credits,itemValue,modifierPercent,score,itemIds:items.map(item=>item.id),statusIds});
    return {playerId:p.id,credits,itemValue,modifierPercent,statusIds,score,items,...(personalScore?{personalScore}:{})};
  });
  for(const g of Object.values(state.ghosts??{})){g.available=false;for(const j of g.jobs)if(j.status==='offered'||j.status==='accepted')j.status='cancelled';}
  state.collector=results;state.listings=[];state.phase='RESULTS';
}

pvpBlockedUntil = (state: AppraisalState, thief: Appraiser, victimId: string): number | undefined => {
  const until = (thief as Thief).pvpBlocks?.[victimId];
  return until !== undefined && state.encounter <= until ? until : undefined;
}

export function npcTheftTell(npc: NpcId): {preferredHand:RpsHand;text:string} {
  return {...npcTells[npc]};
}

export function eligibleItems(state: AppraisalState, victim: Appraiser): string[] {
  return victim.inventory.filter(id => {
    const item = state.items[id];
    return item?.owner === victim.id && unlocked(victim,id) && !victim.npcContracts?.alien?.itemIds.includes(id) &&
      !state.trades.some(t => t.status === 'open' && (t.itemId === id || t.swapItemId === id));
  }).sort();
}

function npcHand(state: AppraisalState, duel: TheftDuel): RpsHand {
  const preferred = npcTheftTell(duel.npc!).preferredHand;
  const roll = randomAt(state.seed,`${duel.id}:round:${duel.round}:npc`);
  if(roll < .6)return preferred;
  const alternatives = hands.filter(hand => hand !== preferred);
  return alternatives[Math.min(1,Math.floor((roll-.6)/.2))]!;
}

export function merchantTradeBanned(state: AppraisalState, p: Appraiser): boolean {
  const crime = (p as Thief).crime;
  return !!crime && state.encounter >= crime.banStartsEncounter && state.encounter <= crime.banUntilEncounter;
}

export function startTheftDuel(state: AppraisalState, p: Appraiser, target: {itemId?: string; victimId?: string}): void {
  check(state.config.core2 && ['APPRAISAL','TRADE'].includes(state.phase) && !p.paused && !p.done && !p.eventOffer && !p.abilityChoice,'steal','ช่วงนี้ขโมยไม่ได้');
  check(!p.stealTried?.length && !openDuel(state,p.id),'steal','ขโมยได้ครั้งเดียวต่อช่วง');
  let item: AppraisalItem;
  let victim: Appraiser | undefined;
  if(target.victimId) {
    victim = state.players.find(v => v.id === target.victimId);
    check(victim && victim.id !== p.id && !victim.paused && !victim.done && !victim.eventOffer && !victim.abilityChoice && !openDuel(state,victim.id),'steal','เริ่มการขโมยกับผู้เล่นนี้ไม่ได้');
    const eligible = eligibleItems(state,victim);
    check(eligible.length > 0,'steal','เริ่มการขโมยกับผู้เล่นนี้ไม่ได้');
    check(pvpBlockedUntil(state,p,victim.id) === undefined,'steal-cooldown','แพ้การขโมยผู้เล่นคนนี้ ต้องรออีก 2 ช่วงก่อนขโมยซ้ำ');
    // The server chooses the concealed good, never accepts a guessed private item ID.
    const index = Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${victim.id}:theft-item`)*eligible.length);
    item = state.items[eligible[index]!]!;
  } else {
    check(target.itemId,'steal','เลือกสินค้าที่จะขโมย');
    item = stockItem(state,p,target.itemId);
  }
  spend(state,p,0,CORE2.steal.energy,'theft-duel');
  (p.stealTried ??= []).push(victim ? `p:${victim.id}` : item.id);
  // Status links: B22 waits for a tied round to matter instead of being spent here for nothing.
  if(state.config.statusLinks !== 1)consumeStatus(p,'B22');
  const duels = ((state as TheftState).theftDuels ??= []);
  const duel: TheftDuel = {
    id: `theft-${state.encounter}-${p.id}-${duels.length}`,
    encounter: state.encounter, thiefId: p.id, itemId: item.id, ask: item.ask,
    ...(victim ? {victimId: victim.id} : {npc: item.npc}),
    hands: {}, round: 1, status: 'open', revealed: [],
  };
  if(state.config.catalogVersion===4){duel.swordIds={};for(const seat of [p,...(victim?[victim]:[])]){const sword=swordForDuel(state,seat);if(sword)duel.swordIds[seat.id]=sword.id;}}
  if(!victim)duel.hands.npc = npcHand(state,duel);
  duels.push(duel);
  trace(state,p,'theft-started',{duelId:duel.id,...(victim ? {victimId:victim.id} : {itemId:item.id,npc:item.npc})});
}

function stillEligible(state: AppraisalState, duel: TheftDuel): boolean {
  if(duel.encounter !== state.encounter || !['APPRAISAL','TRADE'].includes(state.phase))return false;
  const item = state.items[duel.itemId];
  const thief = state.players.find(p => p.id === duel.thiefId);
  if(!thief || thief.paused || thief.done || !item)return false;
  if(duel.victimId) {
    const victim = state.players.find(p => p.id === duel.victimId);
    return !!victim && !victim.paused && !victim.done && eligibleItems(state,victim).includes(item.id);
  }
  return thief.stock.includes(item.id) && item.encounter === state.encounter && item.npcOwnerId === thief.id && item.owner === `npc:${thief.id}:${state.encounter}`;
}

export function cancelTheftDuels(state: AppraisalState): void {
  for(const duel of (state as TheftState).theftDuels ?? []) {
    if(duel.status === 'open' && !stillEligible(state,duel)) {
      duel.status = 'cancelled'; duel.hands = {};
    }
  }
}

export function expireTheftDuel(state: AppraisalState, p: Appraiser, duelId: string): void {
  const duel = (state as TheftState).theftDuels?.find(d => d.id === duelId);
  check(duel && duel.status === 'open' && [duel.thiefId,duel.victimId].includes(p.id),'theft-duel','ไม่มีการเป่ายิ้งฉุบที่หมดเวลา');
  if(state.config.theftTimeoutRules===1){
    if(!stillEligible(state,duel)){cancelTheftDuels(state);return;}
    const round=duel.round,missing=[duel.thiefId,duel.victimId].filter((id):id is string=>!!id&&!duel.hands[id]);
    for(const id of missing){
      if(duel.status!=='open'||duel.round!==round)break;
      const actor=state.players.find(seat=>seat.id===id)!;
      chooseTheftHand(state,actor,duel.id,hands[Math.floor(randomAt(state.seed,`${duel.id}:round:${round}:timeout:${id}`)*hands.length)]!);
      note(actor,'เป่ายิ้งฉุบหมดเวลา ระบบสุ่มเฉพาะมือที่ยังไม่ส่ง');
    }
    trace(state,p,'theft-timeout-resolved',{duelId:duel.id,round,filled:missing});return;
  }
  duel.status = 'cancelled'; duel.hands = {};
  for(const id of [duel.thiefId,duel.victimId]) {
    const seat = id ? state.players.find(v => v.id === id) : undefined;
    if(seat)note(seat,'เป่ายิ้งฉุบหมดเวลา การขโมยครั้งนี้ถูกยกเลิก');
  }
  trace(state,p,'theft-expired',{duelId:duel.id,round:duel.round});
}

function playerFailure(state: AppraisalState, thief: Appraiser, duel: TheftDuel): void {
  const victimId = duel.victimId!;
  ((thief as Thief).pvpBlocks ??= {})[victimId] = state.encounter+PVP_COOLDOWN_ENCOUNTERS;
  const seals = ((state as TheftState).sinnerSeals ??= []);
  seals.push({id:`seal-${duel.id}`,thiefId:thief.id,holderId:victimId,duelId:duel.id,issuedEncounter:state.encounter});
  // Without a recorded trade price no reference exists, so no instalments are scheduled.
  const snapshot = state.items[duel.itemId]?.lastTradePrice ?? 0;
  const amount = Math.floor(snapshot*PVP_COMPENSATION_PERCENT/100);
  if(amount > 0)((state as TheftState).compensations ??= []).push({
    id:`comp-${duel.id}`,duelId:duel.id,thiefId:thief.id,victimId,itemId:duel.itemId,snapshot,amount,settled:[],
    dueEncounters:Array.from({length:PVP_COMPENSATION_INSTALLMENTS},(_,i) => state.encounter+1+i),
  });
  note(thief,`เป่ายิ้งฉุบแพ้ ขโมยผู้เล่นไม่สำเร็จ: เหยื่อได้ตราคนบาป ขโมยคนเดิมไม่ได้ 2 ช่วง${amount > 0 ? ` และต้องจ่ายชดเชยช่วงละ ${amount} เครดิต ${PVP_COMPENSATION_INSTALLMENTS} ช่วง` : ''}`);
  const victim = state.players.find(v => v.id === victimId)!;
  note(victim,'จับขโมยได้: ได้ตราคนบาปของผู้ขโมยหนึ่งใบ');
}

function breakTie(state: AppraisalState, duel: TheftDuel, thief: Appraiser): number {
  const victim = duel.victimId ? state.players.find(v => v.id === duel.victimId) : undefined;
  const edge = linkedThiefEdge(state,thief) - (victim && status(victim,'B21') ? 1 : 0);
  const used = [status(thief,'B22') && 'B22', status(thief,'D21') && 'D21'].filter(Boolean) as Array<'B22'|'D21'>;
  for(const id of used)consumeStatus(thief,id);
  if(victim && status(victim,'B21')) { consumeStatus(victim,'B21'); note(victim,'ผู้คุ้มกันยืนขวางตอนเสมอ'); }
  if(edge !== 0)trace(state,thief,'theft-tie-broken',{duelId:duel.id,to:edge > 0 ? 'thief' : 'defender',used});
  return edge;
}

function merchantFailure(state: AppraisalState, p: Appraiser, duel: TheftDuel): void {
  const npc = duel.npc!;
  (p.npcTrust ??= {})[npc] = Math.max(0,(p.npcTrust[npc] ?? 0)-2);
  const previous = (p as Thief).crime;
  (p as Thief).crime = {
    failures: (previous?.failures ?? 0)+1,
    banStartsEncounter: previous && previous.banUntilEncounter >= state.encounter ? previous.banStartsEncounter : state.encounter+1,
    banUntilEncounter: Math.max(previous?.banUntilEncounter ?? state.encounter,state.encounter)+1,
    cases: [...(previous?.cases ?? []),{itemId:duel.itemId,ask:duel.ask,npc}],
  };
  // Status links: a merchant who caught you keeps an eye on you (D21) until the end of next encounter.
  if(state.config.statusLinks === 1)grant(state,p,'D21');
  note(p,'ขโมยพลาด: ความเชื่อใจพ่อค้าคนนี้ลด 2 และเพิ่มโทษห้ามค้าขายหนึ่งช่วง');
}

export function chooseTheftHand(state: AppraisalState, p: Appraiser, duelId: string, hand: RpsHand): void {
  check(hands.includes(hand),'theft-hand','เลือกค้อน กระดาษ หรือกรรไกร');
  const duel = (state as TheftState).theftDuels?.find(d => d.id === duelId);
  check(duel && duel.status === 'open' && [duel.thiefId,duel.victimId].includes(p.id),'theft-duel','ไม่มีการเป่ายิ้งฉุบที่เลือกได้');
  if(!stillEligible(state,duel)) { duel.status = 'cancelled'; duel.hands = {}; return; }
  check(!duel.hands[p.id],'theft-hand','ส่งมือแล้ว เปลี่ยนไม่ได้');
  duel.hands[p.id] = hand;
  const thiefHand = duel.hands[duel.thiefId];
  const opponentHand = duel.hands[opponentKey(duel)];
  if(!thiefHand || !opponentHand)return;
  duel.revealed.push({thief:thiefHand,opponent:opponentHand});
  duel.hands = {};
  const thief = state.players.find(v => v.id === duel.thiefId)!;
  let won: boolean;
  if(thiefHand === opponentHand) {
    let swordEdge=0;
    for(const [id,itemId] of Object.entries(duel.swordIds??{})){const item=state.items[itemId]!;if(pilotUses(state,item)===0){swordEdge+=id===duel.thiefId?1:-1;usePilot(state,item);trace(state,thief,'pilot-sword-used',{duelId:duel.id,playerId:id,itemId});}}
    const edge = swordEdge+(state.config.statusLinks === 1 ? breakTie(state,duel,thief) : 0);
    if(edge === 0) {
      duel.round++;
      if(!duel.victimId)duel.hands.npc = npcHand(state,duel);
      return;
    }
    won = edge > 0;
  } else won = (thiefHand === 'rock' && opponentHand === 'scissors') || (thiefHand === 'scissors' && opponentHand === 'paper') || (thiefHand === 'paper' && opponentHand === 'rock');
  duel.status = won ? 'won' : 'lost';
  if(won) {
    const item = state.items[duel.itemId]!;
    if(duel.victimId) {
      const victim = state.players.find(v => v.id === duel.victimId)!;
      victim.inventory = victim.inventory.filter(id => id !== item.id);
      if(victim.paid)delete victim.paid[item.id];
      note(victim,'ของที่ถืออยู่ถูกขโมยหนึ่งชิ้น');
    } else thief.stock = thief.stock.filter(id => id !== item.id);
    item.owner = thief.id;
    // Preserve the existing stolen-good restriction until laundering rules are agreed.
    item.stolen = true;
    thief.inventory.push(item.id);
    recordPersonalActivity(state,thief,'theft',1,JSON.stringify([thief.id,'item',personalOrigin(item)]));
    state.listings = state.listings.filter(l => l.itemId !== item.id);
    note(thief,'เป่ายิ้งฉุบชนะ ขโมยสินค้าได้');
  } else if(duel.npc)merchantFailure(state,thief,duel);
  else playerFailure(state,thief,duel);
  trace(state,thief,'theft-resolved',{duelId:duel.id,result:duel.status});
}

export function collectCompensations(state: AppraisalState): void {
  for(const comp of (state as TheftState).compensations ?? []) {
    if(!comp.dueEncounters.includes(state.encounter) || comp.settled.some(s => s.encounter === state.encounter))continue;
    const thief = state.players.find(p => p.id === comp.thiefId)!, victim = state.players.find(p => p.id === comp.victimId)!;
    const paid = gone(thief) || gone(victim) ? 0 : Math.min(comp.amount,thief.credits);
    if(paid > 0) {
      transfer(state,thief,victim,paid,'theft-compensation');
      note(thief,`จ่ายค่าชดเชยขโมยพลาด ${paid} เครดิต`); note(victim,`ได้รับค่าชดเชย ${paid} เครดิต`);
    }
    comp.settled.push({encounter:state.encounter,paid});
    trace(state,thief,'theft-compensation',{compensationId:comp.id,due:comp.amount,paid});
  }
}

export function clearCrime(state: AppraisalState, p: Appraiser): void {
  const crime = (p as Thief).crime;
  check(crime && crime.cases.length > 0,'crime','ไม่มีโทษให้ล้าง');
  const price = pilotCrimeCost(state,p,noticePrice(crime));
  spend(state,p,price,0,'criminal-notice');
  delete (p as Thief).crime;
  note(p,`ซื้อใบประกาศอาชญากร ${price} เครดิต ล้างทุกคดีและโทษห้ามค้าขายทันที`);
  trace(state,p,'crime-cleared',{price,cases:crime.cases.length});
}

function tieView(state: AppraisalState, d: TheftDuel, p: Appraiser): {tieGoesTo?: 'you' | 'opponent'} {
  const edge = d.thiefId === p.id ? linkedThiefEdge(state,p) : (status(p,'B21') ? 1 : 0) - (omenNow(state)?.steal ? 1 : 0);
  return edge > 0 ? {tieGoesTo:'you'} : edge < 0 ? {tieGoesTo:'opponent'} : {};
}

