export function wishChance(markup:number,trust:number,buffs:number,debuffs:number,bonus=0):number {
  const raw=WISH_BASE_CHANCE-markup*WISH_MARKUP_PENALTY+trust*WISH_TRUST_BONUS+(buffs-debuffs)*WISH_STATUS_STEP+bonus;
  return Math.max(WISH_FLOOR,Math.min(WISH_CAP,Math.round(raw)));
}

export function shopNpcOf(p:Appraiser):NpcId|undefined {
  return p.selectedPortalId?p.portals.find(portal=>portal.id===p.selectedPortalId)?.npc:undefined;
}

export function wishPick(state:AppraisalState,p:Appraiser,npc:NpcId,nonce=0,avoid?:ItemKind):{kind:ItemKind;price:number} {
  const all=state.config.trustAbilities?merchantKinds(npc,state.config.catalogVersion??1,!!state.config.cleanse,!!state.config.challenge,!!state.config.expansion,!!state.config.polish,true):merchantKinds(npc,state.config.catalogVersion??1);const others=all.filter(kind=>kind!==avoid);const kinds=others.length?others:all;
  const kind=kinds[Math.floor(randomAt(state.seed,`${state.encounter}:${p.id}:${npc}:wish-kind${nonce?`:${nonce}`:''}`)*kinds.length)]!;
  return {kind,price:wishPrice(kind)};
}

export function wishNow(state:AppraisalState,wish:Wish):{price:number;next:number;age:number;floor:number} {
  const age=contractOn(state) && wish.set!==undefined?Math.max(0,state.encounter-wish.set):0;
  return {price:contractOn(state)?wishDecayed(wish.kind,wish.price,age):wish.price,next:contractOn(state)?wishDecayed(wish.kind,wish.price,age+1):wish.price,age,floor:wishFloor(wish.kind)};
}

export function wishBook(state:AppraisalState,p:Appraiser):WishBookRow[] {
  return (Object.entries(p.wishes??{}) as Array<[NpcId,Wish]>).map(([npc,wish])=>({npc,kind:wish.kind,initial:wish.price,...wishNow(state,wish)}));
}

export function wishEligible(state:AppraisalState,p:Appraiser):boolean {
  const npc=shopNpcOf(p);
  return !!state.config.wishlist && state.phase==='APPRAISAL' && !!npc && !p.wishes?.[npc] && (!contractOn(state) || p.energy>=WISH_ENERGY) && freeBank(state)>=maxAsk(wishPick(state,p,npc).price);
}

export function applyWish(state:AppraisalState,p:Appraiser,npc:NpcId,pick:{kind:ItemKind;price:number},replaceNpc?:NpcId):void {
  const performance=state.config.personalScoringRules===1?{performanceId:JSON.stringify([p.id,npc,state.encounter,state.commands.length])}:{};
  if(!contractOn(state)) {p.wishes![npc]={...pick,...performance};return;}
  const here=p.wishes![npc];const open=Object.keys(p.wishes!).length;
  if(here) check(replaceNpc===undefined || replaceNpc===npc,'wish','คำขอใหม่แทนได้เฉพาะคำขอเดิมของพ่อค้านี้');
  else if(open>=wishSlotsOf(state,p,WISH_MAX_ACTIVE)) check(replaceNpc!==undefined && !!p.wishes![replaceNpc],'wish',`มีคำขอครบ ${wishSlotsOf(state,p,WISH_MAX_ACTIVE)} รายการแล้ว เลือกคำขอเดิมที่จะแทน`);
  else check(replaceNpc===undefined,'wish','ยังมีที่ว่าง ไม่ต้องแทนคำขอเดิม');
  spend(state,p,0,WISH_ENERGY,'wish-contract');
  if(!here && replaceNpc) {delete p.wishes![replaceNpc];p.notes.push(`ยกเลิกคำขอของ${NPC_SPECS[replaceNpc].name}เพื่อทำสัญญาใหม่`);}
  p.wishes![npc]={...pick,set:state.encounter,...performance};
}

export function wishNew(state:AppraisalState,p:Appraiser,replaceNpc?:NpcId):void {
  check(contractOn(state) && state.phase==='APPRAISAL','wish','พ่อค้านี้ยังรับทำสัญญาตามหาของไม่ได้');
  const npc=shopNpcOf(p);check(npc,'wish','ต้องเลือกพ่อค้าก่อน');
  const rolls=(p.wishRolls??0)+1;const pick=wishPick(state,p,npc,rolls,p.wishes![npc]?.kind);
  check(freeBank(state)>=maxAsk(pick.price),'bank','งบธนาคารไม่พอสำหรับคำขอนี้');
  applyWish(state,p,npc,pick,replaceNpc);p.wishRolls=rolls;
  p.notes.push(`${NPC_SPECS[npc].name}อยากได้ ${ITEM_SPECS[pick.kind].name} ให้ ${pick.price} เครดิต แต่ราคาลดลงทุกช่วง ไม่ต่ำกว่า ${wishFloor(pick.kind)} เครดิต`);p.notes=p.notes.slice(-30);
  trace(state,p,'wish-new',{npc,kind:pick.kind,price:pick.price,...(replaceNpc?{replaced:replaceNpc}:{})});
}

export function wishDesk(state:AppraisalState,p:Appraiser):WishDesk|undefined {
  const npc=shopNpcOf(p);
  if(!contractOn(state) || state.phase!=='APPRAISAL' || !npc || p.life===0) return;
  const book=wishBook(state,p);const here=!!p.wishes?.[npc];
  const cap=wishSlotsOf(state,p,WISH_MAX_ACTIVE);
  return {npc,cost:WISH_ENERGY,cap,book,replaces:here?npc:null,replaceable:!here && book.length>=cap?book.map(row=>row.npc):[]};
}

export function drawWishEvent(state:AppraisalState,p:Appraiser,offer:(id:'E73')=>void):boolean {
  if(!state.config.wishlist || p.eventOffer || p.paused || p.done || p.offerSlots>=2 || !wishEligible(state,p)) return false;
  if(randomAt(state.seed,`${state.encounter}:${p.id}:wish`)>=WISH_PROBABILITY) return false;
  offer('E73');return true;
}

export function wishOffer(state:AppraisalState,p:Appraiser):WishOffer|undefined {
  const npc=shopNpcOf(p);const wish=npc && p.wishes?.[npc];
  if(!state.config.wishlist || state.phase!=='APPRAISAL' || !npc || !wish || p.life===0) return;
  const trust=p.npcTrust?.[npc]??0;const {buffs,debuffs}=counts(p);
  const now=wishNow(state,wish);
  return {npc,kind:wish.kind,price:now.price,initial:wish.price,floor:now.floor,next:now.next,age:now.age,trust,buffs,debuffs,tried:!!p.wishTried,
    ...(state.config.rarityEconomy?{itemQuotes:Object.fromEntries(p.inventory.filter(id=>state.items[id]!.kind===wish.kind).map(id=>{const item=state.items[id]!;return [id,WISH_MARKUPS.map(markup=>({markup,price:systemSaleQuote(state,item,copySaleQuote(item,salePreview(state,p,rarityValue(item,wishAsk(now.price,markup)))))}))];}))}:{}),
    options:WISH_MARKUPS.map(markup=>({markup,price:salePreview(state,p,wishAsk(now.price,markup)),chance:wishChance(markup,trust,buffs,debuffs,wishBonus(p))})),
    itemIds:p.inventory.filter(id=>state.items[id]!.kind===wish.kind)};
}

export function wishSell(state:AppraisalState,p:Appraiser,itemId:string,markup:number):void {
  check(!state.config.secureEconomy || !merchantTradeBanned(state,p),'merchant-banned','ยังถูกห้ามค้าขายกับพ่อค้า');
  check(state.config.wishlist && state.phase==='APPRAISAL','wish','พ่อค้านี้ยังรับซื้อตามคำขอไม่ได้');
  const npc=shopNpcOf(p);const wish=npc && p.wishes?.[npc];check(wish,'wish','พ่อค้านี้ไม่ได้บอกของที่อยากได้');
  check(!p.wishTried,'wish','ต่อรองกับพ่อค้านี้แล้วในช่วงนี้');
  check((WISH_MARKUPS as readonly number[]).includes(markup),'wish','ราคาที่เสนอไม่ถูกต้อง');
  const item=ownedItem(state,p,itemId,true);check(item.kind===wish.kind,'wish','พ่อค้าไม่ได้ต้องการสินค้าชนิดนี้');
  const ask=rarityValue(item,wishAsk(wishNow(state,wish).price,markup));const price=systemSaleQuote(state,item,copySaleQuote(item,salePreview(state,p,ask)));check(freeBank(state)>=price,'bank','งบธนาคารไม่พอสำหรับราคานี้');
  p.wishTried=true;const name=ITEM_SPECS[item.kind].name;const who=NPC_SPECS[npc].name;
  if(!item.genuine && randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:wish-fake`)<Math.min(.9,Math.max(.05,.4*NPC_SPECS[npc].sensitivity+(state.config.polish?statusMagnitude(p,'D03',.1)-statusMagnitude(p,'B04',.1):0)))) {
    learn(p,itemId,{genuine:false});p.notes.push(`${who}จับได้ว่า${name}เป็นของปลอม ไม่ซื้อ`);trace(state,p,'wish-refused',{itemId,npc,reason:'fake'});
  } else {
    const trust=p.npcTrust?.[npc]??0;const {buffs,debuffs}=counts(p);const chance=wishChance(markup,trust,buffs,debuffs,wishBonus(p));consumeStatus(p,'B16');
    if(randomAt(state.seed,`${state.encounter}:${p.id}:${itemId}:wish-deal`)*100<chance) {
      const paid=systemSaleQuote(state,item,copySaleQuote(item,saleApply(state,p,ask)));reward(state,p,paid,'npc-wish');recordItemTrade(state,item,paid);retire(state,p,itemId,'npc-wish');delete p.wishes![npc];
      recordPersonalSale(state,p,item,paid);
      if(wish.performanceId)recordPersonalActivity(state,p,'npcContract',1,wish.performanceId);
      if(p.npcTrust)setPersonalTrust(state,p,npc,Math.min(TRUST_CAP,trust+1),item);
      p.notes.push(`${who}ซื้อ${name}ตามที่ตามหา ${paid} เครดิต${paid!==ask?` (ราคาขอ ${ask} ปรับตามสถานะและลางแล้ว)`:''} (โอกาส ${chance}%)`);trace(state,p,'wish-sold',{itemId,npc,price:paid,ask,chance});
    } else {
      p.notes.push(`${who}ไม่ยอมรับราคา ${price} เครดิตสำหรับ${name} (โอกาส ${chance}%) ยังรอของชิ้นนี้ในครั้งหน้า`);trace(state,p,'wish-refused',{itemId,npc,reason:'price',chance});
    }
  }
  p.notes=p.notes.slice(-30);
}

export function randomAt(seed: string, label: string): number {
  const bytes = createHmac("sha256", seed).update(label).digest();
  return bytes.readUInt32BE(0) / 0x100000000;
}

export function pick<T>(values: readonly T[], random: number): T {
  if (values.length === 0 || !Number.isFinite(random) || random < 0 || random >= 1) {
    throw new Error("Cannot pick from an empty collection or invalid random draw");
  }
  return values[Math.floor(random * values.length)]!;
}

RARITY_NAMES:Record<Rarity,{th:string;en:string}> = {
  common:{th:'ธรรมดา',en:'Common'},uncommon:{th:'ไม่ธรรมดา',en:'Uncommon'},rare:{th:'หายาก',en:'Rare'},
  epic:{th:'มหากาพย์',en:'Epic'},legendary:{th:'ตำนาน',en:'Legendary'},mythic:{th:'มหัศจรรย์',en:'Mythic'},
}

THEME_NAMES:Record<Theme,{th:string;en:string}> = {
  plain:{th:'ต้นฉบับ',en:'Original'},inferno:{th:'นรก',en:'Inferno'},frost:{th:'เหมันต์',en:'Frost'},
  storm:{th:'พายุ',en:'Storm'},venom:{th:'พิษ',en:'Venom'},spirit:{th:'วิญญาณ',en:'Spirit'},
  lunar:{th:'จันทรา',en:'Lunar'},solar:{th:'สุริยะ',en:'Solar'},void:{th:'อเวจี',en:'Void'},
  prism:{th:'ปริซึม',en:'Prism'},clockwork:{th:'จักรกล',en:'Clockwork'},
}

export function defaultRarityConfig():RarityConfig {
  return {version:1,rates:{common:.6,uncommon:.25,rare:.1,epic:.035,legendary:.013,mythic:.002},
    themes:Object.fromEntries(RARITIES.map(r=>[r,r==='common'?[{theme:'plain',weight:1}]:THEMES.map(theme=>({theme,weight:1}))])) as RarityConfig['themes']};
}

export function validateRarityConfig(config:RarityConfig):void {
  if(!config || config.version!==1 || !config.rates || !config.themes)throw Error('Invalid rarity config version');
  let sum=0;
  for(const r of RARITIES){
    const rate=config.rates[r];if(!Number.isFinite(rate)||rate<0||rate>1)throw Error(`Invalid rarity rate: ${r}`);sum+=rate;
    const themes=config.themes[r];
    if(!Array.isArray(themes)||themes.length<1||themes.length>11||new Set(themes.map(t=>t.theme)).size!==themes.length)throw Error(`Invalid theme pool: ${r}`);
    if(themes.some(t=>!['plain',...THEMES].includes(t.theme)||!Number.isFinite(t.weight)||t.weight<0||t.weight>10000)||!themes.some(t=>t.weight>0))throw Error(`Invalid theme weight: ${r}`);
  }
  if(Math.abs(sum-1)>1e-9)throw Error('Rarity probabilities must sum to 1');
}

export function appearanceRandom(seed:number,label:string):number {
  let h=(seed>>>0)^0x811c9dc5;
  for(let i=0;i<label.length;i++)h=Math.imul(h^label.charCodeAt(i),0x01000193);
  h^=h>>>16;h=Math.imul(h,0x7feb352d);h^=h>>>15;h=Math.imul(h,0x846ca68b);h^=h>>>16;
  return (h>>>0)/0x100000000;
}

export function weightedPick<T>(entries:readonly {value:T;weight:number}[],draw:number):T {
  if(!Number.isFinite(draw)||draw<0||draw>=1||!entries.length||entries.some(e=>!Number.isFinite(e.weight)||e.weight<0))throw Error('Invalid weighted draw');
  const total=entries.reduce((n,e)=>n+e.weight,0);if(!Number.isFinite(total)||total<=0)throw Error('Empty weighted pool');
  let cursor=draw*total;let last=entries[0]!.value;
  for(const entry of entries){if(entry.weight===0)continue;last=entry.value;cursor-=entry.weight;if(cursor<0)return entry.value;}
  return last;
}

export function rollAppearance(seed:number,config:RarityConfig):ItemAppearance {
  validateRarityConfig(config);if(!Number.isSafeInteger(seed)||seed<0||seed>0xffffffff)throw Error('Invalid appearance seed');
  const rarity=weightedPick(RARITIES.map(value=>({value,weight:config.rates[value]})),appearanceRandom(seed,'rarity'));
  const theme=weightedPick(config.themes[rarity].map(t=>({value:t.theme,weight:t.weight})),appearanceRandom(seed,'theme'));
  return {version:1,rarity,theme,visualSeed:seed};
}

export function validateItemAppearance(appearance:ItemAppearance):void {
  if(!appearance||appearance.version!==1||!RARITIES.includes(appearance.rarity)||!['plain',...THEMES].includes(appearance.theme)||!Number.isSafeInteger(appearance.visualSeed)||appearance.visualSeed<0||appearance.visualSeed>0xffffffff)throw Error('Unsupported item appearance');
}

function rgb(h:number,s:number,l:number):RGB {
  const f=(n:number)=>{const k=(n+h/30)%12,a=s*Math.min(l,1-l);return l-a*Math.max(-1,Math.min(k-3,9-k,1));};
  return [f(0),f(8),f(4)];
}

export function resolveAppearance(appearance:ItemAppearance) {
  validateItemAppearance(appearance);
  const random=(label:string)=>appearanceRandom(appearance.visualSeed,label);
  const palettes=HUES[appearance.theme],pair=palettes[Math.floor(random('palette')*palettes.length)]!;
  const hue=(pair[0]+(random('hue')-.5)*16+360)%360;
  const accent=(pair[1]+(random('accent')-.5)*16+360)%360;
  const level=RARITIES.indexOf(appearance.rarity),strength=[0,.3,.5,.7,.9,1][level]!;
  return {level,strength,theme:appearance.theme,themeIndex:appearance.theme==='plain'?-1:THEMES.indexOf(appearance.theme),
    primary:rgb(hue,.65+random('saturation')*.25,.52+random('lightness')*.1),accent:rgb(accent,.8,.6),
    speed:.65+random('speed')*.7,phase:random('phase')*30,particleCount:level===0?0:6+level*6,
    aura:level===0?0:.08+level*.055,ringCount:level<3?0:level-2};
}

export function defaultRarityEconomy():RarityEconomyConfig {
  return {version:1,tiers:{common:{value:1,effect:1},uncommon:{value:2,effect:2},rare:{value:3,effect:3},epic:{value:4,effect:4},legendary:{value:6,effect:6},mythic:{value:8,effect:8}}};
}

export function validateRarityEconomy(config:RarityEconomyConfig):void {
  if(!config||config.version!==1||!config.tiers)throw Error('Invalid rarity economy version');
  let value=0,effect=0;
  for(const rarity of RARITIES){const t=config.tiers[rarity];
    if(!t||![t.value,t.effect].every(n=>Number.isSafeInteger(n)&&n>=1&&n<=MAX_RARITY_MULTIPLIER)||t.value<value||t.effect<effect)throw Error('Rarity multipliers must increase within 1–8');
    value=t.value;effect=t.effect;
  }
  if(config.tiers.common.value!==1||config.tiers.common.effect!==1)throw Error('Common is the unscaled baseline');
}

export function rarityPowerFor(rarity:Rarity,config:RarityEconomyConfig):RarityPower {
  const tier=config.tiers[rarity];return {version:1,valueMultiplier:tier.value,effectMultiplier:tier.effect};
}

export function validateRarityPower(power:RarityPower):void {
  if(!power||power.version!==1||![power.valueMultiplier,power.effectMultiplier].every(n=>Number.isSafeInteger(n)&&n>=1&&n<=MAX_RARITY_MULTIPLIER))throw Error('Invalid item rarity power');
}

export function validTimerSettings(value:unknown,minimumMs=1000):value is AppraisalTimerSettings {
  if(!value || typeof value!=='object' || Array.isArray(value))return false;
  const body=value as Record<string,unknown>;const durations=body.durationsMs;
  if(Object.keys(body).length!==2 || typeof body.enabled!=='boolean' || !durations || typeof durations!=='object' || Array.isArray(durations))return false;
  const times=durations as Record<string,unknown>;
  return Object.keys(times).length===4 && APPRAISAL_TIMER_PHASES.every(phase=>Number.isSafeInteger(times[phase]) && (times[phase] as number)>=minimumMs && (times[phase] as number)<=900000 && (minimumMs!==1000 || (times[phase] as number)%1000===0));
}

APPRAISAL_PHASE_MS: Record<Exclude<AppraisalPhase, 'RESULTS'>, number> = {
  PORTALS: 30000, APPRAISAL: 90000, TRADE: 45000, REVEAL: 30000,
}

private duelDeadlines(room: Room): Map<string, number> {
    const previous = this.duelClocks.get(room) ?? new Map<string, number>(); const next = new Map<string, number>();
    for (const duel of room.game?.theftDuels ?? []) if (duel.status === 'open') {
      const key = `${duel.id}:${duel.round}`; next.set(key, previous.get(key) ?? this.now() + this.duelMs);
    }
    this.duelClocks.set(room, next); return next;
  }

protected override sweep(room: Room, now: number): boolean {
    let changed = false;
    for (const [key, deadline] of this.duelDeadlines(room)) {
      if (now < deadline || !room.game) continue;
      const duel = room.game.theftDuels?.find(d => d.status === 'open' && `${d.id}:${d.round}` === key);
      if (!duel) continue;
      const previous = room.game;
      try { room.game = applyAppraisalAction(previous, { type: 'theft-expire', duelId: duel.id, playerId: duel.thiefId, requestId: `duel_${room.matchId}_${duel.id}_${duel.round}`, encounter: previous.encounter }); }
      catch (error) { console.error(error); continue; /* the phase timer or the next action settles it */ }
      this.phaseChanged(room, previous); changed = true;
    }
    if (changed) this.duelDeadlines(room);
    return changed;
  }

protected createGame(ids: string[], seed: string, room: Room): AppraisalState {
    const { survival, ...base } = this.runConfig;
    return createAppraisalRun(ids, seed, this.modeOf(room) === 'survival' ? { ...base, survival: survival ?? SURVIVAL_RULES } : base);
  }

protected duration(phase: string,room:Room): number | null {
    const settings=this.timerSettings(room);return settings.enabled?settings.durationsMs[phase as keyof typeof APPRAISAL_PHASE_MS]:null;
  }

protected matchMessage(room: Room, seat: Seat, peer: LifecyclePeer<AppraisalServerMessage>, message: AppraisalClientMessage): void {
    const hand=message.type==='action'&&message.action.type==='theft-hand'&&message.matchId===room.matchId&&room.game?.config.theftTimeoutRules===1?message.action:undefined;
    const acceptedHand=hand&&room.game?.accepted[`${seat.id}:${hand.requestId}`];
    const duel=hand&&room.game?.theftDuels?.find(d=>d.id===hand.duelId&&d.status==='open'&&d.round===hand.round&&d.encounter===hand.encounter&&[d.thiefId,d.victimId].includes(seat.id));
    if(duel&&!acceptedHand){
      const deadline=this.duelDeadlines(room).get(`${duel.id}:${duel.round}`)!;
      if(this.now()>=deadline){if(this.sweep(room,this.now()))this.afterChange(room);this.broadcast(room);insist(false,'duel-expired','รอบเป่ายิ้งฉุบหมดเวลาแล้ว ใช้สถานะล่าสุด');}
    }
    if (!acceptedHand && (message.type === 'action' || message.type === 'reveal-ready') && room.deadline !== null && this.now() >= room.deadline) {
      this.timeout(room, this.now()); this.broadcast(room);
      insist(!!duel, 'phase-expired', 'หมดเวลาช่วงนี้แล้ว ใช้สถานะล่าสุด');
    }
    switch (message.type) {
      case 'timer-settings': {
        this.hostOnly(room,seat);insist(!room.game,'match-started','ตั้งเวลาได้ก่อนเริ่มเกมเท่านั้น');
        const current=this.timerSettings(room);
        if(current.enabled!==message.settings.enabled || APPRAISAL_TIMER_PHASES.some(phase=>current.durationsMs[phase]!==message.settings.durationsMs[phase]))this.unready(room);
        room.timing=structuredClone(message.settings);break;
      }
      case 'add-bot': {
        this.hostOnly(room,seat);insist(!room.game,'match-started','เพิ่มบอทได้ก่อนเริ่มเกมเท่านั้น');
        insist(room.seats.length<4,'room-full','ห้องนี้มีผู้เล่นครบ 4 คนแล้ว');
        const used=new Set(room.seats.filter(s=>s.bot).map(s=>s.name));let n=1;while(used.has(`Bot ${n}`))n++;
        this.addBotSeat(room,`Bot ${n}`,message.policy);break;
      }
      case 'remove-bot': {
        this.hostOnly(room,seat);insist(!room.game,'match-started','นำบอทออกได้ก่อนเริ่มเกมเท่านั้น');
        const bot=room.seats.find(s=>s.id===message.seatId);insist(bot?.bot,'not-a-bot','ที่นั่งนี้ไม่ใช่บอท');
        room.seats=room.seats.filter(s=>s!==bot);break;
      }
      case 'rules-mode': {
        this.hostOnly(room,seat);insist(!room.game,'match-started','เลือกโหมดได้ก่อนเริ่มเกมเท่านั้น');
        insist(!this.runConfig.survival || message.mode==='survival','survival-only','เกมนี้ใช้กติกาเอาชีวิตรอด ไม่ต้องเลือกโหมด');
        if(this.modeOf(room)!==message.mode)this.unready(room);
        room.mode=message.mode;break;
      }
      case 'action': {
        insist(room.game && message.matchId === room.matchId, 'stale-match', 'คำสั่งนี้เป็นของแมตช์เก่า ใช้สถานะล่าสุด');
        insist(!room.revealReady.has(seat.id) || !!room.game.accepted[`${seat.id}:${message.action.requestId}`],'already-ready','ยืนยันไปต่อแล้ว รอรอบถัดไป');
        if(message.action.type==='loan-respond' && message.action.accept){
          const loanId=message.action.loanId;
          const loan=room.game.loans?.find(l=>l.id===loanId);
          insist(!loan || ![loan.borrowerId,loan.lenderId].some(id=>room.revealReady.has(id)),'already-ready','คู่สัญญายืนยันไปต่อแล้ว ทำสัญญาใหม่ช่วงถัดไป');
        }
        if(message.action.type==='seal-respond' && message.action.accept){
          const offerId=message.action.offerId;
          const offer=(room.game as {sealOffers?:Array<{id:string;holderId:string;buyerId:string}>}).sealOffers?.find(o=>o.id===offerId);
          insist(!offer || ![offer.holderId,offer.buyerId].some(id=>room.revealReady.has(id)),'already-ready','คู่ค้ายืนยันไปต่อแล้ว ทำข้อเสนอใหม่ช่วงถัดไป');
        }
        const previous = room.game;
        const prior=previous.accepted[`${seat.id}:${message.action.requestId}`];
        if(message.action.type==='ghost-guess'&&!prior)insist(this.now()-(previous.ghosts?.[seat.id]?.startedAt??Infinity)>=5200,'ghost-shuffling','รอการสลับการ์ดให้จบ');
        const startedAt=message.action.type==='ghost-start'?(prior?(JSON.parse(prior) as {startedAt?:number}).startedAt??this.now():this.now()):undefined;
        room.game = applyAppraisalAction(previous, { ...message.action, ...(startedAt===undefined?{}:{startedAt}), playerId: seat.id });
        this.phaseChanged(room, previous); peer.send({ type: 'ack', requestId: message.action.requestId }); break;
      }
      case 'reveal-ready':
        insist(room.game?.phase === 'REVEAL' && message.matchId === room.matchId && message.encounter === room.game.encounter,
          'stale-reveal', 'ผลช่วงนี้ผ่านไปแล้ว ใช้ผลล่าสุด');
        insist(!room.game.config.survival || room.game.players.find(p=>p.id===seat.id)?.life!==0,'spectator','ชีวิตหมดแล้ว ดูผู้เล่นที่ยังมีชีวิตไปต่อ');
        room.revealReady.add(seat.id);
        if (this.revealDone(room)) this.advance(room);
        break;
      case 'audit':
        insist(room.game?.phase === 'RESULTS' && message.matchId === room.matchId, 'audit-private', 'ดาวน์โหลดข้อมูลลับได้หลังจบ run เท่านั้น');
        peer.send({ type: 'audit', audit: { schemaVersion: room.game.version, matchId: room.matchId!, playtestMode: room.playtestMode,
          startedAt: room.startedAt, endedAt: room.endedAt!, seats: structuredClone(room.matchSeats), run: exportAppraisalAudit(room.game),
          timerSettings:this.timerSettings(room),
          phaseTimes: room.phaseTimes.map(({ number, ...row }) => ({ ...row, encounter: number })),
          timeouts: room.timeouts.map(({ number, ...row }) => ({ ...row, encounter: number })) } });
        break;
      default: break;
    }
  }

private revealDone(room: Room): boolean {
    return room.seats.every(s => room.game?.config.survival && room.game.players.find(p=>p.id===s.id)?.life===0 || room.revealReady.has(s.id));
  }

protected override afterChange(room: Room): void {
    const skipped = new Set<string>();
    for (let guard = 0; room.game && guard < 2000; guard++) {
      const game = room.game;
      if (game.phase === 'RESULTS') return;
      let acted = false;
      if (game.phase === 'REVEAL') {
        for (const seat of room.seats) if (seat.bot && !room.revealReady.has(seat.id) && !(game.config.survival && game.players.find(p=>p.id===seat.id)?.life===0)) { room.revealReady.add(seat.id); acted = true; }
        if (acted && this.revealDone(room)) this.advance(room);
        if (!acted) return;
        continue;
      }
      const current: AppraisalState = room.game!;
      const bots = room.seats.filter(s => s.bot && !skipped.has(s.id)).flatMap(seat => {
        const player = current.players.find(p => p.id === seat.id);
        return player && !player.paused && !player.done ? [{ id: seat.id, policy: seat.bot as AppraisalPolicy }] : [];
      });
      if (!bots.length) return;
      const humansActive = current.players.some(p => !p.paused && !p.done && (!current.config.survival || p.life !== 0) && !room.seats.find(s => s.id === p.id)?.bot);
      const turn = appraisalBotTurn(current, bots, { humansActive, retired: !!current.config.survival && current.config.collectorDeadline === undefined && current.encounter > BOT_RETIRE_ENCOUNTER });
      if (!turn) return;
      const previous: AppraisalState = current;
      const attempt = (body: object): AppraisalState => applyAppraisalAction(previous, { ...body, playerId: turn.id, requestId: `bot-${++this.botSeq}`, encounter: previous.encounter } as AppraisalAction);
      try {
        try { room.game = attempt(turn.body); }
        catch { room.game = attempt({ type: 'done' }); }
        this.phaseChanged(room, previous);
      } catch { skipped.add(turn.id); /* leave this seat to the phase timer */ }
    }
  }

protected timeout(room: Room, now: number): void {
    insist(room.game, 'phase', 'run ยังไม่เริ่ม');
    const phase = room.game.phase, number = room.game.encounter;
    if (phase === 'REVEAL') { room.timeouts.push({ at: now, number, phase, playerId: null }); this.advance(room); return; }
    // Snapshot only the pending seats in the expired phase; the last action may advance it.
    const pending = room.game.players.filter(p => !p.paused && !p.done).map(p => p.id);
    for (const playerId of pending) {
      if (room.game.phase !== phase || room.game.encounter !== number) break;
      const previous = room.game;
      const action = defaultAppraisalAction(previous, playerId, `timeout_${room.matchId}_${number}_${phase}_${playerId}`);
      if (!action) continue;
      room.game = applyAppraisalAction(previous, action); room.timeouts.push({ at: now, number, phase, playerId }); this.phaseChanged(room, previous);
    }
  }

protected broadcast(room: Room): void {
    const clocks = this.duelDeadlines(room);
    for (const seat of room.seats) if (seat.peer) {
      const game = room.game ? appraisalViewFor(room.game, seat.id) : null;
      const duelDeadlines = Object.fromEntries((game?.theft?.duels ?? []).filter(d => d.status === 'open' && clocks.has(`${d.id}:${d.round}`)).map(d => [d.id, clocks.get(`${d.id}:${d.round}`)!]));
      const view: AppraisalRoomView = { rulesVersion: '0.5', mode: this.modeOf(room), code: room.code, hostId: room.hostId, yourSeatId: seat.id,
        seats: room.seats.map(s => ({ id: s.id, name: s.name, ready: s.ready, connected: s.connected, ...(s.bot ? { bot: s.bot as AppraisalBotPolicy } : {}) })), matchSeats: structuredClone(room.matchSeats),
        playtestMode: room.playtestMode, matchId: room.matchId, deadline: room.deadline, serverTime: this.now(), revealReady: [...room.revealReady],
        timerSettings:this.timerSettings(room),
        ...(Object.keys(duelDeadlines).length ? { duelDeadlines } : {}),
        game };
      seat.peer.send({ type: 'state', room: view });
    }
  }

function claims(value: unknown): { genuine?: boolean; cursed?: boolean } {
  const body = object(value); keys(body, ['genuine', 'cursed']);
  return { ...(body.genuine === undefined ? {} : { genuine: boolean(body.genuine) }), ...(body.cursed === undefined ? {} : { cursed: boolean(body.cursed) }) };
}

function action(value: unknown): AppraisalSeatAction {
  const body = object(value); const requestId = string(body.requestId, 80);
  if (!/^[a-zA-Z0-9_-]+$/.test(requestId)) throw new MessageError();
  const base = { requestId, encounter: encounter(body.encounter) };
  const fields = ['type', 'requestId', 'encounter'];
  switch (body.type) {
    case 'collector-wish-request': {
      keys(body,[...fields,'kinds']);
      if(!Array.isArray(body.kinds)||body.kinds.length!==3||new Set(body.kinds).size!==3||!body.kinds.every(k=>typeof k==='string'&&Object.hasOwn(ITEM_SPECS,k)))throw new MessageError();
      return {type:body.type,...base,kinds:body.kinds as ItemKind[]};
    }
    case 'collector-wish-peek': case 'collector-wish-buy': {
      keys(body,[...fields,'batchId','slotId',...(body.type==='collector-wish-buy'?['quoteId']:[])]);
      const slot={batchId:string(body.batchId),slotId:string(body.slotId)};
      return body.type==='collector-wish-buy'?{type:body.type,...base,...slot,quoteId:string(body.quoteId,256)}:{type:body.type,...base,...slot};
    }
    case 'collector-wish-skip': keys(body,[...fields,'batchId']);return {type:body.type,...base,...(body.batchId===undefined?{}:{batchId:string(body.batchId)})};
    case 'ghost-start': keys(body,fields);return {type:body.type,...base};
    case 'ghost-guess': keys(body,[...fields,'round','position']);return {type:body.type,...base,round:integer(body.round),position:integer(body.position)};
    case 'ghost-hire': keys(body,[...fields,'ghostId','choice','quoteId','fee']);return {type:body.type,...base,ghostId:string(body.ghostId),choice:integer(body.choice),quoteId:string(body.quoteId,256),fee:integer(body.fee)};
    case 'ghost-accept': keys(body,[...fields,'jobId','accept']);return {type:body.type,...base,jobId:string(body.jobId),accept:boolean(body.accept)};
    case 'ghost-deliver': keys(body,[...fields,'jobId','slot']);return {type:body.type,...base,jobId:string(body.jobId),slot:integer(body.slot)};
    case 'ghost-rps': keys(body,[...fields,'slot','hand']);if(!['rock','paper','scissors'].includes(String(body.hand)))throw new MessageError();return {type:body.type,...base,slot:integer(body.slot),hand:body.hand as 'rock'|'paper'|'scissors'};
    case 'vault-deposit-item': case 'vault-withdraw-item': case 'liquidate':
      keys(body,[...fields,'itemId']);return {type:body.type,...base,itemId:string(body.itemId)};
    case 'vault-deposit-credits': case 'vault-withdraw-credits':
      keys(body,[...fields,'amount']);return {type:body.type,...base,amount:integer(body.amount)};
    case 'vault-expand': case 'crime-clear':
      keys(body,fields);return {type:body.type,...base};
    case 'reappraise-owned':
      keys(body,[...fields,'itemId','value']);return {type:body.type,...base,itemId:string(body.itemId),value:integer(body.value)};
    case 'loan-propose':
      keys(body,[...fields,'lenderId','itemId','principal','terms']);
      return {type:'loan-propose',...base,lenderId:string(body.lenderId,32),itemId:string(body.itemId),principal:integer(body.principal),...(body.terms===undefined?{}:{terms:loanTerms(body.terms)})};
    case 'loan-counter':
      keys(body,[...fields,'loanId','principal','terms']);
      return {type:'loan-counter',...base,loanId:string(body.loanId),principal:integer(body.principal),...(body.terms===undefined?{}:{terms:loanTerms(body.terms)})};
    case 'loan-respond':
      keys(body,[...fields,'loanId','accept']);return {type:'loan-respond',...base,loanId:string(body.loanId),accept:boolean(body.accept)};
    case 'loan-cancel':
      keys(body,[...fields,'loanId']);return {type:'loan-cancel',...base,loanId:string(body.loanId)};
    case 'loan-repay':
      keys(body,[...fields,'loanId','amount']);return {type:'loan-repay',...base,loanId:string(body.loanId),amount:integer(body.amount)};
    case 'seal-offer': {
      keys(body,[...fields,'sealId','buyerId','credits','energy','life','goods','terms']);
      return {type:'seal-offer',...base,sealId:string(body.sealId),buyerId:string(body.buyerId,32),credits:integer(body.credits),energy:integer(body.energy),life:integer(body.life),goods:integer(body.goods),...(body.terms===undefined?{}:{terms:loanTerms(body.terms)})};
    }
    case 'seal-respond': {
      keys(body,[...fields,'offerId','accept','itemIds']);
      if(body.itemIds!==undefined && (!Array.isArray(body.itemIds) || body.itemIds.length>8))throw new MessageError();
      return {type:'seal-respond',...base,offerId:string(body.offerId),accept:boolean(body.accept),...(body.itemIds===undefined?{}:{itemIds:(body.itemIds as unknown[]).map(id=>string(id))})};
    }
    case 'seal-cancel': keys(body,[...fields,'offerId']);return {type:'seal-cancel',...base,offerId:string(body.offerId)};
    case 'seal-redeem': keys(body,[...fields,'thiefId']);return {type:'seal-redeem',...base,thiefId:string(body.thiefId,32)};
    case 'seal-pick': keys(body,[...fields,'redemptionId','slot']);return {type:'seal-pick',...base,redemptionId:string(body.redemptionId),slot:integer(body.slot)};
    case 'theft-start':
      keys(body,[...fields,'itemId','victimId']);
      if((body.itemId===undefined)===(body.victimId===undefined))throw new MessageError();
      return {type:'theft-start',...base,...(body.itemId===undefined?{victimId:string(body.victimId,32)}:{itemId:string(body.itemId)})};
    case 'theft-hand':
      keys(body,[...fields,'duelId','hand','round']);
      if(body.hand!=='rock' && body.hand!=='paper' && body.hand!=='scissors')throw new MessageError();
      return {type:'theft-hand',...base,duelId:string(body.duelId),...(body.round===undefined?{}:{round:integer(body.round)}),hand:body.hand};
    case 'enter': keys(body, [...fields, 'portalId']); return { type: 'enter', ...base, portalId: string(body.portalId) };
    case 'inspect':
      keys(body, [...fields, 'itemId', 'property']);
      if (body.property !== 'price' && body.property !== 'authenticity' && body.property !== 'effects') throw new MessageError();
      return { type: 'inspect', ...base, itemId: string(body.itemId), property: body.property };
    case 'appraise': case 'counter':
      keys(body, [...fields, 'itemId', 'value', 'acceptDanger']);
      return { type: body.type, ...base, itemId: string(body.itemId), value: integer(body.value),
        ...(body.acceptDanger === undefined ? {} : { acceptDanger: boolean(body.acceptDanger) }) };
    case 'buy': {
      keys(body, [...fields, 'itemIds', 'condition']);
      if (!Array.isArray(body.itemIds) || body.itemIds.length < 1 || body.itemIds.length > 2) throw new MessageError();
      const itemIds = body.itemIds.map(id => string(id));
      if (new Set(itemIds).size !== itemIds.length) throw new MessageError();
      return { type: 'buy', ...base, itemIds, condition: boolean(body.condition) };
    }
    case 'activate': {
      keys(body,[...fields,'itemId','npc','otherNpc']);
      for(const key of ['npc','otherNpc'] as const)if(body[key]!==undefined && (typeof body[key]!=='string'||!Object.hasOwn(NPC_SPECS,body[key])))throw new MessageError();
      return {type:'activate',...base,itemId:string(body.itemId),...(body.npc===undefined?{}:{npc:body.npc as keyof typeof NPC_SPECS}),...(body.otherNpc===undefined?{}:{otherNpc:body.otherNpc as keyof typeof NPC_SPECS})};
    }
    case 'merchant-ability': {
      keys(body,[...fields,'npc','itemId','statusId','choiceId']);
      if(typeof body.npc!=='string'||!Object.hasOwn(NPC_SPECS,body.npc)||body.statusId!==undefined&&!(ALL_STATUS_IDS as readonly unknown[]).includes(body.statusId))throw new MessageError();
      return {type:'merchant-ability',...base,npc:body.npc as keyof typeof NPC_SPECS,...(body.itemId===undefined?{}:{itemId:string(body.itemId)}),...(body.statusId===undefined?{}:{statusId:body.statusId as StatusId}),...(body.choiceId===undefined?{}:{choiceId:string(body.choiceId)})};
    }
    case 'recover-resource': keys(body,[...fields,'target']);if(body.target!=='energy' && body.target!=='life')throw new MessageError();return {type:'recover-resource',...base,target:body.target};
    case 'wish-new': keys(body,[...fields,'replaceNpc']);return {type:'wish-new',...base,...(body.replaceNpc===undefined?{}:{replaceNpc:string(body.replaceNpc,16) as never})};
    case 'wish-sell': keys(body,[...fields,'itemId','markup']);return {type:'wish-sell',...base,itemId:string(body.itemId),markup:integer(body.markup)};
    case 'cleanse': keys(body,[...fields,'itemId','stoneId']);return {type:'cleanse',...base,itemId:string(body.itemId),...(body.stoneId===undefined?{}:{stoneId:string(body.stoneId)})};
    case 'event': {
      keys(body, [...fields, 'key', 'choice', 'itemId', 'itemIds', 'statusId', 'otherPlayerId', 'fact', 'guess']);
      if(body.itemIds!==undefined && (!Array.isArray(body.itemIds) || body.itemIds.length<1 || body.itemIds.length>3 || new Set(body.itemIds).size!==body.itemIds.length))throw new MessageError();
      if (body.statusId !== undefined && !(ALL_STATUS_IDS as readonly string[]).includes(body.statusId as string)) throw new MessageError();
      if (body.fact !== undefined && body.fact !== 'base' && body.fact !== 'genuine' && body.fact !== 'cursed') throw new MessageError();
      return { type: 'event', ...base, key: string(body.key, 256), choice: string(body.choice, 64),
        ...(body.itemId === undefined ? {} : { itemId: string(body.itemId) }),
        ...(body.itemIds === undefined ? {} : {itemIds:(body.itemIds as unknown[]).map(id=>string(id))}),
        ...(body.statusId === undefined ? {} : { statusId: body.statusId as StatusId }),
        ...(body.otherPlayerId === undefined ? {} : { otherPlayerId: string(body.otherPlayerId, 32) }),
        ...(body.fact === undefined ? {} : { fact: body.fact as 'base' | 'genuine' | 'cursed' }),
        ...(body.guess === undefined ? {} : { guess: boolean(body.guess) }) };
    }
    case 'market-sell':
      keys(body,[...fields,'itemId','orderId','resolution']);
      if(body.resolution!==undefined && body.resolution!=='discount' && body.resolution!=='sacrifice')throw new MessageError();
      return {type:'market-sell',...base,itemId:string(body.itemId),orderId:string(body.orderId),...(body.resolution===undefined?{}:{resolution:body.resolution})};
    case 'share': keys(body, [...fields, 'itemId', 'allow', 'purchase', 'claims', 'rebate']); return { type: 'share', ...base, itemId: string(body.itemId), allow: boolean(body.allow), purchase: boolean(body.purchase),
      ...(body.claims === undefined ? {} : { claims: claims(body.claims) }), ...(body.rebate === undefined ? {} : { rebate: integer(body.rebate) }) };
    case 'force-buy': keys(body, [...fields, 'sellerId', 'itemId']); return { type: 'force-buy', ...base, sellerId: string(body.sellerId, 32), itemId: string(body.itemId) };
    case 'propose':
      keys(body, [...fields, 'sellerId', 'itemId', 'credits', 'swapItemId', 'condition', 'challenge', 'sealId']);
      if (body.challenge !== undefined && body.challenge !== 'genuine' && body.challenge !== 'cursed') throw new MessageError();
      return { type: 'propose', ...base, sellerId: string(body.sellerId, 32), itemId: string(body.itemId), credits: integer(body.credits),
        ...(body.swapItemId === undefined ? {} : { swapItemId: string(body.swapItemId) }),
        ...(body.condition === undefined ? {} : { condition: boolean(body.condition) }),
        ...(body.challenge === undefined ? {} : { challenge: body.challenge as 'genuine'|'cursed' }),
        ...(body.sealId === undefined ? {} : { sealId: string(body.sealId) }) };
    case 'respond': keys(body, [...fields, 'offerId', 'accept']); return { type: 'respond', ...base, offerId: string(body.offerId), accept: boolean(body.accept) };
    case 'unsold':
      keys(body, [...fields, 'itemId', 'choice']);
      if (body.choice !== 'buy' && body.choice !== 'penalty' && body.choice !== 'consign') throw new MessageError();
      return { type: 'unsold', ...base, itemId: string(body.itemId), choice: body.choice };
    case 'bid': keys(body, [...fields, 'lotId', 'credits']); return { type: 'bid', ...base, lotId: string(body.lotId), credits: integer(body.credits) };
    case 'reroll-portal': keys(body, [...fields, 'portalId']); return { type: 'reroll-portal', ...base, portalId: string(body.portalId) };
    case 'steal': keys(body, [...fields, 'itemId']); return { type: 'steal', ...base, itemId: string(body.itemId) };
    case 'pickpocket': keys(body, [...fields, 'victimId']); return { type: 'pickpocket', ...base, victimId: string(body.victimId, 32) };
    case 'barter': keys(body, [...fields, 'itemId', 'targetItemId']); return { type: 'barter', ...base, itemId: string(body.itemId), targetItemId: string(body.targetItemId) };
    case 'skill': keys(body, [...fields, 'itemId']); return { type: 'skill', ...base, ...(body.itemId === undefined ? {} : { itemId: string(body.itemId) }) };
    case 'round-flip':
      keys(body,[...fields,'guess','guesses','attempt']);
      if(body.guesses!==undefined && (!Array.isArray(body.guesses) || !body.guesses.length || !body.guesses.every(guess=>guess==='heads' || guess==='tails')))throw new MessageError();
      if(body.guess!=='heads' && body.guess!=='tails')throw new MessageError();
      return {type:'round-flip',...base,guess:body.guess,attempt:integer(body.attempt),...(body.guesses===undefined?{}:{guesses:[...body.guesses as Array<'heads'|'tails'>]})};
    case 'round-raise': keys(body,[...fields,'coinCount','attempt']);return {type:'round-raise',...base,coinCount:integer(body.coinCount),attempt:integer(body.attempt)};
    case 'round-bank': keys(body,fields);return {type:'round-bank',...base};
    case 'done': keys(body, fields); return { type: 'done', ...base };
    default: throw new MessageError();
  }
}

export function parseAppraisalMessage(value: unknown): AppraisalClientMessage {
  const body = object(value);
  if(body.type==='add-bot') {
    keys(body,['type','policy']);if(!(APPRAISAL_BOT_POLICIES as readonly unknown[]).includes(body.policy))throw new MessageError();
    return {type:'add-bot',policy:body.policy as AppraisalBotPolicy};
  }
  if(body.type==='remove-bot') {keys(body,['type','seatId']);return {type:'remove-bot',seatId:string(body.seatId,32)};}
  if(body.type==='rules-mode') {
    keys(body,['type','mode']);if(body.mode!=='classic' && body.mode!=='survival')throw new MessageError();
    return {type:'rules-mode',mode:body.mode};
  }
  if(body.type==='timer-settings') {
    keys(body,['type','settings']);if(!validTimerSettings(body.settings))throw new MessageError();
    return {type:'timer-settings',settings:structuredClone(body.settings)};
  }
  if (body.type === 'action') { keys(body, ['type', 'matchId', 'action']); return { type: 'action', matchId: string(body.matchId, 32), action: action(body.action) }; }
  if (body.type === 'reveal-ready') { keys(body, ['type', 'matchId', 'encounter']); return { type: 'reveal-ready', matchId: string(body.matchId, 32), encounter: encounter(body.encounter) }; }
  const control = parseMessage(value);
  if (control.type === 'action' || control.type === 'reveal-ready') throw new MessageError();
  return control;
}

export function insist(condition: unknown, code: string, message: string): asserts condition {
  if (!condition) throw new RuleError(code, message);
}

handle(peer: LifecyclePeer<M>, message: C): void {
    try {
      // Version-specific parsers reconstruct allowlisted messages before this boundary.
      const control = message as unknown as ControlMessage;
      if (control.type === 'create' || control.type === 'join' || control.type === 'resume') {
        insist(!this.bindings.has(peer), 'already-seated', 'คุณอยู่ในห้องแล้ว ออกจากห้องเดิมก่อน');
        if (control.type === 'create') {
          insist(this.rooms.size < 200, 'room-limit', 'ห้องเต็มเซิร์ฟเวอร์แล้ว ลองอีกครั้งภายหลัง');
          let code: string;
          do { code = Array.from({ length: 6 }, () => ALPHABET[randomInt(ALPHABET.length)]).join(''); } while (this.rooms.has(code));
          const seat = this.newSeat(control.name);
          const room: LifecycleRoom<G, M> = { code, hostId: seat.id, seats: [seat], matchSeats: [], playtestMode: 'no-voice',
            game: null, matchId: null, deadline: null, phaseStartedAt: 0, phaseTimes: [], timeouts: [],
            startedAt: 0, endedAt: null, lastActivity: this.now(), revealReady: new Set() };
          this.rooms.set(code, room); this.attach(room, seat, peer);
        } else {
          const room = this.rooms.get(control.roomCode);
          insist(room, 'room-missing', 'ไม่พบห้องนี้ ห้องอาจหมดอายุหรือเซิร์ฟเวอร์เริ่มใหม่');
          if (control.type === 'resume') {
            const seat = room.seats.find(s => s.token === control.token);
            insist(seat, 'seat-missing', 'กู้ seat ไม่สำเร็จ กลับไปสร้างหรือเข้าห้องใหม่');
            if (seat.peer) { const old = seat.peer; this.bindings.delete(old); old.close(4001, 'Seat resumed in another connection'); }
            this.attach(room, seat, peer);
          } else {
            insist(!room.game, 'match-started', 'แมตช์เริ่มแล้ว รอเข้าห้องในแมตช์ถัดไป');
            insist(room.seats.length < 4, 'room-full', 'ห้องนี้มีผู้เล่นครบ 4 คนแล้ว');
            const seat = this.newSeat(control.name); room.seats.push(seat); this.attach(room, seat, peer);
          }
        }
        return;
      }
      const binding = this.bindings.get(peer);
      insist(binding, 'not-seated', 'สร้างหรือเข้าห้องก่อน');
      const { room, seat } = binding; room.lastActivity = this.now();
      switch (control.type) {
        case 'ready':
          insist(!room.game, 'match-started', 'เปลี่ยนพร้อมเล่นได้เฉพาะใน lobby'); seat.ready = control.ready; break;
        case 'playtest-mode':
          this.hostOnly(room, seat); insist(!room.game, 'match-started', 'เลือกรูปแบบทดสอบก่อนเริ่มเกม'); room.playtestMode = control.mode; break;
        case 'start':
          this.hostOnly(room, seat); insist(!room.game, 'match-started', 'แมตช์เริ่มแล้ว');
          insist(room.seats.length >= 2 && room.seats.every(s => (s.ready || s.id === room.hostId) && s.connected), 'not-ready', 'ต้องมี 2–4 คน และทุกคนพร้อมและเชื่อมต่ออยู่');
          room.matchId = randomBytes(8).toString('hex'); room.matchSeats = room.seats.map(s => ({ id: s.id, name: s.name }));
          room.game = this.createGame(room.seats.map(s => s.id), randomBytes(32).toString('hex'), room);
          room.startedAt = this.now(); room.endedAt = null; room.phaseTimes = []; room.timeouts = []; this.beginPhase(room); break;
        case 'rematch':
          this.hostOnly(room, seat); insist(room.game?.phase === 'RESULTS', 'phase', 'ต้องจบแมตช์ก่อนเล่นอีกครั้ง');
          room.game = null; room.matchId = null; room.deadline = null; room.revealReady.clear(); this.unready(room); break;
        case 'leave':
          insist(!room.game || room.game.phase === 'RESULTS', 'match-started', 'แมตช์กำลังเล่น ปิดแท็บได้และกลับมาที่ seat เดิมภายหลัง');
          this.bindings.delete(peer); room.seats = room.seats.filter(s => s !== seat);
          if (!room.seats.some(s => !s.bot)) this.rooms.delete(room.code); else if (room.hostId === seat.id) room.hostId = room.seats.find(s => !s.bot)!.id;
          peer.send({ type: 'left' } as M); break;
        case 'remove-seat': {
          this.hostOnly(room, seat); insist(!room.game, 'match-started', 'นำ seat ออกได้เฉพาะก่อนเริ่มแมตช์');
          const absent = room.seats.find(s => s.id === control.seatId);
          insist(absent && !absent.connected && absent.id !== seat.id, 'seat-connected', 'นำออกได้เฉพาะ seat ที่ไม่ได้เชื่อมต่อ');
          room.seats = room.seats.filter(s => s !== absent); break;
        }
        default: this.matchMessage(room, seat, peer, message);
      }
      if (this.rooms.has(room.code)) { this.afterChange(room); this.broadcast(room); }
    } catch (error) {
      const body = message as unknown as { type: string; action?: { requestId?: string } };
      peer.send({ type: 'error', code: error instanceof RuleError ? error.code : 'server-error',
        message: error instanceof RuleError ? this.errorMessage(error) : 'เซิร์ฟเวอร์ทำคำสั่งไม่สำเร็จ ลองอีกครั้ง',
        ...(body.type === 'action' && body.action?.requestId ? { requestId: body.action.requestId } : {}) } as unknown as M);
      if (!(error instanceof RuleError)) console.error(error);
    }
  }

disconnect(peer: LifecyclePeer<M>): void {
    const binding = this.bindings.get(peer); if (!binding) return;
    this.bindings.delete(peer); const { room, seat } = binding; seat.peer = null; seat.connected = false;
    if (!room.game) seat.ready = false;
    if (room.hostId === seat.id) room.hostId = room.seats.find(s => s.connected && !s.bot)?.id ?? seat.id;
    this.broadcast(room);
  }

tick(): void {
    const now = this.now();
    for (const room of this.rooms.values()) {
      if (room.seats.every(s => !s.connected || s.bot) && now - room.lastActivity > this.idleMs) { this.rooms.delete(room.code); continue; }
      if (room.game && this.sweep(room, now)) { this.afterChange(room); this.broadcast(room); }
      if (!room.game || room.deadline === null || now < room.deadline) continue;
      this.timeout(room, now); this.afterChange(room); this.broadcast(room);
    }
  }

protected addBotSeat(room: LifecycleRoom<G, M>, name: string, bot: string): void {
    room.seats.push({ ...this.newSeat(name), ready: true, connected: true, bot });
  }

protected phaseChanged(room: LifecycleRoom<G, M>, previous: G): void {
    if (previous.phase === room.game!.phase && this.number(previous) === this.number(room.game!)) return;
    room.phaseTimes.push({ number: this.number(previous), phase: previous.phase, startedAt: room.phaseStartedAt, endedAt: this.now() }); this.beginPhase(room);
  }

private beginPhase(room: LifecycleRoom<G, M>): void {
    room.revealReady.clear(); room.phaseStartedAt = this.now();
    const duration=room.game!.phase==='RESULTS'?null:this.duration(room.game!.phase,room);
    room.deadline = duration===null?null:room.phaseStartedAt+duration;
    if (room.game!.phase === 'RESULTS') room.endedAt = this.now();
  }

private attach(room: LifecycleRoom<G, M>, seat: LifecycleSeat<M>, peer: LifecyclePeer<M>): void {
    seat.peer = peer; seat.connected = true; room.lastActivity = this.now(); this.bindings.set(peer, { room, seat });
    if (!room.seats.find(s => s.id === room.hostId)?.connected) room.hostId = seat.id;
    peer.send({ type: 'joined', roomCode: room.code, token: seat.token, seatId: seat.id } as unknown as M); this.broadcast(room);
  }

function eventAction(v:AppraisalView,policy:AppraisalPolicy):Body {
  const offer=v.self.eventOffer!;const p=v.self;
  if(['E130','E131','E132'].includes(offer.id)){
    const wanted=policy==='cautious'?'decline':offer.id==='E130'?(p.credits>=3?'wind':'decline'):offer.id==='E131'?'haste':'compass';
    return {type:'event',key:offer.key,choice:offer.choices.includes(wanted)?wanted:offer.choices[0]!};
  }
  if(/^E1(1[7-9]|2\d)$/.test(offer.id)) {
    // v0.6 events: penalties are paid in the cheapest listed currency, optional ones only when the bot has spare resources.
    const penalty=['E120','E121','E122','E123','E124'].includes(offer.id);
    const choice=penalty || policy!=='cautious' && p.energy>=3?offer.choices.find(c=>c!=='decline')??'decline':offer.choices.includes('decline')?'decline':offer.choices[0]!;
    const itemId=['item','offer'].includes(choice)?offer.itemIds[0]:undefined;
    return {type:'event',key:offer.key,choice,...(itemId?{itemId}:{})};
  }
  let choice=offer.choices.includes('decline')?'decline':offer.choices.includes('pay')?'pay':offer.choices.includes('oath')?'oath':offer.choices.includes('surrender')?'surrender':offer.choices.includes('die')?'die':offer.choices.includes('energy')?'energy':'item';
  const useful=policy==='aggressive'?['E09','E21','E22','E24','E27','E28','E46']:policy==='collector'?['E02','E04','E05','E07','E15','E18','E26','E29','E31','E33','E34','E35','E36','E38','E39','E41','E42']:policy==='trader'?['E04','E15','E19','E21','E25','E43','E44','E45','E47']:['E03','E04','E12','E15','E16','E17','E18','E22','E28','E30','E35','E41','E42'];
  if(useful.includes(offer.id) && p.credits>=5 && p.energy>=4) choice=offer.choices.find(c=>c!=='decline')!;
  if(Number(offer.id.slice(1))>50 && policy!=='cautious') choice='accept';
  if(offer.id==='E73') choice=policy!=='cautious' && p.energy>=3 && offer.choices.includes('accept')?'accept':'decline';
  if(v.survival && offer.id==='E03' && p.energy<3)choice=p.credits>=2?'pay':p.life!>1?'debt':'decline';
  if(v.survival && offer.id==='E42' && p.energy<3 && offer.choices.includes('energy'))choice='energy';
  const visible=[...p.stock,...p.inventory,...v.listings.map(l=>l.item)];
  let itemId=offer.itemIds[0];
  if(['E11','E46'].includes(offer.id)) itemId=offer.itemIds.find(id=>visible.find(i=>i.id===id)?.knowledge.genuine===undefined);
  if(['E16','E20'].includes(offer.id)) itemId=offer.itemIds.find(id=>!visible.find(i=>i.id===id)?.knowledge[offer.id==='E16'?'effectsKnown':'activationKnown']);
  if(offer.id==='E17') itemId=offer.itemIds.find(id=>visible.find(i=>i.id===id)?.knowledge.base===undefined);
  let statusId=offer.statusIds.find(id=>id.startsWith('D'));
  if(offer.id==='E06') statusId=offer.statusIds.find(id=>id.startsWith('D') && id!==(choice==='interest'?'D04':'D07'));
  if(offer.id==='E108') {statusId=offer.boons![0];choice=policy==='cautious'?'decline':'pick';}
  if(offer.npcTerms){
    choice=policy==='cautious'?'decline':offer.choices.find(c=>c!=='decline')??'decline';
    if(offer.id==='E109' && p.life!<=3)choice='decline';
    return {type:'event',key:offer.key,choice,...(itemId?{itemId}:{}),...(statusId?{statusId}:{}),...(offer.id==='E110' && choice!=='decline'?{itemIds:offer.itemIds.slice(0,Number(choice.slice(5)))}:{}),...(choice==='send-debuff'?{otherPlayerId:offer.otherPlayerIds[0]!}:{})};
  }
  if(offer.id==='E88') statusId=offer.statusIds.find(id=>['D11','D12','D13','D14','D15','D16'].includes(id));
  if(offer.id==='E34') statusId=offer.statusIds.find(id=>id.startsWith('B') && id!=='B10');
  if(offer.id==='E35') statusId=offer.statusIds.find(id=>id==='D01' || id==='D05');
  const target=p.stock.find(i=>i.id===itemId);
  if(['E09','E24','E27','E29','E30'].includes(offer.id) && choice==='accept') {
    const discount=offer.id==='E29'?3:offer.id==='E30'?-2:2;
    if(!target || p.credits<buyPrice(v,target)-discount || p.energy<npcEnergy(v)) choice='decline';
  }
  if(offer.id==='E21' && choice==='accept' && (p.stock.length<2 || p.credits<p.stock.reduce((sum,i)=>sum+i.price,0)-2 || p.energy<npcEnergy(v))) choice='decline';
  // Events without a decline (gifts and mishaps under event choice rules 1) take the first listed option.
  if(!offer.choices.includes(choice)) choice=offer.choices.find(c=>c!=='decline')??offer.choices[0]!;
  const proof=itemId?offer.facts[itemId]:undefined;
  const fact=proof?.base!==undefined?'base':proof?.genuine!==undefined?'genuine':proof?.cursed!==undefined?'cursed':undefined;
  return {type:'event',key:offer.key,choice,...(itemId?{itemId}:{}),...(statusId?{statusId}:{}),...(fact?{fact}:{}),...(offer.id==='E46'?{guess:true}:{})};
}

function worth(v:AppraisalView,item:ItemView):number {
  const k=item.knowledge;
  const base=k.base!==undefined?k.base:k.range?(k.range[0]+k.range[1])/2:item.ask;
  const genuine=k.genuine===undefined?.75+.25*.25:k.genuine?1:.25;
  const clean=k.cursed===undefined?1-.35*.25:k.cursed?.75:1;
  const sealed=v.survival && item.appraisedBy!==undefined && item.appraisedBy!==v.self.id?1.15:1;
  return base*genuine*clean*sealed;
}

function rebateFor(v:AppraisalView,item:ItemView):number {
  const p=v.self;let rebate=0;
  if(knownBad(item)) rebate=Math.min(8,Math.max(2,Math.floor(item.price*.3)));
  else if(v.survival && (p.life??9)<=3 && v.brokerage) rebate=2;
  return Math.max(0,Math.min(rebate,p.credits-8));
}

function dealFor(v:AppraisalView,listing:AppraisalView['listings'][number],policy:AppraisalPolicy):Deal {
  const p=v.self,item=listing.item,npcSource=item.owner.startsWith('npc:'),lowLife=!!v.survival && (p.life??9)<=3;
  const value=worth(v,item),friend=npcSource && friendGoods(v,item);
  const energy=npcSource?(v.freeBuy||friend?0:1)+(has(v,'D06')?1:0):0;
  const rebate=listing.rebate??0;
  const fee=npcSource?(rebate?0:1):Math.max(1,Math.floor(value*.5));
  const cost=(npcSource?buyPrice(v,item):0)+fee;
  let bonus=0;
  if(npcSource && v.survival && p.pulse && !p.pulse.wary && item.appraisedBy!==undefined && item.appraisedBy!==p.id) bonus+=(lowLife?9:4);
  const log=p.buyLog??[];
  if(npcSource && item.appraisedBy!==undefined && item.appraisedBy!==p.id && log.length>0 && log.every(npc=>npc===item.npc)) bonus+=log.length>=2?7:2;
  if(policy==='collector' && !p.inventory.some(i=>i.kind===item.kind)) bonus+=3;
  if(policy==='trader') {const order=v.market.orders.find(o=>o.kind===item.kind && (o.quota[p.id]??0)>0);if(order) bonus+=order.price*.8;}
  const net=value+bonus+rebate-cost-energy*3;
  const ok=p.credits>=cost+4 && p.energy>=energy && net>=BUY_MARGIN[policy] && (!knownBad(item) || rebate>=Math.floor(value*.3) || policy==='aggressive');
  return {listing,net,ok,npcSource,fee};
}

function tradeDecision(v:AppraisalView,policy:AppraisalPolicy):Body {
  const p=v.self;
  const othersActive=v.players.some(o=>o.id!==p.id && seatOpen(v,o.id));
  const incoming=v.trades.find(o=>o.sellerId===p.id && o.status==='open');
  if(incoming) {
    const buyer=v.players.find(other=>other.id===incoming.buyerId)!;
    const listing=v.listings.find(l=>l.itemId===incoming.itemId && l.ownerId===p.id);
    const shopPrice=incoming.source==='npc'?incoming.item.price:0;
    const canPay=!buyer.paused && !buyer.done && buyer.credits>=incoming.credits+shopPrice+(v.fee??0) && (incoming.source!=='npc' || v.freeBuy || buyer.energy>=2) && p.credits+incoming.credits>=(listing?.rebate??0);
    const fair=incoming.source==='npc' || incoming.credits>=Math.floor(worth(v,incoming.item)*SELL_FLOOR[policy]);
    return {type:'respond',offerId:incoming.id,accept:canPay && fair};
  }
  // List what this seat does not want to keep, with a rebate when the goods are poor.
  const listedIds=new Set(v.listings.filter(l=>l.ownerId===p.id).map(l=>l.itemId));
  const shopItem=p.stock.find(i=>i.appraisal!==null && i.owner.startsWith('npc:') && !listedIds.has(i.id));
  if(shopItem) return {type:'share',itemId:shopItem.id,allow:true,purchase:true,...(rebateFor(v,shopItem)?{rebate:rebateFor(v,shopItem)}:{})};
  const surplus=p.inventory.find(i=>i.lockedUntil===null && !listedIds.has(i.id) && (policy==='trader' || policy==='aggressive' || knownBad(i)));
  if(surplus) return {type:'share',itemId:surplus.id,allow:true,purchase:true,...(knownBad(surplus) && rebateFor(v,surplus)?{rebate:rebateFor(v,surplus)}:{})};
  // Buy from friends when the item and the new rewards beat the price; tickets force the best shop item.
  const openOffers=v.trades.filter(o=>o.buyerId===p.id && o.status==='open').length;
  const deals=v.listings.filter(l=>l.ownerId!==p.id && l.purchase && seatOpen(v,l.ownerId) && !l.item.owner.startsWith('alien-loan:') && !v.trades.some(o=>o.buyerId===p.id && o.itemId===l.itemId))
    .map(l=>dealFor(v,l,policy)).filter(d=>d.ok).sort((a,b)=>b.net-a.net);
  if(openOffers<2 && deals.length) {
    const best=deals[0]!,item=best.listing.item;
    if(best.npcSource && (p.darkTickets??0)>=TICKETS_TO_FORCE) return {type:'force-buy',sellerId:best.listing.ownerId,itemId:item.id};
    return {type:'propose',sellerId:best.listing.ownerId,itemId:item.id,credits:best.fee,...(best.npcSource?{condition:item.condition.required}:{})};
  }
  // Stay in the phase while a friend could still answer an offer on a listing; settle unsold goods last.
  const waiting=othersActive && (listedIds.size>0 || openOffers>0);
  const unsold=v.brokerage && !waiting?p.stock.find(i=>i.appraisal!==null && i.owner.startsWith('npc:')):undefined;
  if(unsold) {
    const affordable=p.credits>=buyPrice(v,unsold) && p.energy>=npcEnergy(v) && p.dealMode!=='condition';
    return {type:'unsold',itemId:unsold.id,choice:affordable && policy!=='trader' && !knownBad(unsold)?'buy':policy==='cautious' || knownBad(unsold)?'penalty':'consign'};
  }
  return {type:'done'};
}

export function appraisalBotDecision(v:AppraisalView,policy:AppraisalPolicy):Body {
  const p=v.self;const duel=v.theft?.duels.find(d=>d.needsChoice);
  if(duel)return {type:'theft-hand',duelId:duel.id,...(v.theftTimeoutRules===1?{round:duel.round}:{}),hand:(['rock','paper','scissors'] as const)[(v.encounter+duel.round)%3]!};
  if(p.eventOffer) return eventAction(v,policy);
  const collector=p.collectorWishlist;
  if(collector&&!p.done&&!p.paused&&!p.abilityChoice&&['PORTALS','APPRAISAL'].includes(v.phase)){
    const d=collector.delivery;
    if(d?.status==='open'){
      if(policy==='cautious'||!d.canBuy)return {type:'collector-wish-skip',batchId:d.id};
      const seen=d.slots.find(s=>s.peek),slot=seen??d.slots[0]!;
      if(!seen&&d.canPeek)return {type:'collector-wish-peek',batchId:d.id,slotId:slot.id};
      return {type:'collector-wish-buy',batchId:d.id,slotId:slot.id,quoteId:d.quoteId};
    }
    if(collector.request.available){
      if(policy==='cautious')return {type:'collector-wish-skip'};
      const choices=[...collector.request.kinds].sort((a,b)=>Number(p.inventory.some(i=>i.kind===a.kind))-Number(p.inventory.some(i=>i.kind===b.kind)));
      return {type:'collector-wish-request',kinds:choices.slice(0,3).map(k=>k.kind)};
    }
  }
  if(v.market.open && policy==='trader') {
    const item=p.inventory.find(i=>i.lockedUntil===null && !i.stolen && v.market.orders.some(o=>o.kind===i.kind && (o.quota[p.id]??0)>0));
    if(item) return {type:'market-sell',itemId:item.id,orderId:v.market.orders.find(o=>o.kind===item.kind && (o.quota[p.id]??0)>0)!.id};
  }
  const lot=v.market.lots?.find(l=>l.winnerId===undefined && l.yourBid===null && p.credits>=l.minimum+10);
  const chasing=(p.darkTickets??0)>=1 && (p.darkTickets??0)<TICKETS_TO_FORCE && !!lot && p.credits>=lot.minimum+20;
  if(lot && (policy==='collector' || policy==='trader' || chasing) && v.phase!=='PORTALS') return {type:'bid',lotId:lot.id,credits:lot.minimum+(policy==='collector'?2:chasing?1:0)};
  if(v.phase==='PORTALS') {
    const portals=p.portals.filter(portal=>!portal.disabled);
    const chosen=policy==='trader'?portals.find(portal=>v.market.orders.some(o=>o.kind===portal.hint)):
      policy==='collector'?portals.find(portal=>!p.inventory.some(i=>i.kind===portal.hint)):
      policy==='cautious'?portals.find(portal=>portal.npc==='autometa' || portal.npc==='orc'):portals.find(portal=>portal.npc==='darkone' || portal.npc==='alien');
    return {type:'enter',portalId:(chosen??portals[0])!.id};
  }
  if(p.abilityChoice){const choiceId=p.abilityChoice.itemIds.find(id=>id!==p.abilityChoice!.sourceId)??p.abilityChoice.itemIds[0]!;return {type:'merchant-ability',npc:p.abilityChoice.npc,choiceId};}
  if(v.trustAbilities && ['APPRAISAL','TRADE'].includes(v.phase) && !p.skillUsed){
    const abilities=p.merchantAbilities??[];
    const order=policy==='collector'?['swarm','deepsea','vampire','autometa','orc','darkone','beast','alien']:policy==='cautious'?['deepsea','darkone','autometa','orc','swarm','vampire','beast','alien']:['darkone','orc','autometa','swarm','vampire','beast','deepsea','alien'];
    for(const npc of order){const a=abilities.find(a=>a.npc===npc&&a.ready);if(!a)continue;
      if(a.target==='debuff')return {type:'merchant-ability',npc:a.npc,statusId:a.statusIds[0]!};
      const targets=[...p.stock,...p.inventory].filter(i=>a.itemIds.includes(i.id));
      const item=a.npc==='deepsea'?targets.find(i=>i.knowledge.cursed===true):a.npc==='autometa'?targets.find(i=>i.knowledge.base===undefined):a.npc==='orc'?targets.find(i=>buyPrice(v,i)<=p.credits):targets[0];
      if(item)return {type:'merchant-ability',npc:a.npc,itemId:item.id};
    }
  }
  if(v.phase==='APPRAISAL') {
    const recovery=p.recoveryOffer;
    if(recovery && p.credits>=recovery.credits && (recovery.target==='life'?p.life!<=v.survival!.maxLife-recovery.amount:p.energy<3))return {type:'recover-resource',target:recovery.target};
    if(policy==='cautious' && p.inspections<1 && p.energy>=3) {
      const item=p.stock.find(i=>i.knowledge.genuine===undefined);if(item) return {type:'inspect',itemId:item.id,property:'authenticity'};
    }
    const c2=p.core2Actions;
    if(c2?.skill && p.energy>=3) {
      const itemId=c2.skill.needsItem?p.stock.find(i=>i.knowledge.base===undefined || i.knowledge.genuine===undefined)?.id:undefined;
      if(!c2.skill.needsItem || itemId) return {type:'skill',...(itemId?{itemId}:{})};
    }
    if(c2 && !c2.theftUsed && policy==='aggressive' && p.energy>=5) {
      const victim=v.players.find(o=>o.id!==p.id && !o.paused && o.credits>0);
      if(c2.pickpocketChance && c2.pickpocketChance>=.3 && victim && v.encounter%2===0) return {type:'pickpocket',victimId:victim.id};
      const loot=p.stock.find(i=>i.appraisal===null);
      if(c2.stealChance && c2.stealChance>=.4 && loot && v.encounter%2===1) return {type:'steal',itemId:loot.id};
    }
    const toAppraise=p.stock.find(i=>i.appraisal===null);
    if(toAppraise && !p.caught && p.energy>=3) {
      const [low,high]=toAppraise.range??[toAppraise.price,toAppraise.price];
      const value=Math.round(policy==='aggressive'?low*.65:policy==='trader'?low:policy==='collector'?(low+high)*.4:(low+high)/2);
      return {type:'appraise',itemId:toAppraise.id,value,acceptDanger:true};
    }
    const toBuy=p.stock.find(i=>p.credits>=buyPrice(v,i) && !(knownBad(i) && policy!=='aggressive') && worth(v,i)>=buyPrice(v,i)*BUY_RATIO[policy]);
    if(toBuy && p.energy>=npcEnergy(v)) return {type:'buy',itemIds:[toBuy.id],condition:false};
    if(policy==='collector' && p.energy>=4) {
      const item=p.inventory.find(i=>!p.activated.includes(i.id) && !p.abilityItemUsed?.includes(i.kind) && !['chrono-gear','burden-hourglass'].includes(i.kind) && (!ITEM_SPECS[i.kind].nativeEffect || ITEM_SPECS[i.kind].explicitActivation && !i.pilotUses));if(item) return {type:'activate',itemId:item.id};
      const source=p.merchantAbilities?.find(a=>a.trust>=1&&reducibleCooldown(p,a.npc,v.encounter)>0);
      const gear=p.inventory.find(i=>i.kind==='chrono-gear'&&!p.activated.includes(i.id)&&!p.abilityItemUsed?.includes(i.kind));
      if(source&&gear)return {type:'activate',itemId:gear.id,npc:source.npc};
    }
    return {type:'done'};
  }
  if(v.phase==='TRADE') return tradeDecision(v,policy);
  return {type:'done'};
}

export function appraisalBotTurn(state:AppraisalState,bots:Array<{id:string;policy:AppraisalPolicy}>,options:{humansActive?:boolean;retired?:boolean}={}):{id:string;body:Body}|null {
  const doneBody:Body={type:'done'};
  const decisions=bots.map(bot=>{
    let body:Body=doneBody;
    if(!options.retired) {try {body=appraisalBotDecision(appraisalViewFor(state,bot.id),bot.policy);} catch {body=doneBody;}}
    return {id:bot.id,body};
  });
  const busy=decisions.find(d=>d.body.type!=='done');
  if(busy) return busy;
  const holds=(id:string)=>!!options.humansActive && state.phase==='TRADE' && state.listings.some(l=>l.ownerId===id);
  return decisions.find(d=>!holds(d.id))??null;
}

export function simulateAppraisalRun(count:number,policy:AppraisalPolicy,seed:string,overrides:Partial<AppraisalConfig>={}):AppraisalAudit {
  let state=createAppraisalRun(Array.from({length:count},(_,i)=>`seat${i}`),seed,overrides);
  let cursor=0;
  for(let turn=0;turn<1500 && state.phase!=='RESULTS';turn++) {
    if(state.phase==='REVEAL') {state=advanceAppraisalEncounter(state);continue;}
    const active=state.players.map((player,index)=>({player,index})).filter(({player})=>!player.paused && !player.done)
      .sort((x,y)=>((x.index-cursor+count)%count)-((y.index-cursor+count)%count));
    if(!active.length) throw new Error('No active seat before automatic phase completion');
    // Replenished income can sustain life indefinitely. Runs without a Collector deadline
    // retire synthetic seats after twelve encounters so a replay test remains bounded.
    const turnChoice=appraisalBotTurn(state,active.map(({player})=>({id:player.id,policy})),{retired:!!state.config.survival && state.config.collectorDeadline===undefined && state.encounter>12})??{id:active[0]!.player.id,body:{type:'done'} as Body};
    const chosen=active.find(({player})=>player.id===turnChoice.id)!;cursor=(chosen.index+1)%count;const p=chosen.player;const body=turnChoice.body;
    state=applyAppraisalAction(state,{...body,playerId:p.id,requestId:`sim-${turn}`,encounter:state.encounter} as AppraisalAction);
  }
  if(state.phase!=='RESULTS') throw new Error('Appraisal simulation exceeded action bound');
  const audit=exportAppraisalAudit(state);replayAppraisalAudit(audit);return audit;
}

export function runAppraisalScenarios(runs:number,out:string):void {
  const summaries=[];let example:AppraisalAudit | undefined;
  for(const count of [2,3,4]) for(const policy of APPRAISAL_POLICIES) {
    let deaths=0,exhaustions=0,sales=0,trades=0,caught=0,openMarkets=0,totalScores=0;
    const events=new Set<string>(),routes:Record<string,number>={};
    for(let i=0;i<runs;i++) {
      const audit=simulateAppraisalRun(count,policy,`appraisal-v0.4:${count}:${policy}:${i}`);example??=audit;
      totalScores+=audit.final.reduce((sum,p)=>sum+p.score,0);
      for(const row of audit.history) {if(row.paused==='dead') deaths++;if(row.paused==='exhausted') exhaustions++;}
      openMarkets+=new Set(audit.trace.filter(t=>t.type==='market-sale').map(t=>t.encounter)).size;
      for(const t of audit.trace) {
        if(t.type==='market-sale') sales++;if(t.type==='trade-completed') trades++;
        if(t.type==='appraised' && t.details.caught) caught++;
        if(t.type==='event-resolved') events.add(t.details.id as string);
        if(t.type==='portal-entered') {const npc=t.details.npc as string;routes[npc]=(routes[npc]??0)+1;}
      }
    }
    summaries.push({players:count,policy,runs,deaths,exhaustions,sales,trades,caught,meanScore:totalScores/(runs*count),encountersWithSales:openMarkets,resolvedEventIds:[...events].sort(),routes});
    process.stdout.write(`${count} players / ${policy}: ${runs} replay-verified runs\n`);
  }
  mkdirSync(out,{recursive:true});writeFileSync(resolve(out,'summary.json'),JSON.stringify({schemaVersion:4,runs:runs*12,limitations:'Synthetic runs verify rules and replay. They do not prove human fun or balanced strategies. Event fixtures cover all 50 IDs separately.',scenarios:summaries},null,2)+'\n');
  writeFileSync(resolve(out,'example-run.json'),JSON.stringify(example,null,2)+'\n');
}

