export interface AppraisalAudit {
  personalPerformance?:AppraisalState['personalPerformance'];
  schemaVersion:4 | 5; playerIds:string[]; seed:string; config:AppraisalConfig;
  commands:Array<AppraisalAction|{type:'advance'}>;
  ledger:AppraisalState['ledger']; history:EncounterResult[]; trace:AppraisalState['trace'];
  items:AppraisalState['items']; final: Array<{id:string;credits:number;energy:number;inventory:string[];score:number;life?:number}>;
  collector?:AppraisalState['collector'];
}

export type CollectorWishlistAction=
 | {type:'collector-wish-request';kinds:ItemKind[]}
 | {type:'collector-wish-peek';batchId:string;slotId:string}
 | {type:'collector-wish-buy';batchId:string;slotId:string;quoteId:string}
 | {type:'collector-wish-skip';batchId?:string};

export interface CollectorWishlistView {
 request:{available:boolean;kinds:Array<{kind:ItemKind;name:string;image:string}>;dueAt:number};
 pending?:Pending;
 delivery?:{id:string;quoteId:string;status:Offer['status'];cost:{price:number;fee:number;total:number;energy:number};canPeek:boolean;canBuy:boolean;reason?:string;slots:Array<{id:string;peek?:{kind:ItemKind;name:string;image:string;rarity?:Rarity}}>};
}

export interface BondSpec {
  id:EventId; npc:NpcId; name:string; when:string; description:string; mode:BondMode;
  families?:ItemFamily[]; kinds?:ItemKind[]; exclude?:ItemKind[]; known?:'cursed'|'fake';
  buffs?:StatusId[]; debuffs?:StatusId[]; cleanse?:'D10'|'debuffs'; energy?:number; life?:number;
  energyCost?:number; reveal?:Array<'base'|'genuine'|'cursed'|'effectsKnown'>; price?:number;
  genuineOnly?:boolean; risk?:number;
}

export interface Core2Choice {
  id:string;credits?:number;energy?:number;life?:number;reward?:number;heal?:number;
  grant?:StatusId[];lose?:boolean;door?:'first'|'second';deal?:'cash'|'condition';toVictim?:boolean;
  /** A seeded roll after paying: `chance` of the `win` statuses, else the `lose` ones. */
  gamble?:{chance:number;win:StatusId[];lose:StatusId[]};
}

export interface Core2EventSpec {
  id:EventId;name:string;when:string;phase:'PORTALS'|'APPRAISAL'|'TRADE';consequence?:boolean;description:string;choices:Core2Choice[];
}

export interface ItemEffect {
  effect:keyof PassiveBonuses; amount:number; text:string; en:string;
}

export interface Omen {
  id:OmenId; name:string; text:string;
  /** Percentage points added to every sale of an item the seat owns. */
  salePct?:number;
  /** Extra credits on every NPC purchase, cleansing and recovery deal. */
  fee?:number;
  /** Percentage points added to NPC acceptance and to curse cleansing. */
  accept?:number;
  /** The first inspection of the encounter costs no energy. */
  firstInspectFree?:boolean;
  /** Energy every living seat loses at settlement. */
  settleEnergy?:number;
  /** Credits added to the post-trade round reward. */
  roundBonus?:number;
  /** Core v0.6: multiplier on the dread chance this encounter. */
  dread?:number;
  /** Core v0.6: extra credits on recovery deals. */
  healCost?:number;
  /** Core v0.6: percentage points added to every theft attempt. */
  steal?:number;
  /** Core v0.6: trust a sold appraisal earns on top of the usual. */
  trust?:number;
  /** Core v0.6: percent of credits the Collector's tax takes at settlement. */
  taxPct?:number;
  /** Core v0.6: the Dark Market is always open this encounter. */
  marketOpen?:boolean;
  /** Core v0.6: life every living seat loses at settlement. */
  settleLife?:number;
}

export interface PassiveBonuses {
  freePrice:number; commission:number; income:number; luck:number; coinWin:number; saleFee:number;
  trust:number; acceptance:number; discount:number; buyEnergy:number; freeAuth:number; freeEffects:number;
  market:number; match:number; mitigation:number; energyRecovery:number; lifeRecovery:number; inspections:number;
  maxEnergy:number; maxLife:number; wishSlots:number;
}

export interface PolishEvent {
  phase:AppraisalPhase; credits?:number; energy?:number; reward?:number; grant:StatusId[];
  /** Offered only when none of these statuses is active, so a choice is never a no-op. */
  avoid:StatusId[]; needsAuctions?:boolean;
}

export interface SealOffer {
  id: string;
  sealId: string;
  holderId: string;
  buyerId: string;
  credits: number;
  energy: number;
  life: number;
  /** How many carried goods the buyer must hand over; the buyer chooses which when accepting. */
  goods: number;
  terms: string;
  encounter: number;
  status: 'open' | 'accepted' | 'declined' | 'cancelled';
}

export interface SealRedemption {
  id: string;
  holderId: string;
  thiefId: string;
  sealIds: string[];
  slots: Array<{itemId: string; gone?: boolean}>;
  encounter: number;
  status: 'open' | 'done' | 'cancelled';
}

export type SealAction =
  | {type: 'seal-offer'; sealId: string; buyerId: string; credits: number; energy: number; life: number; goods: number; terms?: string}
  | {type: 'seal-respond'; offerId: string; accept: boolean; itemIds?: string[]}
  | {type: 'seal-cancel'; offerId: string}
  | {type: 'seal-redeem'; thiefId: string}
  | {type: 'seal-pick'; redemptionId: string; slot: number};

export interface SealMarketView {
  offers: Array<SealOffer & {thiefId: string}>;
  redemption?: {id: string; thiefId: string; slots: number[]};
  /** thiefId -> seals held, so the client can offer redemption at two or more. */
  holdings: Array<{thiefId: string; count: number}>;
}

export interface SecuredLoan {
  id:string; borrowerId:string; lenderId:string; itemId:string;
  /** Agreed item value and deadline never change after funding. */
  collateralValue:number; principal:number; repaid:number; proposedAt:number;
  firstPayoutAt:number; dueAt:number; fundedAt?:number; settledAt?:number;
  terms:string; status:'proposed'|'countered'|'active'|'repaid'|'foreclosed'|'cancelled';
}

export type StorageAction =
  | {type:'vault-deposit-item'|'vault-withdraw-item';itemId:string}
  | {type:'vault-deposit-credits'|'vault-withdraw-credits';amount:number}
  | {type:'vault-expand'};

export type LoanAction =
  | {type:'loan-propose';lenderId:string;itemId:string;principal:number;terms?:string}
  | {type:'loan-counter';loanId:string;principal:number;terms?:string}
  | {type:'loan-respond';loanId:string;accept:boolean}
  | {type:'loan-cancel';loanId:string}
  | {type:'loan-repay';loanId:string;amount:number};

export interface CrimeRecord {
  failures: number;
  banStartsEncounter: number;
  banUntilEncounter: number;
  cases: Array<{itemId: string; ask: number; npc: NpcId}>;
}

export interface SinnerSeal {
  id: string;
  thiefId: string;
  holderId: string;
  duelId: string;
  issuedEncounter: number;
}

export interface PvpCompensation {
  id: string;
  duelId: string;
  thiefId: string;
  victimId: string;
  itemId: string;
  snapshot: number;
  amount: number;
  dueEncounters: number[];
  settled: Array<{encounter: number; paid: number}>;
}

export interface TheftDuel {
  id: string;
  encounter: number;
  thiefId: string;
  victimId?: string;
  npc?: NpcId;
  itemId: string;
  ask: number;
  swordIds?:Record<string,string>;
  hands: Record<string, RpsHand>;
  round: number;
  status: 'open' | 'won' | 'lost' | 'cancelled';
  revealed: Array<{thief: RpsHand; opponent: RpsHand}>;
}

export interface TheftDuelView {
  id: string;
  thiefId: string;
  victimId?: string;
  npc?: NpcId;
  npcTell?: {preferredHand: RpsHand; text: string};
  round: number;
  status: TheftDuel['status'];
  needsChoice: boolean;
  submitted: boolean;
  /** Status links: who a tied round goes to, from this seat's own statuses and the omen only. */
  tieGoesTo?: 'you' | 'opponent';
  publicSwords?:{you:boolean;opponent:boolean};
  revealed: TheftDuel['revealed'];
}

export interface TheftView {
  duels: TheftDuelView[];
  targets: Array<{playerId: string; blockedUntilEncounter?: number}>;
  seals: Array<{id: string; thiefId: string}>;
  compensation: Array<{id: string; role: 'payer' | 'receiver'; otherId: string; amount: number; remaining: number[]; paid: number}>;
  crime?: {
    failures: number;
    banStartsEncounter: number;
    banUntilEncounter: number;
    active: boolean;
    noticePrice: number;
    cases: number;
  };
}

export interface AppraisalConfig {
  /** Versioned personal accomplishments; historical audits omit this. */
  personalScoringRules?:1;
  /** Corrected canonical writers; absence preserves pre-review experimental audit receipts. */
  personalScoringFacts?:2;
  /** Dedicated personal Collector purchases; absent in historical audits. */
  collectorWishlistRules?:1;
  /** Absent in visual-only/old audits: no price or effect scaling. */
  rarityEconomy?:import('../../shared/rarity-power.js').RarityEconomyConfig;
  /** Optional in old audits. Appearance-only RNG; no hidden truths or economic multipliers. */
  rarity?:import('../../shared/item-rarity.js').RarityConfig;
  /** Absent in saved audits: preserve the original theft, custody and pricing rules. */
  secureEconomy?:boolean;
  /** Absent in saved audits: active loans stay open when the match ends. New runs foreclose them so the lender keeps the collateral. */
  loanEndSettlement?:boolean;
  /** Absent in old audits: preserve 4% whole-balance interest. 1 uses aged principal at 10%. */
  vaultInterestRules?:1;
  /** Missing in historical audits: cancel timeout instead of choosing absent hands. */
  theftTimeoutRules?:1;
  /** Survival only. Absent in saved audits: the run ends only when every life is gone. Otherwise the Collector arrives after this encounter settles, whoever is still alive. */
  collectorDeadline?:number;
  /** Absent in saved audits: keep the original event choices. 1 removes pointless decline buttons, turns E37/E40 into mishaps you handle, reprices E119/E121/E127 and gives E47 an effect. */
  eventChoiceRules?:1;
  /** Absent in saved audits: v0.6 statuses B21–B24/D21–D24 stay unreachable and theft buffs keep their old chance-based meaning. 1 gives every status a source and makes B21/B22/D21 and the thieves' night omen settle tied theft duels. */
  statusLinks?:1;
  /** Absent in saved audits: preserve historical event eligibility and defaults. 1 revalidates core2 defaults, links healing/guard choices to their requirements and excludes costless blood-pact debt. */
  systemLinks?:1;
  /** Absent in historical runs: keep original skills, catalogs and RNG pools exactly. */
  trustAbilities?:boolean;
  /** Absent in saved audits: preserve historical item effects and activation costs. */
  itemEffects?: boolean;
  /** Absent in original v0.4 audits: retain the original 10-item generation pool. */
  catalogVersion?: 1 | 2 | 3 | 4;
  /** Absent in historical audits: preserve their original economy. */
  roundRewards?: boolean;
  /** Absent in saved runs: retain the original single-coin, lose-all wager. */
  multiCoinRewards?: boolean;
  /** Absent in saved runs: retain the pre-commission/trust/market-contract rules. */
  commerce?: boolean;
  /** Absent in saved runs: retain the one-item bonus for trusting every merchant. */
  totalTrustStock?: boolean;
  /** Absent in saved runs: retain the old effects check where only B02 could reveal a curse. */
  curseSight?: boolean;
  /** Absent in saved runs: buying from an NPC still costs energy there. */
  freeBuy?: boolean;
  /** Absent in saved audits: inspections and appraisals keep their original costs. */
  freeMerchantAction?: boolean;
  /** Absent in saved runs: fake items never produce their good effect there. */
  fakeEffect?: boolean;
  /** Absent in saved runs: merchants do not clean curses and the smith tools are never stocked. */
  cleanse?: boolean;
  /** Absent in saved runs: merchants never announce wishes. */
  wishlist?: boolean;
  /** Absent in saved runs: wishes cost no energy, have no cap and never lose value. */
  wishContract?: boolean;
  /** Absent in saved runs: listings carry no appraiser claims and the challenge tools are never stocked. */
  challenge?: boolean;
  /** Absent in saved runs: the Deep Sea Monster and The Swarm never appear and their items, statuses and events stay out of play. */
  expansion?: boolean;
  /** Absent in saved runs: no omens, sale/fee/life modifiers beyond the original market rules, capacity relics or polish events. */
  polish?: boolean;
  /** Absent in saved runs: no personal merchant contracts or delayed repayments. */
  npcEvents?: boolean;
  /** Absent in saved runs: the v0.6 core (rebalanced prices, door tolls, overvaluation backlash, escalating survival pressure with a Collector deadline, scrap energy, merchant skills, theft, barter and the extra statuses, events and omens). */
  core2?: boolean;
